  // ============================================================================
  // CERTAINTY ANALYZER (Phase 7.2) (~8KB)
  // ============================================================================

/**
 * CertaintyAnalyzer.js
 *
 * Phase 7.2: Detects certainty markers (hedges, boosters, evidentials) in text.
 * Lexicon-based detection within single clauses.
 *
 * Marker Types:
 * - Hedges: Reduce certainty ("might", "possibly", "seems")
 * - Boosters: Increase certainty ("definitely", "clearly", "must")
 * - Evidentials: Mark source of information ("reportedly", "allegedly")
 *
 * @module analyzers/CertaintyAnalyzer
 * @version 1.0.0
 */

/**
 * Hedge markers - reduce certainty/commitment
 * Includes modal hedges, epistemic adverbs, and hedging verbs
 */
const HEDGES = {
  // Modal hedges (auxiliary verbs)
  'might': { strength: 0.4, type: 'modal' },
  'may': { strength: 0.5, type: 'modal' },
  'could': { strength: 0.5, type: 'modal' },
  'would': { strength: 0.6, type: 'modal' },

  // Epistemic adverbs
  'possibly': { strength: 0.4, type: 'adverb' },
  'perhaps': { strength: 0.4, type: 'adverb' },
  'maybe': { strength: 0.4, type: 'adverb' },
  'probably': { strength: 0.6, type: 'adverb' },
  'likely': { strength: 0.6, type: 'adverb' },
  'presumably': { strength: 0.5, type: 'adverb' },
  'seemingly': { strength: 0.5, type: 'adverb' },
  'apparently': { strength: 0.5, type: 'adverb' },
  'potentially': { strength: 0.5, type: 'adverb' },
  'conceivably': { strength: 0.4, type: 'adverb' },
  'ostensibly': { strength: 0.5, type: 'adverb' },

  // Hedging verbs
  'seems': { strength: 0.5, type: 'verb' },
  'seem': { strength: 0.5, type: 'verb' },
  'appears': { strength: 0.5, type: 'verb' },
  'appear': { strength: 0.5, type: 'verb' },
  'suggests': { strength: 0.5, type: 'verb' },
  'suggest': { strength: 0.5, type: 'verb' },
  'indicates': { strength: 0.6, type: 'verb' },
  'indicate': { strength: 0.6, type: 'verb' },
  'tends': { strength: 0.6, type: 'verb' },
  'tend': { strength: 0.6, type: 'verb' },

  // Approximators
  'about': { strength: 0.7, type: 'approximator' },
  'approximately': { strength: 0.7, type: 'approximator' },
  'around': { strength: 0.7, type: 'approximator' },
  'roughly': { strength: 0.6, type: 'approximator' },
  'somewhat': { strength: 0.6, type: 'approximator' },
  'relatively': { strength: 0.7, type: 'approximator' },
  'fairly': { strength: 0.7, type: 'approximator' }
};

/**
 * Booster markers - increase certainty/commitment
 * Includes modal boosters, intensifying adverbs, and emphatic expressions
 */
const BOOSTERS = {
  // Modal boosters (strong obligation/certainty)
  'must': { strength: 0.95, type: 'modal' },
  'shall': { strength: 0.9, type: 'modal' },
  'will': { strength: 0.85, type: 'modal' },

  // Intensifying adverbs
  'definitely': { strength: 0.95, type: 'adverb' },
  'certainly': { strength: 0.95, type: 'adverb' },
  'clearly': { strength: 0.9, type: 'adverb' },
  'obviously': { strength: 0.9, type: 'adverb' },
  'undoubtedly': { strength: 0.95, type: 'adverb' },
  'absolutely': { strength: 1.0, type: 'adverb' },
  'unquestionably': { strength: 0.95, type: 'adverb' },
  'surely': { strength: 0.85, type: 'adverb' },
  'indeed': { strength: 0.8, type: 'adverb' },
  'truly': { strength: 0.85, type: 'adverb' },
  'really': { strength: 0.75, type: 'adverb' },
  'actually': { strength: 0.8, type: 'adverb' },
  'always': { strength: 0.9, type: 'adverb' },
  'never': { strength: 0.9, type: 'adverb' },
  'inevitably': { strength: 0.9, type: 'adverb' },

  // Emphatic verbs/phrases
  'proves': { strength: 0.9, type: 'verb' },
  'prove': { strength: 0.9, type: 'verb' },
  'confirms': { strength: 0.85, type: 'verb' },
  'confirm': { strength: 0.85, type: 'verb' },
  'demonstrates': { strength: 0.85, type: 'verb' },
  'demonstrate': { strength: 0.85, type: 'verb' },
  'establishes': { strength: 0.85, type: 'verb' },
  'establish': { strength: 0.85, type: 'verb' },
  'shows': { strength: 0.8, type: 'verb' },
  'show': { strength: 0.8, type: 'verb' }
};

/**
 * Evidential markers - indicate source of information
 * Marks claims as reported/attributed rather than asserted
 */
const EVIDENTIALS = {
  // Reported speech markers
  'reportedly': { sourceType: 'reported', reliability: 0.6 },
  'allegedly': { sourceType: 'reported', reliability: 0.4 },
  'supposedly': { sourceType: 'reported', reliability: 0.5 },
  'purportedly': { sourceType: 'reported', reliability: 0.5 },

  // Attribution markers
  'according': { sourceType: 'attributed', reliability: 0.7 },  // "according to"
  'claims': { sourceType: 'attributed', reliability: 0.5 },
  'claim': { sourceType: 'attributed', reliability: 0.5 },
  'states': { sourceType: 'attributed', reliability: 0.7 },
  'state': { sourceType: 'attributed', reliability: 0.7 },
  'reports': { sourceType: 'attributed', reliability: 0.7 },
  'report': { sourceType: 'attributed', reliability: 0.7 },

  // Hearsay markers
  'said': { sourceType: 'hearsay', reliability: 0.6 },
  'says': { sourceType: 'hearsay', reliability: 0.6 },
  'told': { sourceType: 'hearsay', reliability: 0.6 },
  'announced': { sourceType: 'hearsay', reliability: 0.7 }
};

/**
 * CertaintyAnalyzer class
 * Detects and classifies certainty markers in text
 */
class CertaintyAnalyzer {
  /**
   * Create a CertaintyAnalyzer
   * @param {Object} [options] - Configuration options
   * @param {boolean} [options.includePositions=true] - Include marker positions
   */
  constructor(options = {}) {
    this.options = {
      includePositions: true,
      ...options
    };
  }

  /**
   * Analyze text for certainty markers
   * @param {string} text - Text to analyze
   * @returns {Object} Certainty analysis result
   */
  analyze(text) {
    const lowerText = text.toLowerCase();
    const words = this._tokenize(text);

    const hedges = this._detectMarkers(lowerText, words, HEDGES, 'hedge');
    const boosters = this._detectMarkers(lowerText, words, BOOSTERS, 'booster');
    const evidentials = this._detectMarkers(lowerText, words, EVIDENTIALS, 'evidential');

    // Calculate overall certainty score
    const certaintyScore = this._calculateCertaintyScore(hedges, boosters);

    // Determine dominant marker type
    const dominantType = this._getDominantType(hedges, boosters, evidentials);

    return {
      certaintyScore,
      dominantType,
      hedges,
      boosters,
      evidentials,
      isHedged: hedges.length > 0,
      isBoosted: boosters.length > 0,
      isEvidential: evidentials.length > 0,
      markerCount: hedges.length + boosters.length + evidentials.length
    };
  }

  /**
   * Analyze a specific claim or assertion
   * @param {string} claimText - The claim text
   * @param {Object} [context] - Additional context
   * @returns {Object} Claim certainty analysis
   */
  analyzeClaimCertainty(claimText, context = {}) {
    const analysis = this.analyze(claimText);

    return {
      'tagteam:certaintyScore': analysis.certaintyScore,
      'tagteam:certaintyType': analysis.dominantType,
      'tagteam:hedges': analysis.hedges.map(h => h.marker),
      'tagteam:boosters': analysis.boosters.map(b => b.marker),
      'tagteam:evidentials': analysis.evidentials.map(e => ({
        marker: e.marker,
        sourceType: e.sourceType
      })),
      'tagteam:isHedged': analysis.isHedged,
      'tagteam:isReported': analysis.isEvidential
    };
  }

  /**
   * Detect markers of a specific type
   * @private
   */
  _detectMarkers(lowerText, words, lexicon, markerType) {
    const detected = [];

    for (const [marker, info] of Object.entries(lexicon)) {
      // Check if marker appears in text
      const regex = new RegExp(`\\b${marker}\\b`, 'gi');
      let match;

      while ((match = regex.exec(lowerText)) !== null) {
        const markerInfo = {
          marker,
          type: markerType,
          position: this.options.includePositions ? match.index : undefined
        };

        // Add type-specific info
        if (markerType === 'hedge' || markerType === 'booster') {
          markerInfo.strength = info.strength;
          markerInfo.subtype = info.type;
        } else if (markerType === 'evidential') {
          markerInfo.sourceType = info.sourceType;
          markerInfo.reliability = info.reliability;
        }

        detected.push(markerInfo);
      }
    }

    return detected;
  }

  /**
   * Calculate overall certainty score (0-1)
   * @private
   */
  _calculateCertaintyScore(hedges, boosters) {
    // Start with neutral certainty
    let score = 0.5;

    // Hedges reduce certainty
    for (const hedge of hedges) {
      // Apply hedge effect: pull score toward hedge strength
      const hedgeEffect = (hedge.strength - score) * 0.3;
      score += hedgeEffect;
    }

    // Boosters increase certainty
    for (const booster of boosters) {
      // Apply booster effect: pull score toward booster strength
      const boostEffect = (booster.strength - score) * 0.3;
      score += boostEffect;
    }

    // Clamp to [0, 1]
    return Math.max(0, Math.min(1, score));
  }

  /**
   * Determine dominant marker type
   * @private
   */
  _getDominantType(hedges, boosters, evidentials) {
    if (evidentials.length > 0) return 'evidential';
    if (hedges.length > boosters.length) return 'hedged';
    if (boosters.length > hedges.length) return 'boosted';
    if (hedges.length > 0 && boosters.length > 0) return 'mixed';
    return 'neutral';
  }

  /**
   * Simple tokenizer
   * @private
   */
  _tokenize(text) {
    return text.toLowerCase().split(/\s+/).map(w => w.replace(/[^\w]/g, ''));
  }

  /**
   * Get all markers in the lexicon
   * @returns {Object} All marker lexicons
   */
  static getLexicon() {
    return {
      hedges: HEDGES,
      boosters: BOOSTERS,
      evidentials: EVIDENTIALS
    };
  }

  /**
   * Get marker count
   * @returns {number} Total markers in lexicon
   */
  static getMarkerCount() {
    return Object.keys(HEDGES).length +
           Object.keys(BOOSTERS).length +
           Object.keys(EVIDENTIALS).length;
  }
}



  // Make CertaintyAnalyzer available globally for SemanticGraphBuilder
  _global.CertaintyAnalyzer = CertaintyAnalyzer;

  // ============================================================================
  // PHASE 7.1: SOURCE ATTRIBUTION DETECTION (~10KB)
  // ============================================================================

/**
 * SourceAttributionDetector.js
 *
 * Phase 7.1: Detects source attribution patterns in text.
 * v1-Limited scope: direct quotes, reported speech, institutional sources.
 *
 * Detection Patterns:
 * - Direct quotes: "X," said Dr. Smith
 * - Reported speech: The nurse reported that...
 * - Institutional: Hospital policy states...
 *
 * @module graph/SourceAttributionDetector
 * @version 1.0.0
 */

/**
 * Attribution reporting verbs - signal that a source is being cited
 */
const REPORTING_VERBS = {
  // Strong attribution (high reliability)
  'said': { strength: 0.9, tense: 'past' },
  'says': { strength: 0.9, tense: 'present' },
  'stated': { strength: 0.95, tense: 'past' },
  'states': { strength: 0.95, tense: 'present' },
  'announced': { strength: 0.9, tense: 'past' },
  'announces': { strength: 0.9, tense: 'present' },
  'declared': { strength: 0.95, tense: 'past' },
  'declares': { strength: 0.95, tense: 'present' },
  'confirmed': { strength: 0.95, tense: 'past' },
  'confirms': { strength: 0.95, tense: 'present' },

  // Medium attribution
  'reported': { strength: 0.8, tense: 'past' },
  'reports': { strength: 0.8, tense: 'present' },
  'claimed': { strength: 0.7, tense: 'past' },
  'claims': { strength: 0.7, tense: 'present' },
  'argued': { strength: 0.75, tense: 'past' },
  'argues': { strength: 0.75, tense: 'present' },
  'noted': { strength: 0.8, tense: 'past' },
  'notes': { strength: 0.8, tense: 'present' },
  'explained': { strength: 0.85, tense: 'past' },
  'explains': { strength: 0.85, tense: 'present' },
  'mentioned': { strength: 0.75, tense: 'past' },
  'mentions': { strength: 0.75, tense: 'present' },
  'told': { strength: 0.85, tense: 'past' },
  'tells': { strength: 0.85, tense: 'present' },
  'informed': { strength: 0.85, tense: 'past' },
  'informs': { strength: 0.85, tense: 'present' },

  // Weaker attribution (may indicate uncertainty)
  'suggested': { strength: 0.6, tense: 'past' },
  'suggests': { strength: 0.6, tense: 'present' },
  'indicated': { strength: 0.65, tense: 'past' },
  'indicates': { strength: 0.65, tense: 'present' },
  'implied': { strength: 0.5, tense: 'past' },
  'implies': { strength: 0.5, tense: 'present' },
  'believed': { strength: 0.55, tense: 'past' },
  'believes': { strength: 0.55, tense: 'present' },
  'thought': { strength: 0.5, tense: 'past' },
  'thinks': { strength: 0.5, tense: 'present' },

  // Written sources
  'wrote': { strength: 0.9, tense: 'past' },
  'writes': { strength: 0.9, tense: 'present' },
  'documented': { strength: 0.9, tense: 'past' },
  'documents': { strength: 0.9, tense: 'present' }
};

/**
 * Institutional source patterns - organizations/policies as sources
 */
const INSTITUTIONAL_PATTERNS = [
  // Policies and guidelines
  { pattern: /(?:hospital|clinic|facility)\s+policy\s+(?:states|requires|mandates|recommends)/i, type: 'policy' },
  { pattern: /(?:medical|clinical|ethical)\s+guidelines?\s+(?:state|require|recommend|suggest)/i, type: 'guideline' },
  { pattern: /(?:treatment|care)\s+protocol\s+(?:states|requires|specifies)/i, type: 'protocol' },
  { pattern: /(?:the|this)\s+(?:organization|institution|hospital|agency)\s+(?:states|requires|mandates)/i, type: 'institutional' },

  // Standards and regulations
  { pattern: /(?:federal|state|local)\s+(?:law|regulation|statute)\s+(?:requires|mandates|prohibits)/i, type: 'regulation' },
  { pattern: /(?:professional|medical|ethical)\s+standards?\s+(?:require|mandate|state)/i, type: 'standard' },
  { pattern: /code\s+of\s+(?:ethics|conduct)\s+(?:states|requires|prohibits)/i, type: 'code' },

  // Official documents
  { pattern: /(?:the|this)\s+(?:report|study|document|memo)\s+(?:states|indicates|shows|confirms)/i, type: 'document' },
  { pattern: /(?:medical|patient)\s+records?\s+(?:show|indicate|confirm|document)/i, type: 'record' },

  // Committee/board decisions (allow adjectives like "ethics committee")
  { pattern: /(?:the|this)\s+(?:\w+\s+)?(?:committee|board|panel|council)\s+(?:decided|ruled|determined|recommended)/i, type: 'committee' }
];

/**
 * Person role patterns for source identification
 */
const PERSON_ROLE_PATTERNS = {
  'doctor': 'Person',
  'dr': 'Person',
  'physician': 'Person',
  'surgeon': 'Person',
  'nurse': 'Person',
  'patient': 'Person',
  'family': 'FamilyMember',
  'relative': 'FamilyMember',
  'researcher': 'Researcher',
  'scientist': 'Researcher',
  'expert': 'Expert',
  'specialist': 'Specialist',
  'lawyer': 'LegalProfessional',
  'attorney': 'LegalProfessional',
  'judge': 'Judge',
  'official': 'Official',
  'spokesperson': 'Spokesperson',
  'witness': 'Witness',
  'professor': 'AcademicProfessional',
  'administrator': 'Administrator'
};

/**
 * SourceAttributionDetector class
 * Detects and classifies source attributions in text
 */
class SourceAttributionDetector {
  /**
   * Create a SourceAttributionDetector
   * @param {Object} [options] - Configuration options
   * @param {boolean} [options.includePositions=true] - Include source text positions
   * @param {number} [options.minConfidence=0.5] - Minimum confidence for detection
   */
  constructor(options = {}) {
    this.options = {
      includePositions: true,
      minConfidence: 0.4, // Lower default to include weak verbs like "implied" (0.5 * 0.9 = 0.45)
      ...options
    };
  }

  /**
   * Analyze text for source attributions
   * @param {string} text - Text to analyze
   * @returns {Object} Attribution analysis result
   */
  analyze(text) {
    const attributions = [];

    // Detect direct quotes
    const quotes = this._detectDirectQuotes(text);
    attributions.push(...quotes);

    // Detect reported speech (non-quoted)
    const reported = this._detectReportedSpeech(text);
    attributions.push(...reported);

    // Detect institutional sources
    const institutional = this._detectInstitutionalSources(text);
    attributions.push(...institutional);

    // Detect "according to" patterns
    const accordingTo = this._detectAccordingTo(text);
    attributions.push(...accordingTo);

    // Deduplicate overlapping attributions (prefer higher confidence)
    const deduped = this._deduplicateAttributions(attributions);

    // Filter by minimum confidence
    const filtered = deduped.filter(a => a.confidence >= this.options.minConfidence);

    return {
      attributions: filtered,
      hasAttributions: filtered.length > 0,
      attributionCount: filtered.length,
      dominantType: this._getDominantType(filtered),
      summary: this._generateSummary(filtered)
    };
  }

  /**
   * Analyze a specific claim for attribution
   * @param {string} claimText - The claim text
   * @param {Object} [context] - Additional context
   * @returns {Object} Claim attribution analysis with tagteam properties
   */
  analyzeClaimAttribution(claimText, context = {}) {
    const analysis = this.analyze(claimText);

    if (analysis.attributions.length === 0) {
      return {
        'tagteam:hasAttribution': false,
        'tagteam:attributionType': 'unattributed'
      };
    }

    const primary = analysis.attributions[0]; // Most confident attribution

    return {
      'tagteam:hasAttribution': true,
      'tagteam:attributionType': primary.type,
      'tagteam:detectedSource': primary.source,
      'tagteam:sourceType': primary.sourceType || null,
      'tagteam:attributionConfidence': primary.confidence,
      'tagteam:attributionEvidence': primary.evidence
    };
  }

  /**
   * Detect direct quote attributions
   * Patterns: "X," said Y / Y said "X" / Y: "X"
   * @private
   */
  _detectDirectQuotes(text) {
    const attributions = [];

    // Name pattern: handles "Dr. Smith", "John Smith", "Smith", "Professor Jones"
    // Allows optional title (Dr., Mr., Mrs., Ms., Prof.) + name(s)
    const namePattern = '(?:(?:Dr|Mr|Mrs|Ms|Prof|Professor)\\.?\\s+)?[A-Z][a-zA-Z]+(?:\\s+[A-Z][a-zA-Z]+)*';

    // Pattern 1: "quote," said Source
    const postQuotePattern = new RegExp(`"([^"]+)",?\\s+(\\w+)\\s+(${namePattern})`, 'g');
    let match;

    while ((match = postQuotePattern.exec(text)) !== null) {
      const [fullMatch, quote, verb, source] = match;
      const verbLower = verb.toLowerCase();

      if (REPORTING_VERBS[verbLower]) {
        attributions.push({
          type: 'direct_quote',
          source: source.trim(),
          sourceType: this._classifySource(source),
          quote: quote.trim(),
          verb: verbLower,
          confidence: REPORTING_VERBS[verbLower].strength,
          evidence: fullMatch,
          position: this.options.includePositions ? match.index : undefined
        });
      }
    }

    // Pattern 2: Source said "quote" / Source said, "quote"
    const preQuotePattern = new RegExp(`(${namePattern})\\s+(\\w+),?\\s+"([^"]+)"`, 'g');

    while ((match = preQuotePattern.exec(text)) !== null) {
      const [fullMatch, source, verb, quote] = match;
      const verbLower = verb.toLowerCase();

      if (REPORTING_VERBS[verbLower]) {
        attributions.push({
          type: 'direct_quote',
          source: source.trim(),
          sourceType: this._classifySource(source),
          quote: quote.trim(),
          verb: verbLower,
          confidence: REPORTING_VERBS[verbLower].strength,
          evidence: fullMatch,
          position: this.options.includePositions ? match.index : undefined
        });
      }
    }

    // Pattern 3: Source: "quote"
    const colonQuotePattern = new RegExp(`(${namePattern}):\\s*"([^"]+)"`, 'g');

    while ((match = colonQuotePattern.exec(text)) !== null) {
      const [fullMatch, source, quote] = match;
      attributions.push({
        type: 'direct_quote',
        source: source.trim(),
        sourceType: this._classifySource(source),
        quote: quote.trim(),
        verb: null,
        confidence: 0.85,
        evidence: fullMatch,
        position: this.options.includePositions ? match.index : undefined
      });
    }

    return attributions;
  }

  /**
   * Detect reported speech (non-quoted)
   * Pattern: The X reported/said/claimed that...
   * @private
   */
  _detectReportedSpeech(text) {
    const attributions = [];

    // Pattern: The/A [role] [verb] that [content]
    // Use single word for source to avoid greedy matching
    const reportedPattern = /(?:the|a|an)\s+(\w+)\s+(\w+)\s+that\s+([^.!?]+[.!?]?)/gi;
    let match;

    while ((match = reportedPattern.exec(text)) !== null) {
      const [fullMatch, source, verb, content] = match;
      const verbLower = verb.toLowerCase();

      if (REPORTING_VERBS[verbLower]) {
        attributions.push({
          type: 'reported_speech',
          source: source.trim(),
          sourceType: this._classifySource(source),
          content: content.trim(),
          verb: verbLower,
          confidence: REPORTING_VERBS[verbLower].strength * 0.9, // Slightly lower than direct quote
          evidence: fullMatch.trim(),
          position: this.options.includePositions ? match.index : undefined
        });
      }
    }

    // Pattern: [Title + Name] [verb] that [content] - handles "Dr. Smith said that"
    const namePattern = '(?:(?:Dr|Mr|Mrs|Ms|Prof|Professor)\\.?\\s+)?[A-Z][a-zA-Z]+(?:\\s+[A-Z][a-zA-Z]+)?';
    const namedReportedPattern = new RegExp(`(${namePattern})\\s+(\\w+)\\s+that\\s+([^.!?]+[.!?]?)`, 'g');

    while ((match = namedReportedPattern.exec(text)) !== null) {
      const [fullMatch, source, verb, content] = match;
      const verbLower = verb.toLowerCase();

      if (REPORTING_VERBS[verbLower]) {
        attributions.push({
          type: 'reported_speech',
          source: source.trim(),
          sourceType: this._classifySource(source),
          content: content.trim(),
          verb: verbLower,
          confidence: REPORTING_VERBS[verbLower].strength * 0.9,
          evidence: fullMatch.trim(),
          position: this.options.includePositions ? match.index : undefined
        });
      }
    }

    return attributions;
  }

  /**
   * Detect institutional source attributions
   * @private
   */
  _detectInstitutionalSources(text) {
    const attributions = [];

    for (const { pattern, type } of INSTITUTIONAL_PATTERNS) {
      const match = text.match(pattern);

      if (match) {
        attributions.push({
          type: 'institutional',
          institutionalType: type,
          source: match[0],
          sourceType: 'Organization',
          confidence: 0.85,
          evidence: match[0],
          position: this.options.includePositions ? match.index : undefined
        });
      }
    }

    return attributions;
  }

  /**
   * Detect "according to" patterns
   * @private
   */
  _detectAccordingTo(text) {
    const attributions = [];

    // Pattern: According to [source], [content]
    const accordingPattern = /according\s+to\s+([^,]+),?\s*([^.!?]+[.!?]?)/gi;
    let match;

    while ((match = accordingPattern.exec(text)) !== null) {
      const [fullMatch, source, content] = match;

      attributions.push({
        type: 'according_to',
        source: source.trim(),
        sourceType: this._classifySource(source),
        content: content.trim(),
        confidence: 0.8,
        evidence: fullMatch.trim(),
        position: this.options.includePositions ? match.index : undefined
      });
    }

    return attributions;
  }

  /**
   * Classify the source type
   * @private
   */
  _classifySource(source) {
    if (!source) return null;

    const lower = source.toLowerCase();

    // Check against known person roles
    for (const [role, type] of Object.entries(PERSON_ROLE_PATTERNS)) {
      if (lower.includes(role)) {
        return type;
      }
    }

    // Check for organizational patterns
    if (/(?:hospital|clinic|agency|organization|institution|committee|board|panel|council)/i.test(lower)) {
      return 'Organization';
    }

    // Check for document patterns
    if (/(?:report|study|document|record|policy|guideline|protocol)/i.test(lower)) {
      return 'InformationContentEntity';
    }

    // Default: assume person if starts with capital (likely a name)
    if (/^[A-Z]/.test(source)) {
      return 'Person';
    }

    return null;
  }

  /**
   * Deduplicate overlapping attributions
   * @private
   */
  _deduplicateAttributions(attributions) {
    if (attributions.length <= 1) return attributions;

    // Sort by confidence (descending)
    const sorted = [...attributions].sort((a, b) => b.confidence - a.confidence);
    const kept = [];

    for (const attr of sorted) {
      // Check if this overlaps with any kept attribution
      const overlaps = kept.some(k => {
        if (k.position === undefined || attr.position === undefined) return false;
        const kEnd = k.position + (k.evidence?.length || 0);
        const aEnd = attr.position + (attr.evidence?.length || 0);
        return (attr.position >= k.position && attr.position < kEnd) ||
               (k.position >= attr.position && k.position < aEnd);
      });

      if (!overlaps) {
        kept.push(attr);
      }
    }

    return kept;
  }

  /**
   * Get dominant attribution type
   * @private
   */
  _getDominantType(attributions) {
    if (attributions.length === 0) return 'none';

    const counts = {};
    for (const attr of attributions) {
      counts[attr.type] = (counts[attr.type] || 0) + 1;
    }

    let maxType = 'none';
    let maxCount = 0;
    for (const [type, count] of Object.entries(counts)) {
      if (count > maxCount) {
        maxType = type;
        maxCount = count;
      }
    }

    return maxType;
  }

  /**
   * Generate summary of attributions
   * @private
   */
  _generateSummary(attributions) {
    if (attributions.length === 0) {
      return 'No source attributions detected';
    }

    const types = new Set(attributions.map(a => a.type));
    const sources = new Set(attributions.map(a => a.source));

    return `${attributions.length} attribution(s): ${[...types].join(', ')} from ${[...sources].join(', ')}`;
  }

  /**
   * Get reporting verbs lexicon
   * @returns {Object} Reporting verbs with metadata
   */
  static getReportingVerbs() {
    return REPORTING_VERBS;
  }

  /**
   * Get count of reporting verbs
   * @returns {number} Number of reporting verbs in lexicon
   */
  static getVerbCount() {
    return Object.keys(REPORTING_VERBS).length;
  }

  /**
   * Get institutional patterns
   * @returns {Array} Institutional source patterns
   */
  static getInstitutionalPatterns() {
    return INSTITUTIONAL_PATTERNS;
  }
}



  // Make SourceAttributionDetector available globally for SemanticGraphBuilder
  _global.SourceAttributionDetector = SourceAttributionDetector;

  // ============================================================================
  // PHASE 7 v7: SENTENCE MODE CLASSIFIER (~6KB)
  // ============================================================================

/**
 * SentenceModeClassifier
 *
 * Classifies verbs as STATIVE_DEFINITE, STATIVE_AMBIGUOUS, or EVENTIVE
 * to determine whether a sentence describes a structural relation (stative)
 * or an intentional act (eventive).
 *
 * Per BFO: stative predicates describe continuant relations (no temporal parts),
 * while eventive predicates describe occurrent processes (unfold in time).
 *
 * @module SentenceModeClassifier
 */

/**
 * Verb taxonomy: maps infinitive verbs to their classification and output relation.
 *
 * STATIVE_DEFINITE: Always structural (never an intentional act)
 * STATIVE_AMBIGUOUS: Context-dependent (may be stative or eventive)
 * EVENTIVE: Default — all other verbs
 */
const STATIVE_DEFINITE = {
  // Membership relations
  'include': { relation: 'has_member_part', inverse: 'member_part_of', group: 'membership' },
  'encompass': { relation: 'has_member_part', inverse: 'member_part_of', group: 'membership' },

  // Composition / containment
  'contain': { relation: 'has_continuant_part', inverse: 'continuant_part_of', group: 'composition' },
  'comprise': { relation: 'has_member_part', inverse: 'member_part_of', group: 'composition' },
  'consist': { relation: 'has_continuant_part', inverse: 'continuant_part_of', group: 'composition' },

  // Possession
  'possess': { relation: 'has_possession', inverse: null, group: 'possession' },
  'own': { relation: 'has_possession', inverse: null, group: 'possession' },

  // Location (stative sense)
  'reside': { relation: 'located_in', inverse: null, group: 'location' },
};

/**
 * "have" is special — it is stative in possessive sense but modal in "have to" sense.
 * We handle it separately: stative only when NOT followed by "to" (modal).
 */
const HAVE_VERB = {
  relation: 'has_possession',
  inverse: null,
  group: 'possession',
  condition: 'possessive_sense'
};

/**
 * Ambiguous verbs: may be stative or eventive depending on context.
 */
const STATIVE_AMBIGUOUS = {
  'represent': {
    stativeCondition: 'object_is_organization_or_nation',
    stativeRelation: 'bears_role_for',
    eventiveActType: 'IntentionalAct',
    // Stative if object is Nation, Organization, GeopoliticalEntity
    stativeObjectTypes: ['GeopoliticalOrganization', 'Organization', 'Country']
  },
  'support': {
    stativeCondition: 'subject_is_artifact',
    stativeRelation: 'has_continuant_part',
    eventiveActType: 'IntentionalAct',
    stativeSubjectTypes: ['Artifact']
  },
  'cover': {
    stativeCondition: 'object_is_measurement',
    stativeRelation: 'has_spatial_extent',
    eventiveActType: 'IntentionalAct',
    stativeObjectTypes: []
  }
};

class SentenceModeClassifier {
  constructor(options = {}) {
    this.options = options;
  }

  /**
   * Classify a verb as stative or eventive.
   *
   * @param {string} infinitive - The verb in infinitive form (e.g., "include", "sign")
   * @param {Object} [context] - Optional context for disambiguation
   * @param {boolean} [context.isModal] - Whether verb is preceded by modal auxiliary
   * @param {string} [context.followedBy] - Next word after verb (for "have to" detection)
   * @returns {{ category: string, relation: string|null, inverse: string|null, group: string|null }}
   */
  classifyVerb(infinitive, context = {}) {
    const verb = (infinitive || '').toLowerCase().trim();

    // Special case: "have" — modal vs possessive
    if (verb === 'have') {
      if (context.followedBy === 'to' || context.isModal) {
        return { category: 'EVENTIVE', relation: null, inverse: null, group: null };
      }
      return {
        category: 'STATIVE_DEFINITE',
        relation: HAVE_VERB.relation,
        inverse: HAVE_VERB.inverse,
        group: HAVE_VERB.group
      };
    }

    // Check definite stative verbs
    if (STATIVE_DEFINITE[verb]) {
      const entry = STATIVE_DEFINITE[verb];
      return {
        category: 'STATIVE_DEFINITE',
        relation: entry.relation,
        inverse: entry.inverse,
        group: entry.group
      };
    }

    // Check ambiguous stative verbs
    if (STATIVE_AMBIGUOUS[verb]) {
      return {
        category: 'STATIVE_AMBIGUOUS',
        relation: STATIVE_AMBIGUOUS[verb].stativeRelation,
        inverse: null,
        group: 'ambiguous'
      };
    }

    // Default: eventive
    return { category: 'EVENTIVE', relation: null, inverse: null, group: null };
  }

  /**
   * Disambiguate an ambiguous stative verb based on entity context.
   *
   * @param {string} infinitive - The verb infinitive
   * @param {Object} context - Disambiguation context
   * @param {string} [context.subjectType] - BFO/CCO type of subject entity
   * @param {string} [context.objectType] - BFO/CCO type of object entity
   * @returns {'STATIVE'|'EVENTIVE'}
   */
  disambiguateStativeVerb(infinitive, context = {}) {
    const verb = (infinitive || '').toLowerCase().trim();
    const entry = STATIVE_AMBIGUOUS[verb];
    if (!entry) return 'EVENTIVE';

    // Check object type condition
    if (entry.stativeObjectTypes && context.objectType) {
      if (entry.stativeObjectTypes.includes(context.objectType)) {
        return 'STATIVE';
      }
    }

    // Check subject type condition
    if (entry.stativeSubjectTypes && context.subjectType) {
      if (entry.stativeSubjectTypes.includes(context.subjectType)) {
        return 'STATIVE';
      }
    }

    // Check if object label suggests organization/nation
    if (verb === 'represent' && context.objectLabel) {
      const label = context.objectLabel.toLowerCase();
      const orgIndicators = ['united', 'states', 'nation', 'republic', 'kingdom',
                             'federation', 'union', 'association', 'organization',
                             'committee', 'council', 'department', 'ministry',
                             'government', 'corporation', 'company'];
      if (orgIndicators.some(ind => label.includes(ind))) {
        return 'STATIVE';
      }
    }

    // Default: eventive
    return 'EVENTIVE';
  }

  /**
   * Get the relation mapping for a stative verb.
   *
   * @param {string} infinitive - The verb infinitive
   * @returns {string|null} The CCO/BFO relation IRI, or null if not stative
   */
  getRelationForStativeVerb(infinitive) {
    const verb = (infinitive || '').toLowerCase().trim();
    if (verb === 'have') return HAVE_VERB.relation;
    if (STATIVE_DEFINITE[verb]) return STATIVE_DEFINITE[verb].relation;
    if (STATIVE_AMBIGUOUS[verb]) return STATIVE_AMBIGUOUS[verb].stativeRelation;
    return null;
  }

  /**
   * Check if a verb is in the stative taxonomy (definite or ambiguous).
   *
   * @param {string} infinitive
   * @returns {boolean}
   */
  isStativeCandidate(infinitive) {
    const verb = (infinitive || '').toLowerCase().trim();
    return verb === 'have' || !!STATIVE_DEFINITE[verb] || !!STATIVE_AMBIGUOUS[verb];
  }
}



  // Make SentenceModeClassifier available globally for ActExtractor
  _global.SentenceModeClassifier = SentenceModeClassifier;

  // ============================================================================
  // PHASE 7 v7: COMPLEX DESIGNATOR DETECTOR (~12KB)
  // ============================================================================

/**
 * ComplexDesignatorDetector
 *
 * Detects multi-word proper names (complex designators) in text using
 * Greedy NER — joining capitalized sequences across conjunctions and
 * prepositions that are typically part of organization/entity names.
 *
 * Per the v7 spec:
 * - Standard NER splits on conjunctions → fragments names
 * - Greedy NER joins on conjunctions when inside proper names
 * - ALL_CAPS words (AIDS, NATO) are never verbs inside capitalized sequences
 * - Morphological overrides suppress Process typing for -tion/-ment inside names
 *
 * @module graph/ComplexDesignatorDetector
 */

/**
 * Words that are NEVER verbs inside capitalized sequences.
 */
const NEVER_VERB_INSIDE_NAME = new Set([
  // Organization suffixes
  'incorporated', 'limited', 'ltd', 'inc', 'corp', 'llc',
  // Common name words
  'international', 'national', 'united', 'joint', 'general',
  // Nominalizations (process-like suffixes that are name components)
  'development', 'settlement', 'investment', 'management', 'services',
  'association', 'organization', 'operation', 'co-operation',
  'cooperation', 'administration', 'commission', 'foundation',
  'institution', 'federation', 'corporation', 'department',
  'programme', 'program', 'institute', 'institutes', 'centre', 'center',
  'council', 'committee', 'ministry', 'bureau', 'agency', 'office',
  'authority', 'board', 'bank', 'fund', 'union'
]);

/**
 * Known acronyms — always nouns, never verbs.
 */
const KNOWN_ACRONYMS = new Set([
  'AIDS', 'HIV', 'NATO', 'UNESCO', 'UNICEF', 'NASA', 'WHO',
  'OECD', 'ICSID', 'UNAIDS', 'IMF', 'WTO', 'EU', 'UN', 'OPEC',
  'ASEAN', 'NAFTA', 'FBI', 'CIA', 'NSA', 'IRS', 'EPA', 'CDC',
  'NIH', 'HHS', 'DOJ', 'DOD', 'DOS', 'DOE', 'USAID'
]);

/**
 * Internal connectors that can join parts of proper names.
 */
const INTERNAL_CONNECTORS = new Set(['and', 'or', 'of', 'for', 'on', 'the']);

/**
 * Determiners that signal the start of a new noun phrase.
 */
const DETERMINERS = new Set(['the', 'a', 'an', 'this', 'that', 'these', 'those']);

/**
 * High-confidence verbs that always signal a boundary even inside capitalized sequences.
 */
const HIGH_CONFIDENCE_VERBS = new Set([
  'is', 'are', 'was', 'were', 'be', 'been', 'being',
  'has', 'have', 'had',
  'do', 'does', 'did',
  'runs', 'eats', 'kills', 'builds', 'destroys',
  'include', 'includes', 'included',
  'support', 'supports', 'supported',
  'visit', 'visits', 'visited',
  'deploy', 'deploys', 'deployed',
  'meet', 'meets', 'met',
  'signed', 'signs', 'sign',
  'said', 'says', 'say',
  'made', 'makes', 'make',
  'took', 'takes', 'take',
  'gave', 'gives', 'give'
]);

class ComplexDesignatorDetector {
  constructor(options = {}) {
    this.options = options;
  }

  /**
   * Detect complex designator spans in text.
   *
   * @param {string} text - Input text
   * @returns {Array<{text: string, start: number, end: number, components: string[]}>}
   */
  detect(text) {
    if (!text || typeof text !== 'string') return [];

    const tokens = this._tokenize(text);
    const spans = [];
    let i = 0;

    while (i < tokens.length) {
      // Look for the start of a capitalized sequence or known acronym
      if (this._isCapitalizedOrAcronym(tokens[i])) {
        const span = this._consumeComplexDesignator(tokens, i);
        // Allow single-component spans if they are known acronyms
        const minComponents = KNOWN_ACRONYMS.has(tokens[i].word) ? 1 : 2;
        if (span && span.components.length >= minComponents) {
          spans.push(span);
          // Skip past this span
          i = span._endIndex;
          continue;
        }
      }
      i++;
    }

    // Post-process: split list-separated spans
    return this._splitListSpans(spans, text);
  }

  /**
   * Create JSON-LD ComplexDesignator nodes from detected spans.
   *
   * @param {Array} spans - Detected spans from detect()
   * @param {Object} [graphBuilder] - Optional graph builder for IRI generation
   * @returns {Array<Object>} JSON-LD nodes
   */
  createNodes(spans, graphBuilder) {
    return spans.map((span, idx) => {
      let id;
      if (graphBuilder) {
        id = graphBuilder.generateIRI(
          span.text.substring(0, 30).replace(/[^a-zA-Z0-9]/g, '_'),
          'ComplexDesignator',
          span.start
        );
      } else {
        const slug = span.text.substring(0, 30).replace(/[^a-zA-Z0-9]/g, '_');
        id = `inst:ComplexDesignator_${slug}_${span.start}`;
      }

      return {
        '@id': id,
        '@type': ['tagteam:ComplexDesignator'],
        'tagteam:fullName': span.text,
        'tagteam:nameComponents': span.components,
        'tagteam:denotedType': 'Organization',
        'tagteam:startPosition': span.start,
        'tagteam:endPosition': span.end
      };
    });
  }

  /**
   * Tokenize text into words with position information.
   * @private
   */
  _tokenize(text) {
    const tokens = [];
    // Match words, punctuation, and apostrophe-attached suffixes
    const regex = /([A-Za-z'-]+|[,;:.])/g;
    let match;
    while ((match = regex.exec(text)) !== null) {
      tokens.push({
        word: match[1],
        start: match.index,
        end: match.index + match[1].length
      });
    }
    return tokens;
  }

  /**
   * Check if a token is capitalized or a known acronym.
   * @private
   */
  _isCapitalizedOrAcronym(token) {
    if (!token) return false;
    const w = token.word;
    if (KNOWN_ACRONYMS.has(w)) return true;
    if (this._isAllCaps(w) && w.length >= 2) return true;
    return /^[A-Z]/.test(w);
  }

  /**
   * Check if a word is ALL_CAPS.
   * @private
   */
  _isAllCaps(word) {
    return word.length >= 2 && word === word.toUpperCase() && /^[A-Z]+$/.test(word);
  }

  /**
   * Consume tokens starting from index i to build a ComplexDesignator span.
   * Greedy: keeps consuming while the sequence looks like a proper name.
   * @private
   */
  _consumeComplexDesignator(tokens, startIdx) {
    const components = [];
    let i = startIdx;
    let lastCapEnd = -1;

    while (i < tokens.length) {
      const token = tokens[i];
      const word = token.word;
      const wordLower = word.toLowerCase();

      // Case 1: Capitalized word or known acronym — always include
      if (this._isCapitalizedOrAcronym(token)) {
        // Check if this is a high-confidence verb that should end the span
        if (components.length > 0 && this._isHighConfidenceVerb(word) &&
            !NEVER_VERB_INSIDE_NAME.has(wordLower) && !this._isAllCaps(word)) {
          break;
        }
        components.push(word);
        lastCapEnd = token.end;
        i++;
        continue;
      }

      // Case 2: Internal connector (and, or, of, for, on)
      if (INTERNAL_CONNECTORS.has(wordLower) && components.length > 0) {
        // Look ahead: if next meaningful token is capitalized or acronym, join
        const nextMeaningful = this._nextMeaningfulToken(tokens, i + 1);
        if (nextMeaningful && this._isCapitalizedOrAcronym(nextMeaningful)) {
          // Special case: "and the [lowercase]" → break (new clause)
          if ((wordLower === 'and' || wordLower === 'or') && i + 1 < tokens.length) {
            const nextToken = tokens[i + 1];
            if (nextToken && DETERMINERS.has(nextToken.word.toLowerCase())) {
              // Check what follows the determiner
              const afterDet = this._nextMeaningfulToken(tokens, i + 2);
              if (afterDet && !this._isCapitalizedOrAcronym(afterDet)) {
                // "and the [lowercase]" → break
                break;
              }
            }
          }
          components.push(word);
          i++;
          continue;
        } else {
          // Next token is lowercase/end — break
          break;
        }
      }

      // Case 3: Comma — context dependent
      if (word === ',') {
        // Look ahead past the comma
        const afterComma = this._nextMeaningfulToken(tokens, i + 1);
        if (!afterComma) break;

        // If "the" follows comma, check if it starts a new list item or a new clause
        if (afterComma.word.toLowerCase() === 'the') {
          // Look further: "the [Capitalized]" could be a new list item in an enumeration
          // But in list context ("..., the X, the Y, and the Z"), each "the" starts a new item
          // We should break here to allow list splitting later
          break;
        }

        // If next is "and" followed by "the" → list terminator, break
        if (afterComma.word.toLowerCase() === 'and') {
          const afterAnd = this._nextMeaningfulToken(tokens, i + 2);
          if (afterAnd && afterAnd.word.toLowerCase() === 'the') {
            break;
          }
        }

        // If next meaningful word is capitalized → still inside the name (e.g., "Marble, Slate")
        if (this._isCapitalizedOrAcronym(afterComma)) {
          components.push(',');
          i++;
          continue;
        }

        // Otherwise break
        break;
      }

      // Case 4: Lowercase word that's not a connector → boundary
      break;
    }

    // Allow single-component spans for known acronyms
    const firstWord = tokens[startIdx]?.word;
    const minLen = (KNOWN_ACRONYMS.has(firstWord) || this._isAllCaps(firstWord)) ? 1 : 2;
    if (components.length < minLen) return null;

    // Build the span text from the original text positions
    const firstToken = tokens[startIdx];
    const lastTokenIdx = startIdx + this._countTokensInComponents(tokens, startIdx, components) - 1;
    const lastToken = tokens[Math.min(lastTokenIdx, tokens.length - 1)];

    // Reconstruct text from original positions
    const spanStart = firstToken.start;
    const spanEnd = lastToken ? lastToken.end : firstToken.end;

    return {
      text: this._reconstructText(tokens, startIdx, components),
      start: spanStart,
      end: spanEnd,
      components: components,
      _endIndex: Math.min(lastTokenIdx + 1, tokens.length)
    };
  }

  /**
   * Reconstruct the span text from components, preserving spacing.
   * @private
   */
  _reconstructText(tokens, startIdx, components) {
    // Walk tokens from startIdx, collecting the original text
    let result = '';
    let tokenIdx = startIdx;
    let compIdx = 0;

    while (compIdx < components.length && tokenIdx < tokens.length) {
      const token = tokens[tokenIdx];
      const comp = components[compIdx];

      if (token.word === comp || token.word.toLowerCase() === comp.toLowerCase() || comp === ',') {
        if (result.length > 0 && comp !== ',') {
          result += ' ';
        } else if (comp === ',') {
          // No space before comma, but handled by original text
        }
        result += token.word;
        tokenIdx++;
        compIdx++;
      } else {
        tokenIdx++;
      }
    }

    return result;
  }

  /**
   * Count how many tokens are consumed by the components list.
   * @private
   */
  _countTokensInComponents(tokens, startIdx, components) {
    let tokenIdx = startIdx;
    let compIdx = 0;
    let count = 0;

    while (compIdx < components.length && tokenIdx < tokens.length) {
      const token = tokens[tokenIdx];
      const comp = components[compIdx];

      if (token.word === comp || token.word.toLowerCase() === comp.toLowerCase()) {
        count++;
        compIdx++;
      }
      tokenIdx++;
      if (tokenIdx - startIdx > components.length * 3) break; // safety
    }

    return count > 0 ? (tokenIdx - startIdx) : components.length;
  }

  /**
   * Get the next meaningful (non-whitespace) token after index.
   * @private
   */
  _nextMeaningfulToken(tokens, idx) {
    if (idx >= tokens.length) return null;
    return tokens[idx]; // tokens already skip whitespace
  }

  /**
   * Check if a word is a high-confidence verb (boundary signal).
   * @private
   */
  _isHighConfidenceVerb(word) {
    return HIGH_CONFIDENCE_VERBS.has(word.toLowerCase());
  }

  /**
   * Split detected spans that are actually comma-separated lists.
   * E.g., "the OECD, the World Bank, and UNICEF" should be 3 spans, not 1.
   * @private
   */
  _splitListSpans(spans, originalText) {
    // The splitting is already handled in _consumeComplexDesignator
    // by breaking at ", the" patterns.
    // This method handles the special case of top-level list detection
    // where items are separated by ", " and joined by "and"

    // If no spans detected, try to detect individual items from a list pattern
    if (spans.length === 0) {
      return this._detectListItems(originalText);
    }

    return spans;
  }

  /**
   * Detect individual ComplexDesignator items from a comma-separated list.
   * Handles: "the OECD, the World Bank, and UNICEF"
   * @private
   */
  _detectListItems(text) {
    // Split on ", " and ", and " to find list items
    // Then check each item for capitalized sequences
    const items = [];

    // Pattern: items separated by ", " with optional "and " before last
    // Remove leading "the " from the whole text first
    const cleanText = text.replace(/^the\s+/i, '');

    // Split on list separators
    const parts = cleanText.split(/,\s*(?:and\s+)?|,\s+/);

    for (const part of parts) {
      const trimmed = part.replace(/^(?:the\s+|and\s+)/i, '').trim();
      if (!trimmed) continue;

      // Check if this part contains capitalized words
      const tokens = this._tokenize(trimmed);
      if (tokens.length > 0 && tokens.some(t => this._isCapitalizedOrAcronym(t))) {
        const span = this._consumeComplexDesignator(tokens, 0);
        if (span) {
          // Adjust positions relative to original text
          const idx = text.indexOf(trimmed);
          if (idx >= 0) {
            span.start = idx;
            span.end = idx + trimmed.length;
          }
          items.push(span);
        }
      }
    }

    return items;
  }
}



  // Make ComplexDesignatorDetector available globally for SemanticGraphBuilder
  _global.ComplexDesignatorDetector = ComplexDesignatorDetector;

  // ============================================================================
  // PHASE 9.3: COMBINED VALIDATION REPORT (~12KB)
  // ============================================================================

/**
 * CombinedValidationReport.js
 *
 * Phase 9.3: Unified validation report combining internal self-assessment
 * and external SHACL validation into a single diagnostic output.
 *
 * Aggregates:
 * - Internal: node coverage, parse metrics, complexity budget usage
 * - External: SHACL compliance score, pattern violations
 * - Phase 7: Certainty and source attribution summaries
 * - Ambiguity: ambiguity detection summary
 *
 * @module graph/CombinedValidationReport
 * @version 1.0.0
 */

/**
 * Recommendation thresholds
 */
const THRESHOLDS = {
  EXCELLENT: 0.90,
  GOOD: 0.75,
  ACCEPTABLE: 0.60,
  POOR: 0.40
};

/**
 * Weights for combined score calculation
 */
const SCORE_WEIGHTS = {
  shaclCompliance: 0.35,    // Ontological correctness is most important
  nodeCoverage: 0.25,       // How much of the input produced output
  budgetHealth: 0.15,       // Whether complexity stayed within bounds
  ambiguityClarity: 0.15,   // Low ambiguity = higher clarity
  completeness: 0.10        // Structural completeness (acts linked to agents, etc.)
};

class CombinedValidationReport {
  /**
   * Create a CombinedValidationReport
   * @param {Object} [options] - Configuration options
   * @param {Object} [options.weights] - Custom score weights
   * @param {boolean} [options.includeDetails=true] - Include detailed breakdowns
   */
  constructor(options = {}) {
    this.options = {
      includeDetails: options.includeDetails !== undefined ? options.includeDetails : true,
      weights: { ...SCORE_WEIGHTS, ...(options.weights || {}) }
    };

    this._sections = {};
    this._timestamp = new Date().toISOString();
  }

  /**
   * Generate a combined validation report from a build result and validators
   * @param {Object} params - Report generation parameters
   * @param {Object} params.graph - The built graph (from SemanticGraphBuilder.build())
   * @param {Object} [params.shaclResult] - Result from SHMLValidator.validate()
   * @param {Object} [params.budgetUsage] - Result from ComplexityBudget.getUsage()
   * @param {Object} [params.ambiguityReport] - AmbiguityReport instance or null
   * @param {string} [params.inputText] - Original input text
   * @returns {Object} Combined validation report
   */
  generate(params) {
    const { graph, shaclResult, budgetUsage, ambiguityReport, inputText } = params;

    const nodes = graph?.['@graph'] || graph?.nodes || [];
    const metadata = graph?._metadata || {};

    // Build each section
    const internal = this._buildInternalAssessment(nodes, metadata, inputText);
    const external = this._buildExternalAssessment(shaclResult);
    const budget = this._buildBudgetAssessment(budgetUsage);
    const ambiguity = this._buildAmbiguityAssessment(ambiguityReport);
    const phase7 = this._buildPhase7Summary(nodes);
    const completeness = this._buildCompletenessCheck(nodes);

    // Calculate combined score
    const combined = this._calculateCombinedScore({
      internal, external, budget, ambiguity, completeness
    });

    const report = {
      '@type': 'tagteam:CombinedValidationReport',
      'tagteam:timestamp': this._timestamp,
      'tagteam:version': '1.0.0',
      validation: {
        internal: {
          selfAssessmentScore: internal.score,
          nodeCount: internal.nodeCount,
          coverageRatio: internal.coverageRatio,
          entityCount: internal.entityCount,
          actCount: internal.actCount
        },
        external: {
          shaclValidationScore: external.score,
          compliancePercentage: external.compliancePercentage,
          violationCount: external.violationCount,
          warningCount: external.warningCount
        },
        budget: {
          withinBudget: budget.withinBudget,
          usagePercentage: budget.usagePercentage,
          truncated: budget.truncated
        },
        combined: {
          overallScore: combined.overallScore,
          grade: combined.grade,
          recommendation: combined.recommendation,
          breakdown: combined.breakdown
        }
      }
    };

    // Add optional detail sections
    if (this.options.includeDetails) {
      report.details = {};

      if (external.patternScores) {
        report.details.shaclPatterns = external.patternScores;
      }
      if (ambiguity.count > 0) {
        report.details.ambiguity = {
          count: ambiguity.count,
          hasCritical: ambiguity.hasCritical,
          byType: ambiguity.byType
        };
      }
      if (phase7.hasCertainty || phase7.hasAttribution) {
        report.details.phase7 = phase7;
      }
      if (completeness.issues.length > 0) {
        report.details.completeness = completeness.issues;
      }
    }

    return report;
  }

  /**
   * Build internal self-assessment metrics
   * @private
   */
  _buildInternalAssessment(nodes, metadata, inputText) {
    const nodesArray = Array.isArray(nodes) ? nodes : [];

    // Count node types
    const entityCount = nodesArray.filter(n => {
      const types = n['@type'] || [];
      return types.includes('tagteam:DiscourseReferent');
    }).length;

    const actCount = nodesArray.filter(n => {
      const types = n['@type'] || [];
      return types.some(t => t.startsWith('ActOf') || t === 'IntentionalAct');
    }).length;

    const roleCount = nodesArray.filter(n => {
      const types = n['@type'] || [];
      return types.some(t => t.includes('Role'));
    }).length;

    // Coverage: ratio of nodes to input length (heuristic)
    const inputLength = inputText?.length || metadata.inputLength || 0;
    const expectedNodes = Math.max(1, Math.floor(inputLength / 20)); // ~1 node per 20 chars
    const coverageRatio = Math.min(1.0, nodesArray.length / expectedNodes);

    // Score: weighted combination of coverage and structural richness
    const hasEntities = entityCount > 0 ? 1 : 0;
    const hasActs = actCount > 0 ? 1 : 0;
    const hasRoles = roleCount > 0 ? 1 : 0;
    const structuralScore = (hasEntities * 0.4 + hasActs * 0.4 + hasRoles * 0.2);
    const score = Math.round((coverageRatio * 0.5 + structuralScore * 0.5) * 100) / 100;

    return {
      score,
      nodeCount: nodesArray.length,
      entityCount,
      actCount,
      roleCount,
      coverageRatio: Math.round(coverageRatio * 100) / 100,
      inputLength
    };
  }

  /**
   * Build external SHACL validation assessment
   * @private
   */
  _buildExternalAssessment(shaclResult) {
    if (!shaclResult) {
      return {
        score: null,
        compliancePercentage: null,
        violationCount: 0,
        warningCount: 0,
        patternScores: null,
        available: false
      };
    }

    const compliancePercentage = shaclResult.complianceScore || 0;
    const score = Math.round(compliancePercentage) / 100;

    // Extract pattern-level scores
    const patternScores = {};
    if (shaclResult.patterns) {
      for (const [name, data] of Object.entries(shaclResult.patterns)) {
        patternScores[name] = {
          passed: data.passed,
          total: data.total,
          score: data.score
        };
      }
    }

    return {
      score,
      compliancePercentage,
      violationCount: shaclResult.violations?.length || 0,
      warningCount: shaclResult.warnings?.length || 0,
      patternScores: Object.keys(patternScores).length > 0 ? patternScores : null,
      available: true
    };
  }

  /**
   * Build complexity budget assessment
   * @private
   */
  _buildBudgetAssessment(budgetUsage) {
    if (!budgetUsage) {
      return {
        withinBudget: true,
        usagePercentage: 0,
        truncated: false,
        score: 1.0,
        available: false
      };
    }

    const nodeUsage = budgetUsage.nodes?.percentage || 0;
    const truncated = budgetUsage.truncated || false;
    const exceeded = budgetUsage.exceeded || false;

    // Budget health score: 1.0 if well within budget, decreases as usage grows
    let score = 1.0;
    if (exceeded) {
      score = 0.3;
    } else if (truncated) {
      score = 0.5;
    } else if (nodeUsage > 80) {
      score = 0.7;
    } else if (nodeUsage > 60) {
      score = 0.85;
    }

    return {
      withinBudget: !exceeded,
      usagePercentage: Math.round(nodeUsage),
      truncated,
      score,
      available: true
    };
  }

  /**
   * Build ambiguity assessment
   * @private
   */
  _buildAmbiguityAssessment(ambiguityReport) {
    if (!ambiguityReport || !ambiguityReport.hasAmbiguities || !ambiguityReport.hasAmbiguities()) {
      return {
        count: 0,
        hasCritical: false,
        score: 1.0, // No ambiguity = perfect clarity
        byType: {},
        available: !!ambiguityReport
      };
    }

    const count = ambiguityReport.count || 0;
    const hasCritical = ambiguityReport.hasCriticalAmbiguities?.() || false;

    // Clarity score: decreases with more ambiguities
    let score = 1.0;
    if (hasCritical) {
      score = 0.4;
    } else if (count > 5) {
      score = 0.6;
    } else if (count > 2) {
      score = 0.75;
    } else if (count > 0) {
      score = 0.85;
    }

    const byType = ambiguityReport.statistics?.byType || {};

    return {
      count,
      hasCritical,
      score,
      byType,
      available: true
    };
  }

  /**
   * Build Phase 7 summary (certainty + attribution)
   * @private
   */
  _buildPhase7Summary(nodes) {
    const nodesArray = Array.isArray(nodes) ? nodes : [];

    // Certainty markers
    const hedgedNodes = nodesArray.filter(n => n['tagteam:isHedged'] === true);
    const boostedNodes = nodesArray.filter(n => n['tagteam:isBoosted'] === true);
    const evidentialNodes = nodesArray.filter(n => n['tagteam:isEvidential'] === true);
    const hasCertainty = hedgedNodes.length > 0 || boostedNodes.length > 0 || evidentialNodes.length > 0;

    // Source attributions
    const attributionNodes = nodesArray.filter(n => {
      const types = n['@type'] || [];
      return types.includes('tagteam:SourceAttribution');
    });
    const hasAttribution = attributionNodes.length > 0;

    return {
      hasCertainty,
      certainty: {
        hedgedCount: hedgedNodes.length,
        boostedCount: boostedNodes.length,
        evidentialCount: evidentialNodes.length
      },
      hasAttribution,
      attribution: {
        count: attributionNodes.length,
        types: [...new Set(attributionNodes.map(n => n['tagteam:attributionType']).filter(Boolean))]
      }
    };
  }

  /**
   * Build structural completeness check
   * @private
   */
  _buildCompletenessCheck(nodes) {
    const nodesArray = Array.isArray(nodes) ? nodes : [];
    const issues = [];

    // Check: Acts should have agents
    const acts = nodesArray.filter(n => {
      const types = n['@type'] || [];
      return types.some(t => t.startsWith('ActOf') || t === 'IntentionalAct');
    });
    const actsWithoutAgent = acts.filter(a => !a['has_agent']);
    if (actsWithoutAgent.length > 0) {
      issues.push({
        type: 'missing_agent',
        count: actsWithoutAgent.length,
        message: `${actsWithoutAgent.length} act(s) without agent`
      });
    }

    // Check: Entities should have denotesType
    const entities = nodesArray.filter(n => {
      const types = n['@type'] || [];
      return types.includes('tagteam:DiscourseReferent');
    });
    const entitiesWithoutType = entities.filter(e => !e['tagteam:denotesType']);
    if (entitiesWithoutType.length > 0) {
      issues.push({
        type: 'missing_denotes_type',
        count: entitiesWithoutType.length,
        message: `${entitiesWithoutType.length} entity(ies) without denotesType`
      });
    }

    // Check: IBE node should exist
    const hasIBE = nodesArray.some(n => {
      const types = n['@type'] || [];
      return types.includes('InformationBearingEntity');
    });
    if (!hasIBE && nodesArray.length > 0) {
      issues.push({
        type: 'missing_ibe',
        count: 1,
        message: 'No InformationBearingEntity node (staircase root)'
      });
    }

    // Completeness score
    const totalChecks = 3;
    const passedChecks = totalChecks - issues.length;
    const score = totalChecks > 0 ? passedChecks / totalChecks : 1.0;

    return {
      score: Math.round(score * 100) / 100,
      issues,
      checksRun: totalChecks,
      checksPassed: passedChecks
    };
  }

  /**
   * Calculate combined overall score
   * @private
   */
  _calculateCombinedScore(sections) {
    const weights = this.options.weights;
    let totalWeight = 0;
    let weightedSum = 0;

    // SHACL compliance
    if (sections.external.available && sections.external.score !== null) {
      weightedSum += sections.external.score * weights.shaclCompliance;
      totalWeight += weights.shaclCompliance;
    }

    // Node coverage
    weightedSum += sections.internal.score * weights.nodeCoverage;
    totalWeight += weights.nodeCoverage;

    // Budget health
    if (sections.budget.available) {
      weightedSum += sections.budget.score * weights.budgetHealth;
      totalWeight += weights.budgetHealth;
    }

    // Ambiguity clarity
    if (sections.ambiguity.available) {
      weightedSum += sections.ambiguity.score * weights.ambiguityClarity;
      totalWeight += weights.ambiguityClarity;
    }

    // Completeness
    weightedSum += sections.completeness.score * weights.completeness;
    totalWeight += weights.completeness;

    // Normalize
    const overallScore = totalWeight > 0
      ? Math.round((weightedSum / totalWeight) * 100) / 100
      : 0;

    // Grade and recommendation
    const grade = this._getGrade(overallScore);
    const recommendation = this._getRecommendation(overallScore, sections);

    // Breakdown
    const breakdown = {
      shaclCompliance: sections.external.available ? sections.external.score : null,
      nodeCoverage: sections.internal.score,
      budgetHealth: sections.budget.available ? sections.budget.score : null,
      ambiguityClarity: sections.ambiguity.available ? sections.ambiguity.score : null,
      completeness: sections.completeness.score
    };

    return { overallScore, grade, recommendation, breakdown };
  }

  /**
   * Get letter grade from score
   * @private
   */
  _getGrade(score) {
    if (score >= THRESHOLDS.EXCELLENT) return 'A';
    if (score >= THRESHOLDS.GOOD) return 'B';
    if (score >= THRESHOLDS.ACCEPTABLE) return 'C';
    if (score >= THRESHOLDS.POOR) return 'D';
    return 'F';
  }

  /**
   * Generate recommendation text based on score and sections
   * @private
   */
  _getRecommendation(score, sections) {
    if (score >= THRESHOLDS.EXCELLENT) {
      return 'Graph is well-formed with high ontological compliance. Ready for downstream consumption.';
    }

    const issues = [];

    if (sections.external.available && sections.external.score < 0.75) {
      issues.push('SHACL compliance is low — review ontological patterns');
    }
    if (sections.internal.coverageRatio < 0.5) {
      issues.push('Low node coverage — input may contain unsupported constructions');
    }
    if (sections.budget.truncated) {
      issues.push('Input was truncated due to complexity budget — consider chunking');
    }
    if (sections.ambiguity.hasCritical) {
      issues.push('Critical ambiguities detected — manual review recommended');
    }
    if (sections.completeness.score < 0.7) {
      issues.push('Structural gaps found — some acts lack agents or entities lack types');
    }

    if (issues.length === 0) {
      return 'Graph quality is acceptable. Minor improvements possible.';
    }

    return issues.join('. ') + '.';
  }

  /**
   * Format the report as a human-readable string
   * @param {Object} report - Report from generate()
   * @returns {string} Formatted report
   */
  format(report) {
    const v = report.validation;
    const lines = [];

    lines.push('=== TagTeam Combined Validation Report ===');
    lines.push(`Timestamp: ${report['tagteam:timestamp']}`);
    lines.push('');

    // Combined score
    lines.push(`Overall Score: ${v.combined.overallScore} (Grade: ${v.combined.grade})`);
    lines.push(`Recommendation: ${v.combined.recommendation}`);
    lines.push('');

    // Internal
    lines.push('--- Internal Self-Assessment ---');
    lines.push(`  Score: ${v.internal.selfAssessmentScore}`);
    lines.push(`  Nodes: ${v.internal.nodeCount} | Entities: ${v.internal.entityCount} | Acts: ${v.internal.actCount}`);
    lines.push(`  Coverage: ${v.internal.coverageRatio}`);
    lines.push('');

    // External
    lines.push('--- External SHACL Validation ---');
    if (v.external.shaclValidationScore !== null) {
      lines.push(`  Compliance: ${v.external.compliancePercentage}%`);
      lines.push(`  Violations: ${v.external.violationCount} | Warnings: ${v.external.warningCount}`);
    } else {
      lines.push('  Not available (SHACL validator not run)');
    }
    lines.push('');

    // Budget
    lines.push('--- Complexity Budget ---');
    lines.push(`  Within budget: ${v.budget.withinBudget}`);
    lines.push(`  Usage: ${v.budget.usagePercentage}%`);
    if (v.budget.truncated) {
      lines.push('  WARNING: Input was truncated');
    }
    lines.push('');

    // Score breakdown
    lines.push('--- Score Breakdown ---');
    const bd = v.combined.breakdown;
    if (bd.shaclCompliance !== null) lines.push(`  SHACL Compliance: ${bd.shaclCompliance}`);
    lines.push(`  Node Coverage:    ${bd.nodeCoverage}`);
    if (bd.budgetHealth !== null) lines.push(`  Budget Health:    ${bd.budgetHealth}`);
    if (bd.ambiguityClarity !== null) lines.push(`  Ambiguity Clarity: ${bd.ambiguityClarity}`);
    lines.push(`  Completeness:     ${bd.completeness}`);

    return lines.join('\n');
  }

  /**
   * Get threshold constants
   * @returns {Object} Threshold values
   */
  static getThresholds() {
    return { ...THRESHOLDS };
  }

  /**
   * Get default score weights
   * @returns {Object} Default weights
   */
  static getDefaultWeights() {
    return { ...SCORE_WEIGHTS };
  }
}



