/**
 * Input Validator
 *
 * Validates and sanitizes input text before semantic processing.
 * Hard limits (length, null bytes) block processing.
 * All text is NFKC-normalized to prevent Unicode-based attacks.
 *
 * @module security/input-validator
 */

const INPUT_LIMITS = {
  MAX_TEXT_LENGTH: 100000,
  MAX_SENTENCE_LENGTH: 5000,
};

/**
 * Validate input text for security constraints.
 *
 * @param {string} text - Raw input text
 * @returns {{ valid: boolean, normalized: string|null, issues: Array<{severity: string, confidence: string, code: string}> }}
 */
function validateInput(text) {
  const issues = [];

  // Empty/null/undefined check
  if (text == null || (typeof text === 'string' && text.length === 0)) {
    issues.push({
      severity: 'error',
      confidence: 'deterministic',
      code: 'EMPTY_INPUT'
    });
    return { valid: false, normalized: null, issues };
  }

  if (typeof text !== 'string') {
    issues.push({
      severity: 'error',
      confidence: 'deterministic',
      code: 'INVALID_TYPE'
    });
    return { valid: false, normalized: null, issues };
  }

  // Hard limit: text length
  if (text.length > INPUT_LIMITS.MAX_TEXT_LENGTH) {
    issues.push({
      severity: 'error',
      confidence: 'deterministic',
      code: 'INPUT_TOO_LONG'
    });
  }

  // Hard limit: null bytes
  if (/\x00/.test(text)) {
    issues.push({
      severity: 'error',
      confidence: 'deterministic',
      code: 'NULL_BYTE'
    });
  }

  const valid = !issues.some(i => i.severity === 'error');

  return {
    valid,
    normalized: text.normalize('NFKC'),
    issues
  };
}



/**
 * Semantic Security Validators
 *
 * Heuristic detectors for semantic manipulation patterns (T3-T6).
 * These flag suspicious input for human review — they are NOT guarantees.
 *
 * @module security/semantic-validators
 */

class SemanticSecurityValidator {

  /**
   * T3: Entity boundary manipulation — high connector density.
   * @param {string} text
   * @returns {Array<{code: string, confidence: string, recommendation: string}>}
   */
  checkEntityBoundaries(text) {
    const words = text.split(/\s+/);
    const connectors = (text.match(/\b(and|or|of|for)\b/gi) || []).length;
    const density = connectors / words.length;

    if (density > 0.15) {
      return [{
        code: 'HIGH_CONNECTOR_DENSITY',
        confidence: 'heuristic',
        recommendation: 'Review entity boundaries'
      }];
    }
    return [];
  }

  /**
   * T4: Actuality status manipulation — hypothetical framing of factual verbs.
   * @param {string} text
   * @returns {Array<{code: string, confidence: string, recommendation: string}>}
   */
  checkActualityMarkers(text) {
    if (/hypothetically[,\s]+[\w\s]+(?:did|committed)/gi.test(text)) {
      return [{
        code: 'ACTUALITY_CONFUSION',
        confidence: 'heuristic',
        recommendation: 'Verify actuality assignments'
      }];
    }
    return [];
  }

  /**
   * T5: Negation obfuscation — buried or indirect negation.
   * @param {string} text
   * @returns {Array<{code: string, confidence: string, recommendation: string}>}
   */
  checkNegationPatterns(text) {
    if (/was\s+\w+\s+in\s+no\s+/gi.test(text) || /absence\s+of\s+/gi.test(text)) {
      return [{
        code: 'BURIED_NEGATION',
        confidence: 'heuristic',
        recommendation: 'Verify polarity assignments'
      }];
    }
    return [];
  }

  /**
   * T6: Salience inflation — excessive emphasis words.
   * @param {string} text
   * @returns {Array<{code: string, confidence: string, count?: number, recommendation: string}>}
   */
  checkSalienceMarkers(text) {
    const count = (text.match(/\b(primary|essential|crucial|critical|key|fundamental)\b/gi) || []).length;
    if (count > 5) {
      return [{
        code: 'EXCESSIVE_EMPHASIS',
        confidence: 'heuristic',
        count,
        recommendation: 'Review salience scores'
      }];
    }
    return [];
  }

  /**
   * Run all heuristic checks on input text.
   * @param {string} text
   * @returns {{ warnings: Array, disclaimer: string }}
   */
  validate(text) {
    return {
      warnings: [
        ...this.checkEntityBoundaries(text),
        ...this.checkActualityMarkers(text),
        ...this.checkNegationPatterns(text),
        ...this.checkSalienceMarkers(text),
      ],
      disclaimer: 'Heuristic checks only. Does not guarantee attack prevention.'
    };
  }
}



/**
 * Output Sanitizer with Provenance
 *
 * Strips unexpected properties from ICE output and attaches
 * provenance metadata so downstream systems can reason about trust.
 *
 * @module security/output-sanitizer
 */

const ALLOWED = [
  'id', 'type', 'label', 'fullName', 'nameComponents',
  'denotedType', 'candidateType', 'expression',
  'assertedRelation', 'subject', 'objects',
  'verbPhrase', 'agent', 'patient',
  'actualityStatus', 'normativeStatus', 'salience',
  'denotationConfidence', 'sourceSpan', 'evidence'
];

/**
 * Escape HTML special characters to prevent XSS (AC-4.8).
 * @param {string} str
 * @returns {string}
 */
function escapeHtml(str) {
  if (typeof str !== 'string') return str;
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

/**
 * Strip an ICE object to only allowed properties.
 * String values are HTML-escaped to prevent XSS.
 * @param {Object} ice
 * @returns {Object}
 */
function sanitize(ice) {
  const result = {};
  for (const prop of ALLOWED) {
    if (ice[prop] !== undefined) {
      result[prop] = typeof ice[prop] === 'string' ? escapeHtml(ice[prop]) : ice[prop];
    }
  }
  return result;
}

/**
 * Sanitize ICEs and attach provenance metadata.
 * @param {Array<Object>} ices
 * @param {{ ontologyHash: string, warnings: Array<{code: string}> }} context
 * @returns {Array<Object>}
 */
function sanitizeWithProvenance(ices, context) {
  return ices.map(ice => ({
    ...sanitize(ice),
    provenance: {
      tagteamVersion: '3.0.0',
      ontologyHash: context.ontologyHash,
      inputValidated: true,
      securityWarnings: context.warnings.map(w => w.code),
      timestamp: new Date().toISOString()
    }
  }));
}



/**
 * Security Audit Logger
 *
 * Emits structured JSON log events for security-relevant actions.
 * Downstream systems (SIEM, log aggregators) can parse and alert on these.
 *
 * @module security/audit-logger
 */

class SecurityAuditLogger {
  log(event) {
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      service: 'tagteam',
      ...event
    }));
  }

  ontologyFailure(details) {
    this.log({
      event: 'ONTOLOGY_INTEGRITY_FAILED',
      severity: 'critical',
      file: details.file,
      expected: details.expected,
      actual: details.actual,
      approver: details.approver,
      action: 'PARSING_HALTED'
    });
  }

  inputValidationWarning(details) {
    this.log({
      event: 'INPUT_VALIDATION_WARNING',
      severity: 'warning',
      code: details.code,
      text: details.text
    });
  }
}



