/**
 * EntityExtractor class - extracts entities and creates DiscourseReferent nodes
 *
 * Two-Tier Architecture:
 * - Creates Tier 1 DiscourseReferent nodes from text
 * - Optionally creates Tier 2 Person/Artifact entities via RealWorldEntityFactory
 * - Links Tier 1 → Tier 2 via cco:is_about
 */
class EntityExtractor {
  /**
   * Create a new EntityExtractor
   * @param {Object} options - Configuration options
   * @param {Object} [options.graphBuilder] - SemanticGraphBuilder instance for IRI generation
   * @param {boolean} [options.createTier2=true] - Whether to create Tier 2 entities
   * @param {string} [options.documentIRI] - Document IRI for Tier 2 scoping
   */
  constructor(options = {}) {
    this.options = {
      createTier2: true,
      ...options
    };
    this.graphBuilder = options.graphBuilder || null;

    // Initialize RealWorldEntityFactory for Tier 2 creation
    this.tier2Factory = new RealWorldEntityFactory({
      graphBuilder: this.graphBuilder,
      documentIRI: options.documentIRI,
      lemmatizer: options.lemmatizer
    });
  }

  /**
   * Extract entities from text and return DiscourseReferent nodes
   *
   * Two-Tier Architecture (v2.2):
   * - Creates Tier 1 DiscourseReferent nodes
   * - Creates Tier 2 Person/Artifact entities (if createTier2 enabled)
   * - Links Tier 1 → Tier 2 via cco:is_about
   *
   * @param {string} text - Input text to analyze
   * @param {Object} [options] - Extraction options
   * @param {boolean} [options.createTier2] - Override Tier 2 creation setting
   * @param {string} [options.documentIRI] - Document IRI for Tier 2 scoping
   * @returns {Array<Object>} Array of nodes (Tier 1 referents + Tier 2 entities)
   *
   * @example
   * const extractor = new EntityExtractor();
   * const entities = extractor.extract("The doctor treats the patient");
   * // Returns array of DiscourseReferent nodes + Person nodes
   */
  extract(text, options = {}) {
    const tier1Entities = [];

    // Update Tier 2 factory document IRI if provided
    if (options.documentIRI) {
      this.tier2Factory.setDocumentIRI(options.documentIRI);
    }

    // V7-012 Phase 1: Use custom NPChunker instead of Compromise
    // Feature flag: options.useNPChunker (default: true for Phase 1 testing)
    const useNPChunker = options.useNPChunker !== false;

    if (useNPChunker) {
      // NEW: Custom NP chunking with jsPOS
      return this._extractWithNPChunker(text, options, tier1Entities);
    }

    // FALLBACK: Original Compromise-based extraction
    // Parse with Compromise NLP
    const doc = nlp(text);

    // Extract nouns with their context
    const nouns = doc.nouns();

    nouns.forEach((noun, index) => {
      let nounText = noun.text();
      const nounJson = noun.json()[0] || {};
      const nounData = nounJson.noun || {};

      // V7-003: Trim trailing verbs from noun phrases to prevent absorption of verbs
      // e.g., "the system restarts" → "the system"
      nounText = this._trimTrailingVerbs(nounText);

      // Skip if trimming removed everything
      if (!nounText || nounText.trim().length === 0) {
        return;
      }

      // Get the root noun (without determiner/adjectives)
      const rootNoun = nounData.root || nounText;

      // Skip non-entity nouns (like "here", "there", etc.)
      if (this._isNonEntityNoun(rootNoun)) {
        return;
      }

      // V7-011: Detect possessive NP ("X's Y") and extract possessor as separate entity
      // Cambridge Grammar §5.4: Possessive constructions have both possessor and possessed
      const possessive = this._detectPossessiveNP(nounText, text);
      if (possessive.isPossessive) {
        // Extract possessor as separate entity ("the admin" from "the admin's credentials")
        const possessorOffset = this._getSpanOffset(text, possessive.possessor, 0);
        const possessorDoc = nlp(possessive.possessor);
        const possessorNounData = possessorDoc.nouns().json()[0]?.noun || {};
        const possessorRootNoun = possessorNounData.root || possessive.possessor;

        if (!this._isNonEntityNoun(possessorRootNoun)) {
          const possessorEntity = this._createEntityFromText(
            possessive.possessor,
            possessorRootNoun,
            possessorOffset,
            text,
            possessorDoc.nouns().first(),
            possessorNounData
          );
          possessorEntity['tagteam:isPossessor'] = true;
          tier1Entities.push(possessorEntity);
        }
        // Continue to extract full possessive phrase as well
      }

      // V7-011: Detect PP modifier ("X in Y") and extract PP object as separate entity
      // Cambridge Grammar §7.2: PP attachment creates hierarchical structure
      const ppModifier = this._detectPPModifier(nounText, text);
      if (ppModifier.hasPP) {
        // Extract PP object as separate entity ("the datacenter" from "the server in the datacenter")
        const ppObjectOffset = this._getSpanOffset(text, ppModifier.ppObject, 0);
        const ppObjectDoc = nlp(ppModifier.ppObject);
        const ppObjectNounData = ppObjectDoc.nouns().json()[0]?.noun || {};
        const ppObjectRootNoun = ppObjectNounData.root || ppModifier.ppObject;

        if (!this._isNonEntityNoun(ppObjectRootNoun)) {
          const ppObjectEntity = this._createEntityFromText(
            ppModifier.ppObject,
            ppObjectRootNoun,
            ppObjectOffset,
            text,
            ppObjectDoc.nouns().first(),
            ppObjectNounData
          );
          ppObjectEntity['tagteam:isPPObject'] = true;
          ppObjectEntity['tagteam:preposition'] = ppModifier.preposition;
          tier1Entities.push(ppObjectEntity);
        }
        // Continue to extract full phrase with PP as well
      }

      // V7-010: Detect and split coordinated noun phrases ("X and Y")
      // Penn Treebank coordination rules: NP conjunction creates separate entities
      const coordination = this._detectCoordination(nounText, text);
      if (coordination.isCoordinated) {
        // Process each conjunct as a separate entity
        coordination.conjuncts.forEach((conjunctText, conjunctIndex) => {
          const conjunctOffset = this._getSpanOffset(text, conjunctText, 0);

          // Extract root noun for conjunct
          const conjunctDoc = nlp(conjunctText);
          const conjunctNounData = conjunctDoc.nouns().json()[0]?.noun || {};
          const conjunctRootNoun = conjunctNounData.root || conjunctText;

          // Skip non-entity nouns
          if (this._isNonEntityNoun(conjunctRootNoun)) {
            return;
          }

          // Detect properties for this conjunct
          const introducingPrep = this._detectIntroducingPreposition(text, conjunctOffset);
          const defInfo = this._detectDefiniteness(nlp(conjunctText).nouns().first(), conjunctText, text, conjunctNounData);
          const scarcityInfo = this._detectScarcity(conjunctText, text, conjunctOffset, conjunctNounData);
          const quantityInfo = this._detectQuantity(conjunctText, text, conjunctOffset, conjunctNounData);

          const fullWords = conjunctText.toLowerCase().trim().split(/\s+/);
          const temporalType = this._checkForTemporalType(conjunctText.toLowerCase().trim(), fullWords);
          const symptomType = !temporalType
            ? this._checkForSymptomType(conjunctText.toLowerCase().trim(), conjunctRootNoun.toLowerCase().trim())
            : null;

          let entityType = temporalType || symptomType || this._determineEntityType(conjunctRootNoun, {
            fullText: text,
            definitenessInfo: defInfo
          });

          let typeRefinedBy = null;
          if (!temporalType && !symptomType) {
            const verbRefinement = this._refineTypeByVerbContext(conjunctRootNoun, text, conjunctOffset);
            if (verbRefinement.refinedType) {
              entityType = verbRefinement.refinedType;
              typeRefinedBy = verbRefinement.governingVerb;
            }
          }

          const temporalUnit = temporalType ? this._extractTemporalUnit(conjunctText) : null;
          const referentialStatus = this._determineReferentialStatus(defInfo, conjunctText, text, index);

          // Create separate entity for this conjunct
          const conjunctReferent = this._createDiscourseReferent({
            text: conjunctText,
            rootNoun: conjunctRootNoun,
            offset: conjunctOffset,
            entityType,
            definiteness: defInfo.definiteness,
            referentialStatus,
            scarcity: scarcityInfo,
            quantity: quantityInfo,
            temporalUnit: temporalUnit,
            typeRefinedBy: typeRefinedBy,
            introducingPreposition: introducingPrep
          });

          // Mark as part of coordination
          conjunctReferent['tagteam:isConjunct'] = true;
          conjunctReferent['tagteam:coordinationType'] = coordination.type;

          tier1Entities.push(conjunctReferent);
        });

        // Skip normal processing since we handled coordination
        return;
      }

      // Get span offset
      const offset = this._getSpanOffset(text, nounText, index);

      // ENH-015: Detect introducing preposition (for role assignment)
      const introducingPreposition = this._detectIntroducingPreposition(text, offset);

      // Use Compromise data for definiteness detection
      const definitenessInfo = this._detectDefiniteness(noun, nounText, text, nounData);

      // Detect scarcity from adjectives and context
      const scarcityInfo = this._detectScarcity(nounText, text, offset, nounData);

      // Detect quantity from Compromise and context
      const quantityInfo = this._detectQuantity(nounText, text, offset, nounData);

      // Check for temporal type using full noun phrase (needs quantity + unit together)
      const fullWords = nounText.toLowerCase().trim().split(/\s+/);
      const temporalType = this._checkForTemporalType(nounText.toLowerCase().trim(), fullWords);

      // V7-011c: Extract syntactic head noun for accurate type classification
      // For complex NPs (possessives, PP modifiers), Compromise's rootNoun is unreliable
      const headNoun = this._extractHeadNoun(nounText, rootNoun);

      // Check for symptom/quality type using full noun phrase AND head noun
      const symptomType = !temporalType
        ? this._checkForSymptomType(nounText.toLowerCase().trim(), headNoun)
        : null;

      // Determine entity type: temporal > symptom > standard matching
      // V7-011c: Use headNoun instead of rootNoun for accurate type classification
      let entityType = temporalType || symptomType || this._determineEntityType(headNoun, {
        fullText: text,
        definitenessInfo: definitenessInfo
      });

      // ENH-001: Verb-context refinement for ambiguous nouns
      // If the noun is ambiguous and governed by a cognitive/physical verb, refine type
      // V7-011c: Use headNoun for accurate refinement
      let typeRefinedBy = null;
      if (!temporalType && !symptomType) {
        const verbRefinement = this._refineTypeByVerbContext(headNoun, text, offset);
        if (verbRefinement.refinedType) {
          entityType = verbRefinement.refinedType;
          typeRefinedBy = verbRefinement.governingVerb;
        }
      }

      // Extract temporal unit if this is a temporal entity
      const temporalUnit = temporalType ? this._extractTemporalUnit(nounText) : null;

      // Determine referential status
      const referentialStatus = this._determineReferentialStatus(
        definitenessInfo,
        nounText,
        text,
        index
      );

      // Create DiscourseReferent node (use full noun phrase as label)
      const referent = this._createDiscourseReferent({
        text: nounText,
        rootNoun: rootNoun,
        offset,
        entityType,
        definiteness: definitenessInfo.definiteness,
        referentialStatus,
        scarcity: scarcityInfo,
        quantity: quantityInfo,
        temporalUnit: temporalUnit,
        typeRefinedBy: typeRefinedBy,  // ENH-001: record refining verb
        introducingPreposition: introducingPreposition  // ENH-015: preposition for role mapping
      });

      tier1Entities.push(referent);
    });

    // V7-007: Extract proper names using Compromise's specialized methods
    // This handles person names, organizations, and places more reliably than
    // capitalization heuristics, especially for sentence-initial names.
    this._extractProperNames(doc, text, tier1Entities);

    // V7-010: Extract pronouns (especially reflexives for Binding Theory)
    // Reflexive pronouns need to be extracted as entities for role assignment
    this._extractPronouns(doc, text, tier1Entities);

    // v2 Phase 0: Wh-word pseudo-entity extraction
    // Scans for Wh-words that Compromise NLP does not recognize as nouns.
    // Handles both standalone Wh-words ("who", "what") and Wh + noun phrases ("which report").
    // V7-004: Skip relativizers (who/whom/which/that after NPs) - they're not entities
    if (options.v2WhEntities !== false) {
      const words = text.toLowerCase().split(/\s+/);
      const relativizers = new Set(['who', 'whom', 'whose', 'which', 'that']);

      for (let i = 0; i < words.length; i++) {
        const cleanWord = words[i].replace(/[^a-z]/g, '');
        const whEntry = WH_PSEUDO_ENTITIES[cleanWord];
        if (!whEntry) continue;

        // V7-004: Skip if this is a relativizer (follows a noun phrase)
        // e.g., "The engineer who..." - "who" follows NP, so it's a relativizer, not interrogative
        if (relativizers.has(cleanWord) && this._isRelativizerContext(tier1Entities, text, i, words)) {
          continue;
        }

        // Build the full Wh-phrase: for "which", include the following noun
        let whPhraseText = words[i];
        let whPhraseType = whEntry.type;
        const rawOffset = text.toLowerCase().indexOf(words[i], i > 0 ? text.toLowerCase().indexOf(words[i - 1]) + words[i - 1].length : 0);

        if (cleanWord === 'which' && i + 1 < words.length) {
          // "which report" — include the head noun
          whPhraseText = words[i] + ' ' + words[i + 1];
        }

        // Check if this Wh-word is already captured by an existing entity
        const alreadyCaptured = tier1Entities.some(e => {
          const eText = (e['rdfs:label'] || '').toLowerCase();
          return eText.includes(cleanWord);
        });
        if (alreadyCaptured) continue;

        // Create DiscourseReferent for Wh-pseudo-entity
        const offset = rawOffset >= 0 ? rawOffset : 0;
        const referent = this._createDiscourseReferent({
          text: whPhraseText,
          rootNoun: cleanWord,
          offset,
          entityType: whPhraseType,
          definiteness: whEntry.definiteness,
          referentialStatus: 'interrogative',
          scarcity: { isScarce: false },
          quantity: { quantity: null },
          temporalUnit: null,
          typeRefinedBy: null,
          introducingPreposition: null
        });

        tier1Entities.push(referent);
      }
    }

    // Create Tier 2 entities and link via is_about (Two-Tier Architecture)
    const shouldCreateTier2 = options.createTier2 !== undefined
      ? options.createTier2
      : this.options.createTier2;

    if (shouldCreateTier2 && tier1Entities.length > 0) {
      const { tier2Entities, linkMap } = this.tier2Factory.createFromReferents(
        tier1Entities,
        { documentIRI: options.documentIRI }
      );

      // Add is_about links to Tier 1 referents
      const linkedReferents = this.tier2Factory.linkReferentsToTier2(tier1Entities, linkMap);

      // Return both Tier 1 (with is_about) and Tier 2 entities
      return [...linkedReferents, ...tier2Entities];
    }

    return tier1Entities;
  }

  /**
   * V7-007: Extract proper names using Compromise NLP's specialized methods.
   *
   * This handles person names, organizations, and places that may not be
   * detected as regular nouns, especially sentence-initial proper names where
   * capitalization doesn't distinguish "The server" from "John".
   *
   * @param {Object} doc - Compromise NLP document
   * @param {string} text - Full input text
   * @param {Array} tier1Entities - Array to add entities to (modified in place)
   */
  _extractProperNames(doc, text, tier1Entities) {
    // Extract person names
    const people = doc.people();
    people.forEach((person, index) => {
      const personText = person.text();

      // Skip if already extracted as noun
      const alreadyExtracted = tier1Entities.some(e => {
        const label = (e['rdfs:label'] || '').toLowerCase();
        return label === personText.toLowerCase() || label.includes(personText.toLowerCase());
      });
      if (alreadyExtracted) return;

      const offset = this._getSpanOffset(text, personText, index);

      const referent = this._createDiscourseReferent({
        text: personText,
        rootNoun: personText,
        offset,
        entityType: 'Person',
        definiteness: 'definite',  // Proper names are inherently definite
        referentialStatus: 'introduced',
        scarcity: { isScarce: false },
        quantity: { quantity: null },
        temporalUnit: null,
        typeRefinedBy: null,
        introducingPreposition: null
      });

      tier1Entities.push(referent);
    });

    // Extract organizations
    const orgs = doc.organizations();
    orgs.forEach((org, index) => {
      const orgText = org.text();

      // Check if already extracted by NPChunker
      const existingEntity = tier1Entities.find(e => {
        const label = (e['rdfs:label'] || '').toLowerCase();
        return label === orgText.toLowerCase();
      });

      if (existingEntity) {
        // Update type if it was extracted by NPChunker with default type
        if (existingEntity['tagteam:denotesType'] === 'MaterialEntity') {
          existingEntity['tagteam:denotesType'] = 'Organization';
          // Also update @type array
          const typeIndex = existingEntity['@type'].indexOf('MaterialEntity');
          if (typeIndex !== -1) {
            existingEntity['@type'][typeIndex] = 'Organization';
          }
        }
        return;
      }

      const offset = this._getSpanOffset(text, orgText, index);

      const referent = this._createDiscourseReferent({
        text: orgText,
        rootNoun: orgText,
        offset,
        entityType: 'Organization',
        definiteness: 'definite',
        referentialStatus: 'introduced',
        scarcity: { isScarce: false },
        quantity: { quantity: null },
        temporalUnit: null,
        typeRefinedBy: null,
        introducingPreposition: null
      });

      tier1Entities.push(referent);
    });

    // Extract places
    const places = doc.places();
    places.forEach((place, index) => {
      const placeText = place.text();

      // Check if already extracted by NPChunker
      const existingEntity = tier1Entities.find(e => {
        const label = (e['rdfs:label'] || '').toLowerCase();
        return label === placeText.toLowerCase();
      });

      if (existingEntity) {
        // Update type if it was extracted by NPChunker with default type
        if (existingEntity['tagteam:denotesType'] === 'MaterialEntity') {
          existingEntity['tagteam:denotesType'] = 'GeopoliticalOrganization';
          // Also update @type array
          const typeIndex = existingEntity['@type'].indexOf('MaterialEntity');
          if (typeIndex !== -1) {
            existingEntity['@type'][typeIndex] = 'GeopoliticalOrganization';
          }
        }
        return;
      }

      const offset = this._getSpanOffset(text, placeText, index);

      // Use GeopoliticalEntity for places (cities, countries, etc.)
      const referent = this._createDiscourseReferent({
        text: placeText,
        rootNoun: placeText,
        offset,
        entityType: 'GeopoliticalOrganization',
        definiteness: 'definite',
        referentialStatus: 'introduced',
        scarcity: { isScarce: false },
        quantity: { quantity: null },
        temporalUnit: null,
        typeRefinedBy: null,
        introducingPreposition: null
      });

      tier1Entities.push(referent);
    });

    // V7-007: Fallback - scan for capitalized words not yet extracted
    // This catches proper names that Compromise doesn't recognize
    this._extractCapitalizedWords(text, tier1Entities);

    // V7-007: Post-process - upgrade default-typed entities if they're capitalized proper names
    this._upgradeCapitalizedDefaultEntities(tier1Entities);
  }

  /**
   * V7-012 Phase 1: Extract entities using custom NPChunker instead of Compromise
   *
   * Replaces Compromise's unreliable .nouns() method with explicit, rule-based chunking:
   * - Uses jsPOS for POS tagging (more reliable than Compromise)
   * - Uses NPChunker for pattern-based NP extraction
   * - Correctly identifies head nouns for possessives and PP-modified NPs
   * - Still uses Compromise for proper names (.people(), .places(), .organizations())
   *
   * @param {string} text - Input text
   * @param {Object} options - Extraction options
   * @param {Array} tier1Entities - Entity array to populate
   * @returns {Array} tier1Entities + tier2Entities (if enabled)
   */
  _extractWithNPChunker(text, options, tier1Entities) {

    // Step 1: Tokenize
    const tokenizer = new Tokenizer();
    const words = tokenizer.tokenizeForPOS(text);

    // Step 2: POS tag
    let tagged;
    if (_usePerceptron && _perceptronTagger) {
      // Phase 1: Averaged perceptron tagger (93.8% accuracy on UD-EWT)
      // Eliminates 89% of AMBIGUOUS_WORD_FIXES
      tagged = _perceptronTagger.tagFormatted(words);
    } else {
      // Fallback: jsPOS rule-based tagger + manual corrections
      const posTagger = new POSTagger();
      tagged = posTagger.tag(words);
    }

    // Step 2.5: Fix common ambiguous words that jsPOS mistags
    // Only apply when using jsPOS fallback.
    // The perceptron handles most of these correctly (50/56 validated).
    // Remaining 6 fixes are still applied regardless of tagger choice.
    const AMBIGUOUS_WORD_FIXES_JSPOS = {
      // Words that jsPOS lists as JJ first but are often nouns after determiners
      'alert': (word, tag, prevTag) => (prevTag === 'DT' && tag === 'JJ') ? 'NN' : tag,
      'access': (word, tag, prevTag) => (prevTag === 'DT' && tag === 'NN') ? 'NN' : tag,
      'change': (word, tag, prevTag) => (prevTag === 'DT' && tag === 'NN') ? 'NN' : tag,

      // Common prepositions (missing from jsPOS lexicon, default to NN)
      'for': (word, tag, prevTag) => 'IN',
      'with': (word, tag, prevTag) => 'IN',
      'on': (word, tag, prevTag) => 'IN',
      'in': (word, tag, prevTag) => 'IN',
      'at': (word, tag, prevTag) => 'IN',
      'from': (word, tag, prevTag) => 'IN',
      'to': (word, tag, prevTag) => 'IN',
      'into': (word, tag, prevTag) => 'IN',
      'onto': (word, tag, prevTag) => 'IN',
      'by': (word, tag, prevTag) => 'IN',
      'of': (word, tag, prevTag) => 'IN',

      // Common determiners (missing from jsPOS lexicon)
      'the': (word, tag, prevTag) => 'DT',
      'a': (word, tag, prevTag) => 'DT',
      'an': (word, tag, prevTag) => 'DT',

      // Coordinating conjunctions (missing from jsPOS lexicon)
      'and': (word, tag, prevTag) => 'CC',
      'or': (word, tag, prevTag) => 'CC',

      // Common nouns mistagged by jsPOS
      'family': (word, tag, prevTag) => 'NN',
      'error': (word, tag, prevTag) => 'NN',
      'harm': (word, tag, prevTag) => 'NN',
      'news': (word, tag, prevTag) => 'NN',
      'hope': (word, tag, prevTag) => 'NN',

      // Common verbs (missing from jsPOS lexicon)
      // Past tense forms
      'gave': (word, tag, prevTag) => 'VBD',
      'sent': (word, tag, prevTag) => 'VBD',
      'told': (word, tag, prevTag) => 'VBD',
      'showed': (word, tag, prevTag) => 'VBD',
      'taught': (word, tag, prevTag) => 'VBD',
      'offered': (word, tag, prevTag) => 'VBD',
      'lent': (word, tag, prevTag) => 'VBD',
      'passed': (word, tag, prevTag) => 'VBD',
      'handed': (word, tag, prevTag) => 'VBD',
      'got': (word, tag, prevTag) => 'VBD',
      'received': (word, tag, prevTag) => 'VBD',
      // V7.3: Recipient test verbs
      'brought': (word, tag, prevTag) => 'VBD',
      'operated': (word, tag, prevTag) => 'VBD',
      'explained': (word, tag, prevTag) => 'VBD',
      'caused': (word, tag, prevTag) => 'VBD',
      'transported': (word, tag, prevTag) => 'VBD',
      // Base forms
      'give': (word, tag, prevTag) => 'VB',
      'send': (word, tag, prevTag) => 'VB',
      'tell': (word, tag, prevTag) => 'VB',
      'show': (word, tag, prevTag) => 'VB',
      'teach': (word, tag, prevTag) => 'VB',
      'offer': (word, tag, prevTag) => 'VB',
      'lend': (word, tag, prevTag) => 'VB',
      'pass': (word, tag, prevTag) => 'VB',
      'hand': (word, tag, prevTag) => 'VB',
      'get': (word, tag, prevTag) => 'VB',
      'receive': (word, tag, prevTag) => 'VB',
      // V7.3: Recipient test verb base forms
      'bring': (word, tag, prevTag) => 'VB',
      'operate': (word, tag, prevTag) => 'VB',
      'explain': (word, tag, prevTag) => 'VB',
      'cause': (word, tag, prevTag) => 'VB',
      'transport': (word, tag, prevTag) => 'VB'
    };

    // Residual fixes still needed even with perceptron (6 words the perceptron misses)
    const PERCEPTRON_RESIDUAL_FIXES = {
      'hope': (word, tag, prevTag) => 'NN',    // perceptron says VBP
      'lent': (word, tag, prevTag) => 'VBD',   // perceptron says NN
      'hand': (word, tag, prevTag) => 'VB',    // perceptron says NN
      // VBN→VBD: functionally equivalent for TagTeam but kept for consistency
      'operated': (word, tag, prevTag) => (tag === 'VBN') ? 'VBD' : tag,
      'caused': (word, tag, prevTag) => (tag === 'VBN') ? 'VBD' : tag,
      'transported': (word, tag, prevTag) => (tag === 'VBN') ? 'VBD' : tag,
    };

    const fixes = (_usePerceptron && _perceptronTagger)
      ? PERCEPTRON_RESIDUAL_FIXES
      : AMBIGUOUS_WORD_FIXES_JSPOS;

    for (let i = 0; i < tagged.length; i++) {
      const [word, tag] = tagged[i];
      const wordLower = word.toLowerCase();
      const prevTag = i > 0 ? tagged[i - 1][1] : null;

      if (fixes[wordLower]) {
        const correctedTag = fixes[wordLower](word, tag, prevTag);
        tagged[i] = [word, correctedTag];
      }
    }

    // Step 3: Chunk NPs
    const npChunker = new NPChunker();
    let chunks = npChunker.chunk(tagged);

    // Step 3.4: Split ditransitive NPs
    // Ditransitive verbs (give, send, tell, etc.) take two objects: recipient + theme
    // NPChunker may merge "DT NN NN" into single chunk (e.g., "the patient medication")
    // We need to split this into two entities for correct role assignment
    const DITRANSITIVE_VERBS = new Set([
      'give', 'gave', 'send', 'sent', 'tell', 'told', 'show', 'showed',
      'teach', 'taught', 'offer', 'offered', 'lend', 'lent',
      'pass', 'passed', 'hand', 'handed'
    ]);

    // Find ditransitive verb positions
    const ditransitiveIndices = [];
    for (let i = 0; i < tagged.length; i++) {
      const [word, tag] = tagged[i];
      if ((tag === 'VB' || tag === 'VBD' || tag === 'VBP' || tag === 'VBZ') &&
          DITRANSITIVE_VERBS.has(word.toLowerCase())) {
        ditransitiveIndices.push(i);
      }
    }

    // If we found a ditransitive verb, split post-verb NPs
    if (ditransitiveIndices.length > 0) {
      const newChunks = [];

      for (let chunkIdx = 0; chunkIdx < chunks.length; chunkIdx++) {
        const chunk = chunks[chunkIdx];

        // Check if this chunk comes after a ditransitive verb
        const afterDitransitive = ditransitiveIndices.some(vIdx => chunk.startIndex > vIdx);

        if (afterDitransitive && chunk.type === 'simple') {
          // Get tokens in this chunk
          const chunkTokens = [];
          for (let i = chunk.startIndex; i <= chunk.endIndex; i++) {
            if (tagged[i]) {
              chunkTokens.push(tagged[i]);
            }
          }

          // Pattern: DT NN NN → split into "DT NN" + "NN"
          // Pattern: NN NN → split into "NN" + "NN"
          if (chunkTokens.length >= 2) {
            const lastTwoAreNouns = chunkTokens.length >= 2 &&
              chunkTokens[chunkTokens.length - 2][1].startsWith('NN') &&
              chunkTokens[chunkTokens.length - 1][1].startsWith('NN');

            if (lastTwoAreNouns) {
              // Split: all but last token → first NP, last token → second NP
              const splitPoint = chunkTokens.length - 1;

              // First chunk: DT NN or just NN
              const firstTokens = chunkTokens.slice(0, splitPoint);
              const firstText = firstTokens.map(t => t[0]).join(' ');
              const firstChunk = {
                text: firstText,
                startIndex: chunk.startIndex,
                endIndex: chunk.startIndex + splitPoint - 1,
                type: 'simple',
                head: firstTokens[firstTokens.length - 1][0],
                structure: { hasDeterminer: firstTokens[0][1] === 'DT' }
              };

              // Second chunk: NN
              const secondToken = chunkTokens[splitPoint];
              const secondChunk = {
                text: secondToken[0],
                startIndex: chunk.startIndex + splitPoint,
                endIndex: chunk.startIndex + splitPoint,
                type: 'simple',
                head: secondToken[0],
                structure: { hasDeterminer: false }
              };

              newChunks.push(firstChunk, secondChunk);
              continue;
            }
          }
        }

        // No split needed, keep original chunk
        newChunks.push(chunk);
      }

      chunks = newChunks;
    }

    // Step 3.5: Detect coordination between adjacent chunks
    // If two chunks are separated by CC (and, or), mark them as coordinated
    const coordinationInfo = new Map(); // chunkIdx → {isConjunct: true, type: 'and'/'or'}

    for (let i = 0; i < chunks.length - 1; i++) {
      const currentChunk = chunks[i];
      const nextChunk = chunks[i + 1];

      // Check if there's a CC token between these chunks
      const betweenStart = currentChunk.endIndex + 1;
      const betweenEnd = nextChunk.startIndex - 1;

      if (betweenStart <= betweenEnd) {
        for (let j = betweenStart; j <= betweenEnd; j++) {
          if (tagged[j] && tagged[j][1] === 'CC') {
            const coordType = tagged[j][0].toLowerCase(); // 'and' or 'or'
            coordinationInfo.set(i, { isConjunct: true, type: coordType });
            coordinationInfo.set(i + 1, { isConjunct: true, type: coordType });
            break;
          }
        }
      }
    }

    // Step 4: Extract entities from NP chunks
    chunks.forEach((chunk, chunkIdx) => {

      // Extract component entities (possessor, PP object, full phrase)
      const components = npChunker.extractComponents(chunk);

      components.forEach((component, compIdx) => {

        // Skip temporal adverbs - these are temporal modifiers, not entities
        // BFO treats these as TemporalRegion annotations, not discourse referents
        const temporalAdverbs = new Set([
          'yesterday', 'today', 'tomorrow', 'now', 'then',
          'recently', 'lately', 'soon', 'earlier', 'later'
        ]);
        if (temporalAdverbs.has(component.text.toLowerCase())) {
          return;
        }

        // Skip if already extracted (avoid duplicates)
        const alreadyExtracted = tier1Entities.some(e => {
          const label = (e['rdfs:label'] || '').toLowerCase().trim();
          return label === component.text.toLowerCase().trim();
        });
        if (alreadyExtracted) {
          return;
        }

        // V7-010 (Phase 2): Check for coordination ("X and Y")
        const coordination = this._detectCoordination(component.text, text);
        if (coordination.isCoordinated) {
          // Split into separate conjunct entities
          coordination.conjuncts.forEach((conjunctText) => {
            // Skip if already extracted
            const conjunctAlreadyExtracted = tier1Entities.some(e => {
              const label = (e['rdfs:label'] || '').toLowerCase().trim();
              return label === conjunctText.toLowerCase().trim();
            });
            if (conjunctAlreadyExtracted) return;

            // Get head noun for conjunct (use simple extraction)
            const conjunctWords = conjunctText.trim().split(/\s+/);
            const conjunctHead = conjunctWords[conjunctWords.length - 1]; // Last word as head

            const conjunctType = this._determineEntityType(conjunctHead, {
              fullText: text,
              definitenessInfo: { definiteness: 'definite' }
            });

            const conjunctOffset = this._getSpanOffset(text, conjunctText, 0);

            const conjunctReferent = this._createDiscourseReferent({
              text: conjunctText,
              rootNoun: conjunctHead,
              offset: conjunctOffset,
              entityType: conjunctType,
              definiteness: 'definite',
              referentialStatus: 'introduced',
              scarcity: { isScarce: false },
              quantity: { quantity: null },
              temporalUnit: null,
              typeRefinedBy: null,
              introducingPreposition: component.properties['tagteam:preposition'] || null
            });

            // Mark as part of coordination
            conjunctReferent['tagteam:isConjunct'] = true;
            conjunctReferent['tagteam:coordinationType'] = coordination.type;

            tier1Entities.push(conjunctReferent);
          });

          // Skip normal processing since we handled coordination
          return;
        }

        // Determine entity type using head noun
        const entityType = this._determineEntityType(component.head, {
          fullText: text,
          definitenessInfo: { definiteness: 'definite' } // Simplified for Phase 1
        });

        // Get offset in original text
        const offset = this._getSpanOffset(text, component.text, 0);

        // Create DiscourseReferent
        const referent = this._createDiscourseReferent({
          text: component.text,
          rootNoun: component.head,
          offset,
          entityType,
          definiteness: 'definite', // Simplified for Phase 1
          referentialStatus: 'introduced',
          scarcity: { isScarce: false },
          quantity: { quantity: null },
          temporalUnit: null,
          typeRefinedBy: null,
          introducingPreposition: component.properties['tagteam:preposition'] || null
        });

        // Add component-specific properties
        Object.assign(referent, component.properties);

        // V7-010 (Phase 2): Mark as conjunct if part of coordination
        const coordInfo = coordinationInfo.get(chunkIdx);
        if (coordInfo) {
          referent['tagteam:isConjunct'] = true;
          referent['tagteam:coordinationType'] = coordInfo.type;
        }

        tier1Entities.push(referent);
      });
    });

    // Step 5: Still use Compromise for proper names (good at this)
    const doc = nlp(text);

    // Extract persons
    const people = doc.people();
    people.forEach((person, index) => {
      const personText = person.text();

      // Check if already extracted by NPChunker
      const existingEntity = tier1Entities.find(e => {
        const label = (e['rdfs:label'] || '').toLowerCase();
        return label === personText.toLowerCase();
      });

      if (existingEntity) {
        // Update type if it was extracted by NPChunker with default type
        if (existingEntity['tagteam:denotesType'] === 'MaterialEntity') {
          existingEntity['tagteam:denotesType'] = 'Person';
          // Also update @type array
          const typeIndex = existingEntity['@type'].indexOf('MaterialEntity');
          if (typeIndex !== -1) {
            existingEntity['@type'][typeIndex] = 'Person';
          }
        }
        return;
      }

      const offset = this._getSpanOffset(text, personText, index);

      const referent = this._createDiscourseReferent({
        text: personText,
        rootNoun: personText,
        offset,
        entityType: 'Person',
        definiteness: 'definite',
        referentialStatus: 'introduced',
        scarcity: { isScarce: false },
        quantity: { quantity: null },
        temporalUnit: null,
        typeRefinedBy: null,
        introducingPreposition: null
      });

      tier1Entities.push(referent);
    });

    // Extract organizations
    const orgs = doc.organizations();
    orgs.forEach((org, index) => {
      const orgText = org.text();

      // Check if already extracted by NPChunker
      const existingEntity = tier1Entities.find(e => {
        const label = (e['rdfs:label'] || '').toLowerCase();
        return label === orgText.toLowerCase();
      });

      if (existingEntity) {
        // Update type if it was extracted by NPChunker with default type
        if (existingEntity['tagteam:denotesType'] === 'MaterialEntity') {
          existingEntity['tagteam:denotesType'] = 'Organization';
          // Also update @type array
          const typeIndex = existingEntity['@type'].indexOf('MaterialEntity');
          if (typeIndex !== -1) {
            existingEntity['@type'][typeIndex] = 'Organization';
          }
        }
        return;
      }

      const offset = this._getSpanOffset(text, orgText, index);

      const referent = this._createDiscourseReferent({
        text: orgText,
        rootNoun: orgText,
        offset,
        entityType: 'Organization',
        definiteness: 'definite',
        referentialStatus: 'introduced',
        scarcity: { isScarce: false },
        quantity: { quantity: null },
        temporalUnit: null,
        typeRefinedBy: null,
        introducingPreposition: null
      });

      tier1Entities.push(referent);
    });

    // Extract places
    const places = doc.places();
    places.forEach((place, index) => {
      const placeText = place.text();

      // Check if already extracted by NPChunker
      const existingEntity = tier1Entities.find(e => {
        const label = (e['rdfs:label'] || '').toLowerCase();
        return label === placeText.toLowerCase();
      });

      if (existingEntity) {
        // Update type if it was extracted by NPChunker with default type
        if (existingEntity['tagteam:denotesType'] === 'MaterialEntity') {
          existingEntity['tagteam:denotesType'] = 'GeopoliticalOrganization';
          // Also update @type array
          const typeIndex = existingEntity['@type'].indexOf('MaterialEntity');
          if (typeIndex !== -1) {
            existingEntity['@type'][typeIndex] = 'GeopoliticalOrganization';
          }
        }
        return;
      }

      const offset = this._getSpanOffset(text, placeText, index);

      const referent = this._createDiscourseReferent({
        text: placeText,
        rootNoun: placeText,
        offset,
        entityType: 'GeopoliticalOrganization',
        definiteness: 'definite',
        referentialStatus: 'introduced',
        scarcity: { isScarce: false },
        quantity: { quantity: null },
        temporalUnit: null,
        typeRefinedBy: null,
        introducingPreposition: null
      });

      tier1Entities.push(referent);
    });

    // Extract pronouns (V7-010: reflexives)
    this._extractPronouns(doc, text, tier1Entities);

    // V7-Priority5: Filter out partial name fragments BEFORE tier2 processing
    // E.g., remove "Dr" and "Smith" when "Dr. Smith" exists
    // This handles title+name patterns where tokenization splits them
    tier1Entities = tier1Entities.filter(entity => {
      const entityText = (entity['rdfs:label'] || '').trim();

      // Check if this entity is a single-word fragment of a multi-word entity
      const entityWords = entityText.split(/\s+/);
      if (entityWords.length === 1) {
        // Single-word entity - check if it appears in a longer entity
        const isPartOfLonger = tier1Entities.some(other => {
          if (other === entity) return false;

          const otherText = (other['rdfs:label'] || '').trim();
          const otherWords = otherText.split(/\s+/);

          // Other must be longer (multi-word)
          if (otherWords.length <= 1) return false;

          // Check if our single word appears in the other entity's words
          // Match with or without punctuation (e.g., "Dr" matches "Dr.")
          return otherWords.some(word => {
            const cleanWord = word.replace(/[.,;:!?]/g, '');
            const cleanEntity = entityText.replace(/[.,;:!?]/g, '');
            return cleanWord.toLowerCase() === cleanEntity.toLowerCase();
          });
        });

        return !isPartOfLonger;
      }

      return true;
    });

    // V7-Priority6: Filter out appositive phrases
    // Pattern: "NP1, NP2," where NP2 provides additional info about NP1
    // E.g., "The engineer, a senior developer," → keep "The engineer", filter "a senior developer"
    tier1Entities = tier1Entities.filter(entity => {
      const entityText = (entity['rdfs:label'] || '').trim();

      // Check if this entity appears in the original text between commas (appositive pattern)
      // Look for pattern: ", <entity>," in the text
      const appositivePattern = new RegExp(`,\\s*${entityText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*,`, 'i');

      if (appositivePattern.test(text)) {
        // This entity appears between commas - likely an appositive
        // Check if there's another entity immediately before it (the head noun)
        const entityIndex = text.toLowerCase().indexOf(entityText.toLowerCase());

        // Look for the preceding entity
        const hasAntecedent = tier1Entities.some(other => {
          if (other === entity) return false;

          const otherText = (other['rdfs:label'] || '').trim();
          const otherIndex = text.toLowerCase().indexOf(otherText.toLowerCase());

          // Other entity should appear before this one
          if (otherIndex >= entityIndex) return false;

          // Check if they're separated by a comma (appositive structure)
          const between = text.substring(otherIndex + otherText.length, entityIndex);
          return /^\s*,\s*$/.test(between);
        });

        // If this entity is an appositive (has antecedent), filter it out
        return !hasAntecedent;
      }

      return true;
    });

    // Create Tier 2 entities and link via is_about (Two-Tier Architecture)
    const shouldCreateTier2 = options.createTier2 !== undefined
      ? options.createTier2
      : this.options.createTier2 !== false;


    if (shouldCreateTier2 && tier1Entities.length > 0) {
      const { tier2Entities, linkMap } = this.tier2Factory.createFromReferents(
        tier1Entities,
        { documentIRI: options.documentIRI }
      );


      // Add is_about links to Tier 1 referents
      const linkedReferents = this.tier2Factory.linkReferentsToTier2(tier1Entities, linkMap);

      const result = [...linkedReferents, ...tier2Entities];

      // Deduplicate by @id (linkReferentsToTier2 may create duplicates)
      const seen = new Set();
      const deduplicated = result.filter(entity => {
        if (seen.has(entity['@id'])) {
          return false;
        }
        seen.add(entity['@id']);
        return true;
      });

      // Return both Tier 1 (with is_about) and Tier 2 entities
      return deduplicated;
    }

    return tier1Entities;
  }

  /**
   * V7-011: Detect possessive NP structure ("X's Y" patterns).
   *
   * Linguistic Foundation: Cambridge Grammar §5.4 (possessive constructions)
   * - Possessive NP has both possessor and possessed
   * - "the admin's credentials" → possessor="the admin", possessed="credentials"
   * - Penn Treebank structure: [NP [NP X]'s [N Y]]
   *
   * @param {string} nounText - The noun phrase text
   * @param {string} fullText - Full input text for context
   * @returns {Object} {isPossessive: boolean, possessor: string, possessed: string}
   */
  _detectPossessiveNP(nounText, fullText) {
    // Possessive pattern: "X's" (possessor + 's)
    // Note: Compromise often splits "X's Y" into two nouns, so we detect just "X's"
    const possessivePattern = /^(.+?)'s$/i;
    const match = nounText.match(possessivePattern);

    if (!match) {
      return { isPossessive: false, possessor: null, possessed: null };
    }

    return {
      isPossessive: true,
      possessor: match[1].trim(),    // "the admin"
      possessed: null                 // Will be in next noun
    };
  }

  /**
   * V7-011: Detect PP modifier in noun phrases ("X in Y" patterns).
   *
   * Linguistic Foundation: Cambridge Grammar §7.2 (PP attachment)
   * - PP modifiers create hierarchical NP structure
   * - "the server in the datacenter" → head="the server", ppObject="the datacenter"
   * - High attachment: both head and PP object are separate entities
   *
   * @param {string} nounText - The noun phrase text
   * @param {string} fullText - Full input text for context
   * @returns {Object} {hasPP: boolean, head: string, preposition: string, ppObject: string}
   */
  _detectPPModifier(nounText, fullText) {
    // PP pattern: "X [PREP] Y" where PREP is locative/directional preposition
    const ppPattern = /^(.+?)\s+(in|on|at|from|to|into|onto|near|inside|outside|within)\s+(.+)$/i;
    const match = nounText.match(ppPattern);

    if (!match) {
      return { hasPP: false, head: null, preposition: null, ppObject: null };
    }

    return {
      hasPP: true,
      head: match[1].trim(),         // "the server"
      preposition: match[2].toLowerCase(),  // "in"
      ppObject: match[3].trim()      // "the datacenter"
    };
  }

  /**
   * V7-011: Helper method to create entity from text components.
   * Extracted from main noun processing loop to avoid code duplication.
   *
   * @param {string} entityText - The entity text
   * @param {string} rootNoun - The root noun
   * @param {number} offset - Text offset
   * @param {string} fullText - Full input text
   * @param {Object} nounObj - Compromise noun object
   * @param {Object} nounData - Noun data from Compromise
   * @returns {Object} DiscourseReferent entity
   */
  _createEntityFromText(entityText, rootNoun, offset, fullText, nounObj, nounData) {
    const introducingPrep = this._detectIntroducingPreposition(fullText, offset);
    const defInfo = this._detectDefiniteness(nounObj, entityText, fullText, nounData);
    const scarcityInfo = this._detectScarcity(entityText, fullText, offset, nounData);
    const quantityInfo = this._detectQuantity(entityText, fullText, offset, nounData);

    // V7-011c: Extract syntactic head noun for accurate type classification
    const headNoun = this._extractHeadNoun(entityText, rootNoun);

    const fullWords = entityText.toLowerCase().trim().split(/\s+/);
    const temporalType = this._checkForTemporalType(entityText.toLowerCase().trim(), fullWords);
    const symptomType = !temporalType
      ? this._checkForSymptomType(entityText.toLowerCase().trim(), headNoun)
      : null;

    let entityType = temporalType || symptomType || this._determineEntityType(headNoun, {
      fullText: fullText,
      definitenessInfo: defInfo
    });

    let typeRefinedBy = null;
    if (!temporalType && !symptomType) {
      const verbRefinement = this._refineTypeByVerbContext(headNoun, fullText, offset);
      if (verbRefinement.refinedType) {
        entityType = verbRefinement.refinedType;
        typeRefinedBy = verbRefinement.governingVerb;
      }
    }

    const temporalUnit = temporalType ? this._extractTemporalUnit(entityText) : null;
    const referentialStatus = this._determineReferentialStatus(defInfo, entityText, fullText, 0);

    return this._createDiscourseReferent({
      text: entityText,
      rootNoun: rootNoun,
      offset,
      entityType,
      definiteness: defInfo.definiteness,
      referentialStatus,
      scarcity: scarcityInfo,
      quantity: quantityInfo,
      temporalUnit: temporalUnit,
      typeRefinedBy: typeRefinedBy,
      introducingPreposition: introducingPrep
    });
  }

  /**
   * V7-011c: Extract syntactic head noun from complex NP.
   *
   * Linguistic Foundation:
   * - Cambridge Grammar §5.4: Possessive NP head is the possessed (rightmost noun)
   * - Cambridge Grammar §7.2: PP-modified NP head is the noun before the preposition
   * - X-bar Theory: Head determines the category and semantic type of the phrase
   *
   * Problem: Compromise NLP doesn't reliably identify syntactic heads for complex NPs:
   * - "admin's credentials" → Compromise returns "admin's" as head (should be "credentials")
   * - "server in datacenter" → Compromise returns "datacenter" or phrase (should be "server")
   *
   * Solution: Apply linguistic rules to extract true head noun:
   * 1. Possessives ("X's Y"): Rightmost noun is head ("credentials")
   * 2. PP modifiers ("X in/on/at Y"): Leftmost noun before prep is head ("server")
   * 3. Otherwise: Use Compromise's rootNoun
   *
   * @param {string} nounText - The full noun phrase text
   * @param {string} rootNoun - Compromise's root noun (fallback)
   * @returns {string} The syntactic head noun
   */
  _extractHeadNoun(nounText, rootNoun) {
    const text = nounText.trim();

    // Pattern 1: Possessive NP ("X's Y" or just "X's")
    // Cambridge Grammar §5.4: In "the admin's credentials", head is "credentials"
    const possessivePattern = /^(.+?)'s(?:\s+(.+))?$/i;
    const possMatch = text.match(possessivePattern);
    if (possMatch) {
      if (possMatch[2]) {
        // "X's Y" form - possessed is head
        const possessed = possMatch[2].trim();
        // Extract rightmost noun from possessed part
        const words = possessed.split(/\s+/);
        return words[words.length - 1].toLowerCase();
      } else {
        // Just "X's" with no Y - use possessor
        const possessor = possMatch[1].trim();
        const words = possessor.split(/\s+/);
        return words[words.length - 1].toLowerCase();
      }
    }

    // Pattern 2: PP modifier ("X in/on/at/from/to/... Y")
    // Cambridge Grammar §7.2: In "the server in the datacenter", head is "server"
    // Use greedy matching (.+) to capture full head phrase before preposition
    const ppPattern = /^(.+)\s+(in|on|at|from|to|into|onto|near|by|with|under|over|above|below|beside|behind|before|after|during|within|outside)\s+(.+)$/i;
    const ppMatch = text.match(ppPattern);
    if (ppMatch) {
      const headPhrase = ppMatch[1].trim();
      // Extract rightmost noun from head phrase (before preposition)
      const words = headPhrase.split(/\s+/);
      return words[words.length - 1].toLowerCase();
    }

    // Pattern 3: No complex structure - use Compromise's rootNoun
    return (rootNoun || text).toLowerCase();
  }

  /**
   * V7-010: Detect coordination in noun phrases ("X and Y" patterns).
   *
   * Linguistic Foundation: Penn Treebank NP coordination rules
   * - "NP and NP" creates two separate entities, not one merged entity
   * - "the admin and the user" → 2 entities: "the admin", "the user"
   * - "servers and databases" → 2 entities: "servers", "databases"
   *
   * Handles both "and" and "or" coordination.
   *
   * @param {string} nounText - The noun phrase text
   * @param {string} fullText - Full input text for context
   * @returns {Object} {isCoordinated: boolean, conjuncts: string[], type: 'and'|'or'}
   */
  _detectCoordination(nounText, fullText) {
    // Coordination pattern: "X and Y" or "X or Y"
    // Use word boundaries to avoid matching "brand" or "standard"
    const andPattern = /\b(\w+(?:\s+\w+)*)\s+and\s+(\w+(?:\s+\w+)*)\b/i;
    const orPattern = /\b(\w+(?:\s+\w+)*)\s+or\s+(\w+(?:\s+\w+)*)\b/i;

    let match = nounText.match(andPattern);
    let type = 'and';

    if (!match) {
      match = nounText.match(orPattern);
      type = 'or';
    }

    if (!match) {
      return { isCoordinated: false, conjuncts: [], type: null };
    }

    // Extract conjuncts
    // For "the admin and the user" → ["the admin", "the user"]
    // For "servers and databases" → ["servers", "databases"]
    const conjuncts = [];

    // Check if pattern has determiners
    const leftPart = match[1].trim();
    const rightPart = match[2].trim();

    // Handle determiner inheritance
    // "the admin and user" → ["the admin", "the user"] (inherit determiner)
    // "the admin and the user" → ["the admin", "the user"] (explicit determiners)
    const determinerPattern = /^(the|a|an|this|that|these|those)\s+/i;
    const leftDet = leftPart.match(determinerPattern);

    if (leftDet && !rightPart.match(determinerPattern)) {
      // Inherit determiner to right conjunct
      conjuncts.push(leftPart);
      conjuncts.push(leftDet[1] + ' ' + rightPart);
    } else {
      // Both have explicit determiners or both are bare
      conjuncts.push(leftPart);
      conjuncts.push(rightPart);
    }

    return {
      isCoordinated: true,
      conjuncts: conjuncts,
      type: type
    };
  }

  /**
   * V7-010: Extract pronouns, especially reflexives for Binding Theory support.
   *
   * Reflexive pronouns (itself, himself, herself, etc.) need to be extracted
   * as entities so ActExtractor can assign them to patient roles.
   *
   * Linguistic Foundation: Chomsky's Binding Theory (Principle A)
   * - Reflexive pronouns must be bound within their local domain
   * - In "The system updated itself", "itself" must be patient of "updated"
   *
   * @param {Object} doc - Compromise NLP document
   * @param {string} text - Full input text
   * @param {Array} tier1Entities - Array to add entities to (modified in place)
   */
  _extractPronouns(doc, text, tier1Entities) {
    // Reflexive pronouns that need entity extraction
    const REFLEXIVE_PRONOUNS = new Set([
      'itself', 'himself', 'herself', 'themselves',
      'ourselves', 'yourself', 'yourselves', 'myself'
    ]);

    // Extract all pronouns using Compromise
    const pronouns = doc.pronouns();

    pronouns.forEach((pronoun, index) => {
      const pronounText = pronoun.text().toLowerCase();

      // Only extract reflexive pronouns (non-reflexives like "it", "he" are handled by anaphora)
      if (!REFLEXIVE_PRONOUNS.has(pronounText)) {
        return;
      }

      // Skip if already extracted (shouldn't happen, but safety check)
      const alreadyExtracted = tier1Entities.some(e => {
        const label = (e['rdfs:label'] || '').toLowerCase();
        return label === pronounText;
      });
      if (alreadyExtracted) return;

      // Get offset in original text
      const offset = this._getSpanOffset(text, pronounText, index);

      // Determine entity type based on pronoun
      // "itself" → generic entity (could be artifact, system, etc.)
      // "himself/herself" → person
      // "themselves/ourselves" → group
      let entityType = 'Entity';  // Default for "itself"
      if (pronounText === 'himself' || pronounText === 'herself' || pronounText === 'myself' || pronounText === 'yourself') {
        entityType = 'Person';
      } else if (pronounText === 'themselves' || pronounText === 'ourselves' || pronounText === 'yourselves') {
        entityType = 'Agent';
      }

      // Create DiscourseReferent for reflexive pronoun
      const referent = this._createDiscourseReferent({
        text: pronounText,
        rootNoun: pronounText,
        offset,
        entityType: entityType,
        definiteness: 'anaphoric',  // Pronouns are anaphoric by definition
        referentialStatus: 'anaphoric',
        scarcity: { isScarce: false },
        quantity: { quantity: null },
        temporalUnit: null,
        typeRefinedBy: null,
        introducingPreposition: null
      });

      // V7-010: Mark as pronoun for ActExtractor
      referent['tagteam:isPronoun'] = true;
      referent['tagteam:pronounType'] = 'reflexive';

      tier1Entities.push(referent);
    });
  }

  /**
   * V7-007: Upgrade entities with default type if they appear to be proper names.
   *
   * Some proper names get extracted as regular nouns with bfo:BFO_0000040 default type.
   * This post-processing step upgrades them based on capitalization heuristics.
   *
   * @param {Array} tier1Entities - Entities to upgrade (modified in place)
   */
  _upgradeCapitalizedDefaultEntities(tier1Entities) {
    const DEFAULT_TYPE = 'MaterialEntity';

    tier1Entities.forEach(entity => {
      // Only upgrade if it has default type
      const types = entity['@type'] || [];
      if (!types.includes(DEFAULT_TYPE)) return;

      const text = entity['rdfs:label'] || '';
      const words = text.trim().split(/\s+/);

      // Check if all main words are capitalized (skip articles)
      const mainWords = words.filter(w => {
        const lower = w.toLowerCase();
        return !['the', 'a', 'an'].includes(lower);
      });

      const allCapitalized = mainWords.every(w => {
        const clean = w.replace(/[.,;:!?]$/, '');
        return clean.length > 0 &&
               clean[0] === clean[0].toUpperCase() &&
               clean[0] !== clean[0].toLowerCase();
      });

      if (!allCapitalized) return;

      // Determine new type based on word count, length, and patterns
      let newType;
      const cleanWords = mainWords.map(w => w.replace(/[.,;:!?]$/, ''));
      const totalLength = cleanWords.join('').length;
      const firstWord = cleanWords[0];

      // Check for known tech companies/products
      const techCompanies = new Set(['Microsoft', 'Google', 'Apple', 'Amazon', 'Facebook', 'Oracle', 'IBM', 'Intel', 'AMD', 'Nvidia']);
      const techProducts = new Set(['Windows', 'Linux', 'Mac', 'Unix', 'Android', 'iOS', 'Chrome', 'Firefox', 'Safari']);

      if (cleanWords.length === 1) {
        // Single capitalized word
        if (techCompanies.has(firstWord)) {
          newType = 'Organization';
        } else if (techProducts.has(firstWord)) {
          newType = 'Artifact';  // Product names are artifacts
        } else if (totalLength >= 3 && totalLength <= 8) {
          // Short word - likely person name (John, Mary, Smith)
          newType = 'Person';
        } else if (totalLength >= 9) {
          // Longer single word - likely organization (Microsoft = 9 chars)
          newType = 'Organization';
        }
      } else if (cleanWords.length === 2) {
        // Two capitalized words
        // Check if second word is a common name suffix (indicates person)
        const nameSuffixes = new Set(['Jr', 'Sr', 'II', 'III']);
        if (nameSuffixes.has(cleanWords[1])) {
          newType = 'Person';
        } else if (totalLength <= 20) {
          // Likely "FirstName LastName"
          newType = 'Person';
        } else {
          // Long two-word phrase - likely organization
          newType = 'Organization';
        }
      } else {
        // Multiple words - likely organization
        newType = 'Organization';
      }

      if (newType) {
        // Replace default type with specific type
        const typeIndex = types.indexOf(DEFAULT_TYPE);
        if (typeIndex !== -1) {
          types[typeIndex] = newType;
        }
      }
    });
  }

  /**
   * V7-007: Extract capitalized words that weren't caught by other methods.
   *
   * Fallback for proper names that Compromise doesn't recognize in its
   * dictionaries (e.g., "John", "Microsoft", "Windows").
   *
   * Heuristics:
   * - Capitalized word(s) not in ENTITY_TYPE_MAPPINGS or common words
   * - Short single words (3-10 chars) → likely Person names
   * - Longer or multi-word → likely Organizations or product names
   *
   * @param {string} text - Full input text
   * @param {Array} tier1Entities - Existing entities (modified in place)
   */
  _extractCapitalizedWords(text, tier1Entities) {
    const words = text.split(/\s+/);
    const commonWords = new Set(['the', 'a', 'an', 'this', 'that', 'these', 'those', 'i', 'he', 'she', 'it', 'we', 'they']);

    let i = 0;
    while (i < words.length) {
      const cleanWord = words[i].replace(/[.,;:!?]$/, '');
      const lowerWord = cleanWord.toLowerCase();

      // Skip if not capitalized or is a common word
      if (cleanWord[0] !== cleanWord[0].toUpperCase() ||
          cleanWord[0] === cleanWord[0].toLowerCase() ||
          commonWords.has(lowerWord)) {
        i++;
        continue;
      }

      // Skip if in ENTITY_TYPE_MAPPINGS (already handled by noun extraction)
      if (ENTITY_TYPE_MAPPINGS[lowerWord]) {
        i++;
        continue;
      }

      // Check if already extracted
      const wordStart = text.indexOf(words[i], i > 0 ? text.indexOf(words[i - 1]) + words[i - 1].length : 0);
      const alreadyExtracted = tier1Entities.some(e => {
        const start = e['tagteam:startPosition'];
        const end = e['tagteam:endPosition'];
        return start <= wordStart && wordStart < end;
      });

      if (alreadyExtracted) {
        i++;
        continue;
      }

      // Check for multi-word capitalized phrase (e.g., "John Smith")
      let phrase = cleanWord;
      let phraseEnd = i;
      while (phraseEnd + 1 < words.length) {
        const nextWord = words[phraseEnd + 1].replace(/[.,;:!?]$/, '');
        if (nextWord[0] === nextWord[0].toUpperCase() && nextWord[0] !== nextWord[0].toLowerCase()) {
          phrase += ' ' + nextWord;
          phraseEnd++;
        } else {
          break;
        }
      }

      // Determine type based on heuristics
      let entityType;
      const phraseLength = phrase.replace(/\s+/g, '').length;

      if (phraseEnd > i) {
        // Multi-word capitalized phrase
        if (phrase.split(/\s+/).length === 2 && phraseLength <= 20) {
          // Likely "FirstName LastName"
          entityType = 'Person';
        } else {
          // Longer phrase - likely Organization
          entityType = 'Organization';
        }
      } else {
        // Single capitalized word
        if (phraseLength >= 3 && phraseLength <= 10) {
          // Short word - likely person name
          entityType = 'Person';
        } else if (phraseLength > 10) {
          // Longer word - likely organization or product
          entityType = 'Organization';
        } else {
          // Very short - skip (might be abbreviation)
          i++;
          continue;
        }
      }

      const offset = wordStart >= 0 ? wordStart : 0;

      const referent = this._createDiscourseReferent({
        text: phrase,
        rootNoun: phrase,
        offset,
        entityType,
        definiteness: 'definite',
        referentialStatus: 'introduced',
        scarcity: { isScarce: false },
        quantity: { quantity: null },
        temporalUnit: null,
        typeRefinedBy: null,
        introducingPreposition: null
      });

      tier1Entities.push(referent);

      i = phraseEnd + 1;
    }
  }

  /**
   * V7-003: Trim trailing verbs from noun phrase to prevent absorption
   * e.g., "the system restarts" → "the system"
   * @param {string} nounPhrase - The noun phrase from Compromise
   * @returns {string} Trimmed noun phrase without trailing verbs
   */
  _trimTrailingVerbs(nounPhrase) {
    const words = nounPhrase.trim().split(/\s+/);
    if (words.length === 0) return nounPhrase;

    // Common verb patterns to trim
    const verbPatterns = [
      /s$/,           // present tense 3rd person (fails, runs, completes, restarts)
      /ed$/,          // past tense (failed, completed, restarted)
      /ing$/,         // present participle (failing, running, completing)
      /es$/,          // present tense (goes, does, reaches)
      /ied$/          // past tense -y verbs (tried, replied)
    ];

    // Common verbs to trim (irregular + common regular)
    const commonVerbs = new Set([
      'fails', 'fail', 'failed', 'receives', 'receive', 'received',
      'completes', 'complete', 'completed', 'restarts', 'restart', 'restarted',
      'runs', 'run', 'ran', 'locks', 'lock', 'locked', 'expires', 'expire', 'expired',
      'approves', 'approve', 'approved', 'blocks', 'block', 'blocked',
      'finishes', 'finish', 'finished', 'launches', 'launch', 'launched',
      'starts', 'start', 'started', 'loads', 'load', 'loaded',
      'stops', 'stop', 'stopped', 'increases', 'increase', 'increased',
      'rises', 'rise', 'rose', 'goes', 'go', 'went', 'does', 'do', 'did',
      'is', 'are', 'was', 'were', 'has', 'have', 'had',
      'designs', 'design', 'designed', 'stores', 'store', 'stored',
      'handles', 'handle', 'handled', 'crashes', 'crash', 'crashed',
      'hired', 'hire', 'hires', 'resigned', 'resign', 'resigns',
      'deployed', 'deploy', 'deploys', 'fixed', 'fix', 'fixes',
      'filed', 'file', 'files', 'caused', 'cause', 'causes',
      'responded', 'respond', 'responds', 'left', 'leave', 'leaves'
    ]);

    // Determiners that should not be left as standalone entities
    const determiners = new Set(['the', 'a', 'an', 'this', 'that', 'these', 'those']);

    // Trim from the end while last word looks like a verb
    while (words.length > 1) {
      const lastWord = words[words.length - 1].toLowerCase().replace(/[.,;:!?]$/, '');

      // Don't trim if it would leave only a determiner
      // e.g., "the load" → don't trim to just "the"
      if (words.length === 2 && determiners.has(words[0].toLowerCase().replace(/[.,;:!?]$/, ''))) {
        break;
      }

      // Check if it's a known verb
      if (commonVerbs.has(lastWord)) {
        words.pop();
        continue;
      }

      // Check if it matches verb patterns
      const matchesVerbPattern = verbPatterns.some(pattern => pattern.test(lastWord));
      if (matchesVerbPattern && lastWord.length > 3) {
        words.pop();
        continue;
      }

      // Not a verb, stop trimming
      break;
    }

    return words.join(' ');
  }

  /**
   * V7-004/V7-005: Check if Wh-word is in relativizer context (follows NP or preposition)
   *
   * Patterns:
   * 1. Direct: "The engineer who..." - "who" follows NP
   * 2. Prepositional: "The server on which..." - "which" follows preposition
   *
   * vs. "Who designed..." - "who" at start, so it's interrogative
   *
   * @param {Array} entities - Extracted entities so far
   * @param {string} text - Full text
   * @param {number} wordIndex - Index of Wh-word in words array
   * @param {Array} words - Words array
   * @returns {boolean} True if this is a relativizer context
   */
  _isRelativizerContext(entities, text, wordIndex, words) {
    // If Wh-word is at start of sentence, it's interrogative, not relativizer
    if (wordIndex === 0) return false;

    // V7-005: Check if immediately preceded by a preposition (prepositional relative)
    // Pattern: "on which", "to whom", "for whose", etc.
    const PREPOSITIONS = ['on', 'in', 'at', 'to', 'from', 'with', 'by', 'for', 'of', 'about', 'through', 'during', 'after', 'before'];
    if (wordIndex > 0) {
      const prevWord = words[wordIndex - 1].toLowerCase().replace(/[.,;:!?]$/, '');
      if (PREPOSITIONS.includes(prevWord)) {
        return true; // Prepositional relative: "on which"
      }
    }

    // Find position of this Wh-word in original text
    let position = 0;
    for (let i = 0; i < wordIndex; i++) {
      position = text.toLowerCase().indexOf(words[i], position) + words[i].length;
    }
    const whWordStart = text.toLowerCase().indexOf(words[wordIndex], position);

    // Check if any entity ends just before this Wh-word
    // Relativizers typically follow immediately after NPs (with maybe a space)
    const precedingEntity = entities.find(e => {
      const entityEnd = e['tagteam:endPosition'];
      // Allow 1-2 character gap (space) between entity and Wh-word
      return entityEnd !== undefined && entityEnd >= whWordStart - 2 && entityEnd <= whWordStart;
    });

    return !!precedingEntity;
  }

  /**
   * Check if noun is a non-entity word to skip
   * @param {string} noun - Noun text
   * @returns {boolean} True if should skip
   */
  _isNonEntityNoun(noun) {
    const nonEntityNouns = ['here', 'there', 'now', 'then', 'help', 'way', 'thing'];
    return nonEntityNouns.includes(noun.toLowerCase().trim());
  }

  /**
   * Detect definiteness from determiner
   * @param {Object} noun - Compromise noun object
   * @param {string} nounText - The noun text
   * @param {string} fullText - Full input text
   * @param {Object} nounData - Compromise noun metadata
   * @returns {Object} Definiteness info
   */
  _detectDefiniteness(noun, nounText, fullText, nounData = {}) {
    // Definite determiners
    const definiteMarkers = ['the', 'this', 'that', 'these', 'those', 'his', 'her', 'its', 'their', 'my', 'our', 'your'];

    // Indefinite determiners
    const indefiniteMarkers = ['a', 'an', 'some', 'any', 'each', 'every', 'no', 'another'];

    // First check Compromise's determiner data
    if (nounData.determiner) {
      const det = nounData.determiner.toLowerCase();
      if (definiteMarkers.includes(det)) {
        return { definiteness: 'definite', determiner: det };
      }
      if (indefiniteMarkers.includes(det)) {
        return { definiteness: 'indefinite', determiner: det };
      }
    }

    // Fallback: check text before noun (Compromise may miss determiners with intervening modifiers)
    // e.g., "the critically ill patient" - Compromise may only see "ill patient"
    const lowerText = fullText.toLowerCase();
    const lowerNoun = nounText.toLowerCase();
    const nounIndex = lowerText.indexOf(lowerNoun);

    if (nounIndex > 0) {
      const beforeNoun = lowerText.substring(0, nounIndex).trim();
      const words = beforeNoun.split(/\s+/);

      // Look back up to 6 words to find a determiner (handles modifiers like "the critically ill")
      const searchLimit = Math.min(6, words.length);
      for (let i = 1; i <= searchLimit; i++) {
        const word = words[words.length - i];
        if (definiteMarkers.includes(word)) {
          return { definiteness: 'definite', determiner: word };
        }
        if (indefiniteMarkers.includes(word)) {
          return { definiteness: 'indefinite', determiner: word };
        }
        // Stop if we hit a verb, preposition, or punctuation (different clause)
        if (word.match(/[.,;:!?]$/) || CLAUSE_BOUNDARY_WORDS.has(word)) {
          break;
        }
      }
    }

    // Check for proper names (inherently definite)
    // Proper names are capitalized and typically don't have determiners
    // e.g., "Dr. Smith", "John", "Mary"
    if (this._isProperName(nounText, fullText, nounIndex)) {
      return { definiteness: 'definite', determiner: null, isProperName: true };
    }

    // Default to indefinite if no determiner
    return { definiteness: 'indefinite', determiner: null };
  }

  /**
   * Check if a noun phrase is a proper name (inherently definite)
   * @param {string} nounText - The noun text
   * @param {string} fullText - Full input text
   * @param {number} nounIndex - Position of noun in text
   * @returns {boolean} True if proper name
   */
  _isProperName(nounText, fullText, nounIndex) {
    // Titles that indicate proper names
    const titles = ['dr', 'dr.', 'mr', 'mr.', 'mrs', 'mrs.', 'ms', 'ms.', 'prof', 'prof.'];

    const words = nounText.split(/\s+/);

    // Check if first word is a title
    if (titles.includes(words[0].toLowerCase())) {
      return true;
    }

    // Check if first word is capitalized (and not at sentence start)
    const firstWord = words[0];
    if (firstWord[0] === firstWord[0].toUpperCase() && firstWord[0] !== firstWord[0].toLowerCase()) {
      // Make sure it's not at the start of a sentence
      if (nounIndex > 0) {
        const charBefore = fullText[nounIndex - 1];
        const twoCharsBefore = nounIndex > 1 ? fullText.substring(nounIndex - 2, nounIndex) : '';
        // If preceded by space (not after period), it's likely a proper name
        if (charBefore === ' ' && !twoCharsBefore.match(/[.!?]\s*$/)) {
          return true;
        }
      }
    }

    return false;
  }

  /**
   * Detect scarcity markers near entity
   * @param {string} nounText - The noun text
   * @param {string} fullText - Full input text
   * @param {number} offset - Span offset
   * @param {Object} nounData - Compromise noun metadata
   * @returns {Object} Scarcity info
   */
  _detectScarcity(nounText, fullText, offset, nounData = {}) {
    // First check adjectives from Compromise
    if (nounData.adjectives && nounData.adjectives.length > 0) {
      for (const adj of nounData.adjectives) {
        const lowerAdj = adj.toLowerCase();
        if (SCARCITY_MARKERS.includes(lowerAdj)) {
          return { isScarce: true, marker: lowerAdj };
        }
      }
    }

    // Fallback: check context before noun
    const lowerText = fullText.toLowerCase();
    const lowerNoun = nounText.toLowerCase();

    const nounIndex = lowerText.indexOf(lowerNoun);
    if (nounIndex === -1) {
      return { isScarce: false, marker: null };
    }

    const contextStart = Math.max(0, nounIndex - 30);
    const beforeContext = lowerText.substring(contextStart, nounIndex);

    for (const marker of SCARCITY_MARKERS) {
      if (beforeContext.includes(marker)) {
        return { isScarce: true, marker };
      }
    }

    return { isScarce: false, marker: null };
  }

  /**
   * Detect quantity from context
   * @param {string} nounText - The noun text
   * @param {string} fullText - Full input text
   * @param {number} offset - Span offset
   * @param {Object} nounData - Compromise noun metadata
   * @returns {Object} Quantity info
   */
  _detectQuantity(nounText, fullText, offset, nounData = {}) {
    // First check Compromise's number data
    if (nounData.number !== null && nounData.number !== undefined) {
      return { quantity: nounData.number, quantifier: 'detected' };
    }

    // Check adjectives for implied quantity (last, only, single = 1)
    const impliedOneMarkers = ['last', 'only', 'sole', 'single', 'remaining', 'final'];
    if (nounData.adjectives && nounData.adjectives.length > 0) {
      for (const adj of nounData.adjectives) {
        if (impliedOneMarkers.includes(adj.toLowerCase())) {
          return { quantity: 1, quantifier: adj.toLowerCase() };
        }
      }
    }

    const lowerText = fullText.toLowerCase();
    const lowerNoun = nounText.toLowerCase();

    // Find noun position
    const nounIndex = lowerText.indexOf(lowerNoun);
    if (nounIndex === -1) {
      return { quantity: null, quantifier: null };
    }

    // Look for quantity word before noun
    const contextStart = Math.max(0, nounIndex - 20);
    const beforeContext = lowerText.substring(contextStart, nounIndex);
    const words = beforeContext.trim().split(/\s+/);

    // Check each word for quantity
    for (let i = words.length - 1; i >= 0; i--) {
      const word = words[i];
      if (QUANTITY_WORDS[word] !== undefined) {
        return { quantity: QUANTITY_WORDS[word], quantifier: word };
      }

      // Check for numeric digits
      if (/^\d+$/.test(word)) {
        return { quantity: parseInt(word, 10), quantifier: word };
      }
    }

    return { quantity: null, quantifier: null };
  }

  /**
   * Extract head noun from a noun phrase
   *
   * In English, the head noun is typically the rightmost noun in a compound.
   * e.g., "medication administration" → "administration" (head)
   *       "patient care plan" → "plan" (head)
   *
   * @param {string} nounPhrase - The noun phrase
   * @returns {string} The head noun
   * @private
   */
  _extractHeadNoun(nounPhrase) {
    const words = nounPhrase.toLowerCase().trim().split(/\s+/);
    return words[words.length - 1];
  }

  /**
   * Check if noun phrase refers to a process/service rather than a physical object
   *
   * Domain-Neutral Detection Order (ONTOLOGICAL_ISSUES_2026_01_19.md v3.1):
   * 0. Compound noun analysis → head noun determines type
   * 1. Physical object indicators → Artifact (override everything)
   * 2. Ontological vocabulary → BFO types (domain-neutral)
   * 3. Result noun exceptions → IC/GDC (override suffixes)
   * 4. Nominalization suffixes → BFO:Process (linguistic patterns - PRIMARY)
   * 5. Domain-specific words → CCO types (DEPRECATED - Phase 2 moves to config)
   *
   * Pattern Precedence (from critique):
   * 1. Verb selectional restrictions (Phase 3)
   * 2. Compound noun as unit - head noun determines type
   * 3. Head noun morphology - suffixes on head noun
   * 4. Modifier constraints - "physical documentation" override (TODO)
   * 5. Suffix heuristics
   * 6. Ontological vocabulary match
   * 7. Default
   *
   * @param {string} nounText - The noun text
   * @param {Object} [context] - Additional context for disambiguation
   * @param {string} [context.determiner] - Determiner if available
   * @returns {Object|null} Type info { isProcess, type } or null if not a process
   */
  _checkForProcessType(nounText, context = {}) {
    const lowerNoun = nounText.toLowerCase().trim();
    const words = lowerNoun.split(/\s+/);
    const lastWord = this._extractHeadNoun(lowerNoun); // Head noun determines type

    // Priority 1: Physical object indicators override everything
    for (const indicator of PHYSICAL_OBJECT_INDICATORS) {
      if (lowerNoun.includes(indicator)) {
        return null; // Not a process, let it fall through to artifact
      }
    }

    // Priority 2: Check ontological vocabulary (domain-neutral)
    // Handle both singular and common plural forms (service/services, activity/activities)
    for (const [term, type] of Object.entries(ONTOLOGICAL_VOCABULARY)) {
      // Match term or term+s or term with y→ies plural
      const pluralS = term + 's';
      const pluralIes = term.endsWith('y') ? term.slice(0, -1) + 'ies' : null;

      const matchesTerm = lastWord === term ||
                          lastWord === pluralS ||
                          (pluralIes && lastWord === pluralIes);

      if (matchesTerm) {
        // Check if it's an occurrent type
        if (type === 'Process' || type === 'Process') {
          // V7-008: Accept both full IRI and compact form
          return { isProcess: true, type: 'Process' };
        }
        // Not a process (person, artifact, GDC) - return null to use other classification
        return null;
      }
    }

    // Priority 3: Check result noun exceptions (these override suffix detection)
    if (RESULT_NOUN_EXCEPTIONS[lastWord]) {
      // It's a result noun (product/entity), not a process
      return null;
    }

    // Priority 4: Domain-specific words from config loader (Phase 2)
    // Config loader takes precedence over suffix detection to allow domain-specific
    // type specialization (e.g., "surgery" → ActOfSurgery instead of bfo:BFO_0000015)
    if (this.configLoader && this.configLoader.isConfigLoaded()) {
      const configType = this.configLoader.getProcessRootWord(lastWord);
      if (configType) {
        return { isProcess: true, type: configType };
      }

      // Also check the full phrase for multi-word matches
      const fullPhraseType = this.configLoader.getProcessRootWord(lowerNoun);
      if (fullPhraseType) {
        return { isProcess: true, type: fullPhraseType };
      }
    }

    // Priority 4.5: V7-008 Action nominalizations → Act
    // These are nominalized intentional acts, not generic processes
    const actionNominalizations = new Set([
      'deployment', 'implementation', 'installation', 'configuration',
      'execution', 'operation', 'deployment', 'migration', 'upgrade'
    ]);
    if (actionNominalizations.has(lastWord)) {
      return { isProcess: true, type: 'Act' };
    }

    // Priority 5: Nominalization suffixes - domain-neutral detection mechanism
    // This is the linguistic pattern approach when no config specialization matches
    for (const suffix of PROCESS_SUFFIXES) {
      const cleanSuffix = suffix.replace('-', '');
      if (lastWord.endsWith(cleanSuffix) && lastWord.length > cleanSuffix.length + 2) {
        // Has process suffix and not in exception list → Process
        return { isProcess: true, type: 'Process' }; // V7-008: Use compact form instead of bfo:BFO_0000015
      }
    }

    // Priority 6: Deprecated domain process words (fallback when no config)
    // TD-001: These will be removed after Phase 2 migration is complete
    if (!this.configLoader || !this.configLoader.isConfigLoaded()) {
      for (const [rootWord, type] of Object.entries(DOMAIN_PROCESS_WORDS)) {
        const regex = new RegExp(`\\b${rootWord}\\b`, 'i');
        if (regex.test(lowerNoun)) {
          return { isProcess: true, type };
        }
      }
    }

    return null;
  }

  /**
   * Check if a word is a known result noun or physical entity
   * These are nominalizations that denote products/entities rather than processes.
   *
   * @param {string} word - Word to check
   * @returns {boolean} True if known result noun or physical entity
   */
  _isKnownPhysicalEntity(word) {
    // Use the RESULT_NOUN_EXCEPTIONS constant for comprehensive coverage
    return RESULT_NOUN_EXCEPTIONS.hasOwnProperty(word.toLowerCase());
  }

  /**
   * Check if a noun phrase denotes a temporal region.
   *
   * Detection rules:
   * 1. Quantity + temporal unit ("three days") → bfo:BFO_0000038 (1D Temporal Region)
   * 2. Numeric + temporal unit ("24 hours") → bfo:BFO_0000038
   * 3. Relative prefix + unit ("last week") → bfo:BFO_0000008 (Temporal Region)
   * 4. Standalone relative term ("yesterday") → bfo:BFO_0000008
   *
   * @param {string} lowerNoun - Lowercased noun text
   * @param {string[]} words - Words array
   * @returns {string|null} BFO temporal type IRI or null
   */
  _checkForTemporalType(lowerNoun, words) {
    const lastWord = words[words.length - 1];

    // Rule 1-2: quantity/number + temporal unit → 1D Temporal Region
    if (words.length >= 2 && TEMPORAL_UNITS[lastWord]) {
      const firstWord = words[0];
      if (QUANTITY_WORDS[firstWord] !== undefined || /^\d+$/.test(firstWord)) {
        return 'OneDimensionalTemporalRegion'; // One-Dimensional Temporal Region
      }
    }

    // Rule 3: relative prefix + temporal unit → Temporal Region (unspecified)
    if (words.length >= 2 && TEMPORAL_UNITS[lastWord]) {
      if (RELATIVE_TEMPORAL_PREFIXES.includes(words[0])) {
        return 'TemporalRegion'; // Temporal Region
      }
    }

    // Rule 4: standalone relative temporal term
    if (words.length === 1 && RELATIVE_TEMPORAL_TERMS.includes(lastWord)) {
      return 'TemporalRegion'; // Temporal Region
    }

    return null;
  }

  /**
   * Extract temporal unit from a noun phrase if it is a temporal expression.
   * Used to annotate Tier 1 nodes with tagteam:unit.
   *
   * @param {string} nounText - The noun text
   * @returns {string|null} Normalized unit ("day", "week", etc.) or null
   */
  _extractTemporalUnit(nounText) {
    const words = nounText.toLowerCase().trim().split(/\s+/);
    const lastWord = words[words.length - 1];
    return TEMPORAL_UNITS[lastWord] || null;
  }

  /**
   * Check if a noun phrase denotes a physiological symptom or quality.
   *
   * Detection rules:
   * 1. Full phrase matches a known multi-word symptom phrase ("chest pain", "shortness of breath")
   * 2. Root noun is a known single-word symptom ("cough", "fever", "nausea")
   * 3. Coordinated symptoms: "cough and fever" — check individual conjuncts
   *
   * @param {string} fullNounLower - Full noun phrase, lowercased
   * @param {string} rootNounLower - Root/head noun, lowercased
   * @returns {string|null} 'Quality' (Quality) or null
   */
  _checkForSymptomType(fullNounLower, rootNounLower) {
    // Rule 0: Disease terms → Disposition, NOT Quality
    // Per OGMS/BFO, diseases are dispositions to undergo pathological processes
    if (DISEASE_TERMS.has(rootNounLower)) {
      return 'Disposition'; // V7-008: Use compact form instead of bfo:BFO_0000016
    }
    // Check head word of multi-word root for diseases
    const rootWordsForDisease = rootNounLower.split(/\s+/);
    if (rootWordsForDisease.length > 1) {
      const headForDisease = rootWordsForDisease[rootWordsForDisease.length - 1];
      if (DISEASE_TERMS.has(headForDisease)) {
        return 'Disposition';
      }
    }

    // Rule 0b: Disposition/capability terms → Disposition
    // "capacity", "capability", "ability" etc. are realizable entities, not artifacts
    if (DISPOSITION_TERMS.has(rootNounLower)) {
      return 'Disposition'; // V7-008: Use compact form
    }

    // Rule 0c: Evaluative quality terms → Quality
    // "disaster", "success", "failure", "demand" etc. are evaluative attributes, not artifacts
    if (EVALUATIVE_QUALITY_TERMS.has(rootNounLower)) {
      return 'Quality'; // V7-008: Use compact form instead of bfo:BFO_0000019
    }

    // Rule 1: Multi-word phrase match (symptoms only)
    for (const phrase of SYMPTOM_PHRASES) {
      if (fullNounLower.includes(phrase)) {
        return 'Quality'; // V7-008: Use compact form
      }
    }

    // Rule 2: Single-word root noun match
    if (SYMPTOM_SINGLE_WORDS.has(rootNounLower)) {
      return 'Quality';
    }

    // Rule 3: Strip adjective modifiers and re-check root
    const rootWords = rootNounLower.split(/\s+/);
    if (rootWords.length > 1) {
      const headWord = rootWords[rootWords.length - 1];
      if (SYMPTOM_SINGLE_WORDS.has(headWord)) {
        return 'Quality';
      }
    }

    // Rule 4: Coordinated nouns — "cough and fever"
    // Check individual conjuncts from the full phrase
    if (fullNounLower.includes(' and ')) {
      const conjuncts = fullNounLower.split(/\s+and\s+/);
      const allAreSymptoms = conjuncts.every(c => {
        const trimmed = c.trim();
        // Strip leading adjective modifiers
        const words = trimmed.split(/\s+/);
        const head = words[words.length - 1];
        // Check disease terms first
        if (DISEASE_TERMS.has(head)) return true;
        // Check single word symptoms
        if (SYMPTOM_SINGLE_WORDS.has(head)) return true;
        // Check multi-word
        for (const phrase of SYMPTOM_PHRASES) {
          if (trimmed.includes(phrase)) return true;
        }
        return false;
      });
      if (allAreSymptoms) {
        // If any conjunct is a disease, the whole phrase is a disposition
        const anyDisease = conjuncts.some(c => {
          const head = c.trim().split(/\s+/).pop();
          return DISEASE_TERMS.has(head);
        });
        return anyDisease ? 'Disposition' : 'Quality';
      }
    }

    return null;
  }

  /**
   * ENH-001: Refine entity type based on governing verb context.
   *
   * For ambiguous nouns (design, report, data), the governing verb determines
   * whether the entity is information content (ICE) or physical artifact.
   *
   * - Cognitive verbs (review, analyze, read) → ICE
   * - Physical verbs (build, carry, print) → Artifact
   *
   * Uses IEE-approved guardrail: checks for intervening nouns between verb
   * and entity to avoid misattribution in multi-verb sentences.
   *
   * @param {string} rootNoun - Root noun to check
   * @param {string} fullText - Full input text
   * @param {number} entityOffset - Position of entity in text
   * @returns {Object} { refinedType: string|null, governingVerb: string|null }
   */
  _refineTypeByVerbContext(rootNoun, fullText, entityOffset) {
    const result = { refinedType: null, governingVerb: null };

    // Only refine ambiguous nouns
    const lowerRoot = rootNoun.toLowerCase().trim();
    const words = lowerRoot.split(/\s+/);
    const lastWord = words[words.length - 1];

    if (!AMBIGUOUS_OBJECT_NOUNS.has(lastWord)) {
      return result;
    }

    // Find the governing verb
    const governingVerb = this._findGoverningVerb(fullText, entityOffset, lowerRoot);
    if (!governingVerb) {
      return result;
    }

    // Refine based on verb class
    if (COGNITIVE_VERBS.has(governingVerb)) {
      result.refinedType = 'InformationContentEntity';
      result.governingVerb = governingVerb;
    } else if (PHYSICAL_VERBS.has(governingVerb)) {
      result.refinedType = 'Artifact';
      result.governingVerb = governingVerb;
    }

    return result;
  }

  /**
   * ENH-001: Find the verb that governs an entity as its direct object.
   *
   * Looks backward from the entity position to find the nearest verb.
   * Includes guardrail to check for intervening nouns (IEE requirement).
   *
   * @param {string} fullText - Full input text
   * @param {number} entityOffset - Position of entity in text
   * @param {string} entityText - The entity text (lowercased)
   * @returns {string|null} Governing verb (infinitive) or null
   */
  _findGoverningVerb(fullText, entityOffset, entityText) {
    const doc = nlp(fullText);
    const verbs = doc.verbs();

    let nearestVerb = null;
    let nearestVerbEnd = -1;

    // Find the nearest verb before the entity
    verbs.forEach(verb => {
      const verbText = verb.text().toLowerCase();
      const verbStart = fullText.toLowerCase().indexOf(verbText);
      const verbEnd = verbStart + verbText.length;

      // Verb must be before the entity
      if (verbEnd <= entityOffset && verbEnd > nearestVerbEnd) {
        // Extract infinitive form
        const verbJson = verb.json()[0] || {};
        const verbData = verbJson.verb || {};
        const infinitive = (verbData.infinitive || verbData.root || verbText).toLowerCase();

        nearestVerb = infinitive;
        nearestVerbEnd = verbEnd;
      }
    });

    if (!nearestVerb) {
      return null;
    }

    // IEE Guardrail: Check if another noun intervenes between verb and entity
    // If so, the entity is likely not the direct object of this verb
    const textBetween = fullText.substring(nearestVerbEnd, entityOffset).toLowerCase();

    // Extract nouns from the text between verb and entity
    const betweenDoc = nlp(textBetween);
    const nounsBetween = betweenDoc.nouns().out('array');

    // Filter out determiners and the entity itself
    const interveningNouns = nounsBetween.filter(n => {
      const nLower = n.toLowerCase().trim();
      // Skip if it's just a determiner or part of the target entity
      if (['the', 'a', 'an'].includes(nLower)) return false;
      if (entityText.includes(nLower) || nLower.includes(entityText)) return false;
      return true;
    });

    if (interveningNouns.length > 0) {
      // Another noun intervenes - this verb doesn't govern our entity
      return null;
    }

    return nearestVerb;
  }

  /**
   * ENH-015: Detect the preposition that introduces an entity.
   *
   * Looks backward from the entity position to find a preposition immediately
   * before the noun phrase (accounting for determiners and adjectives).
   *
   * Prepositions tracked: for, with, to, from, by, at, in, on, about, through
   *
   * @param {string} fullText - Full input text
   * @param {number} entityOffset - Position of entity in text
   * @returns {string|null} Introducing preposition or null
   */
  _detectIntroducingPreposition(fullText, entityOffset) {
    // Get text before the entity (look back ~30 chars should be enough)
    const lookbackStart = Math.max(0, entityOffset - 30);
    const textBefore = fullText.substring(lookbackStart, entityOffset).toLowerCase();

    // ENH-015 fix: Match the NEAREST preposition to the entity
    // Pattern: preposition + optional determiner + optional adjectives (non-prep words) + end
    // We need to ensure we don't match prepositions that have other prepositions after them
    const prepositions = ['with', 'for', 'to', 'from', 'by', 'at', 'in', 'on', 'about', 'through', 'into', 'onto', 'upon'];

    // Find all preposition positions
    let lastPrep = null;
    let lastPrepPos = -1;

    for (const prep of prepositions) {
      // Find all occurrences of this preposition
      const regex = new RegExp(`\\b${prep}\\s+(the|a|an)?\\s*`, 'gi');
      let match;
      while ((match = regex.exec(textBefore)) !== null) {
        // Check that no other preposition appears between this one and the end
        const afterMatch = textBefore.substring(match.index + match[0].length);
        const hasLaterPrep = prepositions.some(p =>
          new RegExp(`\\b${p}\\s+(the|a|an)?\\s`).test(afterMatch)
        );

        if (!hasLaterPrep && match.index > lastPrepPos) {
          lastPrep = prep;
          lastPrepPos = match.index;
        }
      }
    }

    return lastPrep;
  }

  /**
   * Analyze noun phrase context for determiner-sensitive disambiguation
   *
   * Based on ONTOLOGICAL_ISSUES_2026_01_19.md v3.1:
   * - Definite determiner ("the X") → favors entity (IC) reading
   * - Indefinite determiner ("some X") → favors process (Occurrent) reading
   * - "X of Y" complement pattern → favors process reading
   * - Bare noun (no determiner) → favors process reading
   *
   * @param {string} nounText - The noun phrase text
   * @param {string} fullText - The full sentence for context
   * @param {Object} definitenessInfo - Definiteness info from _detectDefiniteness
   * @returns {Object} Context hints for disambiguation
   */
  _analyzeNounPhraseContext(nounText, fullText, definitenessInfo) {
    const result = {
      favorsEntity: false,
      favorsProcess: false,
      reason: null
    };

    const lowerFull = fullText.toLowerCase();
    const lowerNoun = nounText.toLowerCase();

    // Check for "X of Y" complement pattern (strongly favors process reading)
    // e.g., "the organization of files" = process, not entity
    const nounIndex = lowerFull.indexOf(lowerNoun);
    if (nounIndex !== -1) {
      const afterNoun = lowerFull.substring(nounIndex + lowerNoun.length).trim();
      if (afterNoun.startsWith('of ')) {
        result.favorsProcess = true;
        result.reason = 'of-complement';
        return result;
      }
    }

    // Check determiner
    if (definitenessInfo.definiteness === 'definite') {
      // "the administration" → entity reading (the organization)
      result.favorsEntity = true;
      result.reason = 'definite-determiner';
    } else if (definitenessInfo.determiner === null) {
      // Bare noun → process reading
      result.favorsProcess = true;
      result.reason = 'bare-noun';
    } else {
      // Indefinite → process reading
      result.favorsProcess = true;
      result.reason = 'indefinite-determiner';
    }

    return result;
  }

  /**
   * Determine entity type for denotesType property
   *
   * BFO/CCO compliance: Distinguishes between:
   * - Continuants (objects): Person, Artifact
   * - Occurrents (processes): ActOfCare, ActOfMedicalTreatment, etc.
   *
   * Uses determiner-sensitive disambiguation for ambiguous nominalizations.
   *
   * @param {string} nounText - The noun text
   * @param {Object} [context] - Additional context
   * @param {string} [context.fullText] - Full sentence for context analysis
   * @param {Object} [context.definitenessInfo] - Definiteness info
   * @returns {string} Entity type IRI
   */
  _determineEntityType(nounText, context = {}) {
    const lowerNoun = nounText.toLowerCase().trim();
    const words = lowerNoun.split(/\s+/);
    const lastWord = words[words.length - 1];

    // Priority -2: V7-006 Proper name detection
    // If definitenessInfo indicates this is a proper name, infer type from structure
    if (context.definitenessInfo && context.definitenessInfo.isProperName) {
      const originalNoun = nounText.trim();  // Keep original case
      const firstWord = originalNoun.split(/\s+/)[0];

      // Titles indicate person
      const titles = ['Dr', 'Dr.', 'Mr', 'Mr.', 'Mrs', 'Mrs.', 'Ms', 'Ms.', 'Prof', 'Prof.'];
      if (titles.some(t => firstWord.startsWith(t))) {
        return 'Person';
      }

      // Multi-word capitalized names are usually persons or organizations
      // Heuristic: if 2-3 words and all capitalized → Person (e.g., "John Smith")
      // If includes common org indicators → Organization
      const orgIndicators = ['Inc', 'Corp', 'LLC', 'Ltd', 'Company', 'Corporation', 'Foundation'];
      const hasOrgIndicator = orgIndicators.some(ind => originalNoun.includes(ind));

      if (hasOrgIndicator) {
        return 'Organization';
      }

      // V7-Priority5: Product names (software, hardware)
      // Common technology product names should be classified as Artifacts
      const productNames = [
        'Windows', 'Linux', 'macOS', 'iOS', 'Android',
        'Chrome', 'Firefox', 'Safari', 'Edge',
        'Office', 'Excel', 'Word', 'PowerPoint',
        'Photoshop', 'Illustrator',
        'MySQL', 'PostgreSQL', 'MongoDB', 'Redis',
        'Docker', 'Kubernetes',
        'AWS', 'Azure', 'GCP'
      ];
      if (productNames.includes(originalNoun)) {
        return 'Artifact';
      }

      // Single capitalized word: could be person name, product name, or location
      // Default to Person for short single words (common first names)
      // This is a heuristic - proper classification needs context
      if (words.length === 1 && originalNoun.length <= 8) {
        return 'Person';  // Likely a first name
      }

      // Multi-word (2-3 words) all capitalized → Person
      if (words.length >= 2 && words.length <= 3) {
        return 'Person';  // Likely "FirstName LastName"
      }

      // Fall through to other detection for proper nouns we can't classify
    }

    // Priority -1: Pronoun type mapping (IEE realist specification)
    // Pronouns carry selectional presuppositions about ontological category
    if (words.length === 1 && PRONOUN_TYPE_MAPPINGS[lowerNoun]) {
      return PRONOUN_TYPE_MAPPINGS[lowerNoun];
    }

    // Priority 0: Compound noun analysis
    // If the noun phrase has multiple words, check if compound context favors process
    // e.g., "medication administration" → process (administering medication)
    //       "file organization" → process (organizing files)
    if (words.length > 1 && AMBIGUOUS_NOMINALIZATIONS[lastWord]) {
      // Check if any modifier word is a known entity type (suggests process reading)
      // "medication administration" - medication is artifact, so this is about administering it
      const modifiers = words.slice(0, -1);
      for (const modifier of modifiers) {
        // If modifier is a known entity/artifact, compound likely denotes process
        if (UNAMBIGUOUS_RESULT_NOUNS[modifier] ||
            ENTITY_TYPE_MAPPINGS[modifier] ||
            ['patient', 'file', 'data', 'drug', 'medication', 'document'].includes(modifier)) {
          return 'Process'; // Process reading for compound
        }
      }
    }

    // Priority 1: Unambiguous result nouns - ALWAYS return the product type
    // "medication" is always the drug, "documentation" is always the document
    if (UNAMBIGUOUS_RESULT_NOUNS[lastWord]) {
      return UNAMBIGUOUS_RESULT_NOUNS[lastWord];
    }

    // Priority 2: Ambiguous nominalizations - use determiner-sensitive defaults
    // "organization" can be the company (entity) or organizing (process)
    if (AMBIGUOUS_NOMINALIZATIONS[lastWord] && context.definitenessInfo && context.fullText) {
      const nounContext = this._analyzeNounPhraseContext(
        nounText,
        context.fullText,
        context.definitenessInfo
      );

      if (nounContext.favorsProcess && nounContext.reason === 'of-complement') {
        // "organization of files" → process reading
        return 'Process';
      }

      if (nounContext.favorsEntity) {
        // "the administration" → entity reading
        return AMBIGUOUS_NOMINALIZATIONS[lastWord];
      }

      // Bare/indefinite with ambiguous noun → default to entity (more common usage)
      // Note: v3.1 spec says default to process, but entity is safer for most cases
      return AMBIGUOUS_NOMINALIZATIONS[lastWord];
    }

    // Handle ambiguous nominalizations without context (fallback to entity reading)
    if (AMBIGUOUS_NOMINALIZATIONS[lastWord]) {
      return AMBIGUOUS_NOMINALIZATIONS[lastWord];
    }

    // Standard process detection (domain-neutral)
    const processCheck = this._checkForProcessType(lowerNoun, context);
    if (processCheck) {
      return processCheck.type;
    }

    // Check for known entity types (continuants)
    // Use word-boundary matching to avoid substring false positives
    // e.g., "demand" should NOT match "man", "command" should NOT match "man"
    // Also match common plural forms (keyword + "s" or "es")
    for (const [keyword, type] of Object.entries(ENTITY_TYPE_MAPPINGS)) {
      if (keyword === '_default') continue;
      const regex = new RegExp(`\\b${keyword}(?:e?s)?\\b`, 'i');
      if (regex.test(lowerNoun)) {
        return type;
      }
    }

    // Temporal Region detection
    // "three days" (quantity + temporal unit) → bfo:BFO_0000038 (1D Temporal Region)
    // "yesterday", "recently" → bfo:BFO_0000008 (Temporal Region)
    // "last week" (relative prefix + unit) → bfo:BFO_0000008
    const temporalType = this._checkForTemporalType(lowerNoun, words);
    if (temporalType) {
      return temporalType;
    }

    // Direct ONTOLOGICAL_VOCABULARY lookup for non-process types (ICE, GDC, etc.)
    // _checkForProcessType only returns process types; this catches the rest
    // Try exact match first, then simple singularization for plurals
    const vocabType = ONTOLOGICAL_VOCABULARY[lastWord]
      || (lastWord.endsWith('ies') ? ONTOLOGICAL_VOCABULARY[lastWord.slice(0, -3) + 'y'] : null)
      || (lastWord.endsWith('ses') || lastWord.endsWith('zes') || lastWord.endsWith('xes') || lastWord.endsWith('ches') || lastWord.endsWith('shes')
          ? ONTOLOGICAL_VOCABULARY[lastWord.slice(0, -2)] : null)
      || (lastWord.endsWith('s') && !lastWord.endsWith('ss') ? ONTOLOGICAL_VOCABULARY[lastWord.slice(0, -1)] : null);
    if (vocabType && vocabType !== 'Process') {
      return vocabType;
    }

    return ENTITY_TYPE_MAPPINGS['_default'];
  }

  /**
   * Determine referential status based on context
   * @param {Object} definitenessInfo - Definiteness info
   * @param {string} nounText - The noun text
   * @param {string} fullText - Full input text
   * @param {number} index - Entity index in sequence
   * @returns {string} Referential status
   */
  _determineReferentialStatus(definitenessInfo, nounText, fullText, index) {
    const lowerText = fullText.toLowerCase();
    const lowerNoun = nounText.toLowerCase().trim();

    // Modal adjectives on the noun itself → hypothetical
    // "possible diabetes", "suspected infection", "likely pneumonia"
    const modalAdjectives = ['possible', 'likely', 'probable', 'suspected', 'potential',
      'presumed', 'apparent', 'alleged', 'uncertain', 'questionable'];
    const firstWord = lowerNoun.split(/\s+/)[0];
    if (modalAdjectives.includes(firstWord)) {
      return 'hypothetical';
    }

    // Hypothetical markers in surrounding context
    const hypotheticalMarkers = ['if', 'would', 'could', 'might', 'suppose', 'assuming', 'hypothetically'];
    for (const marker of hypotheticalMarkers) {
      if (lowerText.includes(marker)) {
        // Check if marker is near this noun
        const nounIndex = lowerText.indexOf(nounText.toLowerCase());
        const markerIndex = lowerText.indexOf(marker);
        if (markerIndex !== -1 && markerIndex < nounIndex && (nounIndex - markerIndex) < 50) {
          return 'hypothetical';
        }
      }
    }

    // Anaphoric: pronouns or "the [noun]" when noun was mentioned before
    const pronouns = ['he', 'she', 'it', 'they', 'him', 'her', 'them', 'his', 'their'];
    if (pronouns.includes(nounText.toLowerCase())) {
      return 'anaphoric';
    }

    // If definite and not first mention, likely presupposed
    if (definitenessInfo.definiteness === 'definite') {
      return 'presupposed';
    }

    // Indefinite typically introduces new referent
    return 'introduced';
  }

  /**
   * Get span offset for entity in text
   * @param {string} fullText - Full input text
   * @param {string} entityText - Entity text
   * @param {number} index - Entity index
   * @returns {number} Character offset
   */
  _getSpanOffset(fullText, entityText, index) {
    const lowerText = fullText.toLowerCase();
    const lowerEntity = entityText.toLowerCase();

    let offset = 0;
    let searchStart = 0;

    // Find nth occurrence
    for (let i = 0; i <= index; i++) {
      const found = lowerText.indexOf(lowerEntity, searchStart);
      if (found === -1) break;
      offset = found;
      searchStart = found + 1;
    }

    return offset;
  }

  /**
   * Create a DiscourseReferent node (Tier 1)
   *
   * v2.2 spec properties:
   * - sourceText, startPosition, endPosition (instead of extracted_from_span, span_offset)
   * - denotesType kept for backward compatibility (deprecated; use is_about to Tier 2)
   *
   * V7-006: Multi-type classification
   * - @type array includes both DiscourseReferent AND specific CCO/BFO types
   * - Follows RoleDetector pattern for multi-type entities
   *
   * @param {Object} entityInfo - Entity information
   * @returns {Object} DiscourseReferent node
   */
  _createDiscourseReferent(entityInfo) {
    // Generate IRI
    let iri;
    if (this.graphBuilder) {
      iri = this.graphBuilder.generateIRI(
        entityInfo.text,
        'DiscourseReferent',
        entityInfo.offset
      );
    } else {
      // Fallback simple IRI
      const cleanText = entityInfo.text.replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');
      iri = `inst:${cleanText}_Referent_${entityInfo.offset}`;
    }

    // Calculate end position
    const endPosition = entityInfo.offset + entityInfo.text.length;

    // V7-006: Build @type array with specific CCO/BFO type + DiscourseReferent
    // Similar to RoleDetector's multi-type pattern
    const types = [];

    // Add specific CCO/BFO type first (e.g., Person, Artifact)
    if (entityInfo.entityType) {
      types.push(entityInfo.entityType);
    }

    // Add DiscourseReferent (discourse-level classification)
    types.push('tagteam:DiscourseReferent');

    // Add owl:NamedIndividual (OWL requirement)
    types.push('owl:NamedIndividual');

    // Build node with v2.2 properties
    const node = {
      '@id': iri,
      '@type': types,
      'rdfs:label': entityInfo.text,

      // v2.2 position properties
      'tagteam:sourceText': entityInfo.text,
      'tagteam:startPosition': entityInfo.offset,
      'tagteam:endPosition': endPosition,

      // Discourse properties
      'tagteam:definiteness': entityInfo.definiteness,
      'tagteam:referentialStatus': entityInfo.referentialStatus,

      // Legacy compatibility: denotesType (deprecated in v2.2, use is_about instead)
      // Kept for backward compatibility with existing tests
      'tagteam:denotesType': entityInfo.entityType
    };

    // Add scarcity if detected
    if (entityInfo.scarcity && entityInfo.scarcity.isScarce) {
      node['tagteam:is_scarce'] = true;
      node['tagteam:scarcity_marker'] = entityInfo.scarcity.marker;
    }

    // Add quantity if detected
    if (entityInfo.quantity && entityInfo.quantity.quantity !== null) {
      node['tagteam:quantity'] = entityInfo.quantity.quantity;
    }

    // Add temporal unit if this is a temporal entity
    if (entityInfo.temporalUnit) {
      node['tagteam:unit'] = entityInfo.temporalUnit;
    }

    // ENH-001: Add typeRefinedBy if entity type was refined by verb context
    if (entityInfo.typeRefinedBy) {
      node['tagteam:typeRefinedBy'] = entityInfo.typeRefinedBy;
    }

    // ENH-015: Add introducing preposition for role mapping
    if (entityInfo.introducingPreposition) {
      node['tagteam:introducingPreposition'] = entityInfo.introducingPreposition;
    }

    return node;
  }

  /**
   * Set the graph builder for IRI generation
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
    this.tier2Factory.setGraphBuilder(graphBuilder);
  }

  /**
   * Set the document IRI for Tier 2 entity scoping
   * @param {string} documentIRI - Document/IBE IRI
   */
  setDocumentIRI(documentIRI) {
    this.tier2Factory.setDocumentIRI(documentIRI);
  }

  /**
   * Get the Tier 2 factory for direct access
   * @returns {RealWorldEntityFactory} The factory instance
   */
  getTier2Factory() {
    return this.tier2Factory;
  }

  /**
   * Set the domain config loader for type specialization
   *
   * Phase 2: When a config loader is set, domain-specific process words
   * are loaded from the config instead of using the deprecated
   * DOMAIN_PROCESS_WORDS constant.
   *
   * @param {Object|null} configLoader - DomainConfigLoader instance or null to clear
   */
  setConfigLoader(configLoader) {
    this.configLoader = configLoader;
  }

  /**
   * Get domain-specific type from config loader
   *
   * @param {string} term - The term to look up
   * @param {string} bfoType - The BFO base type
   * @returns {string|null} Specialized type or null
   * @private
   */
  _getConfigSpecializedType(term, bfoType) {
    if (!this.configLoader || !this.configLoader.isConfigLoaded()) {
      return null;
    }

    // First check process root words (domain-specific terms like "care", "surgery")
    const processType = this.configLoader.getProcessRootWord(term);
    if (processType) {
      return processType;
    }

    // Then check type specializations for the BFO type
    return this.configLoader.getTypeSpecialization(bfoType, term);
  }
}



  // ============================================================================
  // ACT EXTRACTOR (Phase 4 - Week 1)
  // ============================================================================

/**
 * ActExtractor.js
 *
 * Extracts intentional acts from verb phrases and creates
 * IntentionalAct nodes for the semantic graph.
 *
 * Phase 4 Two-Tier Architecture (v2.2 spec):
 * - Acts link to Tier 2 entities (Person, Artifact) via has_agent/affects
 * - All acts have actualityStatus (Prescribed, Actual, Negated, etc.)
 * - Supports negation detection for Negated status
 *
 * Phase 3: Selectional Restrictions
 * - Verb sense disambiguation based on direct object ontological type
 * - "provide care" → ActOfService, "provide medication" → ActOfTransferOfPossession
 * - Config loader can override restrictions for domain-specific behavior
 *
 * @module graph/ActExtractor
 * @version 4.0.0-phase4
 */

/**
 * Default act type for all extracted verb phrases.
 * All acts are IntentionalAct (verified, ont00000228).
 * The verb lemma (tagteam:lemma) and rdfs:label provide classification
 * breadcrumbs for downstream consumers. Sub-typing is the knowledge
 * graph's responsibility, not the parser's.
 */
const DEFAULT_ACT_TYPE = 'IntentionalAct';

/**
 * Verb infinitive corrections
 * Maps Compromise's truncated/irregular lemmas to correct base forms
 * Fixes: "sent"→"send", "receiv"→"receive", "configur"→"configure"
 */
const VERB_INFINITIVE_CORRECTIONS = {
  // Irregular past tense forms
  'sent': 'send',
  'gave': 'give',
  'got': 'get',
  'received': 'receive',
  'built': 'build',
  'left': 'leave',
  'meant': 'mean',
  'kept': 'keep',
  'slept': 'sleep',
  'felt': 'feel',
  'held': 'hold',
  'told': 'tell',
  'sold': 'sell',
  'showed': 'show',
  'taught': 'teach',
  'offered': 'offer',
  'lent': 'lend',
  'passed': 'pass',
  'handed': 'hand',

  // V7.3: Additional irregular forms for oblique role detection
  'operated': 'operate',
  'explained': 'explain',
  'brought': 'bring',
  'caused': 'cause',
  'transported': 'transport',

  // Compromise truncations (missing final 'e')
  'receiv': 'receive',
  'configur': 'configure',
  'manag': 'manage',
  'produc': 'produce',
  'provid': 'provide',
  'requir': 'require',
  'achiev': 'achieve',
  'believ': 'believe',
  'recogniz': 'recognize',
  'realiz': 'realize',
  'caus': 'cause',
  'updat': 'update',
  'creat': 'create',
  'generat': 'generate',
  'operat': 'operate',
  'observ': 'observe',
  'resolv': 'resolve',
  'delet': 'delete',
  'complet': 'complete',
  'execut': 'execute'
};

/**
 * Verbs that, when used with an inanimate subject, indicate an inference
 * or clinical finding rather than an intentional act.
 * "Blood sugar levels suggest diabetes" → InformationContentEntity, not IntentionalAct
 */
const INFERENCE_VERBS = new Set([
  'suggest', 'indicate', 'show', 'reveal', 'demonstrate',
  'imply', 'point', 'confirm', 'support', 'correlate'
]);

/**
 * Control verbs — verbs that take infinitive complements.
 * "He needs to drop" → "need" is control verb, "drop" is the semantic act.
 * The control verb contributes modality; the infinitive is the actual IntentionalAct.
 */
const CONTROL_VERBS = new Set([
  'need', 'want', 'try', 'attempt', 'decide', 'plan', 'intend',
  'aim', 'seek', 'refuse', 'fail', 'agree', 'promise', 'offer',
  'choose', 'manage', 'expect', 'hope', 'wish', 'prefer',
  'demand', 'require'
]);

/**
 * Modality contributed by control verbs.
 * null = no deontic modality (e.g., "try", "attempt" — aspectual only)
 */
const CONTROL_VERB_MODALITY = {
  'need': 'obligation',
  'require': 'obligation',
  'demand': 'obligation',
  'promise': 'obligation',
  'want': 'intention',
  'intend': 'intention',
  'plan': 'intention',
  'decide': 'intention',
  'choose': 'intention',
  'aim': 'intention',
  'seek': 'intention',
  'hope': 'intention',
  'wish': 'intention',
  'expect': 'intention',
  'agree': 'intention',
  'prefer': 'recommendation',
  'offer': 'permission',
  'refuse': 'prohibition',
  'try': null,
  'attempt': null,
  'fail': null,
  'manage': null
};

/**
 * Ergative/unaccusative verbs — verbs where the subject is the patient/theme,
 * not the agent. "The server rebooted" = server undergoes rebooting (patient).
 * With inanimate subjects, these verbs indicate a process happening TO the subject.
 * With animate subjects, agent reading may still be valid ("He rebooted the server").
 */
const ERGATIVE_VERBS = new Set([
  'reboot', 'restart', 'crash', 'break', 'fail', 'collapse', 'freeze',
  'stall', 'malfunction', 'overheat', 'explode', 'implode', 'melt',
  'dissolve', 'evaporate', 'corrode', 'deteriorate', 'degrade',
  'sink', 'capsize', 'derail', 'rupture', 'fracture', 'shatter',
  'start', 'stop', 'open', 'close', 'change', 'move', 'grow',
  'shrink', 'expand', 'increase', 'decrease', 'improve', 'worsen',
  'sound', 'ring', 'buzz', 'beep', 'flash', 'chime', 'blare', 'tick',
  'emit', 'glow', 'shine', 'flicker', 'hum', 'vibrate', 'rattle'  // ENH-008: emission verbs
]);

// Always-ergative verbs: always intransitive. The inanimate subject is never an intentional agent,
// even when cross-clause linking falsely assigns a patient. These bypass the !links.patient guard.
// Includes emission verbs (sound, ring) and dysfunction verbs (fail, malfunction).
const ALWAYS_ERGATIVE_VERBS = new Set([
  // Emission verbs
  'sound', 'ring', 'buzz', 'beep', 'flash', 'chime', 'blare', 'tick',
  'glow', 'shine', 'flicker', 'hum', 'vibrate', 'rattle',
  'emit',  // ENH-008: "The sensor emitted a signal" → sensor is not agent
  // Dysfunction/state-change verbs (always intransitive when inanimate)
  'fail', 'malfunction', 'stall', 'freeze', 'overheat',
  'corrode', 'deteriorate', 'degrade'
]);

/**
 * Deontic modality mappings
 * Maps modal auxiliaries to modality types
 *
 * Phase 6.4: Extended deontic vocabulary based on BFO-based deontic ontology
 * and Hohfeldian fundamental legal concepts.
 */
const MODALITY_MAPPINGS = {
  // Obligation (duty to act)
  'must': 'obligation',
  'shall': 'obligation',           // Added - legal/formal
  'have to': 'obligation',
  'need to': 'obligation',
  'required': 'obligation',
  'obligated': 'obligation',       // Added

  // Permission (liberty to act)
  'may': 'permission',
  'can': 'permission',
  'allowed': 'permission',
  'permitted': 'permission',       // Added
  'free to': 'permission',         // Added

  // Prohibition (duty not to act)
  'must not': 'prohibition',
  'shall not': 'prohibition',      // Added - legal/formal
  'cannot': 'prohibition',
  'may not': 'prohibition',
  'not allowed': 'prohibition',    // Added

  // Recommendation (soft obligation)
  'should': 'recommendation',
  'ought': 'recommendation',
  'advisable': 'recommendation',   // Added

  // Intention
  'will': 'intention',
  'would': 'intention',
  'going to': 'intention'
};

/**
 * Extended lexical deontic markers
 * Maps lexical patterns to modality types (beyond modal auxiliaries)
 *
 * Phase 6.4: Hohfeldian deontic concepts
 */
const LEXICAL_DEONTIC_MARKERS = {
  // Claim/Right (Hohfeldian claim - correlative of duty)
  claim: {
    patterns: [
      /\b(is|are)\s+entitled\s+to\b/i,
      /\b(has|have)\s+(the\s+)?right\s+to\b/i,
      /\bhas\s+the\s+right\b/i,
      /\bdeserves?\s+\w+/i,
      /\b(is|are)\s+owed\b/i,
      /\bdue\s+to\b/i,
      /\bentitled\s+to\b/i
    ],
    singleWords: ['entitled', 'deserves', 'deserve', 'owed']
  },

  // Power/Authority (Hohfeldian power - ability to change normative relations)
  power: {
    patterns: [
      /\b(is|are)\s+authorized\s+to\b/i,
      /\b(is|are)\s+empowered\s+to\b/i,
      /\bempowers?\s+\w+/i,
      /\bdelegates?\s+\w+/i,
      /\bgrants?\s+\w+/i,
      /\bconfers?\s+\w+/i,
      /\bauthorize[sd]?\s+to\b/i
    ],
    singleWords: ['authorize', 'authorizes', 'authorized', 'empower', 'empowers', 'empowered',
                  'delegate', 'delegates', 'delegated', 'grant', 'grants', 'granted',
                  'confer', 'confers', 'conferred']
  },

  // Immunity (Hohfeldian immunity - protection from power)
  immunity: {
    patterns: [
      /\b(is|are)\s+exempt\s+from\b/i,
      /\b(is|are)\s+immune\s+(from|to)\b/i,
      /\b(is|are)\s+protected\s+from\b/i,
      /\bexempt\s+from\b/i,
      /\bprotected\s+from\b/i,
      /\bimmune\s+(from|to)\b/i
    ],
    singleWords: ['exempt', 'exempted', 'immune']
  },

  // Enhanced prohibition detection
  prohibition: {
    patterns: [
      /\b(is|are)\s+forbidden\s+(to|from)\b/i,
      /\b(is|are)\s+prohibited\s+from\b/i,
      /\b(is|are)\s+not\s+allowed\s+to\b/i,
      /\b(is|are)\s+banned\s+from\b/i,
      /\bforbidden\s+(to|from)\b/i,
      /\bprohibited\s+from\b/i
    ],
    singleWords: ['forbidden', 'prohibited', 'banned']
  },

  // Enhanced permission detection
  permission: {
    patterns: [
      /\b(is|are)\s+allowed\s+to\b/i,
      /\b(is|are)\s+permitted\s+to\b/i
    ],
    singleWords: []
  },

  // Enhanced obligation detection
  obligation: {
    patterns: [
      /\b(is|are)\s+required\s+to\b/i,
      /\b(is|are)\s+obligated\s+to\b/i
    ],
    singleWords: ['required', 'obligated']
  }
};

/**
 * Modality to ActualityStatus mapping
 * Maps deontic modality to appropriate actuality status
 *
 * Phase 6.4: Extended with Hohfeldian-based status values
 */
const MODALITY_TO_STATUS = {
  // Existing
  'obligation': 'tagteam:Prescribed',
  'permission': 'tagteam:Permitted',
  'prohibition': 'tagteam:Prohibited',
  'recommendation': 'tagteam:Prescribed', // Recommendations are a softer form of prescription
  'intention': 'tagteam:Planned',
  'hypothetical': 'tagteam:Hypothetical',

  // Phase 6.4: New Hohfeldian-based statuses
  'claim': 'tagteam:Entitled',            // Right-holder status
  'power': 'tagteam:Empowered',           // Authority status
  'immunity': 'tagteam:Protected'         // Protection status
};

/**
 * Modality to Deontic Type mapping
 * Maps modality to Hohfeldian deontic classification
 *
 * Phase 6.4: For advanced normative relation analysis
 */
const MODALITY_TO_DEONTIC_TYPE = {
  'obligation': 'duty',
  'permission': 'privilege',
  'prohibition': 'duty',        // duty NOT to act
  'recommendation': 'soft_duty',
  'claim': 'claim',
  'power': 'power',
  'immunity': 'immunity',
  'intention': null,
  'hypothetical': null
};

// Selectional Restrictions removed — all acts are IntentionalAct.
// Verb sense disambiguation (ditransitive, communication, transfer) is
// handled by verb class sets (COMMUNICATION_VERBS, TRANSFER_VERBS, etc.)
// for NLP behavior, not for @type emission.

/**
 * BFO type categories for ontological classification
 * Maps denotesType values to ontological categories.
 * Only verified BFO/CCO IRIs.
 */
const TYPE_TO_CATEGORY = {
  // Occurrents (processes)
  'Process': 'occurrent',
  'IntentionalAct': 'occurrent',
  'ActOfCommunication': 'occurrent',

  // Independent Continuants (physical things)
  'MaterialEntity': 'continuant',
  'MaterialEntity': 'continuant',
  'Artifact': 'continuant',
  'Facility': 'continuant',

  // Persons
  'Person': 'person',
  'Agent': 'person',

  // Organizations (treated as continuant for selectional purposes)
  'Organization': 'continuant',
  'GeopoliticalOrganization': 'continuant',

  // Generically Dependent Continuants (information)
  'GenericallyDependentContinuant': 'gdc',
  'InformationContentEntity': 'gdc'
};

/**
 * ActExtractor class - extracts acts and creates IntentionalAct nodes
 *
 * Two-Tier Architecture (v2.2):
 * - Links to Tier 2 entities via is_about resolution
 * - Adds actualityStatus to all acts
 */
class ActExtractor {
  /**
   * Create a new ActExtractor
   * @param {Object} options - Configuration options
   * @param {Object} [options.graphBuilder] - SemanticGraphBuilder instance
   * @param {Array} [options.entities] - Previously extracted entities for linking
   * @param {boolean} [options.linkToTier2=true] - Link to Tier 2 entities instead of Tier 1
   */
  constructor(options = {}) {
    this.options = {
      linkToTier2: true,
      ...options
    };
    this.graphBuilder = options.graphBuilder || null;
    this.entities = options.entities || [];
    this._sentenceModeClassifier = new SentenceModeClassifier();
    // ENH-003: Track implicit "you" entity for reuse across imperatives
    this._implicitYouEntity = null;
  }

  /**
   * Extract acts from text and return IntentionalAct nodes
   *
   * Phase 6.4: Enhanced to detect sentence-level deontic patterns
   * that Compromise NLP may miss.
   *
   * @param {string} text - Input text to analyze
   * @param {Object} [options] - Extraction options
   * @param {Array} [options.entities] - Entities for linking
   * @returns {Array<Object>} Array of IntentionalAct nodes
   */
  extract(text, options = {}) {
    const acts = [];
    const entities = options.entities || this.entities;
    const cdSpans = options.complexDesignatorSpans || [];


    // ENH-003: Reset implicit "you" tracking for fresh text
    this._resetImplicitYou();

    // Phase 6.4: First detect sentence-level deontic patterns
    // These may not be captured by Compromise NLP verb extraction
    const sentenceDeontic = this._detectSentenceLevelDeontic(text, entities);
    if (sentenceDeontic) {
      acts.push(sentenceDeontic);
    }

    // Parse with Compromise NLP
    const doc = nlp(text);

    // Extract verbs
    const verbs = doc.verbs();

    // V7-003: Morphological fallback for verbs Compromise misses
    // Compromise sometimes tags present tense verbs (e.g., "restarts", "completes") as nouns
    const morphologicalVerbs = this._findMorphologicalVerbs(text, doc, verbs);

    // V7.4 DUPLICATE-FIX: Keep verb objects (not strings) to preserve infinitive metadata
    // Before: verbs.out('array') returned strings like "was treated"
    // Now: Iterate verb objects directly to access verbData.infinitive
    const verbObjects = [];
    verbs.forEach(verb => verbObjects.push(verb));
    const allVerbs = [...verbObjects, ...morphologicalVerbs];

    // Pass 1: Collect verb entries, identifying control verbs and infinitive complements
    const verbEntries = [];
    allVerbs.forEach((verb, index) => {
      // V7.4 DUPLICATE-FIX: Handle both Compromise verb objects and plain strings from morphological detection
      // For objects, extract text using verb.text() method
      const verbText = typeof verb === 'string' ? verb : (verb.text ? verb.text() : String(verb));
      const verbJson = typeof verb === 'object' && verb.json ? (verb.json()[0] || {}) : {};
      const verbData = verbJson.verb || {};

      // For morphological verbs (strings), create minimal verbData
      if (typeof verb === 'string') {
        let infinitive = this._getInfinitive(verb);
        // V7-009: Apply infinitive corrections for truncated/irregular forms
        infinitive = VERB_INFINITIVE_CORRECTIONS[infinitive] || infinitive;
        verbEntries.push({
          verbText: verb,
          verbData: {},
          infinitive,
          isInfinitive: false,
          isControlVerb: CONTROL_VERBS.has(infinitive.toLowerCase()),
          index,
          morphological: true
        });
        return;
      }
      // For Compromise verb objects
      if (this._isAuxiliaryOnly(verbData)) return;

      // Get infinitive and strip "to " prefix if present (e.g., "to allocate" → "allocate")
      let infinitive = verbData.infinitive || verbData.root || verbText;
      if (infinitive.toLowerCase().startsWith('to ')) {
        infinitive = infinitive.substring(3);
      }
      // V7-009: Apply infinitive corrections for truncated/irregular forms
      infinitive = VERB_INFINITIVE_CORRECTIONS[infinitive] || infinitive;
      const isInfinitive = !!(verbData.grammar?.isInfinitive && !verbData.auxiliary);
      const isControlVerb = CONTROL_VERBS.has(infinitive.toLowerCase());

      verbEntries.push({ verbText, verbData, infinitive, isInfinitive, isControlVerb, index });
    });

    // Detect interrogative mood (question mark at end of text)
    const isInterrogative = text.trim().endsWith('?');

    // Detect imperative mood: sentence starts with a base-form verb and has no explicit subject
    // e.g., "Submit the report by Friday." — verb-initial, no pronoun/noun subject before verb
    const isImperative = this._isImperativeSentence(text, doc);

    // Do-support filtering: "Did he approve?" → "did" is auxiliary, not a separate act
    // If a do-form verb coexists with other non-do verbs, remove the do-form
    const hasDoForm = verbEntries.some(e => this._isDoForm(e.infinitive));
    const hasNonDoVerb = verbEntries.some(e => !this._isDoForm(e.infinitive));
    if (hasDoForm && hasNonDoVerb) {
      // Remove do-support entries (they carry tense but not semantic content)
      for (let i = verbEntries.length - 1; i >= 0; i--) {
        if (this._isDoForm(verbEntries[i].infinitive)) {
          verbEntries.splice(i, 1);
        }
      }
    }

    // Pass 2: Pair control verbs with their infinitive complements
    const consumedIndices = new Set();
    for (let i = 0; i < verbEntries.length; i++) {
      const entry = verbEntries[i];
      if (entry.isControlVerb && i + 1 < verbEntries.length && verbEntries[i + 1].isInfinitive) {
        // Control verb + infinitive pair found
        // Mark control verb as consumed — the infinitive becomes the primary act
        consumedIndices.add(i);
        // Tag the infinitive with the control verb's modality
        verbEntries[i + 1]._controlVerb = entry.infinitive.toLowerCase();
        verbEntries[i + 1]._controlModality = CONTROL_VERB_MODALITY[entry.infinitive.toLowerCase()] || null;
        // Inherit the control verb's sourceText span for combined sourceText
        verbEntries[i + 1]._controlVerbText = entry.verbText;
      }
    }

    verbEntries.forEach((entry, i) => {
      // Skip consumed control verbs (absorbed into infinitive complement)
      if (consumedIndices.has(i)) return;

      // Skip standalone infinitives not preceded by a control verb
      if (entry.isInfinitive && !entry._controlVerb) return;

      const { verbText, verbData, index } = entry;
      const infinitive = entry.infinitive;

      // Get span offset
      const offset = this._getSpanOffset(text, verbText, index);

      // Phase 7 v7: Skip verbs that fall inside ComplexDesignator spans
      if (cdSpans.length > 0) {
        const verbEnd = offset + verbText.length;
        const insideCD = cdSpans.some(span =>
          offset >= span.start && verbEnd <= span.end
        );
        if (insideCD) return; // Skip — this "verb" is part of a proper name
      }

      // Phase 7 v7: Check if verb is stative — route to StructuralAssertion instead of IntentionalAct
      const followedBy = this._getWordAfterVerb(text, offset, verbText);
      const verbClassification = this._sentenceModeClassifier.classifyVerb(infinitive, { followedBy });

      // Phase 7 v7: In STRUCTURAL mode, suppress non-stative verbs that appear
      // BEFORE the stative verb (participial adjectives like "named" in "Complexly named organizations include...")
      // Verbs after the stative verb are allowed (mixed sentences: "includes X and decided to Y")
      if (options.sentenceMode === 'STRUCTURAL' &&
          verbClassification.category !== 'STATIVE_DEFINITE' &&
          verbClassification.category !== 'STATIVE_AMBIGUOUS') {
        // Find the first stative verb's offset to determine if this verb precedes it
        const firstStativeEntry = verbEntries.find(ve => {
          const inf = ve.infinitive.toLowerCase();
          const fb = this._getWordAfterVerb(text, this._getSpanOffset(text, ve.verbText, ve.index), ve.verbText);
          const cls = this._sentenceModeClassifier.classifyVerb(inf, { followedBy: fb });
          return cls.category === 'STATIVE_DEFINITE' || cls.category === 'STATIVE_AMBIGUOUS';
        });
        if (firstStativeEntry) {
          const stativeOffset = this._getSpanOffset(text, firstStativeEntry.verbText, firstStativeEntry.index);
          if (offset < stativeOffset) {
            return; // Skip pre-stative participial adjective verbs
          }
        }
      }

      if (verbClassification.category === 'STATIVE_DEFINITE') {
        const links = this._linkToEntities(text, verbText, offset, entities);
        const assertion = this._createStructuralAssertion({
          text: verbText,
          infinitive,
          offset,
          relation: verbClassification.relation,
          inverse: verbClassification.inverse,
          links,
          sourceText: text,
          complexDesignatorNodes: options.complexDesignatorNodes || []
        });
        acts.push(assertion);
        return; // Skip IntentionalAct creation
      }

      if (verbClassification.category === 'STATIVE_AMBIGUOUS') {
        const links = this._linkToEntities(text, verbText, offset, entities);
        // Get object entity type for disambiguation
        const objectEntity = links.patientEntity || links.affectedEntity;
        const objectType = objectEntity?.['@type']?.[0] || objectEntity?.['tagteam:denotesType'] || null;
        const objectLabel = objectEntity?.['rdfs:label'] || null;
        const subjectEntity = links.agentEntity || links.subjectEntity;
        const subjectType = subjectEntity?.['@type']?.[0] || subjectEntity?.['tagteam:denotesType'] || null;

        const disambiguation = this._sentenceModeClassifier.disambiguateStativeVerb(infinitive, {
          objectType, objectLabel, subjectType
        });

        if (disambiguation === 'STATIVE') {
          const stativeRelation = this._sentenceModeClassifier.getRelationForStativeVerb(infinitive);
          const assertion = this._createStructuralAssertion({
            text: verbText,
            infinitive,
            offset,
            relation: stativeRelation,
            inverse: null,
            links,
            sourceText: text,
            complexDesignatorNodes: options.complexDesignatorNodes || []
          });
          acts.push(assertion);
          return; // Skip IntentionalAct creation
        }
        // Otherwise fall through to eventive processing
      }

      // Phase 3: Get direct object type for selectional restrictions
      const directObjectType = this._getDirectObjectType(offset, entities);

      // Determine CCO act type (with selectional restrictions if object type available)
      const actType = this._determineActType(infinitive, { directObjectType });

      // Phase 6.4: Enhanced modality detection with lexical markers
      const modalityResult = this._detectModalityEnhanced(verbData, text);
      let modality = modalityResult.modality;
      let deonticType = modalityResult.deonticType;

      // Control verb complement: inherit modality from the control verb
      let controlVerb = null;
      if (entry._controlVerb) {
        controlVerb = entry._controlVerb;
        if (entry._controlModality && !modality) {
          modality = entry._controlModality;
          // Map modality to deontic type
          const MODALITY_TO_DEONTIC = {
            'obligation': 'tagteam:Obligation',
            'permission': 'tagteam:Permission',
            'prohibition': 'tagteam:Prohibition',
            'recommendation': 'tagteam:Recommendation',
            'intention': 'tagteam:Intention'
          };
          deonticType = MODALITY_TO_DEONTIC[modality] || null;
        }
      }

      // Detect negation
      const negation = verbData.negative || false;

      // Extract tense info
      const tense = this._extractTense(verbData);

      // Link to entities (agent, patient, affected)
      // For infinitive complements, use the control verb's position for entity linking
      // since the agent ("He") is syntactically tied to the control verb
      const linkText = entry._controlVerbText || verbText;
      const linkOffset = entry._controlVerbText
        ? this._getSpanOffset(text, entry._controlVerbText, 0)
        : offset;
      const links = this._linkToEntities(text, linkText, linkOffset, entities);

      // Passive voice detection: "X was found [by Y]" → X is patient, Y is agent
      // V7-009d: Use both Compromise grammar.passive flag AND "by" phrase detection
      // (morphological verbs don't have grammar data, so we need the "by" fallback)
      const hasPassiveFlag = !!(verbData.grammar?.passive);
      const byAgent = this._findByAgent(text, { start: offset, end: offset + verbText.length }, entities);
      const isPassive = hasPassiveFlag || byAgent; // Passive if flag OR "by X" phrase detected

      const passiveSubjectIRI = links.agent || links.subjectIRI;
      const passiveSubjectEntity = links.agentEntity || links.subjectEntity;
      if (isPassive && passiveSubjectIRI) {
        // In passive voice, the grammatical subject (pre-verb) is the patient, not the agent
        // Save the subject for patient assignment
        const passiveSubject = passiveSubjectIRI;

        // byAgent was already detected above for passive detection
        if (byAgent) {
          links.agent = byAgent.iri;
          links.agentEntity = byAgent.entity;
          // The entity after "by" is the agent, not the patient
          // Clear patient if it was assigned to the by-agent
          if (links.patient === byAgent.iri) {
            links.patient = null;
            links.patientEntity = null;
          }
        } else {
          // No explicit agent — agent is unknown/implicit
          links.agent = null;
          links.agentEntity = null;
        }

        // The grammatical subject becomes the patient (affected entity)
        links.patient = passiveSubject;
        links.patientEntity = passiveSubjectEntity;
      }

      // ENH-003: Implicit agent for imperatives
      // If this is an imperative sentence, use implicit "you" as agent
      // Exception: if there's an explicit "You" subject pronoun, keep it
      if (isImperative) {
        // Check if the found agent is an explicit "you" pronoun
        const agentLabel = links.agentEntity?.['rdfs:label']?.toLowerCase();
        const hasExplicitYou = agentLabel === 'you';

        if (!hasExplicitYou) {
          // Use implicit "you" - override any incorrectly assigned agent
          const implicitYou = this._getOrCreateImplicitYou();
          links.agent = implicitYou['@id'];
          links.agentEntity = implicitYou;
          links.isImplicitAgent = true;
        }
      }

      // Phase 7.0 Story 3: Inanimate agent re-typing
      // If an inference verb has an inanimate subject, create ICE instead of IntentionalAct
      // Use subjectEntity (includes qualities/temporals) not agentEntity (excludes them)
      const subjectEntity = links.subjectEntity || links.agentEntity;
      if (INFERENCE_VERBS.has(infinitive.toLowerCase()) &&
          subjectEntity && this._isInanimateAgent(subjectEntity)) {
        // Use subject as the "about" source even if filtered from agent
        const inferenceLinks = {
          ...links,
          agent: links.subjectIRI || links.agent,
          agentEntity: subjectEntity
        };
        const inferenceNode = this._createInferenceNode({
          text: verbText,
          infinitive,
          offset,
          links: inferenceLinks
        });
        acts.push(inferenceNode);
        return; // Skip IntentionalAct creation for this verb
      }

      // Ergative verb check: "The server rebooted" → server is patient, not agent
      // When an ergative verb has an inanimate subject and no object, demote agent to participant
      // Always-ergative verbs (emission + dysfunction) always demote — they can never have intentional agents
      const isAlwaysErgative = ALWAYS_ERGATIVE_VERBS.has(infinitive.toLowerCase());
      if (ERGATIVE_VERBS.has(infinitive.toLowerCase()) && links.agentEntity &&
          this._isInanimateAgent(links.agentEntity) && (isAlwaysErgative || !links.patient)) {
        // Demote: agent becomes participant, no agent
        if (!links.participants) links.participants = [];
        links.participants.push(links.agent);
        // ENH-008: Only set agent as patient if no existing patient
        // "The alarm sounded the warning" → warning is patient, alarm is participant
        if (!links.patient) {
          links.patient = links.agent; // The subject undergoes the process
        }
        links.agent = null;
        links.agentEntity = null;
      }

      // Build sourceText: include control verb span if present
      const sourceText = entry._controlVerbText
        ? `${entry._controlVerbText} to ${verbText}`
        : verbText;

      // Actuality overrides:
      // - Interrogative sentences: the act is queried, not asserted
      // - Imperative sentences: the act is commanded, not yet realized
      // - Infinitive complements of control verbs: not yet realized
      let actualityOverride = null;
      if (isInterrogative) {
        actualityOverride = 'tagteam:Interrogative';
      } else if (isImperative) {
        actualityOverride = 'tagteam:Prescribed';
      } else if (controlVerb) {
        actualityOverride = 'tagteam:Prescribed';
      }

      // Create IntentionalAct node (Phase 6.4: includes deonticType)
      const act = this._createIntentionalAct({
        text: sourceText,
        infinitive,
        offset,
        actType,
        modality,
        deonticType,
        negation,
        tense,
        links,
        controlVerb,
        actualityOverride
      });

      acts.push(act);
    });

    // ENH-003: Attach implicit entities to result for graph builder to include
    // Using a property on the array to maintain backward compatibility
    acts._implicitEntities = this._implicitYouEntity ? [this._implicitYouEntity] : [];

    return acts;
  }

  /**
   * ENH-003: Get any implicit entities created during extraction.
   * These should be added to the graph as Tier 2 entities.
   *
   * @returns {Array<Object>} Implicit entities (e.g., implicit "you" for imperatives)
   */
  getImplicitEntities() {
    return this._implicitYouEntity ? [this._implicitYouEntity] : [];
  }

  /**
   * Phase 7 v7: Get the word immediately following the verb in the text.
   * Used for "have to" detection.
   */
  _getWordAfterVerb(text, offset, verbText) {
    const afterIndex = offset + verbText.length;
    const rest = text.slice(afterIndex).trimStart();
    const match = rest.match(/^(\w+)/);
    return match ? match[1].toLowerCase() : null;
  }

  /**
   * Phase 7 v7: Create a StructuralAssertion node for stative verbs.
   * Instead of IntentionalAct + AgentRole/PatientRole, stative verbs produce
   * a subject-relation-object assertion with no act semantics.
   */
  _createStructuralAssertion({ text, infinitive, offset, relation, inverse, links, sourceText, complexDesignatorNodes }) {
    let id;
    if (this.graphBuilder) {
      id = this.graphBuilder.generateIRI(infinitive, 'StructuralAssertion', offset);
    } else {
      const cleanVerb = infinitive.replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');
      id = `inst:StructuralAssertion_${cleanVerb}_${offset}`;
    }

    const subject = links.agent || links.subjectIRI || null;

    const node = {
      '@id': id,
      '@type': ['tagteam:StructuralAssertion'],
      'tagteam:verb': infinitive,
      'tagteam:assertsRelation': relation,
      'tagteam:sourceText': sourceText
    };

    if (subject) {
      node['tagteam:hasSubject'] = { '@id': subject };
    }

    // Phase 7 v7: If ComplexDesignator nodes exist, wire hasObject to them
    // instead of the old fragmented entity references
    if (complexDesignatorNodes && complexDesignatorNodes.length > 0) {
      if (complexDesignatorNodes.length === 1) {
        node['tagteam:hasObject'] = { '@id': complexDesignatorNodes[0]['@id'] };
      } else {
        node['tagteam:hasObject'] = complexDesignatorNodes.map(cd => ({ '@id': cd['@id'] }));
      }
    } else {
      const object = links.patient || links.affected || null;
      if (object) {
        node['tagteam:hasObject'] = { '@id': object };
      }
    }

    if (inverse) {
      node['tagteam:inverseRelation'] = inverse;
    }

    return node;
  }

  /**
   * V7-003: Find verbs using morphological patterns (fallback for Compromise misses)
   * @param {string} text - Full text
   * @param {Object} doc - Compromise doc
   * @param {Object} compromiseVerbs - Verbs found by Compromise
   * @returns {Array<string>} Array of verb strings found morphologically
   */
  _findMorphologicalVerbs(text, doc, compromiseVerbs) {
    const compromiseVerbTexts = new Set(compromiseVerbs.out('array'));
    const morphologicalVerbs = [];
    const words = text.split(/\s+/);

    // V7.4 DUPLICATE-FIX: Get nouns from Compromise to avoid treating them as verbs
    // "The hospital charged the patient excessive fees" → "fees" is noun, not verb
    const compromiseNouns = new Set();
    doc.nouns().forEach(noun => {
      // Extract individual words from noun phrases
      const nounWords = noun.text().toLowerCase().split(/\s+/);
      nounWords.forEach(w => compromiseNouns.add(w));
    });

    // Common verb endings
    const verbPatterns = [
      /s$/,           // present tense 3rd person (fails, runs, completes, restarts)
      /ed$/,          // past tense (failed, completed, restarted)
      /ing$/,         // present participle (failing, running, completing)
      /es$/,          // present tense (goes, does, reaches)
      /ied$/          // past tense -y verbs (tried, replied)
    ];

    // Common verbs that Compromise often misses
    const commonVerbs = new Set([
      'fails', 'fail', 'failed', 'receives', 'receive', 'received',
      'completes', 'complete', 'completed', 'restarts', 'restart', 'restarted',
      'runs', 'run', 'ran', 'locks', 'lock', 'locked', 'expires', 'expire', 'expired',
      'approves', 'approve', 'approved', 'blocks', 'block', 'blocked',
      'finishes', 'finish', 'finished', 'launches', 'launch', 'launched',
      'starts', 'start', 'started', 'loads', 'load', 'loaded',
      'stops', 'stop', 'stopped', 'increases', 'increase', 'increased',
      'rises', 'rise', 'rose', 'goes', 'go', 'went', 'does', 'do', 'did',
      'designs', 'design', 'designed', 'stores', 'store', 'stored',
      'handles', 'handle', 'handled', 'crashes', 'crash', 'crashed',
      'hires', 'hire', 'hired', 'resigns', 'resign', 'resigned',
      'deploys', 'deploy', 'deployed', 'fixes', 'fix', 'fixed',
      'files', 'file', 'filed', 'causes', 'cause', 'caused',
      'responds', 'respond', 'responded', 'leaves', 'leave', 'left'
    ]);

    // Determiners indicate the following word is likely a noun, not a verb
    const determiners = new Set(['the', 'a', 'an', 'this', 'that', 'these', 'those']);

    for (let i = 0; i < words.length; i++) {
      const word = words[i];
      const clean = word.toLowerCase().replace(/[.,;:!?]$/, '');
      const prevWord = i > 0 ? words[i - 1].toLowerCase().replace(/[.,;:!?]$/, '') : null;

      // V7.4 DUPLICATE-FIX: Skip if already found by Compromise (exact match)
      if (compromiseVerbTexts.has(word)) continue;

      // V7.4 DUPLICATE-FIX: Skip if word is part of a Compromise verb phrase
      // e.g., "was treated" contains "treated", "has been running" contains "running"
      // This prevents creating duplicate Acts for passive voice and compound tenses
      const isPartOfCompromiseVerb = Array.from(compromiseVerbTexts).some(verbPhrase => {
        // Check if the verb phrase contains this word as a complete word (not substring)
        // "treated" should match in "was treated", but "eat" should not match in "treated"
        const phraseWords = verbPhrase.toLowerCase().split(/\s+/);
        return phraseWords.includes(clean);
      });
      if (isPartOfCompromiseVerb) continue;

      // Skip if too short
      if (clean.length < 3) continue;

      // Skip if preceded by a determiner (likely a noun, not a verb)
      // e.g., "the load increases" → "load" is a noun
      if (prevWord && determiners.has(prevWord)) continue;

      // V7.4 DUPLICATE-FIX: Skip if Compromise identified this word as a noun
      // "fees" in "excessive fees" should not be treated as verb
      if (compromiseNouns.has(clean)) continue;

      // Check if it's a known verb
      if (commonVerbs.has(clean)) {
        morphologicalVerbs.push(word);
        continue;
      }

      // Check if it matches verb patterns
      const matchesVerbPattern = verbPatterns.some(pattern => pattern.test(clean));
      if (matchesVerbPattern && clean.length > 3) {
        // Exclude non-verbs that happen to match verb patterns
        const nonVerbExceptions = [
          // Common nouns ending in -s/-ss (singular)
          'class', 'business', 'address', 'process', 'access', 'success', 'progress',
          // Common plural nouns that look like verbs
          'errors', 'orders', 'offers', 'users', 'servers', 'systems', 'processes',
          'requests', 'responses', 'issues', 'changes', 'updates', 'patches',
          'loads', 'metrics', 'alerts', 'messages', 'events', 'tasks',
          // Subordinating conjunctions
          'unless', 'as',
          // Other function words
          'this', 'thus', 'yes'
        ];
        if (!nonVerbExceptions.includes(clean)) {
          morphologicalVerbs.push(word);
        }
      }
    }

    return morphologicalVerbs;
  }

  /**
   * V7-003: Get infinitive form of a verb
   * @param {string} verb - Verb text
   * @returns {string} Infinitive form
   */
  _getInfinitive(verb) {
    const clean = verb.toLowerCase().replace(/[.,;:!?]$/, '');

    // Irregular verbs
    const irregulars = {
      'ran': 'run', 'went': 'go', 'did': 'do', 'was': 'be', 'were': 'be',
      'had': 'have', 'has': 'have', 'is': 'be', 'are': 'be',
      'left': 'leave', 'rose': 'rise'
    };

    if (irregulars[clean]) return irregulars[clean];

    // Regular patterns
    if (clean.endsWith('ies')) return clean.slice(0, -3) + 'y';  // tries → try
    if (clean.endsWith('ied')) return clean.slice(0, -3) + 'y';  // tried → try
    if (clean.endsWith('es')) return clean.slice(0, -2);         // goes → go
    if (clean.endsWith('ed')) return clean.slice(0, -2);         // failed → fail
    if (clean.endsWith('ing')) return clean.slice(0, -3);        // failing → fail
    if (clean.endsWith('s')) return clean.slice(0, -1);          // fails → fail

    return clean;
  }

  /**
   * Check if verb is auxiliary only (no main verb content)
   * @param {Object} verbData - Compromise verb data
   * @returns {boolean} True if auxiliary only
   */
  _isAuxiliaryOnly(verbData) {
    const auxOnlyVerbs = ['be', 'is', 'are', 'was', 'were', 'been', 'being'];
    // Phase 7 v7: "have/has/had" removed from aux-only list — they can be stative main verbs
    // (e.g., "The hospital has two ventilators"). The stative check in the verb loop handles routing.
    const haveVerbs = ['have', 'has', 'had'];
    const root = (verbData.infinitive || verbData.root || '').toLowerCase();
    if (auxOnlyVerbs.includes(root) && !verbData.auxiliary) return true;
    // For have/has/had: only filter if it's truly auxiliary (another main verb exists)
    if (haveVerbs.includes(root) && !verbData.auxiliary) {
      // Check if Compromise detected it as a standalone verb (no participle follows)
      const text = verbData.text || '';
      // If the verb phrase is just "has"/"have"/"had" with no participle, it's a main verb
      return false;
    }
    return false;
  }

  /**
   * Check if a verb is do-support (auxiliary "do/did/does" in questions/negation)
   * Do-support is auxiliary when another main verb exists in the sentence.
   * "Did he approve?" → "did" is auxiliary, "approve" is main verb.
   * "He did the dishes" → "did" is main verb (no other verb).
   * @param {string} root - Verb root/infinitive
   * @returns {boolean} True if this is a do-form
   */
  _isDoForm(root) {
    return ['do', 'did', 'does'].includes(root.toLowerCase());
  }

  /**
   * Detect imperative mood: sentence starts with a base-form verb, no explicit subject.
   * "Submit the report by Friday." → imperative (verb-initial, no subject)
   * "He submits the report." → NOT imperative (has subject "He")
   * "Please submit the report." → imperative (polite marker + verb)
   * @param {string} text - Full sentence text
   * @param {Object} doc - Compromise NLP document
   * @returns {boolean} True if sentence is imperative
   */
  _isImperativeSentence(text, doc) {
    const trimmed = text.trim();
    // Questions are not imperatives
    if (trimmed.endsWith('?')) return false;

    // ENH-003: Polite imperative markers that can precede the verb
    const politeMarkers = ['please', 'kindly', 'just'];

    // Get the words of the sentence
    const words = trimmed.split(/\s+/).map(w => w.replace(/[^a-zA-Z]/g, '').toLowerCase());
    if (words.length === 0) return false;

    let firstWord = words[0];
    let verbIndex = 0;

    // Skip polite markers to find the main verb
    if (politeMarkers.includes(firstWord)) {
      if (words.length < 2) return false;
      firstWord = words[1];
      verbIndex = 1;
    }

    // Check if first word is a verb (base form) by looking at Compromise's analysis
    // Also check: no subject pronoun or noun before the first verb
    const nouns = doc.nouns().out('array');

    // If the sentence starts with a noun/pronoun before the verb, it's not imperative
    // Simple heuristic: if the first word is a known subject pronoun or the first noun
    // appears at position 0, it has a subject
    const subjectPronouns = ['i', 'you', 'he', 'she', 'it', 'we', 'they',
                             'who', 'what', 'which', 'that', 'this', 'these', 'those'];
    if (subjectPronouns.includes(firstWord)) return false;

    // Check if first word appears to be a noun (starts with capital in non-initial position doesn't help here)
    // Instead: check if the first token is tagged as a verb by Compromise
    const terms = doc.json()[0]?.terms || [];
    if (terms.length <= verbIndex) return false;

    const verbTerm = terms[verbIndex];
    const verbTags = verbTerm?.tags || [];
    // Compromise tags can be array of strings or object with boolean values
    const tagList = Array.isArray(verbTags) ? verbTags : Object.keys(verbTags);

    // Compromise tags: check if the word is tagged as Verb
    const isVerbWord = tagList.some(t => t === 'Verb' || t === 'Infinitive' || t === 'Imperative');

    if (!isVerbWord) return false;

    // Additional: the first word should NOT be tagged as a Noun (e.g., "Report" could be noun or verb)
    // If it's ONLY a verb tag (not also noun), it's more likely imperative
    // But if it has both Verb and Noun tags, check if a determiner follows (not imperative)
    // For now, trust that verb-initial + no subject pronoun = imperative
    return true;
  }

  /**
   * Determine CCO act type from verb infinitive
   *
   * Phase 3: Now supports selectional restrictions - if direct object type
   * is provided, uses it to disambiguate verb sense.
   *
   * @param {string} infinitive - Verb infinitive form
   * @param {Object} [context] - Optional context for selectional restrictions
   * @param {string} [context.directObjectType] - BFO/CCO type of direct object
   * @returns {string} CCO act type IRI
   */
  _determineActType(infinitive, context = {}) {
    // All acts are IntentionalAct. Verb identity is preserved in
    // tagteam:lemma and rdfs:label for downstream consumers.
    return DEFAULT_ACT_TYPE;
  }

  /**
   * Get ontological category from a BFO/CCO type
   *
   * @param {string} type - BFO/CCO type IRI
   * @returns {string} Category: 'occurrent', 'continuant', 'gdc', 'person', or 'unknown'
   * @private
   */
  _getOntologicalCategory(type) {
    // Check direct mapping
    if (TYPE_TO_CATEGORY[type]) {
      return TYPE_TO_CATEGORY[type];
    }

    // Heuristic fallbacks based on type name patterns
    const lowerType = type.toLowerCase();

    // Occurrents (processes/acts)
    if (lowerType.includes('act') || lowerType.includes('process') ||
        lowerType.includes('event') || lowerType.includes('bfo_0000015')) {
      return 'occurrent';
    }

    // Persons
    if (lowerType.includes('person') || lowerType.includes('patient') ||
        lowerType.includes('physician') || lowerType.includes('nurse') ||
        lowerType.includes('agent')) {
      return 'person';
    }

    // GDC (information entities)
    if (lowerType.includes('information') || lowerType.includes('document') ||
        lowerType.includes('bfo_0000031')) {
      return 'gdc';
    }

    // Default to continuant (physical things)
    return 'continuant';
  }

  /**
   * Get the direct object type from entities near the verb
   *
   * Phase 3: Finds the entity immediately after the verb and returns
   * its denotesType for selectional restriction matching.
   *
   * @param {number} verbOffset - Character offset of verb in text
   * @param {Array} entities - Available entities (Tier 1 referents)
   * @returns {string|null} Direct object's denotesType or null
   * @private
   */
  _getDirectObjectType(verbOffset, entities) {
    if (!entities || entities.length === 0) {
      return null;
    }

    // Filter to only Tier 1 DiscourseReferents
    const referents = entities.filter(e =>
      e['@type'] && e['@type'].includes('tagteam:DiscourseReferent')
    );

    if (referents.length === 0) {
      return null;
    }

    // Find entities after the verb
    const entitiesAfter = referents.filter(entity => {
      const entityStart = this._getEntityStart(entity);
      return entityStart > verbOffset;
    });

    if (entitiesAfter.length === 0) {
      return null;
    }

    // Get the closest entity after the verb (likely direct object)
    const directObject = entitiesAfter.reduce((closest, entity) => {
      const entityStart = this._getEntityStart(entity);
      const closestStart = this._getEntityStart(closest);
      return entityStart < closestStart ? entity : closest;
    });

    // Return its denotesType
    return directObject['tagteam:denotesType'] || null;
  }

  /**
   * Detect deontic modality from verb data and text
   *
   * Phase 6.4: Enhanced to detect both auxiliary-based modals
   * and lexical deontic markers.
   *
   * @param {Object} verbData - Compromise verb data
   * @param {string} [text] - Full text for lexical marker detection
   * @returns {Object} Detection result { modality, markers, confidence, deonticType }
   */
  _detectModality(verbData, text = '') {
    const result = {
      modality: null,
      markers: [],
      confidence: 0,
      deonticType: null
    };

    const auxiliary = (verbData.auxiliary || '').toLowerCase().trim();

    // 1. Check auxiliary-based modality (highest confidence)
    if (auxiliary) {
      // Check for known modality mappings
      if (MODALITY_MAPPINGS[auxiliary]) {
        result.modality = MODALITY_MAPPINGS[auxiliary];
        result.markers.push({ type: 'auxiliary', text: auxiliary });
        result.confidence = 0.9;
      } else {
        // Check for compound modals (e.g., "have to")
        for (const [modal, modality] of Object.entries(MODALITY_MAPPINGS)) {
          if (auxiliary.includes(modal)) {
            result.modality = modality;
            result.markers.push({ type: 'auxiliary', text: modal });
            result.confidence = 0.85;
            break;
          }
        }
      }
    }

    // 2. Check lexical deontic markers if text provided
    if (text) {
      const lexicalResult = this._detectLexicalDeonticMarkers(text);
      // Use lexical result if no auxiliary detected or lexical has higher confidence
      if (lexicalResult.modality && (!result.modality || lexicalResult.confidence > result.confidence)) {
        result.modality = lexicalResult.modality;
        result.markers = result.markers.concat(lexicalResult.markers);
        result.confidence = Math.max(result.confidence, lexicalResult.confidence);
      }
    }

    // 3. Add deontic type classification
    if (result.modality && MODALITY_TO_DEONTIC_TYPE[result.modality]) {
      result.deonticType = MODALITY_TO_DEONTIC_TYPE[result.modality];
    }

    // Return just the modality for backward compatibility
    // The enhanced info is available via _detectModalityEnhanced
    return result.modality;
  }

  /**
   * Detect deontic modality with full result object
   *
   * Phase 6.4: Returns complete detection result including markers and confidence.
   *
   * @param {Object} verbData - Compromise verb data
   * @param {string} [text] - Full text for lexical marker detection
   * @returns {Object} { modality, markers, confidence, deonticType }
   */
  _detectModalityEnhanced(verbData, text = '') {
    const result = {
      modality: null,
      markers: [],
      confidence: 0,
      deonticType: null
    };

    const auxiliary = (verbData.auxiliary || '').toLowerCase().trim();

    // 1. Check auxiliary-based modality
    if (auxiliary) {
      if (MODALITY_MAPPINGS[auxiliary]) {
        result.modality = MODALITY_MAPPINGS[auxiliary];
        result.markers.push({ type: 'auxiliary', text: auxiliary });
        result.confidence = 0.9;
      } else {
        for (const [modal, modality] of Object.entries(MODALITY_MAPPINGS)) {
          if (auxiliary.includes(modal)) {
            result.modality = modality;
            result.markers.push({ type: 'auxiliary', text: modal });
            result.confidence = 0.85;
            break;
          }
        }
      }
    }

    // 2. Check lexical deontic markers
    if (text) {
      const lexicalResult = this._detectLexicalDeonticMarkers(text);
      if (lexicalResult.modality && (!result.modality || lexicalResult.confidence > result.confidence)) {
        result.modality = lexicalResult.modality;
        result.markers = result.markers.concat(lexicalResult.markers);
        result.confidence = Math.max(result.confidence, lexicalResult.confidence);
      }
    }

    // 3. Add deontic type
    if (result.modality && MODALITY_TO_DEONTIC_TYPE[result.modality]) {
      result.deonticType = MODALITY_TO_DEONTIC_TYPE[result.modality];
    }

    return result;
  }

  /**
   * Detect lexical deontic markers in text
   *
   * Phase 6.4: Detects deontic markers like "entitled", "authorized", "forbidden"
   * that are not auxiliary modals but carry deontic meaning.
   *
   * @param {string} text - Text to analyze
   * @returns {Object} { modality, markers, confidence }
   * @private
   */
  _detectLexicalDeonticMarkers(text) {
    const result = {
      modality: null,
      markers: [],
      confidence: 0
    };

    if (!text) return result;

    const lowerText = text.toLowerCase();

    // Check each modality's lexical patterns
    for (const [modality, config] of Object.entries(LEXICAL_DEONTIC_MARKERS)) {
      // Check multi-word patterns first (higher specificity)
      for (const pattern of config.patterns || []) {
        const match = text.match(pattern);
        if (match) {
          result.modality = modality;
          result.markers.push({ type: 'lexical_pattern', text: match[0] });
          result.confidence = 0.85;
          return result; // Return on first match
        }
      }

      // Check single words
      for (const word of config.singleWords || []) {
        if (lowerText.includes(word)) {
          // Verify it's a word boundary match
          const wordPattern = new RegExp(`\\b${word}\\b`, 'i');
          if (wordPattern.test(text)) {
            result.modality = modality;
            result.markers.push({ type: 'lexical_word', text: word });
            result.confidence = 0.75;
            return result; // Return on first match
          }
        }
      }
    }

    return result;
  }

  /**
   * Extract tense information
   * @param {Object} verbData - Compromise verb data
   * @returns {Object} Tense info
   */
  _extractTense(verbData) {
    const grammar = verbData.grammar || {};
    return {
      tense: grammar.tense || 'present',
      form: grammar.form || 'simple',
      aspect: this._determineAspect(grammar.form)
    };
  }

  /**
   * Determine grammatical aspect from form
   * @param {string} form - Verb form
   * @returns {string} Aspect
   */
  _determineAspect(form) {
    if (!form) return 'simple';
    if (form.includes('progressive') || form.includes('continuous')) return 'progressive';
    if (form.includes('perfect')) return 'perfect';
    return 'simple';
  }

  /**
   * Find the agent in a passive "by [agent]" phrase.
   * E.g., "The report was reviewed by the committee." → committee is agent.
   * @param {string} text - Full input text
   * @param {Object} verbOffset - Verb offset info
   * @param {Array} entities - All entities
   * @returns {Object|null} { iri, entity } or null if no "by" agent found
   */
  _findByAgent(text, verbOffset, entities) {
    if (!entities || entities.length === 0) return null;

    const lowerText = text.toLowerCase();
    const verbEnd = verbOffset.end || verbOffset.start + 10;

    // Look for "by" after the verb
    const byIndex = lowerText.indexOf(' by ', verbEnd - 1);
    if (byIndex === -1) return null;

    // Find an entity that starts after "by"
    const byPos = byIndex + 4; // position after "by "
    const referents = entities.filter(e =>
      e['@type'] && e['@type'].includes('tagteam:DiscourseReferent')
    );

    const linkMap = this.options.linkToTier2 ? this._buildTier2LinkMap(entities) : new Map();
    const resolveIRI = (referentIRI) => {
      if (this.options.linkToTier2 && linkMap.has(referentIRI)) {
        return linkMap.get(referentIRI);
      }
      return referentIRI;
    };

    for (const entity of referents) {
      const start = this._getEntityStart(entity);
      // Entity must start near the "by" position (within ~5 chars to account for determiners)
      if (start >= byPos - 1 && start <= byPos + 10) {
        return { iri: resolveIRI(entity['@id']), entity };
      }
    }

    return null;
  }

  /**
   * Get start position from entity (supports both v2.2 and legacy properties)
   * @param {Object} entity - Entity node
   * @returns {number} Start position
   * @private
   */
  _getEntityStart(entity) {
    // v2.2 property
    if (entity['tagteam:startPosition'] !== undefined) {
      return entity['tagteam:startPosition'];
    }
    // Legacy property
    if (entity['tagteam:span_offset']?.[0] !== undefined) {
      return entity['tagteam:span_offset'][0];
    }
    return 0;
  }

  /**
   * Get end position from entity (supports both v2.2 and legacy properties)
   * @param {Object} entity - Entity node
   * @returns {number} End position
   * @private
   */
  _getEntityEnd(entity) {
    // v2.2 property
    if (entity['tagteam:endPosition'] !== undefined) {
      return entity['tagteam:endPosition'];
    }
    // Legacy property
    if (entity['tagteam:span_offset']?.[1] !== undefined) {
      return entity['tagteam:span_offset'][1];
    }
    return 0;
  }

  /**
   * Build a map from Tier 1 referent IRI to Tier 2 entity IRI
   *
   * @param {Array} entities - All entities (both Tier 1 and Tier 2)
   * @returns {Map<string, string>} Map from referent IRI to Tier 2 IRI
   * @private
   */
  _buildTier2LinkMap(entities) {
    const linkMap = new Map();

    // Find all referents with is_about links
    entities.forEach(entity => {
      if (entity['is_about']) {
        // Handle both object notation { '@id': iri } and plain string
        const isAbout = entity['is_about'];
        const iri = typeof isAbout === 'object' ? isAbout['@id'] : isAbout;
        linkMap.set(entity['@id'], iri);
      }
    });

    return linkMap;
  }

  /**
   * V7-010: Find all entities that are coordinated with the given entity.
   *
   * When EntityExtractor splits "X and Y" into separate entities, both are marked
   * with `tagteam:isConjunct: true` and `tagteam:coordinationType: 'and'|'or'`.
   *
   * This method finds all entities that share the same coordination context,
   * allowing ActExtractor to assign the same role to all conjuncts.
   *
   * Linguistic Foundation: Penn Treebank coordination rules
   * - "The engineer and the admin" → both should be agents of the same verb
   * - "configured the server and the database" → both should be patients
   *
   * @param {Object} entity - The entity to find coordination partners for
   * @param {Array} entityPool - Pool of candidate entities to search
   * @returns {Array} - All coordinated entities including the input entity
   */
  _findCoordinatedEntities(entity, entityPool) {
    // If entity is not marked as conjunct, return it alone
    if (!entity['tagteam:isConjunct']) {
      return [entity];
    }

    const coordinationType = entity['tagteam:coordinationType'];
    const entityOffset = this._getEntityStart(entity);

    // Find all entities in the pool that:
    // 1. Are marked as conjuncts
    // 2. Have the same coordination type ('and' or 'or')
    // 3. Are close to each other (within ~100 characters - coordination span)
    const COORDINATION_WINDOW = 100; // Max distance between coordinated entities

    const coordinated = entityPool.filter(e => {
      // Must be a conjunct
      if (!e['tagteam:isConjunct']) return false;

      // Must have same coordination type
      if (e['tagteam:coordinationType'] !== coordinationType) return false;

      // Must be within coordination window
      const eOffset = this._getEntityStart(e);
      const distance = Math.abs(eOffset - entityOffset);
      return distance <= COORDINATION_WINDOW;
    });

    // Return all coordinated entities, sorted by position
    return coordinated.sort((a, b) => {
      return this._getEntityStart(a) - this._getEntityStart(b);
    });
  }

  /**
   * V7-004/V7-005: Find the correct agent for a verb, accounting for relative clauses
   *
   * Handles four patterns:
   * 1. Explicit relativizers: "The engineer who designed the system left"
   * 2. Nested relatives: "The user who filed the issue that caused the crash responded"
   * 3. Zero relativizers: "The patch the team deployed fixed the bug" (reduced relative)
   * 4. Prepositional relatives: "The server on which the app runs is offline" (V7-005)
   *
   * Heuristics:
   * - If explicit relativizer exists → use farthest entity
   * - If prepositional relative (PREP + RELATIVIZER) → use farthest entity
   * - If no relativizer but multiple entities + embedded verbs → zero relativizer → use farthest entity
   * - Otherwise → use closest entity (normal SVO)
   *
   * @param {string} fullText - Full input text
   * @param {number} verbOffset - Position of verb
   * @param {Array} entitiesBefore - Entities before the verb
   * @returns {Object|null} Entity to use as agent
   */
  _findAgentForVerb(fullText, verbOffset, entitiesBefore) {
    const RELATIVIZERS = ['who', 'whom', 'whose', 'which', 'that'];
    const PREPOSITIONS = ['on', 'in', 'at', 'to', 'from', 'with', 'by', 'for', 'of', 'about', 'through', 'during', 'after', 'before'];

    // Sort entities by end position
    const sorted = [...entitiesBefore].sort((a, b) => {
      const endA = this._getEntityEnd(a);
      const endB = this._getEntityEnd(b);
      return endA - endB; // Ascending: farthest first
    });

    if (sorted.length === 0) return null;

    // Check if ANY relativizer exists between any entity and the target verb
    let hasRelativizer = false;

    for (const entity of sorted) {
      const entityEnd = this._getEntityEnd(entity);
      const textBetween = fullText.substring(entityEnd, verbOffset).toLowerCase();
      const words = textBetween.trim().split(/\s+/);

      // Check if first word after entity is a relativizer
      if (words.length > 0) {
        const firstWord = words[0].replace(/[.,;:!?]$/, '');
        if (RELATIVIZERS.includes(firstWord)) {
          hasRelativizer = true;
          break; // Found a relativizer
        }

        // V7-005: Check for prepositional relative: "PREP + RELATIVIZER"
        // Pattern: "The server on which..." → "on" + "which"
        if (words.length > 1 && PREPOSITIONS.includes(firstWord)) {
          const secondWord = words[1].replace(/[.,;:!?]$/, '');
          if (RELATIVIZERS.includes(secondWord)) {
            hasRelativizer = true;
            break; // Found prepositional relativizer
          }
        }
      }
    }

    // If relativizer found, return the FARTHEST entity (head of main clause)
    if (hasRelativizer) {
      return sorted[0]; // First in sorted array = farthest from verb
    }

    // Check for zero relativizer pattern (reduced relative clause)
    // Pattern: Entity1 Entity2 Verb1 Verb2 → Verb2's agent = Entity1
    // Example: "The patch the team deployed fixed" → "fixed"'s agent = "patch"
    // Indicators: 2+ entities, verb(s) between first entity and target verb
    if (sorted.length >= 2) {
      const firstEntity = sorted[0];
      const firstEntityEnd = this._getEntityEnd(firstEntity);

      // Text between first entity and target verb
      const textBetween = fullText.substring(firstEntityEnd, verbOffset);

      // Check if there's an entity + verb pattern (sign of embedded clause)
      // Simple heuristic: check if there's another entity and a verb between first entity and target
      // Pattern: "Entity1 [Entity2 Verb1] Verb2" → indicates zero relativizer
      const wordsInBetween = textBetween.trim().split(/\s+/);
      const hasMultipleWords = wordsInBetween.length >= 3; // At least "the team deployed"

      // Look for verb pattern in between
      const hasEmbeddedVerb = /\b\w+(ed|es|ing)\b/i.test(textBetween);

      if (hasMultipleWords && hasEmbeddedVerb) {
        // Zero relativizer detected → use farthest entity
        return firstEntity;
      }
    }

    // No relativizer, no embedded verb: return closest entity (default SVO behavior)
    return sorted[sorted.length - 1];
  }

  /**
   * V7-009b: Detect prepositional phrases after verb for oblique role detection
   * Maps PP prepositions to semantic roles: for→beneficiary, with→instrument, etc.
   *
   * @param {string} fullText - Full input text
   * @param {number} verbOffset - Verb offset position
   * @param {number} verbEnd - Verb end position
   * @param {Array} entities - Available entities
   * @returns {Array} Array of PP objects with {preposition, entity, role}
   * @private
   */
  _detectPrepositionalPhraseRoles(fullText, verbOffset, verbEnd, entities) {
    const ppRoles = [];

    // Extract text after verb
    const textAfterVerb = fullText.substring(verbEnd);

    // Preposition-to-role mapping (VerbNet semantic frames)
    const PREP_TO_ROLE = {
      'for': 'beneficiary',        // "fixed for the team"
      'with': 'instrument',        // "fixed with the patch" (ambiguous with comitative)
      'on': 'location',            // "installed on the server"
      'in': 'location',            // "stored in the database"
      'at': 'location',            // "deployed at the site"
      'from': 'source',            // "downloaded from the server"
      'to': 'destination',         // "uploaded to the server"
      'into': 'destination',       // "moved into the folder"
      'onto': 'destination'        // "copied onto the disk"
    };

    // Find prepositional phrases using regex
    // Pattern: preposition + determiner? + noun phrase
    const ppPattern = /\b(for|with|on|in|at|from|to|into|onto)\s+(the|a|an)?\s*([a-z]+(?:\s+[a-z]+)*)/gi;
    let match;

    while ((match = ppPattern.exec(textAfterVerb)) !== null) {
      const preposition = match[1].toLowerCase();
      const npText = match[0]; // Full PP text: "with the patch"
      const ppOffset = verbEnd + match.index;

      // Find entity that overlaps with this PP
      const matchingEntity = entities.find(e => {
        if (!e['rdfs:label']) return false;
        const entityLabel = e['rdfs:label'].toLowerCase().replace('entity of ', '');
        const entityStart = this._getEntityStart(e);
        const entityEnd = this._getEntityEnd(e);

        // Check if entity overlaps with PP span
        return entityStart >= ppOffset && entityStart < ppOffset + npText.length;
      });

      if (matchingEntity && PREP_TO_ROLE[preposition]) {
        ppRoles.push({
          preposition,
          role: PREP_TO_ROLE[preposition],
          entity: matchingEntity,
          ppText: npText
        });
      }
    }

    // Special case: "with" can be comitative with animate entities
    // "worked with the admin" → comitative, not instrument
    // Heuristic: if verb is intransitive cooperation verb, "with" is comitative
    const COMITATIVE_VERBS = new Set(['work', 'collaborate', 'cooperate', 'meet', 'talk', 'discuss']);

    // V7.3 Enhancement: Verb-sensitive preposition mapping for recipient role
    // Different verb classes map "to" and "on" to different semantic roles
    const COMMUNICATION_VERBS = new Set([
      'explain', 'tell', 'say', 'speak', 'talk', 'communicate', 'announce',
      'describe', 'report', 'inform', 'notify', 'mention', 'reveal', 'disclose'
    ]);
    const TRANSFER_VERBS = new Set([
      'give', 'send', 'deliver', 'bring', 'take', 'hand', 'pass', 'offer',
      'provide', 'supply', 'grant', 'award', 'lend', 'loan'
    ]);
    const CAUSATION_VERBS = new Set([
      'cause', 'bring', 'lead', 'result', 'contribute'
    ]);
    const MEDICAL_INTERVENTION_VERBS = new Set([
      'operate', 'perform', 'conduct', 'administer', 'carry'
    ]);
    const MOTION_VERBS = new Set([
      'transport', 'move', 'transfer', 'carry', 'convey', 'relocate', 'shift'
    ]);

    const verbText = fullText.substring(verbOffset, verbEnd).toLowerCase().trim();

    // Normalize verb to infinitive form for class checking
    const verbInfinitive = VERB_INFINITIVE_CORRECTIONS[verbText] || verbText;

    ppRoles.forEach(pp => {
      // Handle "with" → comitative for cooperation verbs
      if (pp.role === 'instrument') {
        const entityType = pp.entity['tagteam:denotesType'] || '';
        if (COMITATIVE_VERBS.has(verbInfinitive) || entityType.includes('Person')) {
          pp.role = 'comitative';
        }
      }

      // Handle "to" → recipient for communication/transfer/causation verbs
      // But keep "to" → destination for motion verbs
      if (pp.role === 'destination' && pp.preposition === 'to') {
        if (COMMUNICATION_VERBS.has(verbInfinitive) ||
            TRANSFER_VERBS.has(verbInfinitive) ||
            CAUSATION_VERBS.has(verbInfinitive)) {
          pp.role = 'recipient';
        }
        // Motion verbs keep destination role (e.g., "transported to the hospital" → Goal)
      }

      // Handle "on" → recipient for medical intervention verbs
      if (pp.role === 'location' && pp.preposition === 'on') {
        if (MEDICAL_INTERVENTION_VERBS.has(verbInfinitive)) {
          pp.role = 'recipient';
        }
      }
    });

    return ppRoles;
  }

  /**
   * Link act to discourse referents (Tier 1) or real-world entities (Tier 2)
   *
   * v2.2 spec: Acts should link to Tier 2 entities (Person, Artifact)
   * via has_agent/affects. When linkToTier2 is enabled, resolves Tier 1
   * referents to their Tier 2 entities via cco:is_about.
   *
   * @param {string} fullText - Full input text
   * @param {string} verbText - Verb text
   * @param {number} verbOffset - Verb offset
   * @param {Array} entities - Available entities (both Tier 1 and Tier 2)
   * @returns {Object} Links to entities
   */
  _linkToEntities(fullText, verbText, verbOffset, entities) {
    const links = {
      agent: null,
      patient: null,
      recipient: null, // V7-009c: Ditransitive verb support
      participants: [],
      // V7-009b: Oblique role properties
      beneficiary: null,
      instrument: null,
      location: null,
      source: null,
      destination: null,
      comitative: null
    };

    if (!entities || entities.length === 0) {
      return links;
    }

    // Filter to only Tier 1 DiscourseReferents (not Tier 2 Person/Artifact)
    const referents = entities.filter(e =>
      e['@type'] && e['@type'].includes('tagteam:DiscourseReferent')
    );

    if (referents.length === 0) {
      return links;
    }

    // Build link map from Tier 1 to Tier 2 (if linkToTier2 enabled)
    const linkMap = this.options.linkToTier2 ? this._buildTier2LinkMap(entities) : new Map();

    // Temporal regions and qualities cannot be agents or patients
    const NON_PARTICIPANT_TYPES = ['OneDimensionalTemporalRegion', 'TemporalRegion', 'Quality', 'Disposition'];
    // Types that cannot be agents but CAN be patients (objects of actions)
    const NON_AGENT_TYPES = [...NON_PARTICIPANT_TYPES, 'InformationContentEntity'];

    // V7.3: Get verb infinitive to check for causation verbs
    // Causation verbs allow ICE agents (e.g., "The error caused harm")
    let currentVerbInfinitive = this._getInfinitive(verbText);
    currentVerbInfinitive = VERB_INFINITIVE_CORRECTIONS[currentVerbInfinitive] || currentVerbInfinitive;
    const CAUSATION_VERBS_LOCAL = new Set(['cause', 'bring', 'lead', 'result', 'contribute', 'trigger', 'produce']);

    const isNonAgentEntity = (entity) => {
      const dt = entity['tagteam:denotesType'];
      if (!dt || !NON_AGENT_TYPES.includes(dt)) return false;

      // V7.3: Allow ICE agents for causation verbs
      // "The error caused harm" - error (ICE) can be causal agent
      if (dt === 'InformationContentEntity' && CAUSATION_VERBS_LOCAL.has(currentVerbInfinitive)) {
        return false; // Not filtered - allow as agent
      }

      return true; // Filter out
    };
    const isNonPatientEntity = (entity) => {
      const dt = entity['tagteam:denotesType'];
      return dt && NON_PARTICIPANT_TYPES.includes(dt);
    };

    // Find entities before and after verb
    // Agent candidates: exclude non-agent types (temporal, quality, ICE)
    // Patient candidates: exclude only non-participant types (temporal, quality) — ICE can be patients
    const entitiesBefore = [];
    const entitiesAfter = [];
    const patientCandidatesAfter = [];
    // Also track ALL entities (including non-agent types) for inference detection
    const allEntitiesBefore = [];
    const allEntitiesAfter = [];

    referents.forEach(entity => {
      const entityOffset = this._getEntityStart(entity);
      if (entityOffset < verbOffset) {
        allEntitiesBefore.push(entity);
        if (!isNonAgentEntity(entity)) entitiesBefore.push(entity);
      } else {
        allEntitiesAfter.push(entity);
        if (!isNonAgentEntity(entity)) entitiesAfter.push(entity);
        if (!isNonPatientEntity(entity)) patientCandidatesAfter.push(entity);
      }
    });

    // Helper to resolve IRI (Tier 1 → Tier 2 if linkToTier2 enabled)
    const resolveIRI = (referentIRI) => {
      if (this.options.linkToTier2 && linkMap.has(referentIRI)) {
        return linkMap.get(referentIRI);
      }
      return referentIRI;
    };

    // Track the grammatical subject (closest entity before verb, ANY type) for inference detection
    if (allEntitiesBefore.length > 0) {
      const closestSubject = allEntitiesBefore.reduce((closest, entity) => {
        const entityEnd = this._getEntityEnd(entity);
        const closestEnd = this._getEntityEnd(closest);
        return entityEnd > closestEnd ? entity : closest;
      });
      links.subjectEntity = closestSubject;
      links.subjectIRI = resolveIRI(closestSubject['@id']);
    }

    // Agent is typically the closest entity before the verb (excluding non-agent types)
    // V7-004: For relative clauses, skip embedded entities and use the antecedent
    if (entitiesBefore.length > 0) {
      // Detect relative clause pattern: "The [antecedent] who/which/that [embedded] [main-verb]"
      const agentCandidate = this._findAgentForVerb(fullText, verbOffset, entitiesBefore);
      if (agentCandidate) {
        links.agent = resolveIRI(agentCandidate['@id']);
        links.agentEntity = agentCandidate; // Preserve for animacy checking

        // V7-010: Check if agent is part of a coordination ("X and Y verb")
        // If so, find all coordinated entities and assign agent role to all
        if (agentCandidate['tagteam:isConjunct']) {
          const coordinatedAgents = this._findCoordinatedEntities(agentCandidate, entitiesBefore);
          if (coordinatedAgents.length > 1) {
            // Store all coordinated agents (including the primary agent)
            links.coordinatedAgents = coordinatedAgents.map(e => ({
              iri: resolveIRI(e['@id']),
              entity: e
            }));
          }
        }
      }
    }

    // V7-009d: Reflexive pronoun support (Binding Theory)
    // Reflexives (itself, himself, herself, themselves, etc.) are always patients, coreferent with subject
    const REFLEXIVE_PRONOUNS = ['itself', 'himself', 'herself', 'themselves', 'ourselves', 'yourself', 'yourselves', 'myself'];

    // Search in the text after the verb for reflexive pronouns
    const textAfterVerb = fullText.substring(verbOffset).toLowerCase();
    let reflexiveEntity = null;

    for (const reflex of REFLEXIVE_PRONOUNS) {
      if (textAfterVerb.includes(reflex)) {
        // Found a reflexive pronoun in the text - now find the matching entity
        reflexiveEntity = allEntitiesAfter.find(e => {
          const label = (e['rdfs:label'] || '').toLowerCase();
          const sourceText = (e['tagteam:sourceText'] || '').toLowerCase();
          return label.includes(reflex) || sourceText.includes(reflex) || sourceText === reflex;
        });
        if (reflexiveEntity) break;
      }
    }

    if (reflexiveEntity) {
      // Reflexive is always the patient, coreferent with subject
      links.patient = resolveIRI(reflexiveEntity['@id']);
      links.patientEntity = reflexiveEntity;
    } else if (patientCandidatesAfter.length > 0) {
      // Patient/affected is typically the closest entity after the verb
      // Use patientCandidatesAfter which includes ICE types (they can be objects of actions)
      // Get the closest one to the verb
      // V7.3: When multiple entities start at same position (PP-modified phrases),
      // prefer the shortest one (head-np) over the full phrase
      const closestAfter = patientCandidatesAfter.reduce((closest, entity) => {
        const entityStart = this._getEntityStart(entity);
        const closestStart = this._getEntityStart(closest);

        // If entity is closer to verb, prefer it
        if (entityStart < closestStart) return entity;
        if (entityStart > closestStart) return closest;

        // Same start position - prefer shorter entity (head-np over full-phrase)
        const entityLength = (entity['rdfs:label'] || '').length;
        const closestLength = (closest['rdfs:label'] || '').length;
        return entityLength < closestLength ? entity : closest;
      });
      links.patient = resolveIRI(closestAfter['@id']);
      links.patientEntity = closestAfter; // Preserve for inference target

      // V7-010: Check if patient is part of a coordination ("verb X and Y")
      // If so, find all coordinated entities and assign patient role to all
      if (closestAfter['tagteam:isConjunct']) {
        const coordinatedPatients = this._findCoordinatedEntities(closestAfter, patientCandidatesAfter);
        if (coordinatedPatients.length > 1) {
          // Store all coordinated patients (including the primary patient)
          links.coordinatedPatients = coordinatedPatients.map(e => ({
            iri: resolveIRI(e['@id']),
            entity: e
          }));
        }
      }
    }

    // Track closest entity after verb (ANY type) for inference target
    if (allEntitiesAfter.length > 0) {
      const closestObject = allEntitiesAfter.reduce((closest, entity) => {
        const entityStart = this._getEntityStart(entity);
        const closestStart = this._getEntityStart(closest);
        return entityStart < closestStart ? entity : closest;
      });
      links.objectEntity = closestObject;
      links.objectIRI = resolveIRI(closestObject['@id']);
    }

    // All entities after verb are potential participants (resolved to Tier 2)
    links.participants = entitiesAfter.map(e => resolveIRI(e['@id']));

    // V7-009c: Ditransitive verb support (send, receive, give, tell, etc.)
    // Pattern: "X sent Y Z" → agent=X, recipient=Y (first after verb), patient=Z (second after verb)
    // Pattern: "Y received Z" → recipient=Y (subject), patient=Z (first after verb)
    const DITRANSITIVE_VERBS = new Set([
      'send', 'give', 'tell', 'show', 'teach', 'offer', 'lend', 'pass', 'hand',
      'receive', 'get' // These take recipient as subject
    ]);
    const RECIPIENT_AS_SUBJECT_VERBS = new Set(['receive', 'get']);

    // Get infinitive form for comparison (verbText may be inflected like "sent" or "received")
    let verbInfinitive = this._getInfinitive(verbText);
    // Apply corrections for truncated forms
    verbInfinitive = VERB_INFINITIVE_CORRECTIONS[verbInfinitive] || verbInfinitive;

    if (DITRANSITIVE_VERBS.has(verbInfinitive)) {
      // For "receive"/"get": recipient is subject, patient is first object
      if (RECIPIENT_AS_SUBJECT_VERBS.has(verbInfinitive)) {
        if (links.agent) {
          links.recipient = links.agent; // Subject is recipient
          links.agent = null; // No agent for receive
        }
      }
      // For "send"/"give"/etc: recipient is first object, patient is second object
      else {
        // Use allEntitiesAfter to include all entities (Person and ICE)
        const objectsAfter = allEntitiesAfter.filter(e => !isNonPatientEntity(e));

        if (objectsAfter.length >= 2) {
          // Sort by position
          const sortedAfter = [...objectsAfter].sort((a, b) => {
            return this._getEntityStart(a) - this._getEntityStart(b);
          });

          // First entity after verb = recipient
          links.recipient = resolveIRI(sortedAfter[0]['@id']);
          // Second entity after verb = patient
          links.patient = resolveIRI(sortedAfter[1]['@id']);
        }
        // If only 1 object, it's the patient (not recipient)
        // e.g., "sent an alert" → patient=alert, no recipient
      }
    }

    // V7-009b: Detect prepositional phrase roles for oblique arguments
    const verbEnd = verbOffset + verbText.length;
    const ppRoles = this._detectPrepositionalPhraseRoles(fullText, verbOffset, verbEnd, referents);

    // Populate oblique role links
    ppRoles.forEach(pp => {
      const entityIRI = resolveIRI(pp.entity['@id']);

      switch (pp.role) {
        case 'recipient':
          if (!links.recipient) links.recipient = entityIRI;
          break;
        case 'beneficiary':
          if (!links.beneficiary) links.beneficiary = entityIRI;
          break;
        case 'instrument':
          if (!links.instrument) links.instrument = entityIRI;
          break;
        case 'location':
          if (!links.location) links.location = entityIRI;
          break;
        case 'source':
          if (!links.source) links.source = entityIRI;
          break;
        case 'destination':
          if (!links.destination) links.destination = entityIRI;
          break;
        case 'comitative':
          if (!links.comitative) links.comitative = entityIRI;
          break;
      }
    });

    return links;
  }

  /**
   * Get span offset for verb in text
   * @param {string} fullText - Full input text
   * @param {string} verbText - Verb text
   * @param {number} index - Verb index
   * @returns {number} Character offset
   */
  _getSpanOffset(fullText, verbText, index) {
    const lowerText = fullText.toLowerCase();
    const lowerVerb = verbText.toLowerCase();

    let offset = 0;
    let searchStart = 0;

    // Find nth occurrence
    for (let i = 0; i <= index; i++) {
      const found = lowerText.indexOf(lowerVerb, searchStart);
      if (found === -1) break;
      offset = found;
      searchStart = found + 1;
    }

    return offset;
  }

  /**
   * Determine actuality status based on modality and negation
   *
   * v2.2 spec: All acts have actualityStatus (Named Individual)
   * - Negated acts → tagteam:Negated
   * - Modal verbs → mapped via MODALITY_TO_STATUS
   * - Simple past/present → tagteam:Actual
   *
   * @param {string|null} modality - Detected modality
   * @param {boolean} negation - Whether act is negated
   * @param {Object} tense - Tense information
   * @returns {string} ActualityStatus IRI
   * @private
   */
  _determineActualityStatus(modality, negation, tense) {
    // Negation takes precedence
    if (negation) {
      return 'tagteam:Negated';
    }

    // Modal verbs determine status
    if (modality && MODALITY_TO_STATUS[modality]) {
      return MODALITY_TO_STATUS[modality];
    }

    // Default: past or present tense without modality = Actual
    return 'tagteam:Actual';
  }

  /**
   * Create an IntentionalAct node
   *
   * v2.2 spec updates:
   * - All acts have actualityStatus (Prescribed, Actual, Negated, etc.)
   * - Uses sourceText, startPosition, endPosition (v2.2 position properties)
   * - Links to Tier 2 entities via has_agent/affects
   *
   * @param {Object} actInfo - Act information
   * @returns {Object} IntentionalAct node
   */
  _createIntentionalAct(actInfo) {
    // Generate IRI
    let iri;
    if (this.graphBuilder) {
      iri = this.graphBuilder.generateIRI(
        actInfo.infinitive,
        'IntentionalAct',
        actInfo.offset
      );
    } else {
      // Fallback simple IRI
      const cleanVerb = actInfo.infinitive.replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');
      iri = `inst:${cleanVerb}_Act_${actInfo.offset}`;
    }

    // Determine actuality status (v2.2)
    let actualityStatus = this._determineActualityStatus(
      actInfo.modality,
      actInfo.negation,
      actInfo.tense
    );

    // Control verb override: infinitive complements are Prescribed (not yet realized)
    if (actInfo.actualityOverride) {
      actualityStatus = actInfo.actualityOverride;
    }

    // Build node with v2.2 position properties
    const node = {
      '@id': iri,
      '@type': [actInfo.actType, 'owl:NamedIndividual'],
      'rdfs:label': `Act of ${actInfo.infinitive}`,
      'tagteam:verb': actInfo.infinitive,
      'tagteam:sourceText': actInfo.text,
      'tagteam:startPosition': actInfo.offset,
      'tagteam:endPosition': actInfo.offset + actInfo.text.length,
      'tagteam:actualityStatus': actualityStatus
    };

    // Add control verb reference if this is an infinitive complement
    if (actInfo.controlVerb) {
      node['tagteam:controlVerb'] = actInfo.controlVerb;
    }

    // Add modality if present
    if (actInfo.modality) {
      node['tagteam:modality'] = actInfo.modality;
    }

    // Phase 6.4: Add deontic type for Hohfeldian classification
    if (actInfo.deonticType) {
      node['tagteam:deonticType'] = actInfo.deonticType;
    }

    // Add negation if present (kept for backward compatibility)
    if (actInfo.negation) {
      node['tagteam:negated'] = true;
    }

    // Add tense info
    if (actInfo.tense) {
      node['tagteam:tense'] = actInfo.tense.tense;
      if (actInfo.tense.aspect !== 'simple') {
        node['tagteam:aspect'] = actInfo.tense.aspect;
      }
    }

    // Add links to entities (Tier 2 if linkToTier2 enabled)
    // Use object notation with @id for JSON-LD compliance

    // V7-010: Handle coordinated agents ("The engineer and the admin deployed")
    if (actInfo.links.coordinatedAgents && actInfo.links.coordinatedAgents.length > 0) {
      // Multiple agents: assign agent role to all coordinated entities
      node['has_agent'] = actInfo.links.coordinatedAgents.map(a => ({ '@id': a.iri }));
    } else if (actInfo.links.agent) {
      // Single agent
      node['has_agent'] = { '@id': actInfo.links.agent };
    }

    // V7-010: Handle coordinated patients ("configured the server and the database")
    if (actInfo.links.coordinatedPatients && actInfo.links.coordinatedPatients.length > 0) {
      // Multiple patients: assign patient role to all coordinated entities
      node['affects'] = actInfo.links.coordinatedPatients.map(p => ({ '@id': p.iri }));
    } else if (actInfo.links.patient) {
      // Single patient
      node['affects'] = { '@id': actInfo.links.patient };
    }

    // V7-009c: Add recipient role for ditransitive verbs
    if (actInfo.links.recipient) {
      node['has_recipient'] = { '@id': actInfo.links.recipient };
    }

    // V7-009b: Add oblique role properties (beneficiary, instrument, location, etc.)
    if (actInfo.links.beneficiary) {
      node['tagteam:beneficiary'] = { '@id': actInfo.links.beneficiary };
    }

    if (actInfo.links.instrument) {
      node['tagteam:instrument'] = { '@id': actInfo.links.instrument };
    }

    if (actInfo.links.location) {
      node['tagteam:located_in'] = { '@id': actInfo.links.location };
    }

    if (actInfo.links.source) {
      node['tagteam:source'] = { '@id': actInfo.links.source };
    }

    if (actInfo.links.destination) {
      node['tagteam:destination'] = { '@id': actInfo.links.destination };
    }

    if (actInfo.links.comitative) {
      node['tagteam:comitative'] = { '@id': actInfo.links.comitative };
    }

    // V7-009: Auto-populate has_participant (BFO_0000057) as superproperty
    // has_participant aggregates all semantic participants (agent, patient, oblique roles, etc.)
    const participants = [];

    // V7-010: Include all coordinated agents
    if (actInfo.links.coordinatedAgents && actInfo.links.coordinatedAgents.length > 0) {
      participants.push(...actInfo.links.coordinatedAgents.map(a => a.iri));
    } else if (actInfo.links.agent) {
      participants.push(actInfo.links.agent);
    }

    // V7-010: Include all coordinated patients
    if (actInfo.links.coordinatedPatients && actInfo.links.coordinatedPatients.length > 0) {
      participants.push(...actInfo.links.coordinatedPatients.map(p => p.iri));
    } else if (actInfo.links.patient) {
      participants.push(actInfo.links.patient);
    }
    // V7-009c: Include recipient participant
    if (actInfo.links.recipient) {
      participants.push(actInfo.links.recipient);
    }
    // V7-009b: Include oblique role participants
    if (actInfo.links.beneficiary) {
      participants.push(actInfo.links.beneficiary);
    }
    if (actInfo.links.instrument) {
      participants.push(actInfo.links.instrument);
    }
    if (actInfo.links.location) {
      participants.push(actInfo.links.location);
    }
    if (actInfo.links.source) {
      participants.push(actInfo.links.source);
    }
    if (actInfo.links.destination) {
      participants.push(actInfo.links.destination);
    }
    if (actInfo.links.comitative) {
      participants.push(actInfo.links.comitative);
    }
    // Include any explicitly provided participants
    if (actInfo.links.participants && actInfo.links.participants.length > 0) {
      participants.push(...actInfo.links.participants.filter(p =>
        !participants.includes(p) // Avoid duplicates
      ));
    }

    if (participants.length > 0) {
      node['has_participant'] = participants.map(p => ({ '@id': p }));
    }

    return node;
  }

  /**
   * Create an InformationContentEntity node for inanimate-agent inference verbs.
   * Phase 7.0 Story 3: "Blood sugar levels suggest diabetes" produces an
   * Inference/ClinicalFinding ICE instead of an IntentionalAct with inanimate agent.
   *
   * @param {Object} actInfo - Act information (same shape as _createIntentionalAct input)
   * @returns {Object} InformationContentEntity node
   * @private
   */
  _createInferenceNode(actInfo) {
    const cleanVerb = actInfo.infinitive.replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');
    const iri = this.graphBuilder
      ? this.graphBuilder.generateIRI(actInfo.infinitive, 'Inference', actInfo.offset)
      : `inst:Inference_${cleanVerb}_${actInfo.offset}`;

    // Determine subtype based on verb
    const verb = actInfo.infinitive.toLowerCase();
    const subtype = (verb === 'suggest' || verb === 'imply' || verb === 'point')
      ? 'tagteam:Inference'
      : 'tagteam:ClinicalFinding';

    const node = {
      '@id': iri,
      '@type': ['InformationContentEntity', subtype, 'owl:NamedIndividual'],
      'rdfs:label': `Inference from ${actInfo.links.agentEntity
        ? (actInfo.links.agentEntity['rdfs:label'] || 'source')
        : 'source'}`,
      'tagteam:sourceText': actInfo.text,
      'tagteam:startPosition': actInfo.offset,
      'tagteam:endPosition': actInfo.offset + actInfo.text.length,
      'tagteam:detection_method': 'selectional_retype',
      'tagteam:original_verb': actInfo.infinitive
    };

    // Link to the inanimate entity (the measurement/quality that "suggests")
    if (actInfo.links.agent) {
      node['is_about'] = { '@id': actInfo.links.agent };
    }

    // Link to the inferred entity (what is being suggested)
    // Use patient if available, fall back to objectIRI (which includes quality entities)
    const inferredIRI = actInfo.links.patient || actInfo.links.objectIRI;
    if (inferredIRI) {
      node['tagteam:supports_inference'] = { '@id': inferredIRI };
    }

    return node;
  }

  /**
   * Check if an agent entity is inanimate (not a person/organization)
   * @param {Object} entity - DiscourseReferent entity
   * @returns {boolean} True if inanimate
   * @private
   */
  _isInanimateAgent(entity) {
    if (!entity) return false;
    const dt = entity['tagteam:denotesType'];
    // Persons and organizations are animate agents
    if (dt === 'Person' || dt === 'Agent' || dt === 'Organization') {
      return false;
    }
    // Artifacts, qualities, material entities are inanimate
    return true;
  }

  /**
   * ENH-003: Get or create the implicit "you" entity for imperative sentences.
   *
   * When an imperative sentence has no explicit subject (e.g., "Submit the report"),
   * the addressee "you" is the implicit agent. This method creates a synthetic
   * Tier 2 Person entity representing the implicit "you".
   *
   * The entity is cached and reused across multiple imperatives in the same text,
   * ensuring a single "you" entity is shared (BFO principle: one entity per referent).
   *
   * @returns {Object} Implicit "you" Tier 2 Person entity
   * @private
   */
  _getOrCreateImplicitYou() {
    // Reuse existing implicit "you" if already created
    if (this._implicitYouEntity) {
      return this._implicitYouEntity;
    }

    // Generate IRI for the implicit "you" entity
    const iri = this.graphBuilder
      ? this.graphBuilder.generateIRI('you', 'Person', 0)
      : 'inst:Person_You_implicit';

    // Create Tier 2 Person entity for implicit "you"
    // ENH-003: Include all required properties for a proper Tier 2 entity
    this._implicitYouEntity = {
      '@id': iri,
      '@type': ['Person', 'owl:NamedIndividual'],
      'rdfs:label': 'you',
      'tagteam:denotesType': 'Person',
      'tagteam:referentialStatus': 'deictic',  // "you" refers deictically to addressee
      'tagteam:isImplicit': true,
      'tagteam:implicitReason': 'imperative_addressee'
    };

    return this._implicitYouEntity;
  }

  /**
   * ENH-003: Reset implicit "you" entity tracking.
   * Called at the start of processing new text to ensure fresh state.
   * @private
   */
  _resetImplicitYou() {
    this._implicitYouEntity = null;
  }

  /**
   * Set the graph builder for IRI generation
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
  }

  /**
   * Set entities for linking
   * @param {Array} entities - Entity nodes
   */
  setEntities(entities) {
    this.entities = entities;
  }

  /**
   * Set the domain config loader for verb overrides
   *
   * Phase 2: When a config loader is set, verb sense can be overridden
   * based on the ontological category of the direct object (selectional
   * restrictions to be implemented in Phase 3).
   *
   * @param {Object|null} configLoader - DomainConfigLoader instance or null to clear
   */
  setConfigLoader(configLoader) {
    this.configLoader = configLoader;
  }

  /**
   * Detect sentence-level deontic patterns
   *
   * Phase 6.4: Some deontic patterns aren't captured by verb extraction because:
   * - The main verb is missed (e.g., "shall disclose" only extracts "shall")
   * - The verb is ambiguous with noun (e.g., "delegates", "grants")
   * - The pattern uses adjectives (e.g., "is exempt from", "is entitled to")
   *
   * This method detects these patterns and creates appropriate act nodes.
   *
   * @param {string} text - Input text
   * @param {Array} entities - Available entities
   * @returns {Object|null} IntentionalAct node or null
   * @private
   */
  _detectSentenceLevelDeontic(text, entities) {
    if (!text) return null;

    // Define sentence-level patterns with their deontic type and verb extraction
    const patterns = [
      // Prohibition patterns
      { pattern: /\bshall\s+not\s+(\w+)/i, modality: 'prohibition', verbGroup: 1 },
      { pattern: /\bmust\s+not\s+(\w+)/i, modality: 'prohibition', verbGroup: 1 },

      // Claim/Right patterns
      { pattern: /\b(has|have)\s+the\s+right\s+to\s+(\w+)/i, modality: 'claim', verbGroup: 2 },
      { pattern: /\b(has|have)\s+a\s+right\s+to\s+(\w+)/i, modality: 'claim', verbGroup: 2 },
      { pattern: /\b(is|are)\s+entitled\s+to\s+(\w+)/i, modality: 'claim', verbGroup: 2 },

      // Power patterns - verb-based
      { pattern: /\bdelegates?\s+(authority|power|responsibility)/i, modality: 'power', verb: 'delegate' },
      { pattern: /\bgrants?\s+(permission|authority|access)/i, modality: 'power', verb: 'grant' },
      { pattern: /\bconfers?\s+(the\s+)?(right|authority|power)/i, modality: 'power', verb: 'confer' },
      { pattern: /\b(is|are)\s+authorized\s+to\s+(\w+)/i, modality: 'power', verbGroup: 2 },
      { pattern: /\b(is|are)\s+empowered\s+to\s+(\w+)/i, modality: 'power', verbGroup: 2 },
      { pattern: /\bempowers?\s+(\w+)/i, modality: 'power', verb: 'empower' },

      // Immunity patterns
      { pattern: /\b(is|are)\s+exempt\s+from/i, modality: 'immunity', verb: 'exempt' },
      { pattern: /\b(is|are)\s+protected\s+from/i, modality: 'immunity', verb: 'protect' },
      { pattern: /\b(is|are)\s+immune\s+(from|to)/i, modality: 'immunity', verb: 'immunize' },

      // Enhanced prohibition
      { pattern: /\b(is|are)\s+forbidden\s+(to|from)/i, modality: 'prohibition', verb: 'forbid' },
      { pattern: /\b(is|are)\s+prohibited\s+from/i, modality: 'prohibition', verb: 'prohibit' }
    ];

    for (const p of patterns) {
      const match = text.match(p.pattern);
      if (match) {
        // Extract the verb
        let verb = p.verb;
        if (p.verbGroup && match[p.verbGroup]) {
          verb = match[p.verbGroup];
        }

        // Get offset
        const offset = match.index || 0;

        // Create act node
        return this._createIntentionalAct({
          text: match[0],
          infinitive: verb || match[0],
          offset,
          actType: 'IntentionalAct',
          modality: p.modality,
          deonticType: MODALITY_TO_DEONTIC_TYPE[p.modality] || null,
          negation: false,
          tense: { tense: 'present', form: 'simple', aspect: 'simple' },
          links: this._linkToEntities(text, match[0], offset, entities)
        });
      }
    }

    return null;
  }
}



  // ============================================================================
  // ROLE DETECTOR (Phase 4 - Week 1)
  // ============================================================================

/**
 * RoleDetector.js
 *
 * Detects BFO roles from acts and links them to entities.
 * Roles link entities (bearers) to acts (realizations).
 *
 * Phase 4 Two-Tier Architecture v2.4:
 * - PatientRole ONLY inheres in Person (not artifacts)
 * - Artifacts use AffectedEntityRole or no role
 * - Roles only realize in Actual acts (not Prescribed/Planned)
 * - PatientRole assigned to ObjectAggregate members (v2.4)
 *
 * @module graph/RoleDetector
 * @version 4.0.0-phase4-v2.4
 */

/**
 * Extract IRI from a relation value (handles both string and object notation)
 * @param {string|Object} value - Relation value (IRI string or {`@id`: IRI})
 * @returns {string|null} The IRI string, or null if invalid
 */
function extractIRI(value) {
  if (!value) return null;
  if (typeof value === 'string') return value;
  if (typeof value === 'object' && value['@id']) return value['@id'];
  return null;
}

/**
 * Extract IRIs from an array of relation values
 * @param {Array} values - Array of relation values
 * @returns {Array<string>} Array of IRI strings
 */
function extractIRIs(values) {
  if (!values) return [];
  if (!Array.isArray(values)) return [extractIRI(values)].filter(Boolean);
  return values.map(extractIRI).filter(Boolean);
}

/**
 * Role type mappings based on relationship to act
 * Maps role positions to CCO/BFO role types
 *
 * IMPORTANT: PatientRole is ONLY for Person entities (BFO/CCO constraint)
 * Artifacts do not bear PatientRole - they are affected but not patients
 */
/**
 * Role type mappings — all roles are bfo:Role (BFO_0000023, verified).
 * The role label carries the semantic distinction (AgentRole, PatientRole, etc.)
 * via rdfs:label on the role node.
 */
const ROLE_TYPE_MAPPINGS = {
  'agent': 'AgentRole',
  'performer': 'AgentRole',
  'actor': 'AgentRole',
  'patient': 'PatientRole',
  'recipient': 'RecipientRole',
  'instrument': 'InstrumentRole',
  'tool': 'InstrumentRole',
  'beneficiary': 'BeneficiaryRole',
  'participant': 'Role',
  '_default': 'Role'
};

/**
 * Entity types that CAN bear PatientRole (BFO/CCO constraint)
 * PatientRole is a specific medical/care role that only inheres in persons
 */
const PATIENT_ROLE_ELIGIBLE_TYPES = [
  'Person',
  'Agent'
];

/**
 * ActualityStatus values where roles can be realized
 * Roles are only realized in actual occurrences, not prescriptions
 */
const REALIZABLE_STATUSES = [
  'tagteam:Actual'
];

/**
 * RoleDetector class - detects roles and links them to acts and bearers
 */
class RoleDetector {
  /**
   * Create a new RoleDetector
   * @param {Object} options - Configuration options
   * @param {Object} [options.graphBuilder] - SemanticGraphBuilder instance for IRI generation
   */
  constructor(options = {}) {
    this.options = options;
    this.graphBuilder = options.graphBuilder || null;
  }

  /**
   * Detect roles from acts and entities
   *
   * v2.3 changes:
   * - PatientRole ONLY for Person entities (not artifacts)
   * - Roles only realize in Actual acts (not Prescribed/Planned)
   *
   * @param {Array} acts - Array of IntentionalAct nodes from ActExtractor
   * @param {Array} entities - Array of entity nodes (Tier 1 + Tier 2)
   * @param {Object} [options] - Detection options
   * @returns {Array<Object>} Array of Role nodes
   */
  detect(acts, entities, options = {}) {
    if (!acts || !entities || acts.length === 0 || entities.length === 0) {
      return [];
    }

    // Build entity lookup by IRI
    const entityIndex = new Map();
    entities.forEach(entity => {
      entityIndex.set(entity['@id'], entity);
    });

    // Phase 7.1: Consolidate roles per (roleType, bearerIRI).
    // BFO roles are continuants — one role per bearer, realized across multiple acts.
    // Key: "roleType|bearerIRI", Value: { roleInfo, actEntries: [{actIRI, canRealize}] }
    const roleAccumulator = new Map();

    const accumulateRole = (roleType, bearerIRI, bearer, actIRI, act, canRealize) => {
      const key = `${roleType}|${bearerIRI}`;
      if (roleAccumulator.has(key)) {
        roleAccumulator.get(key).actEntries.push({ actIRI, canRealize });
      } else {
        roleAccumulator.set(key, {
          roleType, bearerIRI, bearer,
          actEntries: [{ actIRI, canRealize }]
        });
      }
    };

    // Process each act to find roles
    acts.forEach(act => {
      // Phase 7 v7: Skip StructuralAssertions — stative verbs have no agent/patient roles
      const types = Array.isArray(act['@type']) ? act['@type'] : [act['@type']];
      if (types.some(t => t && t.includes('StructuralAssertion'))) return;
      const actualityStatus = act['tagteam:actualityStatus'];
      const canRealize = REALIZABLE_STATUSES.includes(actualityStatus);

      // Detect agent role (from has_agent)
      const agentIRI = extractIRI(act['has_agent']);
      if (agentIRI) {
        const bearer = entityIndex.get(agentIRI);
        if (bearer && this._canBearAgentRole(bearer)) {
          accumulateRole('agent', agentIRI, bearer, act['@id'], act, canRealize);
        }
      }

      // Detect patient/affected role (from affects)
      // ENH-015: Use preposition to determine specific role type
      const affectedIRI = extractIRI(act['affects']);
      if (affectedIRI) {
        const bearer = entityIndex.get(affectedIRI);
        if (bearer) {
          // ENH-015: Check for introducing preposition to determine role
          const prep = bearer['tagteam:introducingPreposition'];
          const roleType = this._getRoleTypeFromPreposition(prep, bearer);
          if (roleType) {
            accumulateRole(roleType, affectedIRI, bearer, act['@id'], act, canRealize);
          } else {
            // ENH-015: Direct object without preposition = patient role
            // This applies to both persons and artifacts (semantic patient = affected entity)
            accumulateRole('patient', affectedIRI, bearer, act['@id'], act, canRealize);
          }
        }
      }

      // Detect participant roles (from has_participant)
      // ENH-015: Use preposition to determine specific role type
      const participantIRIs = extractIRIs(act['has_participant']);
      if (participantIRIs.length > 0) {
        participantIRIs.forEach(participantIRI => {
          if (participantIRI === agentIRI || participantIRI === affectedIRI) return;

          const bearer = entityIndex.get(participantIRI);
          if (bearer) {
            if (this._isObjectAggregate(bearer)) {
              const members = extractIRIs(bearer['has_member_part']);
              members.forEach(memberIRI => {
                const member = entityIndex.get(memberIRI);
                if (member && this._isPersonEntity(member)) {
                  accumulateRole('patient', memberIRI, member, act['@id'], act, canRealize);
                }
              });
            } else {
              // ENH-015: Check for introducing preposition first
              const prep = bearer['tagteam:introducingPreposition'];
              const prepRoleType = this._getRoleTypeFromPreposition(prep, bearer);
              if (prepRoleType) {
                accumulateRole(prepRoleType, participantIRI, bearer, act['@id'], act, canRealize);
              } else {
                const roleType = this._isPersonEntity(bearer) ? 'patient' : 'participant';
                accumulateRole(roleType, participantIRI, bearer, act['@id'], act, canRealize);
              }
            }
          }
        });
      }
    });

    // Build consolidated role nodes
    const roles = [];
    for (const [, entry] of roleAccumulator) {
      const role = this._createConsolidatedRole(entry);
      roles.push(role);
      this._addBearerLink(entry.bearer, role['@id']);
    }

    return roles;
  }

  /**
   * ENH-015: Get role type based on introducing preposition
   *
   * Preposition → Role mapping:
   * - "for" → beneficiary
   * - "with" + inanimate → instrument
   * - "with" + person → participant (comitative)
   * - "to" → recipient
   * - "from" → participant (source)
   *
   * @param {string|null} preposition - The introducing preposition
   * @param {Object} bearer - The entity bearing the role
   * @returns {string|null} Role type key or null for default handling
   */
  _getRoleTypeFromPreposition(preposition, bearer) {
    if (!preposition) return null;

    const prep = preposition.toLowerCase();
    const isPerson = this._isPersonEntity(bearer);

    switch (prep) {
      case 'for':
        return 'beneficiary';
      case 'with':
        // "with" + person = comitative (participant)
        // "with" + inanimate = instrument
        return isPerson ? 'participant' : 'instrument';
      case 'to':
        return 'recipient';
      case 'from':
        // Source is treated as participant
        return 'participant';
      case 'by':
        // "by" in passive = agent (handled elsewhere)
        return null;
      default:
        return null;
    }
  }

  /**
   * Check if an entity is a Person type (can bear PatientRole)
   * @param {Object} entity - Entity node
   * @returns {boolean} True if entity is a Person
   */
  _isPersonEntity(entity) {
    const types = entity['@type'] || [];
    return types.some(type =>
      PATIENT_ROLE_ELIGIBLE_TYPES.some(eligible => type.includes(eligible))
    );
  }

  /**
   * Check if an entity can bear AgentRole
   * @param {Object} entity - Entity node
   * @returns {boolean} True if entity can be an agent
   */
  _canBearAgentRole(entity) {
    // AgentRole is primarily for persons, but could extend to organizations
    const types = entity['@type'] || [];
    return types.some(type =>
      type.includes('Person') ||
      type.includes('Organization') ||
      type.includes('Agent')
    );
  }

  /**
   * Check if an entity is an ObjectAggregate (v2.4)
   * @param {Object} entity - Entity node
   * @returns {boolean} True if ObjectAggregate
   */
  _isObjectAggregate(entity) {
    const types = entity['@type'] || [];
    return types.some(type => type.includes('BFO_0000027'));
  }

  /**
   * Add bearer link to entity
   * @param {Object} bearer - Bearer entity
   * @param {string} roleIRI - Role IRI
   */
  _addBearerLink(bearer, roleIRI) {
    if (!bearer['is_bearer_of']) {
      bearer['is_bearer_of'] = [];
    }
    if (!Array.isArray(bearer['is_bearer_of'])) {
      bearer['is_bearer_of'] = [bearer['is_bearer_of']];
    }
    // Deduplicate: don't add the same role IRI twice
    const existing = bearer['is_bearer_of'].some(ref =>
      (typeof ref === 'object' ? ref['@id'] : ref) === roleIRI
    );
    if (!existing) {
      bearer['is_bearer_of'].push({ '@id': roleIRI });
    }
  }

  /**
   * Create a Role node
   *
   * v2.3: Roles only have realized_in for Actual acts
   * For Prescribed/Planned acts, role exists but is not yet realized
   *
   * @param {Object} roleInfo - Role information
   * @returns {Object} Role node
   */
  /**
   * Create a consolidated role node from accumulated act entries.
   * One role per (roleType, bearerIRI), with realized_in as array when multiple acts.
   */
  _createConsolidatedRole(entry) {
    const { roleType, bearerIRI, bearer, actEntries } = entry;

    const iri = this._generateRoleIRI(roleType, bearerIRI);
    const roleLabel = ROLE_TYPE_MAPPINGS[roleType] || ROLE_TYPE_MAPPINGS['_default'];

    const role = {
      '@id': iri,
      '@type': ['Role', 'owl:NamedIndividual'],
      'rdfs:label': roleLabel,
      'tagteam:roleType': roleType,
      'tagteam:syntacticBasis': roleType,
      'inheres_in': { '@id': bearerIRI }
    };

    // Separate actual vs non-actual acts
    const realizedActs = actEntries.filter(e => e.canRealize).map(e => ({ '@id': e.actIRI }));
    const wouldRealizeActs = actEntries.filter(e => !e.canRealize).map(e => ({ '@id': e.actIRI }));

    if (realizedActs.length === 1) {
      role['realized_in'] = realizedActs[0];
    } else if (realizedActs.length > 1) {
      role['realized_in'] = realizedActs;
    }

    if (wouldRealizeActs.length === 1) {
      role['tagteam:would_be_realized_in'] = wouldRealizeActs[0];
    } else if (wouldRealizeActs.length > 1) {
      role['tagteam:would_be_realized_in'] = wouldRealizeActs;
    }

    return role;
  }

  /**
   * Generate IRI for a role
   * @param {string} roleType - Type of role
   * @param {string} bearerIRI - Bearer IRI
   * @param {string} actIRI - Act IRI
   * @returns {string} Role IRI
   */
  _generateRoleIRI(roleType, bearerIRI) {
    // Phase 7.1: Hash only roleType|bearerIRI — one role per bearer
    const hashInput = `${roleType}|${bearerIRI}`;

    // Generate SHA-256 hash
    const hash = crypto
      .createHash('sha256')
      .update(hashInput)
      .digest('hex');

    // Take first 8 characters
    const hashSuffix = hash.substring(0, 8);

    // Format: inst:RoleType_Role_hash
    const typeLabel = roleType.charAt(0).toUpperCase() + roleType.slice(1);
    return `inst:${typeLabel}_Role_${hashSuffix}`;
  }

  /**
   * Generate human-readable label for role
   * @param {string} roleType - Type of role
   * @param {Object} bearer - Bearer entity
   * @param {Object} act - Act node
   * @returns {string} Role label
   */
  _generateRoleLabel(roleType, bearer) {
    const bearerLabel = bearer['rdfs:label'] || 'entity';
    return `${roleType} role of ${bearerLabel}`;
  }

  /**
   * Set the graph builder for IRI generation
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
  }

  /**
   * Get role type for a given position
   * @param {string} position - Role position (agent, patient, etc.)
   * @returns {string} CCO/BFO role type
   */
  static getRoleType(position) {
    return ROLE_TYPE_MAPPINGS[position] || ROLE_TYPE_MAPPINGS['_default'];
  }
}



  // ============================================================================
  // JSON-LD SERIALIZER (Phase 4 - Week 1)
  // ============================================================================

/**
 * JSONLDSerializer.js
 *
 * Serializes semantic graphs to JSON-LD format with proper @context.
 *
 * Phase 4 Two-Tier Architecture v2.4 + Week 2:
 * - ScarcityAssertion ICE type
 * - DeonticContent / DirectiveInformationContentEntity
 * - ObjectAggregate (bfo:BFO_0000027)
 * - Role realization properties
 * - ValueAssertionEvent, ContextAssessmentEvent (Week 2)
 * - EthicalValueICE, ContextDimensionICE (Week 2)
 * - IBE/ICE concretization linkage (Week 2)
 *
 * @module graph/JSONLDSerializer
 * @version 4.0.0-phase4-week2
 */

/**
 * JSON-LD Serializer for semantic graphs
 */
class JSONLDSerializer {
  /**
   * Create a new JSONLDSerializer
   * @param {Object} options - Serialization options
   * @param {boolean} [options.compact=true] - Use compact format
   * @param {boolean} [options.pretty=false] - Pretty-print JSON
   */
  constructor(options = {}) {
    this.options = {
      compact: options.compact !== false,
      pretty: options.pretty || false,
      ...options
    };
  }

  /**
   * Serialize a graph to JSON-LD string
   *
   * @param {Object} graph - Graph object with @graph array
   * @param {Array} graph['@graph'] - Array of nodes (optional, can be graph.nodes)
   * @returns {string} JSON-LD string
   *
   * @example
   * const serializer = new JSONLDSerializer();
   * const jsonld = serializer.serialize({ '@graph': nodes });
   */
  serialize(graph) {
    // Build JSON-LD structure
    const jsonld = {
      '@context': this._buildContext(),
      '@graph': graph['@graph'] || graph.nodes || []
    };

    // Convert to string
    const indent = this.options.pretty ? 2 : 0;
    return JSON.stringify(jsonld, null, indent);
  }

  /**
   * Build the @context object with all namespaces and type coercions
   *
   * @returns {Object} @context object
   * @private
   */
  _buildContext() {
    return {
      // ===== Namespace Prefixes =====
      bfo: 'http://purl.obolibrary.org/obo/',
      cco: 'https://www.commoncoreontologies.org/',
      tagteam: 'http://tagteam.fandaws.org/ontology/',
      inst: 'http://tagteam.fandaws.org/instance/',
      rdf: 'http://www.w3.org/1999/02/22-rdf-syntax-ns#',
      rdfs: 'http://www.w3.org/2000/01/rdf-schema#',
      owl: 'http://www.w3.org/2002/07/owl#',
      xsd: 'http://www.w3.org/2001/XMLSchema#',

      // ===== Tier 1 Classes (ICE - Parsing Layer) =====
      DiscourseReferent: 'tagteam:DiscourseReferent',
      VerbPhrase: 'tagteam:VerbPhrase',
      DirectiveContent: 'tagteam:DirectiveContent',
      ScarcityAssertion: 'tagteam:ScarcityAssertion',
      ValueDetectionRecord: 'tagteam:ValueDetectionRecord',
      ContextAssessmentRecord: 'tagteam:ContextAssessmentRecord',
      InterpretationContext: 'tagteam:InterpretationContext',

      // ===== Week 2: Assertion Event Classes =====
      ValueAssertionEvent: 'tagteam:ValueAssertionEvent',
      ContextAssessmentEvent: 'tagteam:ContextAssessmentEvent',
      EthicalValueICE: 'tagteam:EthicalValueICE',
      ContextDimensionICE: 'tagteam:ContextDimensionICE',

      // ===== CCO Verified Classes (opaque IRIs from CCO 2.0) =====
      Act: 'cco:ont00000005',
      ActOfCommunication: 'cco:ont00000402',
      Agent: 'cco:ont00001017',
      Artifact: 'cco:ont00000995',
      Country: 'cco:ont00000139',
      Facility: 'cco:ont00000192',
      GeopoliticalOrganization: 'cco:ont00000176',
      InformationBearingEntity: 'cco:ont00000253',
      InformationContentEntity: 'cco:ont00000958',
      IntentionalAct: 'cco:ont00000228',
      Organization: 'cco:ont00001180',
      Person: 'cco:ont00001262',

      // ===== BFO Verified Classes (opaque IRIs from BFO 2020) =====
      Entity: 'bfo:BFO_0000001',
      Continuant: 'bfo:BFO_0000002',
      IndependentContinuant: 'bfo:BFO_0000004',
      TemporalRegion: 'bfo:BFO_0000008',
      Process: 'bfo:BFO_0000015',
      Disposition: 'bfo:BFO_0000016',
      Quality: 'bfo:BFO_0000019',
      Role: 'bfo:BFO_0000023',
      ObjectAggregate: 'bfo:BFO_0000027',
      Site: 'bfo:BFO_0000029',
      Object: 'bfo:BFO_0000030',
      GenericallyDependentContinuant: 'bfo:BFO_0000031',
      OneDimensionalTemporalRegion: 'bfo:BFO_0000038',
      MaterialEntity: 'bfo:BFO_0000040',
      RelationalQuality: 'bfo:BFO_0000145',

      // ===== GIT-Minimal Classes =====
      AutomatedDetection: 'tagteam:AutomatedDetection',
      HumanValidation: 'tagteam:HumanValidation',
      HumanRejection: 'tagteam:HumanRejection',
      HumanCorrection: 'tagteam:HumanCorrection',

      // ===== Actuality Status Named Individuals =====
      ActualityStatus: 'tagteam:ActualityStatus',
      Actual: 'tagteam:Actual',
      Prescribed: 'tagteam:Prescribed',
      Permitted: 'tagteam:Permitted',
      Prohibited: 'tagteam:Prohibited',
      Hypothetical: 'tagteam:Hypothetical',
      Planned: 'tagteam:Planned',
      Negated: 'tagteam:Negated',
      // Phase 6.4: Hohfeldian deontic statuses
      Entitled: 'tagteam:Entitled',      // Claim/Right holder status
      Empowered: 'tagteam:Empowered',    // Authority/Power status
      Protected: 'tagteam:Protected',    // Immunity/Protection status

      // ===== Cross-Tier Relations (CCO verified — opaque IRIs) =====
      is_about: { '@id': 'cco:ont00001808', '@type': '@id' },
      prescribes: { '@id': 'cco:ont00001942', '@type': '@id' },
      prescribed_by: { '@id': 'tagteam:prescribed_by', '@type': '@id' },

      // ===== ICE Concretization (BFO 2020) =====
      is_concretized_by: { '@id': 'bfo:BFO_0000058', '@type': '@id' },
      concretizes: { '@id': 'bfo:BFO_0000059', '@type': '@id' },

      // ===== Tier 1 Relations =====
      has_component: { '@id': 'tagteam:has_component', '@type': '@id' },
      extracted_from: { '@id': 'tagteam:extracted_from', '@type': '@id' },
      corefersWith: { '@id': 'tagteam:corefersWith', '@type': '@id' },
      describes_quality: { '@id': 'tagteam:describes_quality', '@type': '@id' },

      // ===== Tier 2 Relations (BFO 2020) =====
      inheres_in: { '@id': 'bfo:BFO_0000197', '@type': '@id' },
      is_bearer_of: { '@id': 'bfo:BFO_0000196', '@type': '@id' },
      realized_in: { '@id': 'bfo:BFO_0000054', '@type': '@id' },
      realizes: { '@id': 'bfo:BFO_0000055', '@type': '@id' },
      has_participant: { '@id': 'bfo:BFO_0000057', '@type': '@id' },
      has_member_part: { '@id': 'bfo:BFO_0000115', '@type': '@id' },

      // v2.3: Role realization (for Prescribed acts where role is not yet realized)
      would_be_realized_in: { '@id': 'tagteam:would_be_realized_in', '@type': '@id' },

      // ===== Tier 2 Relations (CCO verified — opaque IRIs) =====
      has_agent: { '@id': 'cco:ont00001833', '@type': '@id' },
      has_recipient: { '@id': 'cco:ont00001922', '@type': '@id' },
      has_input: { '@id': 'tagteam:has_input', '@type': '@id' },
      has_output: { '@id': 'tagteam:has_output', '@type': '@id' },
      affects: { '@id': 'cco:ont00001834', '@type': '@id' },
      designates: { '@id': 'cco:ont00001916', '@type': '@id' },
      is_designated_by: { '@id': 'cco:ont00001879', '@type': '@id' },
      is_measured_by: { '@id': 'cco:ont00001904', '@type': '@id' },
      measures: { '@id': 'cco:ont00001966', '@type': '@id' },
      uses_measurement_unit: { '@id': 'cco:ont00001863', '@type': '@id' },

      // ===== Tier 2 Relations (BFO re-exports — opaque IRIs) =====
      occupies_temporal_region: { '@id': 'bfo:BFO_0000199', '@type': '@id' },
      participates_in: { '@id': 'bfo:BFO_0000056', '@type': '@id' },
      is_part_of: { '@id': 'bfo:BFO_0000176', '@type': '@id' },

      // ===== Structural Assertion Relations (BFO verified) =====
      located_in: { '@id': 'bfo:BFO_0000171', '@type': '@id' },
      has_continuant_part: { '@id': 'bfo:BFO_0000178', '@type': '@id' },
      continuant_part_of: { '@id': 'bfo:BFO_0000176', '@type': '@id' },
      member_part_of: { '@id': 'bfo:BFO_0000129', '@type': '@id' },

      // ===== Structural Assertion Relations (TagTeam-defined — not in CCO/BFO) =====
      has_possession: { '@id': 'tagteam:has_possession', '@type': '@id' },
      has_function: { '@id': 'tagteam:has_function', '@type': '@id' },
      has_spatial_extent: { '@id': 'tagteam:has_spatial_extent', '@type': '@id' },
      bears_role_for: { '@id': 'tagteam:bears_role_for', '@type': '@id' },

      // ===== Aspirational Properties (not yet in use — tagteam namespace) =====
      occurs_during: { '@id': 'tagteam:occurs_during', '@type': '@id' },
      has_measurement_value: { '@id': 'tagteam:has_measurement_value', '@type': '@id' },
      has_start_time: { '@id': 'tagteam:has_start_time', '@type': '@id' },
      has_end_time: { '@id': 'tagteam:has_end_time', '@type': '@id' },

      // ===== GIT-Minimal Properties =====
      assertionType: { '@id': 'tagteam:assertionType', '@type': '@id' },
      validInContext: { '@id': 'tagteam:validInContext', '@type': '@id' },
      actualityStatus: { '@id': 'tagteam:actualityStatus', '@type': '@id' },
      validatedBy: { '@id': 'tagteam:validatedBy', '@type': '@id' },
      validationTimestamp: { '@id': 'tagteam:validationTimestamp', '@type': 'xsd:dateTime' },
      supersedes: { '@id': 'tagteam:supersedes', '@type': '@id' },
      framework: 'tagteam:framework',

      // ===== Provenance Properties (v2.2) =====
      instantiated_at: { '@id': 'tagteam:instantiated_at', '@type': 'xsd:dateTime' },
      instantiated_by: { '@id': 'tagteam:instantiated_by', '@type': '@id' },
      negationMarker: 'tagteam:negationMarker',

      // ===== Confidence Properties =====
      extractionConfidence: { '@id': 'tagteam:extractionConfidence', '@type': 'xsd:decimal' },
      classificationConfidence: { '@id': 'tagteam:classificationConfidence', '@type': 'xsd:decimal' },
      relevanceConfidence: { '@id': 'tagteam:relevanceConfidence', '@type': 'xsd:decimal' },
      aggregateConfidence: { '@id': 'tagteam:aggregateConfidence', '@type': 'xsd:decimal' },
      aggregationMethod: 'tagteam:aggregationMethod',

      // ===== Deontic Properties =====
      modalType: 'tagteam:modalType',
      modalMarker: 'tagteam:modalMarker',
      modalStrength: { '@id': 'tagteam:modalStrength', '@type': 'xsd:decimal' },

      // ===== Scarcity Properties (v2.3: ScarcityAssertion ICE) =====
      scarceResource: { '@id': 'tagteam:scarceResource', '@type': '@id' },
      competingParties: { '@id': 'tagteam:competingParties', '@type': '@id', '@container': '@set' },
      supplyCount: { '@id': 'tagteam:supplyCount', '@type': 'xsd:integer' },
      demandCount: { '@id': 'tagteam:demandCount', '@type': 'xsd:integer' },
      scarcityRatio: { '@id': 'tagteam:scarcityRatio', '@type': 'xsd:decimal' },
      scarcityMarker: 'tagteam:scarcityMarker',
      evidenceText: 'tagteam:evidenceText',
      detected_at: { '@id': 'tagteam:detected_at', '@type': 'xsd:dateTime' },

      // ===== Object Aggregate Properties (v2.3) =====
      member_count: { '@id': 'tagteam:member_count', '@type': 'xsd:integer' },
      member_index: { '@id': 'tagteam:member_index', '@type': 'xsd:integer' },

      // ===== Classification Properties (nomination pattern) =====
      classificationLabel: 'tagteam:classificationLabel',
      classificationBasis: 'tagteam:classificationBasis',

      // ===== Quality Properties (v2.4) =====
      qualifierText: 'tagteam:qualifierText',
      severity: 'tagteam:severity',
      ageCategory: 'tagteam:ageCategory',

      // ===== Discourse Referent Properties =====
      sourceText: 'tagteam:sourceText',
      startPosition: { '@id': 'tagteam:startPosition', '@type': 'xsd:integer' },
      endPosition: { '@id': 'tagteam:endPosition', '@type': 'xsd:integer' },
      definiteness: 'tagteam:definiteness',
      quantity: { '@id': 'tagteam:quantity', '@type': 'xsd:integer' },
      quantityIndicator: 'tagteam:quantityIndicator',
      qualifiers: 'tagteam:qualifiers',

      // ===== VerbPhrase Properties =====
      verb: 'tagteam:verb',
      lemma: 'tagteam:lemma',
      tense: 'tagteam:tense',
      hasModalMarker: 'tagteam:hasModalMarker',

      // ===== IBE Properties =====
      has_text_value: 'cco:ont00001765',
      char_count: { '@id': 'tagteam:char_count', '@type': 'xsd:integer' },
      word_count: { '@id': 'tagteam:word_count', '@type': 'xsd:integer' },
      received_at: { '@id': 'tagteam:received_at', '@type': 'xsd:dateTime' },
      temporal_extent: { '@id': 'tagteam:temporal_extent', '@type': 'xsd:dateTime' },

      // ===== Week 2: Parser Agent Properties =====
      version: 'tagteam:version',
      algorithm: 'tagteam:algorithm',
      capabilities: 'tagteam:capabilities',

      // ===== Week 2: Value/Context Assertion Properties =====
      valueName: 'tagteam:valueName',
      valueCategory: 'tagteam:valueCategory',
      evidence: 'tagteam:evidence',
      sourceSpan: 'tagteam:sourceSpan',
      category: 'tagteam:category',

      // ===== Value Detection Properties =====
      asserts: { '@id': 'tagteam:asserts', '@type': '@id' },
      detected_by: { '@id': 'tagteam:detected_by', '@type': '@id' },
      based_on: { '@id': 'tagteam:based_on', '@type': '@id' },
      polarity: { '@id': 'tagteam:polarity', '@type': 'xsd:integer' },
      salience: { '@id': 'tagteam:salience', '@type': 'xsd:decimal' },
      matched_markers: 'tagteam:matched_markers',
      detection_method: 'tagteam:detection_method',
      dimension: 'tagteam:dimension',
      score: { '@id': 'tagteam:score', '@type': 'xsd:decimal' }
    };
  }

  /**
   * Parse a JSON-LD string back to graph object
   *
   * @param {string} jsonldString - JSON-LD string
   * @returns {Object} Graph object
   */
  parse(jsonldString) {
    const parsed = JSON.parse(jsonldString);

    return {
      '@graph': parsed['@graph'] || [],
      '@context': parsed['@context']
    };
  }
}



  // ============================================================================
  // SCARCITY ASSERTION FACTORY (Phase 4 - v2.3)
  // Creates ScarcityAssertion ICE nodes for scarcity information
  // ============================================================================

/**
 * ScarcityAssertionFactory.js
 *
 * Creates ScarcityAssertion ICE nodes from detected scarcity in text.
 * Scarcity is an Information Content Entity (ICE), NOT a property of
 * real-world entities (Tier 2).
 *
 * Phase 4 Two-Tier Architecture v2.3:
 * - Scarcity info belongs in Tier 1 (ICE layer)
 * - ScarcityAssertion is_about the Tier 2 resource
 * - Tier 2 entities (Person, Artifact) stay clean
 *
 * @module graph/ScarcityAssertionFactory
 * @version 4.0.0-phase4-v2.3
 */

/**
 * ScarcityAssertionFactory - creates ScarcityAssertion ICE nodes
 */
class ScarcityAssertionFactory {
  /**
   * Create a new ScarcityAssertionFactory
   * @param {Object} options - Configuration options
   * @param {Object} [options.graphBuilder] - SemanticGraphBuilder for IRI generation
   * @param {string} [options.documentIRI] - Document IRI for provenance
   */
  constructor(options = {}) {
    this.options = options;
    this.graphBuilder = options.graphBuilder || null;
  }

  /**
   * Create ScarcityAssertion nodes from entities with scarcity markers
   *
   * @param {Array} tier1Referents - Tier 1 DiscourseReferent nodes
   * @param {Array} tier2Entities - Tier 2 entities
   * @param {Map} linkMap - Map from Tier 1 IRI to Tier 2 IRI
   * @returns {Object} { scarcityAssertions, cleanedReferents }
   */
  createFromEntities(tier1Referents, tier2Entities, linkMap) {
    const scarcityAssertions = [];
    const cleanedReferents = [];

    tier1Referents.forEach(referent => {
      // Check if this referent has scarcity markers
      const isScarce = referent['tagteam:is_scarce'];
      const scarcityMarker = referent['tagteam:scarcity_marker'];
      const quantity = referent['tagteam:quantity'];

      if (isScarce) {
        // Create ScarcityAssertion ICE node
        const tier2IRI = linkMap.get(referent['@id']);
        const assertion = this._createScarcityAssertion({
          sourceText: referent['tagteam:sourceText'] || referent['rdfs:label'],
          scarcityMarker,
          quantity,
          resourceIRI: tier2IRI,
          referentIRI: referent['@id']
        });
        scarcityAssertions.push(assertion);
      }

      // Create cleaned referent (without scarcity properties on Tier 1)
      // Keep scarcity on Tier 1 for now as evidence, but Tier 2 should be clean
      cleanedReferents.push(referent);
    });

    // Clean Tier 2 entities - remove scarcity properties
    const cleanedTier2 = tier2Entities.map(entity => {
      const cleaned = { ...entity };
      // Remove scarcity properties from Tier 2 (they belong in ScarcityAssertion)
      delete cleaned['tagteam:is_scarce'];
      delete cleaned['tagteam:scarcity_marker'];
      delete cleaned['tagteam:quantity'];
      return cleaned;
    });

    return {
      scarcityAssertions,
      cleanedReferents,
      cleanedTier2
    };
  }

  /**
   * Create a ScarcityAssertion node
   *
   * @param {Object} info - Scarcity information
   * @returns {Object} ScarcityAssertion node
   * @private
   */
  _createScarcityAssertion(info) {
    const { sourceText, scarcityMarker, quantity, resourceIRI, referentIRI } = info;

    // Generate IRI
    const iri = this._generateIRI(sourceText, resourceIRI);

    const assertion = {
      '@id': iri,
      '@type': ['tagteam:ScarcityAssertion', 'InformationContentEntity', 'owl:NamedIndividual'],
      'rdfs:label': `Resource Scarcity: ${sourceText}`,
      'tagteam:evidenceText': sourceText
    };

    // Add supply count (quantity of scarce resource)
    if (quantity !== null && quantity !== undefined) {
      assertion['tagteam:supplyCount'] = quantity;
    }

    // Add scarcity marker
    if (scarcityMarker) {
      assertion['tagteam:scarcityMarker'] = scarcityMarker;
    }

    // Link to the Tier 2 resource this is about
    if (resourceIRI) {
      assertion['is_about'] = { '@id': resourceIRI };
    }

    // Link to the source referent
    if (referentIRI) {
      assertion['tagteam:extracted_from'] = { '@id': referentIRI };
    }

    // Add timestamp
    assertion['tagteam:detected_at'] = new Date().toISOString();

    return assertion;
  }

  /**
   * Generate IRI for a ScarcityAssertion
   *
   * @param {string} sourceText - Source text
   * @param {string} resourceIRI - Resource IRI
   * @returns {string} Generated IRI
   * @private
   */
  _generateIRI(sourceText, resourceIRI) {
    const hashInput = `ScarcityAssertion|${sourceText}|${resourceIRI || ''}`;

    const hash = crypto
      .createHash('sha256')
      .update(hashInput)
      .digest('hex')
      .substring(0, 12);

    // Clean source text for IRI
    const cleanText = (sourceText || 'resource')
      .split(' ')
      .slice(0, 3)
      .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
      .join('_')
      .replace(/[^a-zA-Z0-9_]/g, '');

    return `inst:ScarcityAssertion_${cleanText}_${hash}`;
  }

  /**
   * Set the graph builder
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
  }
}



  // ============================================================================
  // DIRECTIVE EXTRACTOR (Phase 4 - v2.3)
  // Extracts DirectiveContent ICE for modal markers (must, should, may)
  // ============================================================================

/**
 * DirectiveExtractor.js
 *
 * Extracts Directive Information Content Entities from text.
 * Directives represent deontic/modal content (must, should, may, etc.)
 *
 * Phase 4 Two-Tier Architecture v2.3:
 * - DirectiveInformationContentEntity for modal markers
 * - Links to acts via cco:prescribes
 * - Properly separates linguistic content (ICE) from acts (occurrents)
 *
 * @module graph/DirectiveExtractor
 * @version 4.0.0-phase4-v2.3
 */

/**
 * Modal marker to deontic type mapping
 */
const MODAL_MAPPINGS = {
  // Obligation (must, have to, shall)
  'must': { type: 'obligation', strength: 1.0 },
  'shall': { type: 'obligation', strength: 1.0 },
  'have to': { type: 'obligation', strength: 0.9 },
  'need to': { type: 'obligation', strength: 0.8 },
  'ought to': { type: 'obligation', strength: 0.7 },
  'should': { type: 'obligation', strength: 0.6 },

  // Permission (may, can, could)
  'may': { type: 'permission', strength: 0.7 },
  'can': { type: 'permission', strength: 0.6 },
  'could': { type: 'permission', strength: 0.5 },
  'might': { type: 'permission', strength: 0.4 },

  // Prohibition (must not, cannot)
  'must not': { type: 'prohibition', strength: 1.0 },
  'cannot': { type: 'prohibition', strength: 0.9 },
  'shall not': { type: 'prohibition', strength: 1.0 },

  // Intention (will, going to)
  'will': { type: 'intention', strength: 0.8 },
  'going to': { type: 'intention', strength: 0.7 }
};

/**
 * DirectiveExtractor - extracts deontic/modal directives from text
 */
class DirectiveExtractor {
  /**
   * Create a new DirectiveExtractor
   * @param {Object} options - Configuration options
   */
  constructor(options = {}) {
    this.options = options;
    this.graphBuilder = options.graphBuilder || null;
  }

  /**
   * Extract Directive ICE nodes from acts
   *
   * @param {Array} acts - Array of IntentionalAct nodes
   * @param {string} fullText - Original input text
   * @returns {Array<Object>} Array of DirectiveInformationContentEntity nodes
   */
  extract(acts, fullText) {
    const directives = [];

    acts.forEach(act => {
      const modality = act['tagteam:modality'];

      if (modality) {
        // Find the modal marker in the source text
        const sourceText = act['tagteam:sourceText'] || '';
        const modalMarker = this._findModalMarker(sourceText, fullText);

        if (modalMarker) {
          const directive = this._createDirective({
            modalMarker: modalMarker.marker,
            modalType: modalMarker.type,
            modalStrength: modalMarker.strength,
            actIRI: act['@id'],
            sourceText: act['tagteam:sourceText']
          });
          directives.push(directive);

          // Link act back to directive
          act['tagteam:prescribed_by'] = { '@id': directive['@id'] };
        }
      }
    });

    return directives;
  }

  /**
   * Find modal marker in text
   *
   * @param {string} sourceText - Act source text
   * @param {string} fullText - Full input text
   * @returns {Object|null} Modal info or null
   * @private
   */
  _findModalMarker(sourceText, fullText) {
    const textLower = sourceText.toLowerCase();

    // Check for multi-word markers first (must not, have to, etc.)
    const multiWordMarkers = ['must not', 'shall not', 'have to', 'need to', 'ought to', 'going to'];
    for (const marker of multiWordMarkers) {
      if (textLower.includes(marker)) {
        const mapping = MODAL_MAPPINGS[marker];
        return { marker, ...mapping };
      }
    }

    // Check single-word markers
    for (const [marker, mapping] of Object.entries(MODAL_MAPPINGS)) {
      if (!marker.includes(' ') && textLower.includes(marker)) {
        return { marker, ...mapping };
      }
    }

    return null;
  }

  /**
   * Create a DirectiveInformationContentEntity node
   *
   * @param {Object} info - Directive information
   * @returns {Object} Directive ICE node
   * @private
   */
  _createDirective(info) {
    const { modalMarker, modalType, modalStrength, actIRI, sourceText } = info;

    // Generate IRI
    const iri = this._generateIRI(modalMarker, actIRI);

    const directive = {
      '@id': iri,
      // Per ontology: DirectiveContent is subclass of both DeonticContent and InformationContentEntity
      '@type': ['tagteam:DirectiveContent', 'InformationContentEntity', 'owl:NamedIndividual'],
      'rdfs:label': `${modalType.charAt(0).toUpperCase() + modalType.slice(1)} Directive: ${modalMarker}`,
      'tagteam:modalMarker': modalMarker,
      'tagteam:modalType': modalType,
      'tagteam:modalStrength': modalStrength,

      // Link to the act this directive prescribes
      'prescribes': { '@id': actIRI }
    };

    if (sourceText) {
      directive['tagteam:evidenceText'] = sourceText;
    }

    return directive;
  }

  /**
   * Generate IRI for a Directive
   *
   * @param {string} modalMarker - Modal marker
   * @param {string} actIRI - Act IRI
   * @returns {string} Generated IRI
   * @private
   */
  _generateIRI(modalMarker, actIRI) {
    const hashInput = `Directive|${modalMarker}|${actIRI}`;

    const hash = crypto
      .createHash('sha256')
      .update(hashInput)
      .digest('hex')
      .substring(0, 12);

    const cleanMarker = modalMarker
      .split(' ')
      .map(w => w.charAt(0).toUpperCase() + w.slice(1))
      .join('_');

    return `inst:Directive_${cleanMarker}_${hash}`;
  }

  /**
   * Set the graph builder
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
  }
}



  // ============================================================================
  // OBJECT AGGREGATE FACTORY (Phase 4 - v2.3)
  // Creates ObjectAggregate for plural entities with individual members
  // ============================================================================

/**
 * ObjectAggregateFactory.js
 *
 * Creates BFO Object Aggregate nodes for plural entities.
 * When text mentions "two patients", this creates:
 * - Two individual Person nodes
 * - One bfo:BFO_0000027 (Object Aggregate) containing them
 *
 * Phase 4 Two-Tier Architecture v2.3:
 * - Properly represents plural entities as aggregates
 * - Each member is a distinct Independent Continuant
 * - Aggregate has has_member relations to individuals
 *
 * @module graph/ObjectAggregateFactory
 * @version 4.0.0-phase4-v2.3
 */

/**
 * ObjectAggregateFactory - creates aggregates for plural entities
 */
class ObjectAggregateFactory {
  /**
   * Create a new ObjectAggregateFactory
   * @param {Object} options - Configuration options
   * @param {Object} [options.lemmatizer] - Lemmatizer instance for morphological reduction
   */
  constructor(options = {}) {
    this.options = options;
    this.graphBuilder = options.graphBuilder || null;
    this.lemmatizer = options.lemmatizer || null;
  }

  /**
   * Process Tier 2 entities and create aggregates for plural entities
   *
   * @param {Array} tier2Entities - Array of Tier 2 entities
   * @param {Array} tier1Referents - Array of Tier 1 referents (for quantity info)
   * @param {Map} linkMap - Map from Tier 1 IRI to Tier 2 IRI
   * @returns {Object} { expandedEntities, aggregates, updatedLinkMap }
   */
  processEntities(tier2Entities, tier1Referents, linkMap) {
    const expandedEntities = [];
    const aggregates = [];
    const updatedLinkMap = new Map(linkMap);

    // Build reverse map: Tier 2 IRI -> Tier 1 referent
    const reverseMap = new Map();
    linkMap.forEach((tier2IRI, tier1IRI) => {
      reverseMap.set(tier2IRI, tier1Referents.find(r => r['@id'] === tier1IRI));
    });

    tier2Entities.forEach(entity => {
      const referent = reverseMap.get(entity['@id']);
      const quantity = referent ? referent['tagteam:quantity'] : null;

      // Check if this is a plural entity (quantity > 1)
      if (quantity && quantity > 1 && this._isPersonEntity(entity)) {
        // Create individual members
        const members = this._createMembers(entity, quantity, referent);
        expandedEntities.push(...members);

        // Create aggregate
        const aggregate = this._createAggregate(entity, members, referent);
        aggregates.push(aggregate);

        // Update link map: referent now points to aggregate
        const tier1IRI = [...linkMap.entries()]
          .find(([t1, t2]) => t2 === entity['@id'])?.[0];
        if (tier1IRI) {
          updatedLinkMap.set(tier1IRI, aggregate['@id']);
        }

        // Don't include the original entity (it's been expanded)
      } else {
        // Keep entity as-is
        expandedEntities.push(entity);
      }
    });

    return {
      expandedEntities,
      aggregates,
      updatedLinkMap
    };
  }

  /**
   * Check if entity is a Person type
   * @param {Object} entity - Entity node
   * @returns {boolean} True if Person
   * @private
   */
  _isPersonEntity(entity) {
    const types = entity['@type'] || [];
    return types.some(t => t.includes('Person'));
  }

  /**
   * Create individual member entities
   *
   * @param {Object} originalEntity - Original plural entity
   * @param {number} count - Number of members
   * @param {Object} referent - Source referent
   * @returns {Array<Object>} Array of individual member nodes
   * @private
   */
  _createMembers(originalEntity, count, referent) {
    const members = [];
    let baseLabel = originalEntity['rdfs:label'] || 'entity';
    if (this.lemmatizer) {
      baseLabel = this.lemmatizer.lemmatizePhrase(baseLabel);
    }

    // Extract qualifiers from label (e.g., "critically ill" from "two critically ill patients")
    const qualifiers = this._extractQualifiers(referent);

    for (let i = 1; i <= count; i++) {
      const member = {
        '@id': this._generateMemberIRI(originalEntity['@id'], i),
        '@type': [...originalEntity['@type']],
        'rdfs:label': `${baseLabel.replace(/two|three|four|five|six|seven|eight|nine|ten|\d+/i, '').trim()} ${i}`,
        'tagteam:instantiated_at': new Date().toISOString(),
        'tagteam:member_index': i
      };

      // Add qualifiers as qualities if present
      if (qualifiers.length > 0) {
        member['tagteam:qualifiers'] = qualifiers;
      }

      members.push(member);
    }

    return members;
  }

  /**
   * Create an Object Aggregate node
   *
   * @param {Object} originalEntity - Original plural entity
   * @param {Array} members - Member entities
   * @param {Object} referent - Source referent
   * @returns {Object} Object Aggregate node
   * @private
   */
  _createAggregate(originalEntity, members, referent) {
    let label = referent?.['rdfs:label'] || originalEntity['rdfs:label'];
    if (this.lemmatizer) {
      label = this.lemmatizer.lemmatizePhrase(label);
    }

    const aggregate = {
      '@id': this._generateAggregateIRI(originalEntity['@id']),
      '@type': ['ObjectAggregate', 'owl:NamedIndividual'], // Object Aggregate
      'rdfs:label': `Aggregate of ${label}`,
      // Use object notation with @id for JSON-LD compliance
      'has_member_part': members.map(m => ({ '@id': m['@id'] })),
      'tagteam:member_count': members.length,
      'tagteam:instantiated_at': new Date().toISOString()
    };

    return aggregate;
  }

  /**
   * Extract qualifiers from referent label
   *
   * @param {Object} referent - Source referent
   * @returns {Array<string>} Array of qualifier strings
   * @private
   */
  _extractQualifiers(referent) {
    if (!referent) return [];

    const label = referent['rdfs:label'] || '';
    const qualifiers = [];

    // Common medical qualifiers
    const qualifierPatterns = [
      /critically\s+ill/i,
      /terminally\s+ill/i,
      /severely\s+injured/i,
      /elderly/i,
      /young/i,
      /pediatric/i
    ];

    qualifierPatterns.forEach(pattern => {
      const match = label.match(pattern);
      if (match) {
        qualifiers.push(match[0].toLowerCase());
      }
    });

    return qualifiers;
  }

  /**
   * Generate IRI for a member
   * @private
   */
  _generateMemberIRI(baseIRI, index) {
    const hash = crypto
      .createHash('sha256')
      .update(`${baseIRI}|member|${index}`)
      .digest('hex')
      .substring(0, 12);

    // Extract entity type from base IRI
    const typeMatch = baseIRI.match(/inst:(\w+)_/);
    const type = typeMatch ? typeMatch[1] : 'Entity';

    return `inst:${type}_Member_${index}_${hash}`;
  }

  /**
   * Generate IRI for an aggregate
   * @private
   */
  _generateAggregateIRI(baseIRI) {
    const hash = crypto
      .createHash('sha256')
      .update(`${baseIRI}|aggregate`)
      .digest('hex')
      .substring(0, 12);

    return `inst:ObjectAggregate_${hash}`;
  }

  /**
   * Set the graph builder
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
  }
}



  // ============================================================================
  // QUALITY FACTORY (Phase 4 - v2.4)
  // Creates BFO Quality nodes for entity qualifiers
  // ============================================================================

/**
 * QualityFactory.js
 *
 * Creates BFO Quality nodes (bfo:BFO_0000019) for entity qualifiers.
 * Qualities inhere in Independent Continuants and represent their
 * intrinsic properties.
 *
 * Phase 4 Two-Tier Architecture v2.4:
 * - "critically ill" → Quality inhering in Person
 * - Links qualities to bearers via inheres_in (BFO_0000197)
 *
 * @module graph/QualityFactory
 * @version 4.0.0-phase4-v2.4
 */

/**
 * Known quality types mapped to BFO/CCO types
 */
const QUALITY_TYPE_MAPPINGS = {
  'critically ill': {
    type: 'Quality',
    label: 'Critical Illness Quality',
    severity: 'critical'
  },
  'terminally ill': {
    type: 'Quality',
    label: 'Terminal Illness Quality',
    severity: 'terminal'
  },
  'severely injured': {
    type: 'Quality',
    label: 'Severe Injury Quality',
    severity: 'severe'
  },
  'elderly': {
    type: 'Quality',
    label: 'Elderly Age Quality',
    ageCategory: 'elderly'
  },
  'young': {
    type: 'Quality',
    label: 'Young Age Quality',
    ageCategory: 'young'
  },
  'pediatric': {
    type: 'Quality',
    label: 'Pediatric Age Quality',
    ageCategory: 'pediatric'
  }
};

/**
 * QualityFactory - creates BFO Quality nodes for entity qualifiers
 */
class QualityFactory {
  /**
   * Create a new QualityFactory
   * @param {Object} options - Configuration options
   */
  constructor(options = {}) {
    this.options = options;
    this.graphBuilder = options.graphBuilder || null;
  }

  /**
   * Create Quality nodes for entities with qualifiers
   *
   * @param {Array} entities - Array of Tier 2 entities
   * @returns {Object} { qualities, updatedEntities }
   */
  createFromEntities(entities) {
    const qualities = [];
    const updatedEntities = [];

    entities.forEach(entity => {
      const entityQualities = [];
      const qualifiers = entity['tagteam:qualifiers'] || [];

      if (qualifiers.length > 0) {
        qualifiers.forEach(qualifier => {
          const quality = this._createQuality(qualifier, entity);
          if (quality) {
            qualities.push(quality);
            entityQualities.push(quality['@id']);
          }
        });
      }

      // Update entity with quality bearer links
      const updatedEntity = { ...entity };
      if (entityQualities.length > 0) {
        updatedEntity['is_bearer_of'] = [
          ...(updatedEntity['is_bearer_of'] || []),
          ...entityQualities
        ];
      }
      updatedEntities.push(updatedEntity);
    });

    return { qualities, updatedEntities };
  }

  /**
   * Create a Quality node for a qualifier
   *
   * @param {string} qualifier - Qualifier string (e.g., "critically ill")
   * @param {Object} bearer - Bearer entity
   * @returns {Object|null} Quality node or null if unknown qualifier
   * @private
   */
  _createQuality(qualifier, bearer) {
    const normalizedQualifier = qualifier.toLowerCase().trim();
    const mapping = QUALITY_TYPE_MAPPINGS[normalizedQualifier];

    if (!mapping) {
      // Unknown qualifier - create generic quality
      return this._createGenericQuality(qualifier, bearer);
    }

    const iri = this._generateQualityIRI(qualifier, bearer['@id']);

    const quality = {
      '@id': iri,
      '@type': [mapping.type, 'Quality', 'owl:NamedIndividual'],
      'rdfs:label': `${mapping.label} of ${bearer['rdfs:label']}`,
      // Use object notation with @id for JSON-LD compliance
      'inheres_in': { '@id': bearer['@id'] },
      'tagteam:qualifierText': qualifier,
      'tagteam:instantiated_at': new Date().toISOString()
    };

    // Add severity/category if applicable
    if (mapping.severity) {
      quality['tagteam:severity'] = mapping.severity;
    }
    if (mapping.ageCategory) {
      quality['tagteam:ageCategory'] = mapping.ageCategory;
    }

    return quality;
  }

  /**
   * Create a generic Quality node for unknown qualifiers
   *
   * @param {string} qualifier - Qualifier string
   * @param {Object} bearer - Bearer entity
   * @returns {Object} Quality node
   * @private
   */
  _createGenericQuality(qualifier, bearer) {
    const iri = this._generateQualityIRI(qualifier, bearer['@id']);

    return {
      '@id': iri,
      '@type': ['Quality', 'owl:NamedIndividual'],
      'rdfs:label': `${qualifier} quality of ${bearer['rdfs:label']}`,
      // Use object notation with @id for JSON-LD compliance
      'inheres_in': { '@id': bearer['@id'] },
      'tagteam:qualifierText': qualifier,
      'tagteam:instantiated_at': new Date().toISOString()
    };
  }

  /**
   * Generate IRI for a quality
   * @private
   */
  _generateQualityIRI(qualifier, bearerIRI) {
    const hash = crypto
      .createHash('sha256')
      .update(`${qualifier}|${bearerIRI}`)
      .digest('hex')
      .substring(0, 12);

    // Normalize qualifier for IRI
    const qualifierSlug = qualifier
      .replace(/\s+/g, '_')
      .replace(/[^a-zA-Z0-9_]/g, '')
      .substring(0, 20);

    return `inst:Quality_${qualifierSlug}_${hash}`;
  }

  /**
   * Set the graph builder
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
  }
}



  // ============================================================================
  // ASSERTION EVENT BUILDER (Phase 4 - Week 2)
  // Creates ValueAssertionEvent and ContextAssessmentEvent nodes
  // ============================================================================

/**
 * AssertionEventBuilder.js
 *
 * Creates ValueAssertionEvent and ContextAssessmentEvent nodes.
 * Wraps existing value and context detections as semantically honest
 * assertion events with GIT-Minimal provenance tracking.
 *
 * Phase 4 Week 2 Implementation:
 * - Three-way confidence decomposition (extraction, classification, relevance)
 * - GIT-Minimal properties (assertionType, validInContext)
 * - ICE nodes as separate entities linked via asserts
 * - Parser agent provenance via detected_by
 * - IBE linkage via based_on
 *
 * @module graph/AssertionEventBuilder
 * @version 4.0.0-phase4-week2
 */

/**
 * Context dimension definitions for ContextAssessmentEvents
 * Maps to ContextAnalyzer's 12 dimensions
 */
const CONTEXT_DIMENSIONS = {
  // Temporal
  urgency: { category: 'temporal', label: 'Urgency' },
  timePressure: { category: 'temporal', label: 'Time Pressure' },
  irreversibility: { category: 'temporal', label: 'Irreversibility' },

  // Relational
  powerDifferential: { category: 'relational', label: 'Power Differential' },
  dependencyLevel: { category: 'relational', label: 'Dependency Level' },
  trustRequirement: { category: 'relational', label: 'Trust Requirement' },

  // Consequential
  stakesLevel: { category: 'consequential', label: 'Stakes Level' },
  scopeOfImpact: { category: 'consequential', label: 'Scope of Impact' },
  cascadeRisk: { category: 'consequential', label: 'Cascade Risk' },

  // Epistemic
  informationCompleteness: { category: 'epistemic', label: 'Information Completeness' },
  expertiseRequired: { category: 'epistemic', label: 'Expertise Required' },
  uncertaintyLevel: { category: 'epistemic', label: 'Uncertainty Level' }
};

/**
 * AssertionEventBuilder - creates assertion events with GIT-Minimal provenance
 */
class AssertionEventBuilder {
  /**
   * Create a new AssertionEventBuilder
   * @param {Object} options - Configuration options
   * @param {Object} [options.graphBuilder] - SemanticGraphBuilder instance
   * @param {string} [options.namespace='inst'] - IRI namespace prefix
   */
  constructor(options = {}) {
    this.options = {
      namespace: options.namespace || 'inst',
      ...options
    };
    this.graphBuilder = options.graphBuilder || null;
  }

  /**
   * Create ValueAssertionEvents from scored values
   *
   * @param {Array} scoredValues - Array from ValueScorer.scoreValues()
   * @param {Object} context - Context for assertions
   * @param {string} context.contextIRI - InterpretationContext IRI
   * @param {string} context.ibeIRI - Input IBE IRI
   * @param {string} context.parserAgentIRI - Parser agent IRI
   * @returns {Object} { assertionEvents: [], iceNodes: [] }
   */
  createValueAssertions(scoredValues, context) {
    const assertionEvents = [];
    const iceNodes = [];

    if (!scoredValues || !Array.isArray(scoredValues)) {
      return { assertionEvents, iceNodes };
    }

    scoredValues.forEach((scoredValue, index) => {
      // Create ICE node for the value content
      const iceNode = this._createValueICE(scoredValue, context, index);
      iceNodes.push(iceNode);

      // Create assertion event
      const assertionEvent = this._createValueAssertionEvent(
        scoredValue,
        iceNode['@id'],
        context,
        index
      );
      assertionEvents.push(assertionEvent);
    });

    return { assertionEvents, iceNodes };
  }

  /**
   * Create ContextAssessmentEvents from context analysis
   *
   * @param {Object} contextIntensity - Object from ContextAnalyzer.analyzeContext()
   * @param {Object} context - Context for assertions
   * @param {string} context.contextIRI - InterpretationContext IRI
   * @param {string} context.ibeIRI - Input IBE IRI
   * @param {string} context.parserAgentIRI - Parser agent IRI
   * @returns {Object} { assessmentEvents: [], iceNodes: [] }
   */
  createContextAssessments(contextIntensity, context) {
    const assessmentEvents = [];
    const iceNodes = [];

    if (!contextIntensity || typeof contextIntensity !== 'object') {
      return { assessmentEvents, iceNodes };
    }

    // Process each dimension
    Object.entries(CONTEXT_DIMENSIONS).forEach(([dimension, meta]) => {
      const score = contextIntensity[dimension];
      if (score === undefined || score === null) return;

      // Create ICE node for dimension content
      const iceNode = this._createContextDimensionICE(dimension, score, meta, context);
      iceNodes.push(iceNode);

      // Create assessment event
      const assessmentEvent = this._createContextAssessmentEvent(
        dimension,
        score,
        meta,
        iceNode['@id'],
        context
      );
      assessmentEvents.push(assessmentEvent);
    });

    return { assessmentEvents, iceNodes };
  }

  /**
   * Compute three-way confidence breakdown
   *
   * @param {Object} scoredValue - Scored value with confidence data
   * @returns {Object} { extraction, classification, relevance, aggregate }
   */
  _computeConfidenceBreakdown(scoredValue) {
    // Extract confidence components
    // If not provided, use reasonable defaults based on overall confidence
    const overallConfidence = scoredValue.confidence || scoredValue.score || 0.5;

    // Extraction: How confident we found the text pattern
    const extraction = scoredValue.extractionConfidence ||
                       scoredValue.patternStrength ||
                       Math.min(1.0, overallConfidence + 0.1);

    // Classification: How confident it's the right value type
    const classification = scoredValue.classificationConfidence ||
                           scoredValue.typeConfidence ||
                           overallConfidence;

    // Relevance: How relevant to the ethical context
    const relevance = scoredValue.relevanceConfidence ||
                      scoredValue.contextualScore ||
                      Math.max(0.5, overallConfidence - 0.1);

    // Aggregate: Geometric mean (conservative combination)
    const aggregate = Math.pow(extraction * classification * relevance, 1/3);

    return {
      extraction: this._roundConfidence(extraction),
      classification: this._roundConfidence(classification),
      relevance: this._roundConfidence(relevance),
      aggregate: this._roundConfidence(aggregate)
    };
  }

  /**
   * Create EthicalValueICE node
   *
   * @param {Object} scoredValue - Scored value
   * @param {Object} context - Context for assertions
   * @param {number} index - Index for uniqueness
   * @returns {Object} ICE node
   * @private
   */
  _createValueICE(scoredValue, context, index) {
    const valueName = scoredValue.value || scoredValue.name || 'UnknownValue';
    const iri = this._generateIRI(valueName, 'ICE', index);

    return {
      '@id': iri,
      '@type': ['tagteam:EthicalValueICE', 'InformationContentEntity', 'owl:NamedIndividual'],
      'rdfs:label': `${valueName} Value Content`,
      'is_about': { '@id': `tagteam:${valueName}` },
      'is_concretized_by': { '@id': context.ibeIRI },
      'tagteam:valueName': valueName,
      'tagteam:valueCategory': scoredValue.category || 'ethical',
      'tagteam:instantiated_at': new Date().toISOString()
    };
  }

  /**
   * Create ValueAssertionEvent node
   *
   * @param {Object} scoredValue - Scored value
   * @param {string} iceIRI - ICE node IRI
   * @param {Object} context - Context for assertions
   * @param {number} index - Index for uniqueness
   * @returns {Object} Assertion event node
   * @private
   */
  _createValueAssertionEvent(scoredValue, iceIRI, context, index) {
    const valueName = scoredValue.value || scoredValue.name || 'UnknownValue';
    const iri = this._generateIRI(valueName, 'ValueAssertion', index);
    const confidence = this._computeConfidenceBreakdown(scoredValue);

    const event = {
      '@id': iri,
      '@type': ['tagteam:ValueAssertionEvent', 'owl:NamedIndividual'],
      'rdfs:label': `${valueName} Value Assertion`,

      // Core assertion links
      'tagteam:asserts': { '@id': iceIRI },
      'tagteam:detected_by': { '@id': context.parserAgentIRI },
      'tagteam:based_on': { '@id': context.ibeIRI },

      // GIT-Minimal required properties
      'tagteam:assertionType': { '@id': 'tagteam:AutomatedDetection' },
      'tagteam:validInContext': { '@id': context.contextIRI },

      // Three-way confidence decomposition
      'tagteam:extractionConfidence': confidence.extraction,
      'tagteam:classificationConfidence': confidence.classification,
      'tagteam:relevanceConfidence': confidence.relevance,
      'tagteam:aggregateConfidence': confidence.aggregate,
      'tagteam:aggregationMethod': 'geometric_mean',

      // Metadata
      'tagteam:instantiated_at': new Date().toISOString()
    };

    // Add evidence if available
    if (scoredValue.evidence || scoredValue.matchedText) {
      event['tagteam:evidence'] = scoredValue.evidence || scoredValue.matchedText;
    }

    // Add source span if available
    if (scoredValue.span) {
      event['tagteam:sourceSpan'] = scoredValue.span;
    }

    return event;
  }

  /**
   * Create ContextDimensionICE node
   *
   * @param {string} dimension - Dimension name
   * @param {number} score - Dimension score
   * @param {Object} meta - Dimension metadata
   * @param {Object} context - Context for assertions
   * @returns {Object} ICE node
   * @private
   */
  _createContextDimensionICE(dimension, score, meta, context) {
    const iri = this._generateIRI(dimension, 'DimensionICE', 0);

    return {
      '@id': iri,
      '@type': ['tagteam:ContextDimensionICE', 'InformationContentEntity', 'owl:NamedIndividual'],
      'rdfs:label': `${meta.label} Dimension Content`,
      'is_concretized_by': context.ibeIRI,
      'tagteam:dimension': dimension,
      'tagteam:category': meta.category,
      'tagteam:score': this._roundConfidence(score),
      'tagteam:instantiated_at': new Date().toISOString()
    };
  }

  /**
   * Create ContextAssessmentEvent node
   *
   * @param {string} dimension - Dimension name
   * @param {number} score - Dimension score
   * @param {Object} meta - Dimension metadata
   * @param {string} iceIRI - ICE node IRI
   * @param {Object} context - Context for assertions
   * @returns {Object} Assessment event node
   * @private
   */
  _createContextAssessmentEvent(dimension, score, meta, iceIRI, context) {
    const iri = this._generateIRI(dimension, 'ContextAssessment', 0);

    return {
      '@id': iri,
      '@type': ['tagteam:ContextAssessmentEvent', 'owl:NamedIndividual'],
      'rdfs:label': `${meta.label} Context Assessment`,

      // Core assertion links
      'tagteam:asserts': { '@id': iceIRI },
      'tagteam:detected_by': { '@id': context.parserAgentIRI },
      'tagteam:based_on': { '@id': context.ibeIRI },

      // GIT-Minimal required properties
      'tagteam:assertionType': { '@id': 'tagteam:AutomatedDetection' },
      'tagteam:validInContext': { '@id': context.contextIRI },

      // Dimension-specific properties
      'tagteam:dimension': dimension,
      'tagteam:category': meta.category,
      'tagteam:score': this._roundConfidence(score),

      // Confidence (simpler for context assessment - single score)
      'tagteam:aggregateConfidence': this._roundConfidence(score),
      'tagteam:aggregationMethod': 'direct_score',

      // Metadata
      'tagteam:instantiated_at': new Date().toISOString()
    };
  }

  /**
   * Generate deterministic IRI
   *
   * @param {string} text - Text for IRI
   * @param {string} type - Type label
   * @param {number} index - Index for uniqueness
   * @returns {string} IRI
   * @private
   */
  _generateIRI(text, type, index) {
    const hash = crypto
      .createHash('sha256')
      .update(`${text}|${type}|${index}|${Date.now()}`)
      .digest('hex')
      .substring(0, 12);

    const cleanText = text
      .replace(/\s+/g, '_')
      .replace(/[^a-zA-Z0-9_]/g, '')
      .substring(0, 20);

    return `${this.options.namespace}:${cleanText}_${type}_${hash}`;
  }

  /**
   * Round confidence to 2 decimal places
   *
   * @param {number} value - Confidence value
   * @returns {number} Rounded value
   * @private
   */
  _roundConfidence(value) {
    return Math.round(value * 100) / 100;
  }

  /**
   * Set the graph builder
   *
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
  }
}



  // ============================================================================
  // CONTEXT MANAGER (Phase 4 - Week 2)
  // Manages InterpretationContext nodes for GIT-Minimal compliance
  // ============================================================================

/**
 * ContextManager.js
 *
 * Manages InterpretationContext nodes for GIT-Minimal compliance.
 * Every assertion must have a validInContext link.
 *
 * Phase 4 Week 2 Implementation:
 * - Predefined interpretation contexts (MedicalEthics, etc.)
 * - Default context fallback (tagteam:Default_Context vocabulary term)
 * - Context node generation with framework metadata
 *
 * @module graph/ContextManager
 * @version 4.0.0-phase4-week2
 */

/**
 * Predefined interpretation contexts
 * These represent common ethical frameworks for value interpretation
 */
const PREDEFINED_CONTEXTS = {
  MedicalEthics: {
    label: 'Medical Ethics Framework',
    framework: 'Principlism (Beauchamp & Childress)',
    comment: 'Four principles: autonomy, beneficence, non-maleficence, justice'
  },
  DeontologicalEthics: {
    label: 'Deontological Ethics Framework',
    framework: 'Kantian',
    comment: 'Duty-based reasoning, categorical imperative'
  },
  UtilitarianEthics: {
    label: 'Utilitarian Ethics Framework',
    framework: 'Consequentialist',
    comment: 'Greatest good for greatest number'
  },
  VirtueEthics: {
    label: 'Virtue Ethics Framework',
    framework: 'Aristotelian',
    comment: 'Character, flourishing, moral exemplars'
  },
  CareEthics: {
    label: 'Care Ethics Framework',
    framework: 'Relational',
    comment: 'Relationships, responsibilities, context-sensitive care'
  },
  BusinessEthics: {
    label: 'Business Ethics Framework',
    framework: 'Stakeholder Theory',
    comment: 'Corporate responsibility, stakeholder interests, sustainability'
  },
  ResearchEthics: {
    label: 'Research Ethics Framework',
    framework: 'Belmont Report',
    comment: 'Respect for persons, beneficence, justice in research'
  },
  Default: {
    label: 'Default Interpretation Context',
    framework: 'TagTeam General',
    comment: 'No specific framework; general ethical value detection'
  }
};

/**
 * ContextManager - manages InterpretationContext nodes
 */
class ContextManager {
  /**
   * Create a new ContextManager
   * @param {Object} options - Configuration options
   * @param {Object} [options.graphBuilder] - SemanticGraphBuilder instance
   * @param {string} [options.namespace='inst'] - IRI namespace prefix
   */
  constructor(options = {}) {
    this.options = {
      namespace: options.namespace || 'inst',
      ...options
    };
    this.graphBuilder = options.graphBuilder || null;

    // Cache for created context nodes
    this._contextCache = new Map();
  }

  /**
   * Get or create InterpretationContext node
   *
   * @param {string} contextName - Context name (e.g., 'MedicalEthics', 'Default')
   * @returns {Object|null} Context node for @graph, or null for Default
   */
  getOrCreateContext(contextName) {
    // Default context uses vocabulary term, no node needed
    if (contextName === 'Default') {
      return null;
    }

    // Return cached node if already created
    if (this._contextCache.has(contextName)) {
      return this._contextCache.get(contextName);
    }

    // Create new context node
    const node = this._createContextNode(contextName);
    this._contextCache.set(contextName, node);

    return node;
  }

  /**
   * Get context IRI (may be vocabulary term or instance)
   *
   * @param {string} contextName - Context name
   * @returns {string} IRI - 'tagteam:Default_Context' or 'inst:Name_Context'
   */
  getContextIRI(contextName) {
    // Default context is a vocabulary term, not an instance
    if (contextName === 'Default' || !contextName) {
      return 'tagteam:Default_Context';
    }

    // Instance IRI for named contexts
    return `${this.options.namespace}:${contextName}_Context`;
  }

  /**
   * Create InterpretationContext node
   *
   * @param {string} contextName - Context name
   * @returns {Object} Node
   * @private
   */
  _createContextNode(contextName) {
    const iri = this.getContextIRI(contextName);
    const definition = PREDEFINED_CONTEXTS[contextName] || {
      label: `${contextName} Interpretation Context`,
      framework: 'Custom',
      comment: `Custom interpretation context: ${contextName}`
    };

    return {
      '@id': iri,
      '@type': ['tagteam:InterpretationContext', 'owl:NamedIndividual'],
      'rdfs:label': definition.label,
      'tagteam:framework': definition.framework,
      'rdfs:comment': definition.comment,
      'tagteam:instantiated_at': new Date().toISOString()
    };
  }

  /**
   * Check if context is predefined
   *
   * @param {string} contextName - Context name
   * @returns {boolean} True if predefined
   */
  isPredefined(contextName) {
    return contextName in PREDEFINED_CONTEXTS;
  }

  /**
   * Get all predefined context names
   *
   * @returns {Array<string>} Context names
   */
  getPredefinedContextNames() {
    return Object.keys(PREDEFINED_CONTEXTS);
  }

  /**
   * Get all created context nodes (for inclusion in @graph)
   *
   * @returns {Array<Object>} Context nodes
   */
  getContextNodes() {
    return Array.from(this._contextCache.values());
  }

  /**
   * Reset cache (for testing)
   */
  reset() {
    this._contextCache.clear();
  }

  /**
   * Set the graph builder
   *
   * @param {Object} graphBuilder - SemanticGraphBuilder instance
   */
  setGraphBuilder(graphBuilder) {
    this.graphBuilder = graphBuilder;
  }
}



  // ============================================================================
  // INFORMATION STAIRCASE BUILDER (Phase 4 - Week 2)
  // Creates IBE node and parser agent for provenance
  // ============================================================================

/**
 * InformationStaircaseBuilder.js
 *
 * Creates IBE (Information Bearing Entity) node and parser agent node.
 * Links assertion events and ICE nodes to IBE via based_on/is_concretized_by.
 *
 * Information Staircase (SHML):
 *   Literal (text) → IBE → ICE (content) → Assertions
 *
 * Phase 4 Week 2 Implementation:
 * - IBE node for input text with cco:has_text_value
 * - Parser agent as Agent
 * - Deterministic IRI generation for reproducibility
 *
 * @module graph/InformationStaircaseBuilder
 * @version 4.0.0-phase4-week2
 */

/**
 * InformationStaircaseBuilder - creates IBE and parser agent nodes
 */
class InformationStaircaseBuilder {
  /**
   * Create a new InformationStaircaseBuilder
   * @param {Object} options - Configuration options
   * @param {string} [options.version='4.0.0-phase4'] - TagTeam version string
   * @param {string} [options.namespace='inst'] - IRI namespace prefix
   */
  constructor(options = {}) {
    this.options = {
      version: options.version || '4.0.0-phase4',
      namespace: options.namespace || 'inst',
      ...options
    };

    // Cache for singleton parser agent
    this._parserAgentNode = null;
    this._parserAgentIRI = null;
  }

  /**
   * Create IBE node for input text
   *
   * @param {string} inputText - Full input text
   * @param {string} timestamp - ISO timestamp
   * @returns {Object} IBE node for @graph
   */
  createInputIBE(inputText, timestamp) {
    const iri = this.getIBE_IRI(inputText);

    return {
      '@id': iri,
      '@type': ['InformationBearingEntity', 'owl:NamedIndividual'],
      'rdfs:label': 'Input text',
      'has_text_value': inputText,
      'tagteam:char_count': inputText.length,
      'tagteam:word_count': this._countWords(inputText),
      'tagteam:received_at': timestamp
    };
  }

  /**
   * Create parser agent node (singleton per version)
   *
   * The parser agent represents TagTeam as an intentional agent
   * performing detection acts. Used in detected_by relations.
   *
   * @returns {Object} Agent node for @graph
   */
  createParserAgent() {
    // Return cached node if already created
    if (this._parserAgentNode) {
      return this._parserAgentNode;
    }

    const iri = this.getParserAgentIRI();

    this._parserAgentNode = {
      '@id': iri,
      '@type': ['Agent', 'owl:NamedIndividual'],
      'rdfs:label': `TagTeam.js Parser v${this.options.version}`,
      'tagteam:version': this.options.version,
      'tagteam:algorithm': 'BFO-aware NLP with CCO mapping',
      'tagteam:capabilities': [
        'entity_extraction',
        'act_extraction',
        'role_detection',
        'value_detection',
        'context_analysis'
      ]
    };

    return this._parserAgentNode;
  }

  /**
   * Get IRI for input IBE
   *
   * Uses SHA-256 hash of text for deterministic IRI generation.
   * Same text always produces same IRI.
   *
   * @param {string} inputText - Input text
   * @returns {string} IRI
   */
  getIBE_IRI(inputText) {
    const hash = this._hashText(inputText);
    return `${this.options.namespace}:Input_Text_IBE_${hash}`;
  }

  /**
   * Get IRI for parser agent (singleton)
   *
   * @returns {string} IRI
   */
  getParserAgentIRI() {
    if (this._parserAgentIRI) {
      return this._parserAgentIRI;
    }

    // Version-based IRI for parser agent
    const versionSlug = this.options.version.replace(/\./g, '_').replace(/-/g, '_');
    this._parserAgentIRI = `${this.options.namespace}:TagTeam_Parser_v${versionSlug}`;

    return this._parserAgentIRI;
  }

  /**
   * Generate deterministic hash for text
   *
   * @param {string} text - Text to hash
   * @returns {string} 12-char hex hash
   * @private
   */
  _hashText(text) {
    return crypto
      .createHash('sha256')
      .update(text)
      .digest('hex')
      .substring(0, 12);
  }

  /**
   * Count words in text
   *
   * @param {string} text - Input text
   * @returns {number} Word count
   * @private
   */
  _countWords(text) {
    return text.trim().split(/\s+/).filter(w => w.length > 0).length;
  }

  /**
   * Reset cached parser agent (for testing)
   */
  reset() {
    this._parserAgentNode = null;
    this._parserAgentIRI = null;
  }
}



  // ============================================================================
  // SHML VALIDATOR (Phase 4 - Week 3)
  // Validates graphs against SHACL patterns for BFO/CCO compliance
  // ============================================================================

/**
 * SHMLValidator.js
 *
 * Validates JSON-LD graphs against SHACL patterns for BFO/CCO compliance.
 * Implements 8 expert-certified validation patterns from SHACL_PATTERNS_REFERENCE.md.
 *
 * Patterns:
 * 1. Information Staircase (ICE → IBE → Literal)
 * 2. Role Pattern (bearer necessity, realization)
 * 3. Designation Pattern
 * 4. Temporal Interval Pattern
 * 5. Measurement Pattern
 * 6. Socio-Primal Pattern (Agent/Act)
 * 7. Domain/Range Validation
 * 8. Vocabulary Validation
 *
 * Severity Levels:
 * - VIOLATION: Must be fixed (ontologically impossible otherwise)
 * - WARNING: Should be addressed (incomplete but valid)
 * - INFO: Suggestion (nice to have)
 *
 * @module graph/SHMLValidator
 * @version 4.0.0-phase4-week3
 */

/**
 * Extract IRI from a relation value (handles both string and object notation)
 * @param {string|Object} value - Relation value (IRI string or {`@id`: IRI})
 * @returns {string|null} The IRI string, or null if invalid
 */
function extractIRI(value) {
  if (!value) return null;
  if (typeof value === 'string') return value;
  if (typeof value === 'object' && value['@id']) return value['@id'];
  return null;
}

/**
 * Known CCO/BFO class names for vocabulary validation
 */
const KNOWN_CLASSES = new Set([
  // BFO Classes
  'bfo:BFO_0000001', // Entity
  'bfo:BFO_0000002', // Continuant
  'bfo:BFO_0000003', // Occurrent
  'bfo:BFO_0000004', // IndependentContinuant
  'bfo:BFO_0000015', // Process
  'bfo:BFO_0000016', // Disposition
  'bfo:BFO_0000017', // RealizableEntity
  'bfo:BFO_0000019', // Quality
  'bfo:BFO_0000020', // SpecificallyDependentContinuant
  'bfo:BFO_0000023', // Role
  'bfo:BFO_0000027', // ObjectAggregate
  'bfo:BFO_0000031', // GenericallyDependentContinuant
  'bfo:BFO_0000040', // MaterialEntity
  'bfo:BFO_0000115', // has_member_part
  'bfo:BFO_0000197', // inheres_in
  'bfo:BFO_0000196', // is_bearer_of
  'bfo:BFO_0000054', // realized_in
  'bfo:BFO_0000055', // realizes
  'bfo:BFO_0000057', // has_participant
  'bfo:BFO_0000058', // is_concretized_by
  'bfo:BFO_0000059', // concretizes

  // CCO Classes
  'Agent', 'Person', 'Organization', 'GeopoliticalOrganization',
  'Artifact', 'Facility',
  'Act', 'IntentionalAct', 'ActOfCommunication',
  'InformationBearingEntity', 'InformationContentEntity',
  'Role',

  // OWL
  'owl:NamedIndividual', 'owl:Thing', 'owl:Class',

  // TagTeam Classes
  'tagteam:DiscourseReferent', 'tagteam:VerbPhrase',
  'tagteam:DeonticContent', 'tagteam:DirectiveContent', 'tagteam:ScarcityAssertion',
  'tagteam:ValueDetectionRecord', 'tagteam:ContextAssessmentRecord',
  'tagteam:InterpretationContext',
  'tagteam:ValueAssertionEvent', 'tagteam:ContextAssessmentEvent',
  'tagteam:EthicalValueICE', 'tagteam:ContextDimensionICE',
  'tagteam:AutomatedDetection', 'tagteam:HumanValidation',
  'tagteam:HumanRejection', 'tagteam:HumanCorrection',
  'tagteam:StructuralAssertion', 'tagteam:ComplexDesignator'
]);

/**
 * Known predicates for vocabulary validation
 */
const KNOWN_PREDICATES = new Set([
  // BFO Relations (bare aliases — resolved via @context to opaque IRIs)
  'inheres_in', 'is_bearer_of', 'realized_in', 'realizes',
  'has_participant', 'has_member_part',
  'is_concretized_by', 'concretizes',

  // CCO Relations (bare aliases — resolved via @context)
  'is_about', 'prescribes', 'has_recipient',
  'has_text_value',
  'has_agent', 'affects',
  'occupies_temporal_region', 'participates_in', 'is_part_of',
  'occurs_during', 'designates', 'is_designated_by',
  'is_measured_by', 'measures', 'has_measurement_value',
  'uses_measurement_unit', 'has_start_time', 'has_end_time',

  // RDF/RDFS/OWL
  'rdf:type', 'rdfs:label', 'rdfs:comment', 'rdfs:subClassOf',

  // TagTeam Properties - Core
  'tagteam:has_component', 'tagteam:extracted_from', 'tagteam:corefersWith',
  'tagteam:would_be_realized_in', 'tagteam:assertionType', 'tagteam:validInContext',
  'tagteam:actualityStatus', 'tagteam:validatedBy', 'tagteam:validationTimestamp',
  'tagteam:supersedes', 'tagteam:framework', 'tagteam:instantiated_at',
  'tagteam:instantiated_by', 'tagteam:negationMarker',
  // TagTeam Properties - Confidence
  'tagteam:extractionConfidence', 'tagteam:classificationConfidence',
  'tagteam:relevanceConfidence', 'tagteam:aggregateConfidence', 'tagteam:aggregationMethod',
  // TagTeam Properties - Modal
  'tagteam:modalType', 'tagteam:modalMarker', 'tagteam:modalStrength',
  // TagTeam Properties - Scarcity
  'tagteam:scarceResource', 'tagteam:competingParties', 'tagteam:supplyCount',
  'tagteam:demandCount', 'tagteam:scarcityRatio', 'tagteam:scarcityMarker',
  // TagTeam Properties - Entity/Quality
  'tagteam:evidenceText', 'tagteam:detected_at', 'tagteam:member_count',
  'tagteam:member_index', 'tagteam:qualifierText', 'tagteam:severity', 'tagteam:ageCategory',
  'tagteam:sourceText', 'tagteam:startPosition', 'tagteam:endPosition',
  'tagteam:definiteness', 'tagteam:quantity', 'tagteam:quantityIndicator', 'tagteam:qualifiers',
  'tagteam:referentialStatus', 'tagteam:denotesType', 'tagteam:roleType',
  'tagteam:extracted_from_span', 'tagteam:span_offset',
  // TagTeam Properties - Act
  'tagteam:verb', 'tagteam:lemma', 'tagteam:tense', 'tagteam:hasModalMarker',
  'tagteam:modality', 'tagteam:aspect',
  // TagTeam Properties - IBE
  'tagteam:char_count', 'tagteam:word_count', 'tagteam:received_at', 'tagteam:temporal_extent',
  'tagteam:version', 'tagteam:algorithm', 'tagteam:capabilities',
  // TagTeam Properties - Value/Context
  'tagteam:valueName', 'tagteam:valueCategory', 'tagteam:evidence', 'tagteam:sourceSpan',
  'tagteam:category', 'tagteam:asserts', 'tagteam:detected_by', 'tagteam:based_on',
  'tagteam:polarity', 'tagteam:salience', 'tagteam:matched_markers',
  'tagteam:detection_method', 'tagteam:dimension', 'tagteam:score',
  // TagTeam Properties - Directive
  'tagteam:prescribes',
  // TagTeam Properties - StructuralAssertion (Phase 7 v7)
  'tagteam:assertsRelation', 'tagteam:hasSubject', 'tagteam:hasObject', 'tagteam:inverseRelation'
]);

/**
 * SHML Validator class
 */
class SHMLValidator {
  /**
   * Create a new SHMLValidator
   * @param {Object} options - Validation options
   * @param {boolean} [options.strict=false] - Treat warnings as violations
   * @param {boolean} [options.verbose=false] - Include INFO level issues
   */
  constructor(options = {}) {
    this.options = {
      strict: options.strict || false,
      verbose: options.verbose || false,
      ...options
    };

    this.results = {
      violations: [],
      warnings: [],
      info: [],
      patterns: {}
    };
  }

  /**
   * Validate a JSON-LD graph against all SHACL patterns
   *
   * @param {Object} graph - JSON-LD graph with @graph array
   * @returns {Object} Validation result with violations, warnings, info, and compliance score
   *
   * @example
   * const validator = new SHMLValidator();
   * const result = validator.validate(graph);
   * console.log(result.complianceScore); // 85
   * console.log(result.violations);      // [{pattern, message, node}]
   */
  validate(graph) {
    // Reset results
    this.results = {
      violations: [],
      warnings: [],
      info: [],
      patterns: {}
    };

    const nodes = graph['@graph'] || [];
    const nodeMap = this._buildNodeMap(nodes);

    // Run all patterns
    this._validateInformationStaircase(nodes, nodeMap);
    this._validateRolePattern(nodes, nodeMap);
    this._validateDesignationPattern(nodes, nodeMap);
    this._validateTemporalIntervalPattern(nodes, nodeMap);
    this._validateMeasurementPattern(nodes, nodeMap);
    this._validateSocioPrimalPattern(nodes, nodeMap);
    this._validateDomainRange(nodes, nodeMap);
    this._validateVocabulary(nodes);

    // Calculate compliance score
    const complianceScore = this._calculateComplianceScore(nodes);

    return {
      valid: this.results.violations.length === 0,
      complianceScore,
      violations: this.results.violations,
      warnings: this.results.warnings,
      info: this.options.verbose ? this.results.info : [],
      patterns: this.results.patterns,
      summary: {
        totalNodes: nodes.length,
        violationCount: this.results.violations.length,
        warningCount: this.results.warnings.length,
        infoCount: this.results.info.length
      }
    };
  }

  /**
   * Build a map of node IDs to nodes for quick lookup
   * @private
   */
  _buildNodeMap(nodes) {
    const map = new Map();
    for (const node of nodes) {
      if (node['@id']) {
        map.set(node['@id'], node);
      }
    }
    return map;
  }

  /**
   * Get types of a node as an array
   * @private
   */
  _getTypes(node) {
    const type = node['@type'];
    if (!type) return [];
    return Array.isArray(type) ? type : [type];
  }

  /**
   * Check if node has a specific type
   * @private
   */
  _hasType(node, typePattern) {
    const types = this._getTypes(node);
    return types.some(t => t.includes(typePattern));
  }

  /**
   * Add a validation issue
   * @private
   */
  _addIssue(severity, pattern, message, nodeId = null, suggestion = null) {
    const issue = {
      severity,
      pattern,
      message,
      nodeId,
      suggestion
    };

    switch (severity) {
      case 'VIOLATION':
        this.results.violations.push(issue);
        break;
      case 'WARNING':
        if (this.options.strict) {
          this.results.violations.push(issue);
        } else {
          this.results.warnings.push(issue);
        }
        break;
      case 'INFO':
        this.results.info.push(issue);
        break;
    }
  }

  // ================================================================
  // Pattern 1: Information Staircase
  // ================================================================

  /**
   * Validate Information Staircase pattern (ICE → IBE → Literal)
   * @private
   */
  _validateInformationStaircase(nodes, nodeMap) {
    let passed = 0;
    let total = 0;

    // Find all ICE nodes
    const iceNodes = nodes.filter(n =>
      this._hasType(n, 'InformationContentEntity') ||
      this._hasType(n, 'EthicalValueICE') ||
      this._hasType(n, 'ContextDimensionICE')
    );

    // Find all IBE nodes
    const ibeNodes = nodes.filter(n =>
      this._hasType(n, 'InformationBearingEntity')
    );

    // Rule 1: ICE should have is_concretized_by
    for (const ice of iceNodes) {
      total++;
      if (ice['is_concretized_by']) {
        passed++;
      } else {
        this._addIssue(
          'WARNING',
          'InformationStaircase',
          `ICE node ${ice['@id']} has no is_concretized_by link to IBE`,
          ice['@id'],
          'Add is_concretized_by property pointing to the IBE'
        );
      }
    }

    // Rule 2: IBE should have has_text_value
    for (const ibe of ibeNodes) {
      total++;
      if (ibe['has_text_value']) {
        passed++;
      } else {
        this._addIssue(
          'WARNING',
          'InformationStaircase',
          `IBE node ${ibe['@id']} has no has_text_value literal`,
          ibe['@id'],
          'Add cco:has_text_value property with the source text'
        );
      }
    }

    // Rule 3: IBE should concretize at least one ICE
    for (const ibe of ibeNodes) {
      total++;
      // Check if any ICE links to this IBE
      const hasConcretization = iceNodes.some(ice =>
        extractIRI(ice['is_concretized_by']) === ibe['@id']
      );

      if (hasConcretization || extractIRI(ibe['concretizes'])) {
        passed++;
      } else {
        this._addIssue(
          'WARNING',
          'InformationStaircase',
          `IBE node ${ibe['@id']} does not concretize any ICE`,
          ibe['@id'],
          'Ensure ICE nodes link to this IBE via is_concretized_by'
        );
      }
    }

    this.results.patterns['InformationStaircase'] = {
      passed,
      total,
      score: total > 0 ? Math.round((passed / total) * 100) : 100
    };
  }

  // ================================================================
  // Pattern 2: Role Pattern
  // ================================================================

  /**
   * Validate Role Pattern (bearer necessity, realization)
   * @private
   */
  _validateRolePattern(nodes, nodeMap) {
    let passed = 0;
    let total = 0;

    // Find all Role nodes
    const roleNodes = nodes.filter(n =>
      this._hasType(n, 'Role') ||
      this._hasType(n, 'BFO_0000023') ||
      this._hasType(n, 'AgentRole') ||
      this._hasType(n, 'PatientRole')
    );

    // Build reverse map: role ID -> bearer (from is_bearer_of on entities)
    const roleBearers = new Map();
    for (const node of nodes) {
      const bearerOf = node['is_bearer_of'];
      if (bearerOf) {
        const roles = Array.isArray(bearerOf) ? bearerOf : [bearerOf];
        for (const roleId of roles) {
          roleBearers.set(roleId, node['@id']);
        }
      }
    }

    for (const role of roleNodes) {
      // Rule 1: Role MUST have bearer (VIOLATION)
      // Check: (1) reverse link via is_bearer_of, OR (2) direct link via inheres_in
      total++;
      const hasReverseLink = roleBearers.has(role['@id']);
      const inheresIn = extractIRI(role['inheres_in']);
      const hasDirectLink = inheresIn && nodeMap.has(inheresIn);

      if (hasReverseLink || hasDirectLink) {
        passed++;
        // Track the bearer for later type checking
        if (hasDirectLink && !roleBearers.has(role['@id'])) {
          roleBearers.set(role['@id'], inheresIn);
        }
      } else {
        this._addIssue(
          'VIOLATION',
          'RolePattern',
          `Role ${role['@id']} has no bearer - ontologically impossible`,
          role['@id'],
          'Add inheres_in on role or is_bearer_of on bearer entity'
        );
      }

      // Rule 3: Role SHOULD be realized (WARNING)
      total++;
      const isRealized = extractIRI(role['realized_in']) ||
        extractIRI(role['tagteam:would_be_realized_in']);

      // Also check if any process realizes this role
      const processRealizes = nodes.some(n =>
        extractIRI(n['realizes']) === role['@id']
      );

      if (isRealized || processRealizes) {
        passed++;
      } else {
        this._addIssue(
          'WARNING',
          'RolePattern',
          `Role ${role['@id']} is not realized by any process`,
          role['@id'],
          'Add cco:realized_in or tagteam:would_be_realized_in to link to a process'
        );
      }
    }

    // Rule 2: Check bearer types (WARNING)
    for (const [roleId, bearerId] of roleBearers) {
      const bearer = nodeMap.get(bearerId);
      if (bearer) {
        total++;
        const isIndependentContinuant =
          this._hasType(bearer, 'Agent') ||
          this._hasType(bearer, 'Person') ||
          this._hasType(bearer, 'Artifact') ||
          this._hasType(bearer, 'IndependentContinuant') ||
          this._hasType(bearer, 'BFO_0000004') ||
          this._hasType(bearer, 'MaterialEntity') ||
          this._hasType(bearer, 'DiscourseReferent'); // TagTeam discourse referents can bear roles

        if (isIndependentContinuant) {
          passed++;
        } else {
          this._addIssue(
            'WARNING',
            'RolePattern',
            `Role bearer ${bearerId} should be an IndependentContinuant`,
            bearerId,
            'Bearer should be Person, Agent, Artifact or similar'
          );
        }
      }
    }

    this.results.patterns['RolePattern'] = {
      passed,
      total,
      score: total > 0 ? Math.round((passed / total) * 100) : 100
    };
  }

  // ================================================================
  // Pattern 3: Designation Pattern
  // ================================================================

  /**
   * Validate Designation Pattern
   * @private
   */
  _validateDesignationPattern(nodes, nodeMap) {
    let passed = 0;
    let total = 0;

    // Find all Designative ICE nodes
    const designativeNodes = nodes.filter(n =>
      this._hasType(n, 'DesignativeInformationContentEntity')
    );

    for (const designative of designativeNodes) {
      total++;

      // Rule 1: Must designate something (VIOLATION)
      if (designative['designates'] || designative['is_designated_by']) {
        passed++;
      } else {
        this._addIssue(
          'VIOLATION',
          'DesignationPattern',
          `Designative ICE ${designative['@id']} does not designate any entity`,
          designative['@id'],
          'Add cco:designates property linking to the designated entity'
        );
      }
    }

    this.results.patterns['DesignationPattern'] = {
      passed,
      total,
      score: total > 0 ? Math.round((passed / total) * 100) : 100
    };
  }

  // ================================================================
  // Pattern 4: Temporal Interval Pattern
  // ================================================================

  /**
   * Validate Temporal Interval Pattern
   * @private
   */
  _validateTemporalIntervalPattern(nodes, nodeMap) {
    let passed = 0;
    let total = 0;

    // Find all TemporalInterval nodes
    const temporalNodes = nodes.filter(n =>
      this._hasType(n, 'TemporalInterval')
    );

    for (const interval of temporalNodes) {
      const hasStart = interval['has_start_time'];
      const hasEnd = interval['has_end_time'];

      // Rule 1: Should have start time (WARNING)
      total++;
      if (hasStart) {
        passed++;
      } else {
        this._addIssue(
          'WARNING',
          'TemporalIntervalPattern',
          `Temporal interval ${interval['@id']} has no start time`,
          interval['@id'],
          'Add cco:has_start_time property'
        );
      }

      // Rule 2: Should have end time (WARNING)
      total++;
      if (hasEnd) {
        passed++;
      } else {
        this._addIssue(
          'WARNING',
          'TemporalIntervalPattern',
          `Temporal interval ${interval['@id']} has no end time`,
          interval['@id'],
          'Add cco:has_end_time property (if process is complete)'
        );
      }

      // Rule 3: Start must be <= end (VIOLATION)
      if (hasStart && hasEnd) {
        total++;
        const startDate = new Date(hasStart);
        const endDate = new Date(hasEnd);

        if (startDate <= endDate) {
          passed++;
        } else {
          this._addIssue(
            'VIOLATION',
            'TemporalIntervalPattern',
            `Temporal interval ${interval['@id']} has backwards time (start > end)`,
            interval['@id'],
            'Start time must be before or equal to end time'
          );
        }
      }
    }

    this.results.patterns['TemporalIntervalPattern'] = {
      passed,
      total,
      score: total > 0 ? Math.round((passed / total) * 100) : 100
    };
  }

  // ================================================================
  // Pattern 5: Measurement Pattern
  // ================================================================

  /**
   * Validate Measurement Pattern
   * @private
   */
  _validateMeasurementPattern(nodes, nodeMap) {
    let passed = 0;
    let total = 0;

    // Find all QualityMeasurement nodes
    const measurementNodes = nodes.filter(n =>
      this._hasType(n, 'QualityMeasurement')
    );

    for (const measurement of measurementNodes) {
      // Rule 1: Must be linked to a Quality (VIOLATION)
      total++;
      const qualityLinks = nodes.some(n =>
        extractIRI(n['is_measured_by']) === measurement['@id']
      );

      if (qualityLinks || extractIRI(measurement['measures'])) {
        passed++;
      } else {
        this._addIssue(
          'VIOLATION',
          'MeasurementPattern',
          `Measurement ${measurement['@id']} is not linked to any quality`,
          measurement['@id'],
          'Link a Quality node to this measurement via cco:is_measured_by'
        );
      }

      // Rule 2: Must have measurement value (VIOLATION)
      total++;
      if (measurement['has_measurement_value'] !== undefined) {
        passed++;
      } else {
        this._addIssue(
          'VIOLATION',
          'MeasurementPattern',
          `Measurement ${measurement['@id']} has no value`,
          measurement['@id'],
          'Add cco:has_measurement_value property'
        );
      }

      // Rule 3: Must have measurement unit (VIOLATION)
      total++;
      if (measurement['uses_measurement_unit']) {
        passed++;
      } else {
        this._addIssue(
          'VIOLATION',
          'MeasurementPattern',
          `Measurement ${measurement['@id']} has no unit`,
          measurement['@id'],
          'Add cco:uses_measurement_unit property'
        );
      }
    }

    this.results.patterns['MeasurementPattern'] = {
      passed,
      total,
      score: total > 0 ? Math.round((passed / total) * 100) : 100
    };
  }

  // ================================================================
  // Pattern 6: Socio-Primal Pattern (Agent/Act)
  // ================================================================

  /**
   * Validate Socio-Primal Pattern
   * @private
   */
  _validateSocioPrimalPattern(nodes, nodeMap) {
    let passed = 0;
    let total = 0;

    // Find all Act nodes
    const actNodes = nodes.filter(n =>
      this._hasType(n, 'Act') ||
      this._hasType(n, 'IntentionalAct') ||
      this._hasType(n, 'Process') ||
      this._hasType(n, 'BFO_0000015')
    );

    for (const act of actNodes) {
      // Rule 1: Act should have temporal grounding (WARNING)
      total++;
      if (act['occurs_during'] || act['tagteam:temporal_extent']) {
        passed++;
      } else {
        this._addIssue(
          'WARNING',
          'SocioPrimalPattern',
          `Act ${act['@id']} has no temporal grounding`,
          act['@id'],
          'Add cco:occurs_during linking to a TemporalInterval'
        );
      }

      // Rule 2: Act should have participant (WARNING)
      total++;
      const hasParticipant = extractIRI(act['has_participant']) ||
        extractIRI(act['has_agent']);

      // Also check if any agent participates in this act
      const agentParticipates = nodes.some(n =>
        extractIRI(n['participates_in']) === act['@id']
      );

      if (hasParticipant || agentParticipates) {
        passed++;
      } else {
        this._addIssue(
          'WARNING',
          'SocioPrimalPattern',
          `Act ${act['@id']} has no participant`,
          act['@id'],
          'Add cco:has_participant or link an agent via cco:participates_in'
        );
      }
    }

    this.results.patterns['SocioPrimalPattern'] = {
      passed,
      total,
      score: total > 0 ? Math.round((passed / total) * 100) : 100
    };
  }

  // ================================================================
  // Pattern 7: Domain/Range Validation
  // ================================================================

  /**
   * Validate Domain/Range constraints
   * @private
   */
  _validateDomainRange(nodes, nodeMap) {
    let passed = 0;
    let total = 0;

    for (const node of nodes) {
      // is_concretized_by: ICE → IBE (BFO_0000058)
      const concretizedBy = extractIRI(node['is_concretized_by']);
      if (concretizedBy) {
        total++;
        const target = nodeMap.get(concretizedBy);

        if (target && this._hasType(target, 'InformationBearingEntity')) {
          passed++;
        } else if (target) {
          this._addIssue(
            'WARNING',
            'DomainRangeValidation',
            `is_concretized_by target ${concretizedBy} is not an IBE`,
            node['@id'],
            'Target of is_concretized_by should be InformationBearingEntity'
          );
        }
      }

      // is_bearer_of: IndependentContinuant → Role (BFO_0000196)
      const bearerOfRaw = node['is_bearer_of'];
      if (bearerOfRaw) {
        const roleIds = Array.isArray(bearerOfRaw)
          ? bearerOfRaw.map(r => extractIRI(r)).filter(Boolean)
          : [extractIRI(bearerOfRaw)].filter(Boolean);

        for (const roleId of roleIds) {
          total++;
          const role = nodeMap.get(roleId);

          if (role && (this._hasType(role, 'Role') || this._hasType(role, 'BFO_0000023'))) {
            passed++;
          } else if (role) {
            this._addIssue(
              'WARNING',
              'DomainRangeValidation',
              `is_bearer_of target ${roleId} is not a Role`,
              node['@id'],
              'Target of is_bearer_of should be bfo:Role'
            );
          }
        }
      }

      // is_part_of: Continuant → Continuant (NOT Process)
      const partOf = extractIRI(node['is_part_of']);
      if (partOf) {
        total++;
        const target = nodeMap.get(partOf);

        if (target) {
          const targetIsProcess = this._hasType(target, 'Process') ||
            this._hasType(target, 'Act') ||
            this._hasType(target, 'BFO_0000015');

          if (targetIsProcess) {
            this._addIssue(
              'VIOLATION',
              'DomainRangeValidation',
              `is_part_of links Continuant ${node['@id']} to Process ${partOf}`,
              node['@id'],
              'Continuants can participate_in Processes but never be part_of them'
            );
          } else {
            passed++;
          }
        } else {
          passed++; // Can't validate if target not in graph
        }
      }

      // asserts: Event → ICE
      const asserts = extractIRI(node['tagteam:asserts']);
      if (asserts) {
        total++;
        const target = nodeMap.get(asserts);

        if (target && (
          this._hasType(target, 'InformationContentEntity') ||
          this._hasType(target, 'EthicalValueICE') ||
          this._hasType(target, 'ContextDimensionICE')
        )) {
          passed++;
        } else if (target) {
          this._addIssue(
            'WARNING',
            'DomainRangeValidation',
            `asserts target ${asserts} is not an ICE`,
            node['@id'],
            'Target of asserts should be an InformationContentEntity'
          );
        }
      }

      // CCO Expert Checklist Rule: has_agent - Domain: bfo:Process, Range: Agent
      const hasAgent = extractIRI(node['has_agent']);
      if (hasAgent) {
        total++;
        const nodeIsProcess = this._hasType(node, 'Process') ||
          this._hasType(node, 'Act') ||
          this._hasType(node, 'IntentionalAct') ||
          this._hasType(node, 'BFO_0000015');
        const target = nodeMap.get(hasAgent);
        const targetIsAgent = target && (
          this._hasType(target, 'Agent') ||
          this._hasType(target, 'Person') ||
          this._hasType(target, 'Organization')
        );

        if (nodeIsProcess && targetIsAgent) {
          passed++;
        } else {
          if (!nodeIsProcess) {
            this._addIssue(
              'VIOLATION',
              'DomainRangeValidation',
              `has_agent used on non-Process node ${node['@id']}`,
              node['@id'],
              'has_agent domain must be bfo:Process (CCO Expert Checklist)'
            );
          }
          if (!targetIsAgent && target) {
            this._addIssue(
              'VIOLATION',
              'DomainRangeValidation',
              `has_agent target ${hasAgent} is not an Agent`,
              node['@id'],
              'has_agent range must be Agent (CCO Expert Checklist)'
            );
          }
        }
      }

      // CCO Expert Checklist Rule: prescribes - Domain: DirectiveContent, Range: bfo:Process
      const prescribes = extractIRI(node['prescribes']) || extractIRI(node['tagteam:prescribes']);
      if (prescribes) {
        total++;
        const nodeIsDirective = this._hasType(node, 'DirectiveContent') ||
          this._hasType(node, 'DeonticContent') ||
          this._hasType(node, 'DirectiveInformationContentEntity');
        const target = nodeMap.get(prescribes);
        const targetIsProcess = target && (
          this._hasType(target, 'Process') ||
          this._hasType(target, 'Act') ||
          this._hasType(target, 'IntentionalAct') ||
          this._hasType(target, 'BFO_0000015')
        );

        if (nodeIsDirective && targetIsProcess) {
          passed++;
        } else {
          if (!nodeIsDirective) {
            this._addIssue(
              'WARNING',
              'DomainRangeValidation',
              `prescribes used on non-DirectiveContent node ${node['@id']}`,
              node['@id'],
              'prescribes domain should be tagteam:DirectiveContent (CCO Expert Checklist)'
            );
          }
          if (!targetIsProcess && target) {
            this._addIssue(
              'WARNING',
              'DomainRangeValidation',
              `prescribes target ${prescribes} is not a Process`,
              node['@id'],
              'prescribes range should be bfo:Process (CCO Expert Checklist)'
            );
          }
        }
      }

      // CCO Expert Checklist Rule: inheres_in - Domain: Role/Quality, Range: IndependentContinuant
      const inheresIn = extractIRI(node['inheres_in']);
      if (inheresIn) {
        total++;
        const nodeIsRoleOrQuality = this._hasType(node, 'Role') ||
          this._hasType(node, 'BFO_0000023') ||
          this._hasType(node, 'Quality') ||
          this._hasType(node, 'BFO_0000019');
        const target = nodeMap.get(inheresIn);
        const targetIsIC = target && (
          this._hasType(target, 'IndependentContinuant') ||
          this._hasType(target, 'BFO_0000004') ||
          this._hasType(target, 'Person') ||
          this._hasType(target, 'Agent') ||
          this._hasType(target, 'Artifact') ||
          this._hasType(target, 'MaterialEntity') ||
          this._hasType(target, 'BFO_0000040')
        );

        if (nodeIsRoleOrQuality && targetIsIC) {
          passed++;
        } else {
          if (!nodeIsRoleOrQuality) {
            this._addIssue(
              'VIOLATION',
              'DomainRangeValidation',
              `inheres_in used on non-Role/Quality node ${node['@id']}`,
              node['@id'],
              'inheres_in domain must be bfo:Role or bfo:Quality (CCO Expert Checklist)'
            );
          }
          if (!targetIsIC && target) {
            this._addIssue(
              'VIOLATION',
              'DomainRangeValidation',
              `inheres_in target ${inheresIn} is not an IndependentContinuant`,
              node['@id'],
              'inheres_in range must be bfo:IndependentContinuant (CCO Expert Checklist)'
            );
          }
        }
      }
    }

    this.results.patterns['DomainRangeValidation'] = {
      passed,
      total,
      score: total > 0 ? Math.round((passed / total) * 100) : 100
    };
  }

  // ================================================================
  // Pattern 8: Vocabulary Validation
  // ================================================================

  /**
   * Validate vocabulary (catch typos and unknown terms)
   * @private
   */
  _validateVocabulary(nodes) {
    let passed = 0;
    let total = 0;

    for (const node of nodes) {
      // Check types
      const types = this._getTypes(node);
      for (const type of types) {
        // Skip common simple types
        if (type === 'string' || type === 'number') continue;

        total++;
        if (this._isKnownClass(type)) {
          passed++;
        } else {
          this._addIssue(
            'WARNING',
            'VocabularyValidation',
            `Unknown class: ${type}`,
            node['@id'],
            `Check spelling or add to known vocabulary. Similar: ${this._suggestSimilar(type, KNOWN_CLASSES)}`
          );
        }
      }

      // Check predicates
      for (const key of Object.keys(node)) {
        // Skip JSON-LD keywords
        if (key.startsWith('@')) continue;
        // Skip rdfs:label and rdfs:comment
        if (key === 'rdfs:label' || key === 'rdfs:comment') continue;

        total++;
        if (this._isKnownPredicate(key)) {
          passed++;
        } else {
          this._addIssue(
            'WARNING',
            'VocabularyValidation',
            `Unknown predicate: ${key}`,
            node['@id'],
            `Check spelling or add to known vocabulary. Similar: ${this._suggestSimilar(key, KNOWN_PREDICATES)}`
          );
        }
      }
    }

    this.results.patterns['VocabularyValidation'] = {
      passed,
      total,
      score: total > 0 ? Math.round((passed / total) * 100) : 100
    };
  }

  /**
   * Check if a class name is known
   * @private
   */
  _isKnownClass(className) {
    // Direct match
    if (KNOWN_CLASSES.has(className)) return true;

    // Check without prefix
    const localName = className.includes(':') ? className.split(':')[1] : className;

    // Check common prefixed versions
    for (const prefix of ['bfo:', 'cco:', 'tagteam:', 'owl:', 'rdf:', 'rdfs:']) {
      if (KNOWN_CLASSES.has(prefix + localName)) return true;
    }

    // Check if it's a BFO numeric ID
    if (/BFO_\d+/.test(localName)) return true;

    return false;
  }

  /**
   * Check if a predicate is known
   * @private
   */
  _isKnownPredicate(predicate) {
    // Direct match
    if (KNOWN_PREDICATES.has(predicate)) return true;

    // Check without prefix
    const localName = predicate.includes(':') ? predicate.split(':')[1] : predicate;

    // Check common prefixed versions
    for (const prefix of ['bfo:', 'cco:', 'tagteam:', 'owl:', 'rdf:', 'rdfs:']) {
      if (KNOWN_PREDICATES.has(prefix + localName)) return true;
    }

    // Check if it's a BFO numeric ID
    if (/BFO_\d+/.test(localName)) return true;

    return false;
  }

  /**
   * Suggest similar known terms
   * @private
   */
  _suggestSimilar(unknown, knownSet) {
    const localName = unknown.includes(':') ? unknown.split(':')[1] : unknown;
    const suggestions = [];

    for (const known of knownSet) {
      const knownLocal = known.includes(':') ? known.split(':')[1] : known;
      if (this._levenshteinDistance(localName.toLowerCase(), knownLocal.toLowerCase()) <= 3) {
        suggestions.push(known);
      }
    }

    return suggestions.slice(0, 3).join(', ') || 'none';
  }

  /**
   * Calculate Levenshtein distance between two strings
   * @private
   */
  _levenshteinDistance(a, b) {
    const matrix = [];

    for (let i = 0; i <= b.length; i++) {
      matrix[i] = [i];
    }

    for (let j = 0; j <= a.length; j++) {
      matrix[0][j] = j;
    }

    for (let i = 1; i <= b.length; i++) {
      for (let j = 1; j <= a.length; j++) {
        if (b.charAt(i - 1) === a.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1,
            matrix[i][j - 1] + 1,
            matrix[i - 1][j] + 1
          );
        }
      }
    }

    return matrix[b.length][a.length];
  }

  // ================================================================
  // Compliance Score
  // ================================================================

  /**
   * Calculate overall compliance score (0-100)
   * @private
   */
  _calculateComplianceScore(nodes) {
    if (nodes.length === 0) return 100;

    // Weight violations heavily, warnings moderately
    const violationPenalty = this.results.violations.length * 10;
    const warningPenalty = this.results.warnings.length * 2;

    // Base score from pattern scores
    const patternScores = Object.values(this.results.patterns)
      .filter(p => p.total > 0)
      .map(p => p.score);

    const avgPatternScore = patternScores.length > 0
      ? patternScores.reduce((a, b) => a + b, 0) / patternScores.length
      : 100;

    // Final score with penalties
    const score = Math.max(0, avgPatternScore - violationPenalty - warningPenalty);

    return Math.round(score);
  }

  /**
   * Get a summary report as formatted string
   *
   * @param {Object} result - Validation result from validate()
   * @returns {string} Formatted report
   */
  formatReport(result) {
    const lines = [];

    lines.push('=== SHML Validation Report ===\n');
    lines.push(`Status: ${result.valid ? 'VALID' : 'INVALID'}`);
    lines.push(`Compliance Score: ${result.complianceScore}%`);
    lines.push(`Total Nodes: ${result.summary.totalNodes}`);
    lines.push('');

    lines.push('--- Pattern Results ---');
    for (const [pattern, data] of Object.entries(result.patterns)) {
      if (data.total > 0) {
        lines.push(`${pattern}: ${data.passed}/${data.total} (${data.score}%)`);
      }
    }
    lines.push('');

    if (result.violations.length > 0) {
      lines.push('--- VIOLATIONS (Must Fix) ---');
      for (const v of result.violations) {
        lines.push(`[${v.pattern}] ${v.message}`);
        if (v.suggestion) lines.push(`  → ${v.suggestion}`);
      }
      lines.push('');
    }

    if (result.warnings.length > 0) {
      lines.push('--- WARNINGS (Should Address) ---');
      for (const w of result.warnings) {
        lines.push(`[${w.pattern}] ${w.message}`);
        if (w.suggestion) lines.push(`  → ${w.suggestion}`);
      }
      lines.push('');
    }

    if (result.info.length > 0) {
      lines.push('--- INFO (Suggestions) ---');
      for (const i of result.info) {
        lines.push(`[${i.pattern}] ${i.message}`);
      }
    }

    return lines.join('\n');
  }
}



  // ============================================================================
  // COMPLEXITY BUDGET (Phase 4 - Week 3)
  // Enforces complexity limits on graph construction
  // ============================================================================

/**
 * ComplexityBudget.js
 *
 * Enforces complexity limits on graph construction to prevent explosion.
 * Implements configurable budgets for nodes, referents, assertions, and text length.
 *
 * Default Limits (from PHASE4_ANSWERS.md):
 * - Max 200 nodes per graph
 * - Max 30 discourse referents
 * - Max 50 assertion events
 * - Max 2000 characters input text
 * - Max 500ms parse time
 *
 * @module graph/ComplexityBudget
 * @version 4.0.0-phase4-week3
 */

/**
 * Complexity budget error types
 */
const BudgetError = {
  MAX_NODES: 'MAX_NODES',
  MAX_REFERENTS: 'MAX_REFERENTS',
  MAX_ASSERTIONS: 'MAX_ASSERTIONS',
  MAX_TEXT_LENGTH: 'MAX_TEXT_LENGTH',
  MAX_PARSE_TIME: 'MAX_PARSE_TIME'
};

/**
 * Complexity Budget Manager
 */
class ComplexityBudget {
  /**
   * Create a new ComplexityBudget
   *
   * @param {Object} options - Budget configuration
   * @param {number} [options.maxNodes=200] - Maximum nodes in graph
   * @param {number} [options.maxReferents=30] - Maximum discourse referents
   * @param {number} [options.maxAssertions=50] - Maximum assertion events
   * @param {number} [options.maxTextLength=2000] - Maximum input text chars
   * @param {number} [options.maxParseTime=500] - Maximum parse time in ms
   * @param {boolean} [options.throwOnExceed=true] - Throw error when exceeded
   * @param {boolean} [options.autoChunk=false] - Auto-chunk on exceed
   *
   * @example
   * const budget = new ComplexityBudget({ maxNodes: 100 });
   * budget.addNode('DiscourseReferent');
   * console.log(budget.getUsage()); // { nodes: 1, referents: 1, ... }
   */
  constructor(options = {}) {
    // Budget limits
    this.maxNodes = options.maxNodes ?? 200;
    this.maxReferents = options.maxReferents ?? 30;
    this.maxAssertions = options.maxAssertions ?? 50;
    this.maxTextLength = options.maxTextLength ?? 2000;
    this.maxParseTime = options.maxParseTime ?? 500;

    // Behavior options
    this.throwOnExceed = options.throwOnExceed !== false;
    this.autoChunk = options.autoChunk || false;

    // Current counts
    this.nodeCount = 0;
    this.referentCount = 0;
    this.assertionCount = 0;
    this.textLength = 0;
    this.startTime = null;

    // Tracking
    this.warnings = [];
    this.exceeded = false;
    this.truncated = false;
  }

  /**
   * Reset the budget counters for a new parse
   */
  reset() {
    this.nodeCount = 0;
    this.referentCount = 0;
    this.assertionCount = 0;
    this.textLength = 0;
    this.startTime = null;
    this.warnings = [];
    this.exceeded = false;
    this.truncated = false;
  }

  /**
   * Start timing the parse operation
   */
  startParse() {
    this.startTime = Date.now();
  }

  /**
   * Check if text length is within budget
   *
   * @param {string} text - Input text to check
   * @returns {boolean} True if within budget
   * @throws {Error} If throwOnExceed is true and budget exceeded
   */
  checkTextLength(text) {
    this.textLength = text.length;

    if (this.textLength > this.maxTextLength) {
      const error = this._createError(
        BudgetError.MAX_TEXT_LENGTH,
        `Text length (${this.textLength}) exceeds maximum (${this.maxTextLength}). Consider chunking the input.`
      );

      if (this.throwOnExceed) {
        throw error;
      }

      this.exceeded = true;
      this.warnings.push(error.message);
      return false;
    }

    return true;
  }

  /**
   * Check if a node can be added
   *
   * @param {string} nodeType - Type of node to add
   * @returns {boolean} True if node can be added
   * @throws {Error} If throwOnExceed is true and budget exceeded
   */
  canAddNode(nodeType) {
    // Check total nodes
    if (this.nodeCount >= this.maxNodes) {
      return this._handleExceeded(
        BudgetError.MAX_NODES,
        `Maximum nodes (${this.maxNodes}) exceeded. Graph construction will be truncated.`
      );
    }

    // Check referent limit
    if (this._isReferentType(nodeType) && this.referentCount >= this.maxReferents) {
      return this._handleExceeded(
        BudgetError.MAX_REFERENTS,
        `Maximum discourse referents (${this.maxReferents}) exceeded. Consider chunking input.`
      );
    }

    // Check assertion limit
    if (this._isAssertionType(nodeType) && this.assertionCount >= this.maxAssertions) {
      return this._handleExceeded(
        BudgetError.MAX_ASSERTIONS,
        `Maximum assertion events (${this.maxAssertions}) exceeded. Consider chunking input.`
      );
    }

    // Check parse time
    if (this.startTime && (Date.now() - this.startTime) > this.maxParseTime) {
      return this._handleExceeded(
        BudgetError.MAX_PARSE_TIME,
        `Parse time exceeded maximum (${this.maxParseTime}ms). Consider chunking input.`
      );
    }

    return true;
  }

  /**
   * Add a node to the budget tracking
   *
   * @param {string} nodeType - Type of node being added
   * @returns {boolean} True if added successfully
   * @throws {Error} If throwOnExceed is true and budget exceeded
   */
  addNode(nodeType) {
    if (!this.canAddNode(nodeType)) {
      this.truncated = true;
      return false;
    }

    this.nodeCount++;

    if (this._isReferentType(nodeType)) {
      this.referentCount++;
    }

    if (this._isAssertionType(nodeType)) {
      this.assertionCount++;
    }

    return true;
  }

  /**
   * Add multiple nodes at once
   *
   * @param {Array<string>} nodeTypes - Array of node types
   * @returns {number} Number of nodes successfully added
   */
  addNodes(nodeTypes) {
    let added = 0;
    for (const type of nodeTypes) {
      if (this.addNode(type)) {
        added++;
      } else {
        break; // Stop on first failure
      }
    }
    return added;
  }

  /**
   * Get current usage statistics
   *
   * @returns {Object} Current budget usage
   */
  getUsage() {
    const elapsed = this.startTime ? Date.now() - this.startTime : 0;

    return {
      nodes: {
        current: this.nodeCount,
        max: this.maxNodes,
        percentage: Math.round((this.nodeCount / this.maxNodes) * 100)
      },
      referents: {
        current: this.referentCount,
        max: this.maxReferents,
        percentage: Math.round((this.referentCount / this.maxReferents) * 100)
      },
      assertions: {
        current: this.assertionCount,
        max: this.maxAssertions,
        percentage: Math.round((this.assertionCount / this.maxAssertions) * 100)
      },
      textLength: {
        current: this.textLength,
        max: this.maxTextLength,
        percentage: Math.round((this.textLength / this.maxTextLength) * 100)
      },
      parseTime: {
        current: elapsed,
        max: this.maxParseTime,
        percentage: Math.round((elapsed / this.maxParseTime) * 100)
      },
      exceeded: this.exceeded,
      truncated: this.truncated,
      warnings: this.warnings
    };
  }

  /**
   * Check if graph was truncated due to budget limits
   *
   * @returns {boolean} True if truncated
   */
  wasTruncated() {
    return this.truncated;
  }

  /**
   * Check if any budget limit was exceeded
   *
   * @returns {boolean} True if exceeded
   */
  wasExceeded() {
    return this.exceeded;
  }

  /**
   * Get remaining capacity
   *
   * @returns {Object} Remaining capacity for each metric
   */
  getRemaining() {
    return {
      nodes: this.maxNodes - this.nodeCount,
      referents: this.maxReferents - this.referentCount,
      assertions: this.maxAssertions - this.assertionCount,
      textChars: this.maxTextLength - this.textLength
    };
  }

  /**
   * Estimate if text needs chunking
   *
   * @param {string} text - Input text
   * @returns {Object} Chunking recommendation
   */
  estimateChunking(text) {
    const textLength = text.length;
    const needsChunking = textLength > this.maxTextLength;

    if (!needsChunking) {
      return {
        needsChunking: false,
        chunks: 1,
        recommendation: null
      };
    }

    // Estimate chunks needed
    const estimatedChunks = Math.ceil(textLength / this.maxTextLength);

    return {
      needsChunking: true,
      chunks: estimatedChunks,
      textLength,
      maxTextLength: this.maxTextLength,
      recommendation: `Text (${textLength} chars) exceeds maximum (${this.maxTextLength}). ` +
        `Recommend splitting into ${estimatedChunks} chunks.`
    };
  }

  /**
   * Chunk text into budget-compliant pieces
   *
   * @param {string} text - Input text to chunk
   * @param {Object} options - Chunking options
   * @param {number} [options.maxChars] - Max chars per chunk (default: maxTextLength)
   * @param {boolean} [options.preserveSentences=true] - Split on sentence boundaries
   * @returns {Array<Object>} Array of chunk objects
   */
  chunkText(text, options = {}) {
    const maxChars = options.maxChars || this.maxTextLength;
    const preserveSentences = options.preserveSentences !== false;

    if (text.length <= maxChars) {
      return [{
        index: 0,
        text: text,
        startOffset: 0,
        endOffset: text.length
      }];
    }

    const chunks = [];

    if (preserveSentences) {
      // Split on sentence boundaries
      const sentences = text.match(/[^.!?]+[.!?]+/g) || [text];
      let currentChunk = '';
      let currentOffset = 0;
      let chunkStartOffset = 0;

      for (const sentence of sentences) {
        if ((currentChunk + sentence).length > maxChars) {
          if (currentChunk) {
            chunks.push({
              index: chunks.length,
              text: currentChunk.trim(),
              startOffset: chunkStartOffset,
              endOffset: currentOffset
            });
          }
          currentChunk = sentence;
          chunkStartOffset = currentOffset;
        } else {
          currentChunk += sentence;
        }
        currentOffset += sentence.length;
      }

      if (currentChunk) {
        chunks.push({
          index: chunks.length,
          text: currentChunk.trim(),
          startOffset: chunkStartOffset,
          endOffset: currentOffset
        });
      }
    } else {
      // Simple character-based splitting
      let offset = 0;
      while (offset < text.length) {
        const endOffset = Math.min(offset + maxChars, text.length);
        chunks.push({
          index: chunks.length,
          text: text.substring(offset, endOffset),
          startOffset: offset,
          endOffset: endOffset
        });
        offset = endOffset;
      }
    }

    return chunks;
  }

  /**
   * Get metadata for inclusion in graph output
   *
   * @returns {Object} Budget metadata for JSON-LD
   */
  getMetadata() {
    const usage = this.getUsage();

    return {
      'tagteam:budgetUsage': {
        nodes: usage.nodes.current,
        referents: usage.referents.current,
        assertions: usage.assertions.current
      },
      'tagteam:truncated': this.truncated,
      'tagteam:budgetWarnings': this.warnings.length > 0 ? this.warnings : undefined
    };
  }

  // ================================================================
  // Private Methods
  // ================================================================

  /**
   * Check if node type is a discourse referent
   * @private
   */
  _isReferentType(nodeType) {
    if (!nodeType) return false;
    return nodeType.includes('DiscourseReferent') ||
      nodeType.includes('Person') ||
      nodeType.includes('Agent') ||
      nodeType.includes('Artifact');
  }

  /**
   * Check if node type is an assertion event
   * @private
   */
  _isAssertionType(nodeType) {
    if (!nodeType) return false;
    return nodeType.includes('AssertionEvent') ||
      nodeType.includes('ValueAssertionEvent') ||
      nodeType.includes('ContextAssessmentEvent');
  }

  /**
   * Handle budget exceeded
   * @private
   */
  _handleExceeded(errorType, message) {
    this.exceeded = true;
    this.warnings.push(message);

    if (this.throwOnExceed) {
      throw this._createError(errorType, message);
    }

    return false;
  }

  /**
   * Create a budget error
   * @private
   */
  _createError(type, message) {
    const error = new Error(message);
    error.name = 'ComplexityBudgetError';
    error.type = type;
    error.budget = this.getUsage();
    return error;
  }
}

// Export error types
ComplexityBudget.BudgetError = BudgetError;



  // ============================================================================
  // DOMAIN CONFIG LOADER (Phase 2 - Domain-Neutral Implementation)
  // Loads domain-specific type mappings for BFO → CCO specialization
  // ============================================================================

/**
 * DomainConfigLoader.js
 *
 * Manages loadable domain configuration files for type specialization.
 * Enables domain-neutral core with pluggable domain vocabularies.
 *
 * Phase 2 Implementation:
 * - Load JSON config files for domain-specific type mappings
 * - Specialize BFO types to domain-specific CCO/custom types
 * - Support verb sense overrides based on selectional restrictions
 * - Allow multiple domains to be loaded additively
 *
 * @module graph/DomainConfigLoader
 * @version 4.0.0-phase4
 */

/**
 * Loader for domain-specific configuration files
 *
 * @example
 * const loader = new DomainConfigLoader();
 * loader.loadConfig('config/medical.json');
 * const type = loader.getTypeSpecialization('Process', 'care');
 * // Returns: 'cco:ActOfCare'
 */
class DomainConfigLoader {
  /**
   * Create a new DomainConfigLoader
   */
  constructor() {
    // Map of domain name -> config object
    this.configs = new Map();

    // Merged type specializations from all loaded configs
    // Structure: Map<bfoType, Map<term, specializedType>>
    this.typeSpecializations = new Map();

    // Merged verb overrides from all loaded configs
    // Structure: Map<verb, { objectIsOccurrent, objectIsContinuant, objectIsGDC, default }>
    this.verbOverrides = new Map();

    // Process root words (domain-specific process terms)
    // Structure: Map<term, specializedType>
    this.processRootWords = new Map();

    // Track load order for conflict resolution (last wins)
    this.loadOrder = [];
  }

  /**
   * Load a domain configuration from a JSON file
   *
   * @param {string} configPath - Path to the JSON config file
   * @returns {boolean} True if loaded successfully
   * @throws {Error} If file cannot be read or parsed
   *
   * @example
   * loader.loadConfig('config/medical.json');
   */
  loadConfig(configPath) {
    throw new Error('DomainConfigLoader.loadConfig() requires Node.js. Use loadConfigObject(jsonObj) in the browser bundle.');
  }

  /**
   * Load a domain configuration from an object
   *
   * @param {Object} config - Configuration object
   * @param {string} config.domain - Domain name (e.g., 'medical', 'legal')
   * @param {string} config.version - Config version
   * @param {Object} [config.typeSpecializations] - BFO type -> term -> specialized type
   * @param {Object} [config.verbOverrides] - Verb sense overrides
   * @param {Object} [config.processRootWords] - Domain-specific process terms
   * @returns {boolean} True if loaded successfully
   *
   * @example
   * loader.loadConfigObject({
   *   domain: 'medical',
   *   version: '1.0',
   *   typeSpecializations: {
   *     'Process': {
   *       'care': 'cco:ActOfCare'
   *     }
   *   }
   * });
   */
  loadConfigObject(config) {
    // Validate required fields
    if (!config.domain) {
      throw new Error('Config must have a "domain" field');
    }
    if (!config.version) {
      throw new Error('Config must have a "version" field');
    }

    // Check for existing domain (warn on conflict)
    if (this.configs.has(config.domain)) {
      console.warn(
        `Warning: Domain '${config.domain}' already loaded. Overwriting with new config.`
      );
    }

    // Store the config
    this.configs.set(config.domain, config);
    this.loadOrder.push(config.domain);

    // Merge type specializations
    if (config.typeSpecializations) {
      for (const [bfoType, terms] of Object.entries(config.typeSpecializations)) {
        if (!this.typeSpecializations.has(bfoType)) {
          this.typeSpecializations.set(bfoType, new Map());
        }
        const typeMap = this.typeSpecializations.get(bfoType);

        for (const [term, specializedType] of Object.entries(terms)) {
          // Check for conflict
          if (typeMap.has(term) && typeMap.get(term) !== specializedType) {
            console.warn(
              `Warning: Term '${term}' already mapped to '${typeMap.get(term)}'. ` +
              `Overwriting with '${specializedType}' from ${config.domain} config.`
            );
          }
          typeMap.set(term.toLowerCase(), specializedType);
        }
      }
    }

    // Merge verb overrides
    if (config.verbOverrides) {
      for (const [verb, overrides] of Object.entries(config.verbOverrides)) {
        // Check for conflict
        if (this.verbOverrides.has(verb)) {
          console.warn(
            `Warning: Verb '${verb}' already has overrides. ` +
            `Merging with ${config.domain} config (last wins).`
          );
        }
        this.verbOverrides.set(verb.toLowerCase(), {
          ...this.verbOverrides.get(verb.toLowerCase()),
          ...overrides
        });
      }
    }

    // Merge process root words
    if (config.processRootWords) {
      for (const [term, type] of Object.entries(config.processRootWords)) {
        if (this.processRootWords.has(term.toLowerCase()) &&
            this.processRootWords.get(term.toLowerCase()) !== type) {
          console.warn(
            `Warning: Process root word '${term}' already mapped. ` +
            `Overwriting with ${config.domain} config.`
          );
        }
        this.processRootWords.set(term.toLowerCase(), type);
      }
    }

    return true;
  }

  /**
   * Get specialized type for a term given its BFO base type
   *
   * @param {string} bfoType - BFO base type (e.g., 'Process')
   * @param {string} term - The term to specialize (e.g., 'care')
   * @returns {string|null} Specialized type or null if no specialization found
   *
   * @example
   * loader.getTypeSpecialization('Process', 'care')
   * // Returns: 'cco:ActOfCare' (if medical config loaded)
   */
  getTypeSpecialization(bfoType, term) {
    const typeMap = this.typeSpecializations.get(bfoType);
    if (!typeMap) {
      return null;
    }

    const normalizedTerm = term.toLowerCase().trim();

    // Direct match
    if (typeMap.has(normalizedTerm)) {
      return typeMap.get(normalizedTerm);
    }

    // Check for partial match (term contains the key)
    for (const [key, value] of typeMap) {
      if (normalizedTerm.includes(key) || key.includes(normalizedTerm)) {
        return value;
      }
    }

    return null;
  }

  /**
   * Get process type for a domain-specific root word
   *
   * @param {string} term - The term to check (e.g., 'care', 'surgery')
   * @returns {string|null} Process type or null if not found
   *
   * @example
   * loader.getProcessRootWord('care')
   * // Returns: 'cco:ActOfCare' (if medical config loaded)
   */
  getProcessRootWord(term) {
    const normalizedTerm = term.toLowerCase().trim();

    // Direct match
    if (this.processRootWords.has(normalizedTerm)) {
      return this.processRootWords.get(normalizedTerm);
    }

    // Check if term contains any root word
    for (const [rootWord, type] of this.processRootWords) {
      if (normalizedTerm.includes(rootWord)) {
        return type;
      }
    }

    return null;
  }

  /**
   * Get verb sense override based on direct object type
   *
   * @param {string} verb - The verb (e.g., 'provide')
   * @param {string} objectCategory - Object ontological category
   *   ('occurrent', 'continuant', 'gdc', or specific type)
   * @returns {string|null} Override act type or null
   *
   * @example
   * loader.getVerbOverride('provide', 'occurrent')
   * // Returns: 'cco:ActOfService'
   */
  getVerbOverride(verb, objectCategory) {
    const overrides = this.verbOverrides.get(verb.toLowerCase());
    if (!overrides) {
      return null;
    }

    // Map category to override key
    const categoryMap = {
      'occurrent': 'objectIsOccurrent',
      'process': 'objectIsOccurrent',
      'continuant': 'objectIsContinuant',
      'ic': 'objectIsContinuant',
      'gdc': 'objectIsGDC',
      'information': 'objectIsGDC'
    };

    const overrideKey = categoryMap[objectCategory.toLowerCase()] || objectCategory;

    if (overrides[overrideKey]) {
      return overrides[overrideKey];
    }

    // Fall back to default if available
    if (overrides.default) {
      return overrides.default;
    }

    return null;
  }

  /**
   * Check if any domain config is loaded
   *
   * @returns {boolean} True if at least one config is loaded
   */
  isConfigLoaded() {
    return this.configs.size > 0;
  }

  /**
   * Get list of loaded domain names
   *
   * @returns {Array<string>} Array of domain names in load order
   */
  getLoadedDomains() {
    return [...this.loadOrder];
  }

  /**
   * Get a specific loaded config by domain name
   *
   * @param {string} domain - Domain name
   * @returns {Object|null} Config object or null if not found
   */
  getConfig(domain) {
    return this.configs.get(domain) || null;
  }

  /**
   * Clear all loaded configurations
   * Returns parser to BFO-only mode
   */
  clearConfigs() {
    this.configs.clear();
    this.typeSpecializations.clear();
    this.verbOverrides.clear();
    this.processRootWords.clear();
    this.loadOrder = [];
  }

  /**
   * Get all type specializations (for debugging/introspection)
   *
   * @returns {Object} Nested object of all specializations
   */
  getAllTypeSpecializations() {
    const result = {};
    for (const [bfoType, terms] of this.typeSpecializations) {
      result[bfoType] = Object.fromEntries(terms);
    }
    return result;
  }

  /**
   * Get all process root words (for debugging/introspection)
   *
   * @returns {Object} Object of term -> type mappings
   */
  getAllProcessRootWords() {
    return Object.fromEntries(this.processRootWords);
  }
}



  // ============================================================================
  // PHASE 5: AMBIGUITY REPORT
  // Data structure for ambiguity detection results
  // ============================================================================

/**
 * AmbiguityReport - Phase 5.3
 *
 * Structured output for detected ambiguities.
 * Designed for Phase 6 InterpretationLattice integration.
 *
 * @example
 * const report = new AmbiguityReport([
 *   { type: 'modal_force', span: 'should', nodeId: 'act_1', readings: ['obligation', 'expectation'] }
 * ]);
 * report.getByType('modal_force')
 * report.toJSONLD()
 */

class AmbiguityReport {
  constructor(ambiguities = []) {
    this.ambiguities = ambiguities;
    this.timestamp = new Date().toISOString();
    this.statistics = this._computeStatistics();
  }

  /**
   * Get confidence level for an ambiguity
   * Based on selectional preference strength and contextual signals
   * @param {Object} ambiguity - The ambiguity object
   * @returns {string} - 'high', 'medium', or 'low'
   */
  getConfidence(ambiguity) {
    if (ambiguity.confidence) {
      return ambiguity.confidence;
    }
    return this._computeConfidence(ambiguity);
  }

  /**
   * Compute confidence based on ambiguity characteristics
   * @private
   */
  _computeConfidence(ambiguity) {
    const { type, signals = [] } = ambiguity;

    // Selectional violations are high confidence (categorical mismatch)
    if (type === 'selectional_violation') return 'high';

    // Strong contextual signals increase confidence
    if (signals.length >= 2) return 'high';

    // Single signal or preference-based = lower confidence
    return signals.length === 1 ? 'medium' : 'low';
  }

  /**
   * Filter ambiguities by type
   * @param {string} type - The ambiguity type
   * @returns {Array<Object>} - Matching ambiguities
   */
  getByType(type) {
    return this.ambiguities.filter(a => a.type === type);
  }

  /**
   * Filter by severity (number of readings)
   * @param {number} minReadings - Minimum readings to match
   * @returns {Array<Object>} - Matching ambiguities
   */
  getBySeverity(minReadings = 2) {
    return this.ambiguities.filter(a =>
      a.readings && a.readings.length >= minReadings
    );
  }

  /**
   * Get ambiguities affecting a specific node
   * @param {string} nodeId - The node ID to filter by
   * @returns {Array<Object>} - Matching ambiguities
   */
  getForNode(nodeId) {
    return this.ambiguities.filter(a => a.nodeId === nodeId);
  }

  /**
   * Check if any critical ambiguities exist
   * Critical = more than 2 possible readings
   * @returns {boolean}
   */
  hasCriticalAmbiguities() {
    return this.ambiguities.some(a =>
      a.readings && a.readings.length > 2
    );
  }

  /**
   * Check if report has any ambiguities
   * @returns {boolean}
   */
  hasAmbiguities() {
    return this.ambiguities.length > 0;
  }

  /**
   * Get total count of ambiguities
   * @returns {number}
   */
  get count() {
    return this.ambiguities.length;
  }

  /**
   * Serialize for JSON-LD integration
   * @returns {Object} - JSON-LD compatible object
   */
  toJSONLD() {
    return {
      '@type': 'tagteam:AmbiguityReport',
      'tagteam:ambiguityCount': this.ambiguities.length,
      'tagteam:timestamp': this.timestamp,
      'tagteam:statistics': {
        '@type': 'tagteam:AmbiguityStatistics',
        'tagteam:total': this.statistics.total,
        'tagteam:byType': this.statistics.byType,
        'tagteam:averageReadings': this.statistics.avgReadings
      },
      'tagteam:ambiguities': this.ambiguities.map(a => this._ambiguityToJSONLD(a))
    };
  }

  /**
   * Convert single ambiguity to JSON-LD format
   * @private
   */
  _ambiguityToJSONLD(ambiguity) {
    const jsonld = {
      '@type': 'tagteam:DetectedAmbiguity',
      'tagteam:ambiguityType': ambiguity.type,
      'tagteam:confidence': this.getConfidence(ambiguity)
    };

    if (ambiguity.span) {
      jsonld['tagteam:span'] = ambiguity.span;
    }

    if (ambiguity.nodeId) {
      jsonld['tagteam:affectsNode'] = { '@id': ambiguity.nodeId };
    }

    if (ambiguity.readings) {
      jsonld['tagteam:possibleReadings'] = ambiguity.readings;
    }

    if (ambiguity.defaultReading) {
      jsonld['tagteam:defaultReading'] = ambiguity.defaultReading;
    }

    if (ambiguity.signals && ambiguity.signals.length > 0) {
      jsonld['tagteam:detectionSignals'] = ambiguity.signals;
    }

    // Type-specific fields
    if (ambiguity.type === 'selectional_violation') {
      if (ambiguity.signal) {
        jsonld['tagteam:violationType'] = ambiguity.signal;
      }
      if (ambiguity.subject) {
        jsonld['tagteam:subject'] = ambiguity.subject;
      }
      if (ambiguity.verb) {
        jsonld['tagteam:verb'] = ambiguity.verb;
      }
      if (ambiguity.ontologyConstraint) {
        jsonld['tagteam:ontologyConstraint'] = ambiguity.ontologyConstraint;
      }
    }

    if (ambiguity.type === 'modal_force') {
      if (ambiguity.modal) {
        jsonld['tagteam:modal'] = ambiguity.modal;
      }
      if (ambiguity.negationScope) {
        jsonld['tagteam:negationScope'] = ambiguity.negationScope;
      }
    }

    if (ambiguity.type === 'scope') {
      if (ambiguity.quantifier) {
        jsonld['tagteam:quantifier'] = ambiguity.quantifier;
      }
      if (ambiguity.negation) {
        jsonld['tagteam:negation'] = ambiguity.negation;
      }
      if (ambiguity.formalizations) {
        jsonld['tagteam:formalizations'] = ambiguity.formalizations;
      }
    }

    return jsonld;
  }

  /**
   * Compute statistics about ambiguities
   * @private
   */
  _computeStatistics() {
    const byType = {};
    let totalReadings = 0;

    this.ambiguities.forEach(a => {
      byType[a.type] = (byType[a.type] || 0) + 1;
      if (a.readings) {
        totalReadings += a.readings.length;
      }
    });

    return {
      total: this.ambiguities.length,
      byType,
      avgReadings: this.ambiguities.length > 0
        ? totalReadings / this.ambiguities.length
        : 0
    };
  }

  /**
   * Create a summary string
   * @returns {string}
   */
  toString() {
    if (this.ambiguities.length === 0) {
      return 'AmbiguityReport: No ambiguities detected';
    }

    const typeStr = Object.entries(this.statistics.byType)
      .map(([type, count]) => `${type}: ${count}`)
      .join(', ');

    return `AmbiguityReport: ${this.ambiguities.length} ambiguities (${typeStr})`;
  }
}

// Export for both Node.js and browser
// ============================================================================
  // PHASE 5: AMBIGUITY DETECTOR
  // Detects modal, scope, noun category, and selectional ambiguities
  // ============================================================================

/**
 * AmbiguityDetector - Phase 5.3 (Phase 6.0 Updated)
 *
 * Identifies potentially ambiguous spans in parsed output.
 * Does NOT resolve ambiguity - only flags it for Phase 6 lattice.
 *
 * Phase 6.0 Update: Now uses SelectionalPreferences for centralized
 * verb→argument validation, properly handling organizations as valid
 * agents for mental/communication acts.
 *
 * Ambiguity Types:
 * - noun_category: Nominalizations ambiguous between process/continuant
 * - modal_force: Modal verbs ambiguous between deontic/epistemic
 * - scope: Quantifier + negation scope ambiguity
 * - selectional_violation: Categorical constraint violations
 * - selectional_preference: Soft constraint notes
 * - potential_metonymy: Possible metonymic usage
 * - verb_sense: Multiple selectional matches for verb
 *
 * @example
 * const detector = new AmbiguityDetector();
 * const report = detector.detect(text, entities, acts, roles);
 */

class AmbiguityDetector {
  constructor(config = {}) {
    // Phase 6.0: Use centralized SelectionalPreferences for verb/entity validation
    this.selectionalPreferences = new SelectionalPreferences(config.selectionalConfig);

    // Nominalization suffixes for process/continuant ambiguity
    this.nominalizationSuffixes = [
      { suffix: 'tion', label: '-tion' },
      { suffix: 'sion', label: '-sion' },
      { suffix: 'ment', label: '-ment' },
      { suffix: 'ing', label: '-ing' },
      { suffix: 'ance', label: '-ance/-ence' },
      { suffix: 'ence', label: '-ance/-ence' },
      { suffix: 'al', label: '-al' },
      { suffix: 'age', label: '-age' }
    ];

    // Words that are nominalizations but also commonly used as pure continuants
    this.continuantDominant = new Set([
      'building', 'painting', 'ceiling', 'morning', 'evening', 'thing',
      'meeting', 'wedding', 'setting', 'clothing', 'feeling'
    ]);

    // Modal verbs and their ambiguity profile
    this.deonticModals = ['must', 'should', 'shall', 'ought'];
    this.epistemicModals = ['may', 'might', 'could', 'should'];
    this.ambiguousModals = ['must', 'should', 'may', 'can', 'could', 'would'];

    // Scope-relevant quantifiers
    this.universalQuantifiers = ['all', 'every', 'each'];
    this.existentialQuantifiers = ['some', 'any', 'a', 'an'];
    this.negativeQuantifiers = ['no', 'none', 'neither'];

    // Stative verbs (more likely epistemic modal reading)
    // Note: Also available via selectionalPreferences.getVerbClass() === 'stative'
    this.stativeVerbs = new Set([
      'be', 'have', 'know', 'believe', 'think', 'want', 'need',
      'like', 'love', 'hate', 'prefer', 'understand', 'seem',
      'appear', 'belong', 'contain', 'consist', 'exist', 'own'
    ]);

    // Metonymy patterns (location for institution)
    // These are also in SelectionalPreferences.entityCategories.organization
    this.metonymyPatterns = new Set([
      'house', 'street', 'hill', 'place', 'office', 'court', 'bench'
    ]);

    // Duration predicates (signal process reading)
    this.durationPredicates = new Set([
      'last', 'take', 'continue', 'persist', 'endure', 'span'
    ]);

    this.config = config;
  }

  /**
   * Detect all ambiguities in parsed output
   * @param {string} text - Original text
   * @param {Array} entities - Extracted entities
   * @param {Array} acts - Extracted acts
   * @param {Array} roles - Semantic roles (optional)
   * @returns {AmbiguityReport}
   */
  detect(text, entities = [], acts = [], roles = []) {
    const ambiguities = [];

    // 1. Check nouns for process/continuant ambiguity
    ambiguities.push(...this._detectNounAmbiguity(entities, acts, roles));

    // 2. Check for selectional constraint violations
    ambiguities.push(...this._detectSelectionalViolations(entities, acts, roles));

    // 3. Check modals for deontic/epistemic ambiguity
    ambiguities.push(...this._detectModalAmbiguity(acts, entities, roles));

    // 4. Check for scope ambiguity (quantifiers + negation)
    ambiguities.push(...this._detectScopeAmbiguity(text, entities, acts));

    // 5. Check for potential metonymy
    ambiguities.push(...this._detectMetonymy(entities, acts, roles));

    return new AmbiguityReport(ambiguities);
  }

  /**
   * Detect nominalization ambiguity (process vs continuant)
   * @private
   */
  _detectNounAmbiguity(entities, acts, roles) {
    const ambiguities = [];

    for (const entity of entities) {
      const noun = this._getNounWord(entity);
      if (!noun) continue;

      const nominalization = this._checkNominalization(noun);
      if (!nominalization.isNominalization) continue;

      // Skip if clearly a continuant-dominant word
      if (this.continuantDominant.has(noun.toLowerCase())) continue;

      const signals = [];
      let defaultReading = null;
      let confidence = 'medium';

      // Check context signals
      const isAgent = this._isAgentOf(entity, acts, roles);
      const hasOfComplement = this._hasOfComplement(entity);
      const hasDurationPredicate = this._hasDurationPredicate(entity, acts);

      if (isAgent) {
        signals.push('subject_of_intentional_act');
        defaultReading = 'continuant';
        confidence = 'high';
      }

      if (hasOfComplement) {
        signals.push('of_complement');
        if (!defaultReading) defaultReading = 'process';
      }

      if (hasDurationPredicate) {
        signals.push('duration_predicate');
        defaultReading = 'process';
        confidence = 'high';
      }

      // Check for predicate adjective (suggests process if difficulty-related)
      if (this._hasDifficultyPredicate(entity)) {
        signals.push('predicate_adjective');
        if (!defaultReading) defaultReading = 'process';
      }

      ambiguities.push({
        type: 'noun_category',
        span: entity.label || entity.sourceText || noun,
        nodeId: entity['@id'],
        readings: ['process', 'continuant'],
        signals,
        defaultReading: defaultReading || 'continuant',
        confidence,
        nominalizationSuffix: nominalization.suffix
      });
    }

    return ambiguities;
  }

  /**
   * Check if a word is a nominalization
   * @private
   */
  _checkNominalization(word) {
    const lw = word.toLowerCase();

    for (const { suffix, label } of this.nominalizationSuffixes) {
      if (lw.endsWith(suffix) && lw.length > suffix.length + 2) {
        return { isNominalization: true, suffix: label };
      }
    }

    return { isNominalization: false };
  }

  /**
   * Detect selectional constraint violations
   * @private
   */
  _detectSelectionalViolations(entities, acts, roles) {
    const ambiguities = [];

    for (const act of acts) {
      const violation = this._checkActSelectionalConstraints(act, entities, roles);
      if (violation) {
        ambiguities.push(violation);
      }
    }

    return ambiguities;
  }

  /**
   * Check selectional constraints for a single act
   * Phase 6.0: Now uses SelectionalPreferences for proper validation
   * @private
   */
  _checkActSelectionalConstraints(act, entities, roles) {
    const agent = this._findAgentFor(act, entities, roles);
    const patient = this._findPatientFor(act, entities, roles);
    const verb = this._getVerbLemma(act);

    if (!agent) return null;

    const agentNoun = this._getNounWord(agent);
    if (!agentNoun) return null;

    // Phase 6.0: Use SelectionalPreferences for validation
    const violation = this.selectionalPreferences.getViolation(verb, agentNoun);

    if (violation) {
      return {
        type: 'selectional_violation',
        signal: violation.signal,
        subject: this._getEntityLabel(agent),
        verb: verb,
        verbClass: violation.verbClass,
        agentCategory: violation.agentCategory,
        nodeId: act['@id'],
        confidence: 'high',
        ontologyConstraint: violation.ontologyConstraint
      };
    }

    return null;
  }

  /**
   * Detect modal force ambiguity (deontic vs epistemic)
   * @private
   */
  _detectModalAmbiguity(acts, entities, roles) {
    const ambiguities = [];

    for (const act of acts) {
      const modal = this._getModal(act);
      if (!modal) continue;

      // Check if modal is potentially ambiguous
      if (!this.ambiguousModals.includes(modal.toLowerCase())) continue;

      const signals = [];
      let defaultReading = null;
      const readings = [];

      const lowerModal = modal.toLowerCase();
      const verb = this._getVerbLemma(act);
      const agent = this._findAgentFor(act, entities, roles);
      const hasPerfectAspect = this._hasPerfectAspect(act);
      const isStative = this.stativeVerbs.has(verb);

      // Determine readings based on modal
      if (lowerModal === 'must' || lowerModal === 'should') {
        readings.push('obligation', 'expectation');
        if (lowerModal === 'must') {
          readings[1] = 'inference'; // "must have" = inference
        }
      } else if (lowerModal === 'may' || lowerModal === 'might') {
        readings.push('permission', 'possibility');
      } else if (lowerModal === 'can' || lowerModal === 'could') {
        readings.push('ability', 'possibility');
      } else if (lowerModal === 'would') {
        readings.push('conditional', 'habitual');
      }

      // Context signals for disambiguation
      if (hasPerfectAspect) {
        signals.push('perfect_aspect');
        // Perfect aspect strongly suggests epistemic
        defaultReading = readings[1]; // expectation/inference/possibility
      }

      if (isStative) {
        signals.push('stative_verb');
        if (!defaultReading) defaultReading = readings[1];
      }

      if (agent && this._isAnimate(agent)) {
        signals.push('agent_subject');
        if (!defaultReading) defaultReading = readings[0]; // deontic
      }

      if (this._isIntentionalAct(act)) {
        signals.push('intentional_act');
        if (!defaultReading) defaultReading = readings[0];
      }

      // Check for second person (you) - suggests deontic
      if (agent && this._isSecondPerson(agent)) {
        signals.push('second_person_subject');
        defaultReading = readings[0];
      }

      // Check negation scope
      const negationScope = this._getNegationScope(act);

      ambiguities.push({
        type: 'modal_force',
        span: act.sourceText || act.label,
        nodeId: act['@id'],
        modal: modal,
        readings,
        signals,
        defaultReading: defaultReading || readings[0],
        negationScope
      });
    }

    return ambiguities;
  }

  /**
   * Detect scope ambiguity (quantifiers + negation)
   * @private
   */
  _detectScopeAmbiguity(text, entities, acts) {
    const ambiguities = [];
    const lowerText = text.toLowerCase();

    // Check for universal quantifier + negation
    for (const quantifier of this.universalQuantifiers) {
      if (lowerText.includes(quantifier)) {
        // Check for negation
        if (lowerText.includes('not') || lowerText.includes("n't") || lowerText.includes('never')) {
          // Check word order for default reading
          const quantIdx = lowerText.indexOf(quantifier);
          const notIdx = Math.max(
            lowerText.indexOf('not'),
            lowerText.indexOf("n't"),
            lowerText.indexOf('never')
          );

          const readings = ['wide', 'narrow'];
          let defaultReading = 'narrow'; // Default: quantifier scopes over negation
          let confidence = 'medium';

          // "Not all" = clear wide scope
          if (lowerText.includes('not all') || lowerText.includes('not every')) {
            defaultReading = 'wide';
            confidence = 'high';
          }

          ambiguities.push({
            type: 'scope',
            span: text,
            quantifier,
            negation: 'not',
            readings,
            defaultReading,
            confidence,
            formalizations: {
              wide: `¬∀x.P(x)`,
              narrow: `∀x.¬P(x)`
            }
          });
        }
      }
    }

    // Check for multiple quantifiers
    const foundQuantifiers = [];
    for (const q of [...this.universalQuantifiers, ...this.existentialQuantifiers]) {
      if (lowerText.includes(q + ' ')) {
        foundQuantifiers.push(q);
      }
    }

    if (foundQuantifiers.length >= 2) {
      ambiguities.push({
        type: 'scope',
        span: text,
        quantifiers: foundQuantifiers,
        readings: ['subject_wide', 'object_wide'],
        defaultReading: 'subject_wide', // Default: surface order
        confidence: 'medium'
      });
    }

    // Check for modal + negation scope
    for (const act of acts) {
      const modal = this._getModal(act);
      const isNegated = act.negated || act['tagteam:polarity'] === 'negative';

      if (modal && isNegated) {
        const lowerModal = modal.toLowerCase();

        if (lowerModal === 'may') {
          ambiguities.push({
            type: 'scope',
            span: act.sourceText || act.label,
            nodeId: act['@id'],
            modal,
            readings: ['permission_denied', 'possibility_denied'],
            defaultReading: 'permission_denied',
            confidence: 'medium'
          });
        }
      }
    }

    return ambiguities;
  }

  /**
   * Detect potential metonymy
   * @private
   */
  _detectMetonymy(entities, acts, roles) {
    const ambiguities = [];

    for (const entity of entities) {
      const noun = this._getNounWord(entity);
      if (!noun) continue;

      if (this.metonymyPatterns.has(noun.toLowerCase())) {
        // Check if used as agent of intentional act
        const isAgent = this._isAgentOf(entity, acts, roles);

        if (isAgent) {
          ambiguities.push({
            type: 'potential_metonymy',
            span: entity.label || entity.sourceText || noun,
            nodeId: entity['@id'],
            signal: 'location_as_agent',
            suggestedReading: 'institution',
            confidence: 'medium'
          });
        }
      }
    }

    return ambiguities;
  }

  // ============ Helper Methods ============

  /**
   * Get the main noun word from an entity
   * For phrases like "organization of files", returns "organization" (before "of")
   * Handles both test data (entity.label) and SemanticGraphBuilder output (rdfs:label)
   * @private
   */
  _getNounWord(entity) {
    if (entity.head) return entity.head;

    // For label/sourceText, handle "X of Y" patterns
    // Support both test format (label) and graph format (rdfs:label)
    const text = entity.label || entity['rdfs:label'] || entity.sourceText;
    if (!text) return null;

    // If contains " of ", take the word before "of"
    const ofIndex = text.toLowerCase().indexOf(' of ');
    if (ofIndex > 0) {
      const beforeOf = text.substring(0, ofIndex).trim();
      return beforeOf.split(' ').pop();
    }

    // Otherwise take the last word
    return text.split(' ').pop();
  }

  /**
   * Get entity label for display
   * Handles both test data (entity.label) and SemanticGraphBuilder output (rdfs:label)
   * @private
   */
  _getEntityLabel(entity) {
    return entity.label || entity['rdfs:label'] || entity.sourceText || entity.head || 'unknown';
  }

  /**
   * Get verb lemma from act
   * Handles both test data and SemanticGraphBuilder output
   * @private
   */
  _getVerbLemma(act) {
    // Direct properties
    if (act.lemma) return act.lemma;
    if (act.verb) return act.verb;
    // SemanticGraphBuilder output uses tagteam:verb
    if (act['tagteam:verb']) return act['tagteam:verb'];
    // Fallback
    return act.label || act['rdfs:label'] || '';
  }

  /**
   * Get modal from act
   * Handles both test data (act.modal) and SemanticGraphBuilder output (tagteam:modality)
   * @private
   */
  _getModal(act) {
    // Direct modal property (from tests or VerbPhraseExtractor)
    if (act.modal) return act.modal;

    // From SemanticGraphBuilder: tagteam:modality gives the semantic type
    // We need to infer the modal word from sourceText or modality mapping
    const modality = act['tagteam:modality'];
    if (modality) {
      // Map modality types back to modal words for ambiguity detection
      const modalityToModal = {
        'recommendation': 'should',
        'obligation': 'must',
        'permission': 'may',
        'possibility': 'might',
        'ability': 'can',
        'conditional': 'would',
        'futurity': 'will'
      };
      if (modalityToModal[modality]) {
        return modalityToModal[modality];
      }
    }

    // Try to extract from sourceText
    const sourceText = act['tagteam:sourceText'] || act.sourceText || '';
    const modalMatch = sourceText.toLowerCase().match(/\b(must|should|may|might|can|could|will|would|shall|ought)\b/);
    if (modalMatch) {
      return modalMatch[1];
    }

    return null;
  }

  /**
   * Find agent for an act
   * Handles both test data and SemanticGraphBuilder output
   * @private
   */
  _findAgentFor(act, entities, roles) {
    // Check roles first
    for (const role of roles) {
      if (role.act === act['@id'] && role.type === 'agent') {
        return entities.find(e => e['@id'] === role.entity);
      }
    }

    // Test data format: act.agent
    if (act.agent) {
      return entities.find(e => e['@id'] === act.agent || e.label === act.agent);
    }

    // SemanticGraphBuilder format: cco:has_agent
    const hasAgent = act['has_agent'];
    if (hasAgent) {
      const agentIRI = typeof hasAgent === 'object' ? hasAgent['@id'] : hasAgent;
      return entities.find(e => e['@id'] === agentIRI);
    }

    return null;
  }

  /**
   * Find patient for an act
   * @private
   */
  _findPatientFor(act, entities, roles) {
    for (const role of roles) {
      if (role.act === act['@id'] && role.type === 'patient') {
        return entities.find(e => e['@id'] === role.entity);
      }
    }

    if (act.patient) {
      return entities.find(e => e['@id'] === act.patient || e.label === act.patient);
    }

    return null;
  }

  /**
   * Check if entity is agent of any act
   * @private
   */
  _isAgentOf(entity, acts, roles) {
    const entityId = entity['@id'];
    const entityLabel = entity.label || entity.sourceText;

    for (const role of roles) {
      if (role.entity === entityId && role.type === 'agent') {
        return true;
      }
    }

    for (const act of acts) {
      if (act.agent === entityId || act.agent === entityLabel) {
        return true;
      }
    }

    return false;
  }

  /**
   * Check if entity is inanimate
   * Phase 6.0: Now uses SelectionalPreferences
   * @private
   */
  _isInanimate(entity) {
    const noun = this._getNounWord(entity);
    if (!noun) return false;

    return this.selectionalPreferences.isInanimate(noun);
  }

  /**
   * Check if entity is animate (person, not organization)
   * Phase 6.0: Now uses SelectionalPreferences
   * @private
   */
  _isAnimate(entity) {
    const noun = this._getNounWord(entity);
    if (!noun) return false;

    return this.selectionalPreferences.isAnimate(noun);
  }

  /**
   * Check if entity is an organization
   * Phase 6.0: New method using SelectionalPreferences
   * @private
   */
  _isOrganization(entity) {
    const noun = this._getNounWord(entity);
    if (!noun) return false;

    return this.selectionalPreferences.isOrganization(noun);
  }

  /**
   * Check if entity is abstract
   * Phase 6.0: Now uses SelectionalPreferences
   * @private
   */
  _isAbstract(entity) {
    const noun = this._getNounWord(entity);
    if (!noun) return false;

    return this.selectionalPreferences.isAbstract(noun);
  }

  /**
   * Check if act is intentional (mental, communication, transfer, etc.)
   * Phase 6.0: Now uses SelectionalPreferences verb classes
   * @private
   */
  _isIntentionalAct(act) {
    const verb = this._getVerbLemma(act);
    const verbClass = this.selectionalPreferences.getVerbClass(verb);

    // Intentional acts include mental, communication, transfer, employment, governance
    const intentionalClasses = [
      'intentional_mental',
      'communication',
      'transfer',
      'employment',
      'governance',
      'creation'
    ];

    return intentionalClasses.includes(verbClass);
  }

  /**
   * Check if act is physical
   * Phase 6.0: Now uses SelectionalPreferences verb classes
   * @private
   */
  _isPhysicalAct(act) {
    const verb = this._getVerbLemma(act);
    const verbClass = this.selectionalPreferences.getVerbClass(verb);

    return verbClass === 'intentional_physical' || verbClass === 'perception';
  }

  /**
   * Check if act has perfect aspect
   * @private
   */
  _hasPerfectAspect(act) {
    return act.tense === 'perfect' ||
           (act.auxiliary && act.auxiliary.some(a =>
             ['have', 'has', 'had'].includes(a)
           ));
  }

  /**
   * Check for of-complement (signals process reading)
   * @private
   */
  _hasOfComplement(entity) {
    const text = entity.sourceText || entity.label || '';
    return text.includes(' of ');
  }

  /**
   * Check for duration predicate
   * @private
   */
  _hasDurationPredicate(entity, acts) {
    // Check if entity is subject of a duration verb
    for (const act of acts) {
      const verb = this._getVerbLemma(act);
      if (this.durationPredicates.has(verb.toLowerCase())) {
        // Check if this entity is subject
        if (act.agent === entity['@id'] || act.agent === entity.label) {
          return true;
        }
      }
    }
    return false;
  }

  /**
   * Check for difficulty predicate adjective
   * @private
   */
  _hasDifficultyPredicate(entity) {
    // This would need more context - simplified check
    return false;
  }

  /**
   * Check if entity is second person pronoun
   * @private
   */
  _isSecondPerson(entity) {
    const label = (entity.label || entity.sourceText || '').toLowerCase();
    return label === 'you' || label === 'your';
  }

  /**
   * Get negation scope info
   * @private
   */
  _getNegationScope(act) {
    if (!act.negated) return null;

    const modal = this._getModal(act);
    if (modal) {
      // "must not" = obligation not to (negation under modal)
      return 'under_modal';
    }

    return 'predicate';
  }
}

// Export for both Node.js and browser
// ============================================================================
  // PHASE 6: SELECTIONAL PREFERENCES
  // Defines verb classes and entity categories for selectional constraints
  // ============================================================================

/**
 * SelectionalPreferences - Phase 6.0
 *
 * Centralizes verb→argument requirements for semantic role validation.
 * Used by AmbiguityDetector to determine selectional violations.
 *
 * This module replaces ad-hoc verb classification with a structured lookup
 * table that properly handles organizations, institutions, and collectives
 * as valid agents for mental/communication acts.
 *
 * @example
 * const prefs = new SelectionalPreferences();
 * prefs.isValidAgent('decide', 'committee'); // true (org can decide)
 * prefs.isValidAgent('decide', 'rock');      // false (inanimate can't)
 * prefs.isValidAgent('lift', 'committee');   // false (org can't physically lift)
 */

// Verb classes with their selectional requirements
const VERB_CLASSES = {
  // Mental acts requiring animate/organization agents
  intentional_mental: {
    verbs: new Set([
      'decide', 'believe', 'intend', 'think', 'consider', 'judge',
      'evaluate', 'assess', 'plan', 'hope', 'wish', 'choose',
      'determine', 'conclude', 'assume', 'suspect', 'doubt',
      'prefer', 'want', 'need', 'desire', 'expect', 'anticipate',
      'know', 'understand', 'realize', 'recognize', 'remember',
      'forget', 'learn', 'discover', 'notice', 'perceive', 'fear'
    ]),
    subjectRequirement: ['animate', 'organization', 'collective'],
    subjectForbidden: ['inanimate', 'abstract'],
    objectRequirement: null,  // Mental verbs have loose object constraints
    ontologyType: 'MentalAct'
  },

  // Physical acts requiring animate agents (NOT organizations)
  intentional_physical: {
    verbs: new Set([
      'lift', 'throw', 'carry', 'push', 'pull', 'hit', 'kick',
      'jump', 'climb', 'cut', 'break', 'touch',
      'grasp', 'hold', 'grab', 'drop', 'catch', 'shake',
      'bend', 'stretch', 'squeeze', 'tear', 'rip', 'fold',
      'eat', 'drink', 'swim', 'fly'
      // Note: 'walk', 'run', 'breathe', 'sleep' are motion/state verbs, not in this class
    ]),
    subjectRequirement: ['animate'],
    subjectForbidden: ['inanimate', 'abstract', 'organization'],
    objectRequirement: ['material_entity', 'inanimate'],  // Physical objects
    objectForbidden: ['abstract'],
    ontologyType: 'PhysicalAct'
  },

  // Communication acts (organizations can communicate)
  communication: {
    verbs: new Set([
      'announce', 'report', 'claim', 'state', 'declare', 'tell',
      'inform', 'ask', 'request', 'promise', 'warn', 'advise',
      'suggest', 'recommend', 'propose', 'order', 'command',
      'forbid', 'permit', 'authorize', 'deny', 'confirm', 'reject',
      'say', 'speak', 'write', 'publish', 'broadcast', 'notify',
      'respond', 'reply', 'answer', 'explain', 'describe', 'assert',
      'indicate', 'show', 'reveal', 'demonstrate', 'imply', 'point'
    ]),
    subjectRequirement: ['animate', 'organization', 'collective'],
    subjectForbidden: ['inanimate'],
    objectRequirement: null,  // Can announce anything
    ontologyType: 'CommunicativeAct'
  },

  // Transfer acts (organizations can transfer)
  transfer: {
    verbs: new Set([
      'give', 'allocate', 'assign', 'distribute', 'provide',
      'deliver', 'send', 'offer', 'grant', 'donate', 'lend',
      'return', 'transfer', 'convey', 'supply', 'furnish',
      'award', 'bestow', 'contribute', 'share', 'pass'
    ]),
    subjectRequirement: ['animate', 'organization', 'collective'],
    subjectForbidden: ['inanimate', 'abstract'],
    objectRequirement: null,  // Can transfer many things - be permissive
    ontologyType: 'TransferAct'
  },

  // Employment/organizational acts
  employment: {
    verbs: new Set([
      'hire', 'fire', 'employ', 'appoint', 'dismiss', 'recruit',
      'promote', 'demote', 'transfer', 'assign', 'terminate',
      'suspend', 'reinstate', 'retire', 'resign', 'layoff'
    ]),
    subjectRequirement: ['animate', 'organization'],
    objectRequirement: ['animate'],
    ontologyType: 'OrganizationalAct'
  },

  // Governance/policy acts
  governance: {
    verbs: new Set([
      'govern', 'regulate', 'legislate', 'enforce', 'implement',
      'enact', 'ratify', 'amend', 'repeal', 'veto', 'override',
      'review', 'audit', 'investigate', 'sanction', 'penalize',
      'certify', 'accredit', 'license', 'ban', 'prohibit'
    ]),
    subjectRequirement: ['animate', 'organization'],
    objectRequirement: null,
    ontologyType: 'GovernanceAct'
  },

  // Creation/production acts
  creation: {
    verbs: new Set([
      'create', 'make', 'build', 'construct', 'produce', 'manufacture',
      'design', 'develop', 'invent', 'compose', 'write', 'draw',
      'paint', 'sculpt', 'craft', 'assemble', 'fabricate',
      'generate', 'synthesize', 'formulate', 'establish', 'found'
    ]),
    subjectRequirement: ['animate', 'organization'],
    objectRequirement: ['continuant'],
    ontologyType: 'CreationAct'
  },

  // Perception acts (animate only, not organizations)
  perception: {
    verbs: new Set([
      'see', 'hear', 'smell', 'taste', 'feel', 'sense',
      'watch', 'observe', 'look', 'listen', 'view', 'witness',
      'detect', 'perceive', 'experience', 'undergo'
    ]),
    subjectRequirement: ['animate'],
    objectRequirement: null,
    ontologyType: 'PerceptionAct'
  },

  // Causation (any subject can cause - even inanimate)
  causation: {
    verbs: new Set([
      'cause', 'create', 'produce', 'generate', 'make',
      'trigger', 'induce', 'bring', 'result', 'lead',
      'provoke', 'spark', 'initiate', 'start', 'begin'
    ]),
    subjectRequirement: null,  // Any subject allowed (storms can cause)
    subjectForbidden: [],
    objectRequirement: null,
    ontologyType: 'Process'
  },

  // Stative/relational (broad subject requirements)
  stative: {
    verbs: new Set([
      'be', 'have', 'own', 'possess', 'contain', 'include',
      'consist', 'comprise', 'belong', 'exist', 'remain',
      'seem', 'appear', 'look', 'sound', 'feel',
      'cost', 'weigh', 'measure', 'equal', 'represent'
    ]),
    subjectRequirement: null, // Any subject allowed
    subjectForbidden: [],
    objectRequirement: null,
    ontologyType: 'RelationalQuality'
  }
};

// Entity categories for validation
